type Trace = {
  phaseClass: string;
  relay_phaseClass: string;
  memoryStatus: string;
  memoryMode: string;
  couplingTrigger: string;
  grammarCandidate?: string;
  gapSeverity: string;
  deltaLIS: number;
  deltaMTS: number;
  deltaRCS: number;
  deltaMemory: number;
  dominantStratum: string;
  z3z2Weight?: number;
  z0MeanReturn?: number;
  z4MeanReturn?: number;
  trajectorySignature: string;
  developmentalClassification?: string;
  totalBenchmarkScore?: number;
};

const SESSION_ID = "c1-main";
const MEMORY_DIR = path.join(process.cwd(), ".amelia-memory");
const MEMORY_FILE = path.join(MEMORY_DIR, `${SESSION_ID}.json`);

const g = globalThis as typeof globalThis & {
  __ameliaBridgeTraces?: Trace[];
  __ameliaBridgeLoaded?: boolean;
  __ameliaBridgeLoadPromise?: Promise<void>;
};

if (!g.__ameliaBridgeTraces) {
  g.__ameliaBridgeTraces = [];
}

function traces(): Trace[] {
  return g.__ameliaBridgeTraces!;
}

async function ensureMemoryDir(): Promise<void> {
  await mkdir(MEMORY_DIR, { recursive: true });
}

async function ensureTracesLoaded(): Promise<void> {
  if (g.__ameliaBridgeLoaded) return;

  if (!g.__ameliaBridgeLoadPromise) {
    g.__ameliaBridgeLoadPromise = (async () => {
      await ensureMemoryDir();
      try {
        const raw = await readFile(MEMORY_FILE, "utf8");
        const parsed = JSON.parse(raw);
        g.__ameliaBridgeTraces = Array.isArray(parsed?.traces)
          ? parsed.traces
          : [];
      } catch (error) {
        console.error("Failed to load traces:", error);
        g.__ameliaBridgeTraces = [];
      }
      ensurePhaseXXCanonicalBootstrapLoaded();
      g.__ameliaBridgeLoaded = true;
    })();
  }
  await g.__ameliaBridgeLoadPromise;
}

