function ensurePhaseXXCanonicalBootstrapLoaded(): {
  added: number;
  alreadyPresent: number;
  totalBootstrap: number;
} {
  const bootstrap = getPhaseXXCanonicalBootstrapTraces();
  let added = 0;
  let alreadyPresent = 0;

  for (const trace of bootstrap) {
    const exists = traces().some(
      (t) => t.trajectorySignature === trace.trajectorySignature,
    );
    if (exists) {
      alreadyPresent++;
      continue;
    }
    traces().push(trace);
    added++;
  }
  return { added, alreadyPresent, totalBootstrap: bootstrap.length };
}

async function saveTraces(): Promise<void> {
  await ensureMemoryDir();
  await writeFile(
    MEMORY_FILE,
    JSON.stringify(
      {
        sessionId: SESSION_ID,
        updatedAt: new Date().toISOString(),
        traces: traces(),
      },
      null,
      2,
    ),
    "utf8",
  );
}

async function clearPersistentAndLocalMemory(): Promise<void> {
  await ensureMemoryDir();
  try {
    await rm(MEMORY_FILE, { force: true });
  } catch (error) {
    console.error("Failed to clear persistent memory:", error);
  }
  g.__ameliaBridgeTraces = [];
  g.__ameliaBridgeLoaded = true;
  g.__ameliaBridgeLoadPromise = undefined;
}

