// --- Helpers ---

function hasTraceSignaturePart(part: string): boolean {
  return traces().some((t) => t.trajectorySignature?.includes(part));
}

async function appendTraceIfMissing(trace: Trace): Promise<"ADDED" | "EXISTS"> {
  await ensureTracesLoaded();

  const exists = traces().some(
    (t) => t.trajectorySignature === trace.trajectorySignature,
  );

  if (exists) return "EXISTS";

  traces().push(trace);
  await saveTraces();
  return "ADDED";
}

async function routeD2WriteTrace(label: string, trace: Trace): Promise<string> {
  const status = await appendTraceIfMissing(trace);

  return [
    `BRIDGE ${label}`,
    "",
    `writeStatus: ${status}`,
    `phaseClass: ${trace.phaseClass}`,
    `grammarCandidate: ${trace.grammarCandidate}`,
    `dominantStratum: ${trace.dominantStratum}`,
    `memoryStatus: ${trace.memoryStatus}`,
    `z3z2Weight: ${trace.z3z2Weight}`,
    `z0MeanReturn: ${trace.z0MeanReturn}`,
    `z4MeanReturn: ${trace.z4MeanReturn}`,
    `memoryMode: ${trace.memoryMode}`,
    `trajectorySignature: ${trace.trajectorySignature}`,
    "",
    "pass/fail: PASS",
  ].join("\n");
}

async function arcBTraceAudit(): Promise<string> {
  await ensureTracesLoaded();

  const hasInit = hasTraceSignaturePart(
    "B0_arc-b_independent-configuration-initialized",
  );
  const hasFormation = hasTraceSignaturePart("B1_arc-b_formation");
  const hasLZI = hasTraceSignaturePart("B2_arc-b_lzi-deformation");
  const hasFailure = hasTraceSignaturePart("B3_arc-b_failure-boundary");
  const hasRecovery = hasTraceSignaturePart("B4_arc-b_recovery-boundary");
  const hasTaskTransfer = hasTraceSignaturePart("B5_arc-b_task-transfer");

  const arcBComplete =
    hasInit &&
    hasFormation &&
    hasLZI &&
    hasFailure &&
    hasRecovery &&
    hasTaskTransfer;

  return [
    "BRIDGE ARC B TRACE AUDIT",
    "",
    `hasIndependentInitialization: ${hasInit}`,
    `hasFormation: ${hasFormation}`,
    `hasLZI: ${hasLZI}`,
    `hasFailureBoundary: ${hasFailure}`,
    `hasRecoveryBoundary: ${hasRecovery}`,
    `hasTaskTransfer: ${hasTaskTransfer}`,
    `schemaCompatibleWithArcA: ${arcBComplete}`,
    `arcBComplete: ${arcBComplete}`,
    "",
    arcBComplete
      ? "interpretation: Arc B now constitutes a genuine independent developmental arc with formation, LZI deformation, failure-boundary, recovery-boundary, and task-transfer structure."
      : "interpretation: Arc B is incomplete. Complete all Arc B developmental events before Route D2 injection testing.",
    "",
    `pass/fail: ${arcBComplete ? "PASS" : "FAIL"}`,
  ].join("\n");
}

