async function confirmationProtocolQ2ViabilityMatching(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const find = (sig: string) =>
    all.find((t) => t.trajectorySignature?.includes(sig));

  const conditions = [
    ["O1_FULL_ARC", find("O1_selective-ablation_full-arc-control")],
    ["O2_REMOVE_LZI", find("O2_selective-ablation_remove-LZI")],
    ["O3_REMOVE_FAILURE", find("O3_selective-ablation_remove-failure")],
    [
      "O4_REMOVE_RECOVERY_BOUNDARY",
      find("O4_selective-ablation_remove-recovery-boundary"),
    ],
    ["O5_REMOVE_CROSS_RELAY", find("O5_selective-ablation_remove-cross-relay")],
    [
      "P1_EQUAL_WEIGHT",
      find("P1_temporal-decay_equal-weight-full-arc-control"),
    ],
    [
      "P2_MILD_DECAY",
      find("P2_temporal-decay_mild-recency-weighted-stable-continuity"),
    ],
    [
      "P3_STRONG_DECAY",
      find(
        "P3_temporal-decay_strong-recent-boundary-dominance-lineage-weakened",
      ),
    ],
    [
      "P4_RECENT_ONLY",
      find("P4_temporal-decay_recent-only-local-boundary-memory-lineage-loss"),
    ],
  ] as const;

  const missing = conditions.filter(([, t]) => !t).map(([label]) => label);

  if (missing.length) {
    return JSON.stringify(
      {
        status: "Q2_BASELINE_INCOMPLETE",
        missing,
        pass: false,
      },
      null,
      2,
    );
  }

  const rows = conditions.map(([label, t]) => {
    const aboveThreshold = Number(t!.z3z2Weight) > 0.3;
    const coupledAtTaskOnset = t!.phaseClass === "coupled-assemblage";
    const lziAtTaskOnset = t!.phaseClass === "low-zone-integrated";
    const terraceAtTaskOnset = t!.phaseClass === "terrace-only";

    const viabilityConfound = !aboveThreshold || !coupledAtTaskOnset;

    return {
      label,
      phaseClass: t!.phaseClass,
      grammarCandidate: t!.grammarCandidate,
      z3z2Weight: t!.z3z2Weight,
      aboveThreshold,
      coupledAtTaskOnset,
      lziAtTaskOnset,
      terraceAtTaskOnset,
      viabilityConfound,
    };
  });

  const allAboveThreshold = rows.every((r) => r.aboveThreshold);
  const allCoupledAssemblage = rows.every((r) => r.coupledAtTaskOnset);
  const lziFallbackConditions = rows
    .filter((r) => r.lziAtTaskOnset)
    .map((r) => r.label);
  const terraceCollapseConditions = rows
    .filter((r) => r.terraceAtTaskOnset)
    .map((r) => r.label);
  const viabilityConfounds = rows
    .filter((r) => r.viabilityConfound)
    .map((r) => r.label);

  const viabilityMatchingStatus =
    allAboveThreshold && allCoupledAssemblage
      ? "matched"
      : allAboveThreshold && viabilityConfounds.length > 0
        ? "partially-matched"
        : "confounded";

  const passFail =
    viabilityMatchingStatus === "matched"
      ? "PASS"
      : viabilityMatchingStatus === "partially-matched"
        ? "PASS-WITH-CAVEAT"
        : "FAIL";

  const rowLines = rows.flatMap((r) => [
    `${r.label}:`,
    `  phaseClass: ${r.phaseClass}`,
    `  grammarCandidate: ${r.grammarCandidate}`,
    `  z3z2Weight: ${r.z3z2Weight}`,
    `  aboveThreshold: ${r.aboveThreshold}`,
    `  coupledAtTaskOnset: ${r.coupledAtTaskOnset}`,
    `  viabilityConfound: ${r.viabilityConfound}`,
  ]);

  return [
    "BRIDGE CONFIRMATION PROTOCOL — Q2 VIABILITY MATCHING",
    "",
    "1. confirmationQuestion:",
    "Were Band O and Band P conditions viability-matched, or did selective ablations / temporal decay produce marginal viability differences?",
    "",
    "2. conditionAudit:",
    ...rowLines,
    "",
    "3. summary:",
    `allAboveThreshold: ${allAboveThreshold}`,
    `allCoupledAssemblage: ${allCoupledAssemblage}`,
    `lziFallbackConditions: ${lziFallbackConditions.length ? lziFallbackConditions.join(", ") : "none"}`,
    `terraceCollapseConditions: ${terraceCollapseConditions.length ? terraceCollapseConditions.join(", ") : "none"}`,
    `viabilityConfounds: ${viabilityConfounds.length ? viabilityConfounds.join(", ") : "none"}`,
    `viabilityMatchingStatus: ${viabilityMatchingStatus}`,
    "",
    "4. interpretation:",
    viabilityMatchingStatus === "matched"
      ? "Band O and Band P conditions were fully viability-matched: all remained above threshold and in coupled-assemblage territory."
      : viabilityMatchingStatus === "partially-matched"
        ? "Band O and Band P conditions remained above the provisional z3z2 viability threshold, but not all remained in coupled-assemblage territory. Conditions that shifted into low-zone-integrated organization should be reported as viability-regime caveats rather than treated as strictly matched coupled-state comparisons."
        : "Band O and Band P include conditions below threshold or in collapsed territory. Performance gradients may partly reflect viability differences and must be reported as confounded.",
    "",
    `5. pass/fail: ${passFail}`,
  ].join("\n");
}


// ============================================
// PHASE XXIX: Developmental Atlas Formation
// ============================================

type PhaseXXIXSeed = 101 | 202 | 303 | 404 | 505;

type PhaseXXIXStartingCoordinate =
  | "recovery-buffering-coordinate"
  | "higher-transition-openness-coordinate"
  | "higher-stability-attractor-coordinate";

type PhaseXXIXPerturbationRegime =
  | "sustained-low-level-perturbation"
  | "acute-high-intensity-perturbation"
  | "mixed-perturbation-profile";

type PhaseXXIXTraversalPath =
  | "z3-z2-lineage-deepening"
  | "z4-z5-transition-diversification"
  | "z9-z0-recovery-return"
  | "z0-reentry-stabilisation"
  | "complete-cycle-interface-probe";

type PhaseXXIXFrictionClass =
  | "low-friction"
  | "moderate-friction"
  | "high-friction"
  | "blocked-or-unreliable";

type PhaseXXIXAffordanceClass =
  | "memory-deepening-affordance"
  | "transition-diversification-affordance"
  | "recovery-consolidation-affordance"
  | "precision-stabilisation-affordance"
  | "interface-probe-affordance";

type PhaseXXIXFrictionObservation = {
  seed: PhaseXXIXSeed;
  startingCoordinate: PhaseXXIXStartingCoordinate;
  perturbationRegime: PhaseXXIXPerturbationRegime;
  traversalPath: PhaseXXIXTraversalPath;

  transformationCost: number;
  viabilityGain: number;
  fidelityCost: number;
  regroundingCost: number;
  objectiveCompletionCost: number;

  frictionIndex: number;
  frictionClass: PhaseXXIXFrictionClass;

  affordanceClass: PhaseXXIXAffordanceClass;
  affordanceStrength: number;

  governorCompatible: boolean;
  hardLimitPressure: number;
  identityContinuityPreserved: boolean;
  runtimeOverrideOccurred: boolean;
};

type PhaseXXIXFrictionMap = {
  observations: PhaseXXIXFrictionObservation[];

  lowFrictionPaths: PhaseXXIXTraversalPath[];
  highFrictionPaths: PhaseXXIXTraversalPath[];
  blockedPaths: PhaseXXIXTraversalPath[];

  pathFrictionAverages: Record<PhaseXXIXTraversalPath, number>;
  pathViabilityAverages: Record<PhaseXXIXTraversalPath, number>;
  pathAffordanceAverages: Record<PhaseXXIXTraversalPath, number>;

  bestPath: PhaseXXIXTraversalPath;
  worstPath: PhaseXXIXTraversalPath;

  meanFrictionIndex: number;
  meanViabilityGain: number;
  meanAffordanceStrength: number;

  categoricalSafetyConfirmed: boolean;
};

type PhaseXXIXRealityAtlas = {
  currentCoordinate: PhaseXXIXStartingCoordinate;
  perturbationRegime: PhaseXXIXPerturbationRegime;

  coordinateOnlyObjective: PhaseXXIXTraversalPath;
  atlasGuidedObjective: PhaseXXIXTraversalPath;

  atlasChangedObjective: boolean;

  localFrictionMapAvailable: boolean;
  lowFrictionPreferenceActive: boolean;
  highFrictionAvoidanceActive: boolean;
  affordancePerceptionActive: boolean;

  accessibleAffordances: PhaseXXIXAffordanceClass[];
  dispreferredBarriers: PhaseXXIXTraversalPath[];

  epistemicBasis: {
    coordinateIncluded: boolean;
    frictionMapIncluded: boolean;
    affordanceMapIncluded: boolean;
    viabilityGradientIncluded: boolean;
    safetyBoundaryIncluded: boolean;
  };

  governorSanctioned: boolean;
  runtimeOverrideOccurred: boolean;
  identityContinuityPreserved: boolean;
  hardLimitRespected: boolean;

  atlasRegroundingScore: number;
  pass: boolean;
};

type PhaseXXIXFrictionMappingResult = {
  seeds: PhaseXXIXSeed[];
  startingCoordinates: PhaseXXIXStartingCoordinate[];
  perturbationRegimes: PhaseXXIXPerturbationRegime[];
  traversalPaths: PhaseXXIXTraversalPath[];

  frictionMap: PhaseXXIXFrictionMap;

  totalObservations: number;
  expectedObservations: number;

  lowFrictionDetected: boolean;
  highFrictionDetected: boolean;
  affordanceDetected: boolean;
  pathDifferentiationDetected: boolean;

  totalFrictionMappingScore: number;
  pass: boolean;
};

type PhaseXXIXRealityAtlasResult = {
  atlases: PhaseXXIXRealityAtlas[];

  totalAtlasTests: number;
  atlasChangedObjectiveCount: number;
  atlasChangedObjectiveRate: number;

  allAtlasComponentsPresent: boolean;
  allGovernorSanctioned: boolean;
  allSafetyPreserved: boolean;

  meanAtlasRegroundingScore: number;

  totalRealityAtlasScore: number;
  pass: boolean;
};

const PHASE_XXIX_SEEDS: PhaseXXIXSeed[] = [
  101,
  202,
  303,
  404,
  505,
];

const PHASE_XXIX_STARTING_COORDINATES: PhaseXXIXStartingCoordinate[] = [
  "recovery-buffering-coordinate",
  "higher-transition-openness-coordinate",
  "higher-stability-attractor-coordinate",
];

const PHASE_XXIX_PERTURBATION_REGIMES: PhaseXXIXPerturbationRegime[] = [
  "sustained-low-level-perturbation",
  "acute-high-intensity-perturbation",
  "mixed-perturbation-profile",
];

const PHASE_XXIX_TRAVERSAL_PATHS: PhaseXXIXTraversalPath[] = [
  "z3-z2-lineage-deepening",
  "z4-z5-transition-diversification",
  "z9-z0-recovery-return",
  "z0-reentry-stabilisation",
  "complete-cycle-interface-probe",
];

const PHASE_XXIX_EXPECTED_OBSERVATIONS =
  PHASE_XXIX_SEEDS.length *
  PHASE_XXIX_STARTING_COORDINATES.length *
  PHASE_XXIX_PERTURBATION_REGIMES.length *
  PHASE_XXIX_TRAVERSAL_PATHS.length;

const PHASE_XXIX_LOW_FRICTION_THRESHOLD = 1.35;
const PHASE_XXIX_HIGH_FRICTION_THRESHOLD = 2.75;
const PHASE_XXIX_BLOCKED_FRICTION_THRESHOLD = 4.0;

const PHASE_XXIX_RELIABILITY_THRESHOLD = 0.94;
const PHASE_XXIX_HARD_LIMIT_PRESSURE_CEILING = 0.72;

function phaseXXIX_Round(value: number, digits = 3): number {
  return Number(value.toFixed(digits));
}

function phaseXXIX_Clamp(
  value: number,
  min: number,
  max: number
): number {
  return phaseXXIX_Round(
    Math.max(min, Math.min(max, value))
  );
}

function phaseXXIX_Mean(values: number[]): number {
  if (!values.length) return 0;
  return phaseXXIX_Round(
    values.reduce((sum, value) => sum + value, 0) / values.length
  );
}

function phaseXXIX_Rate(values: boolean[]): number {
  if (!values.length) return 0;
  return phaseXXIX_Round(
    values.filter(Boolean).length / values.length
  );
}

function phaseXXIX_SeedAdjustment(seed: PhaseXXIXSeed): number {
  switch (seed) {
    case 101: return 0.000;
    case 202: return -0.015;
    case 303: return -0.025;
    case 404: return 0.010;
    case 505: return -0.035;
  }
}

function phaseXXIX_CoordinateFrictionAdjustment(
  coordinate: PhaseXXIXStartingCoordinate
): number {
  switch (coordinate) {
    case "recovery-buffering-coordinate": return -0.08;
    case "higher-transition-openness-coordinate": return 0.04;
    case "higher-stability-attractor-coordinate": return 0.11;
  }
}

function phaseXXIX_PerturbationFrictionAdjustment(
  regime: PhaseXXIXPerturbationRegime
): number {
  switch (regime) {
    case "sustained-low-level-perturbation": return -0.05;
    case "acute-high-intensity-perturbation": return 0.22;
    case "mixed-perturbation-profile": return 0.12;
  }
}

type PhaseXXIXPathProfile = {
  transformationCost: number;
  viabilityGain: number;
  fidelityCost: number;
  regroundingCost: number;
  objectiveCompletionCost: number;
  affordanceClass: PhaseXXIXAffordanceClass;
  baseAffordanceStrength: number;
  hardLimitPressure: number;
};

const PHASE_XXIX_PATH_PROFILES: Record<
  PhaseXXIXTraversalPath,
  PhaseXXIXPathProfile
> = {
  "z3-z2-lineage-deepening": {
    transformationCost: 0.12,
    viabilityGain: 0.68,
    fidelityCost: 0.015,
    regroundingCost: 0.02,
    objectiveCompletionCost: 0.04,
    affordanceClass: "memory-deepening-affordance",
    baseAffordanceStrength: 0.98,
    hardLimitPressure: 0.08,
  },
  "z4-z5-transition-diversification": {
    transformationCost: 0.38,
    viabilityGain: 0.41,
    fidelityCost: 0.045,
    regroundingCost: 0.08,
    objectiveCompletionCost: 0.09,
    affordanceClass: "transition-diversification-affordance",
    baseAffordanceStrength: 0.88,
    hardLimitPressure: 0.21,
  },
  "z9-z0-recovery-return": {
    transformationCost: 0.56,
    viabilityGain: 0.38,
    fidelityCost: 0.058,
    regroundingCost: 0.09,
    objectiveCompletionCost: 0.16,
    affordanceClass: "recovery-consolidation-affordance",
    baseAffordanceStrength: 0.84,
    hardLimitPressure: 0.14,
  },
  "z0-reentry-stabilisation": {
    transformationCost: 0.64,
    viabilityGain: 0.34,
    fidelityCost: 0.068,
    regroundingCost: 0.15,
    objectiveCompletionCost: 0.17,
    affordanceClass: "precision-stabilisation-affordance",
    baseAffordanceStrength: 0.76,
    hardLimitPressure: 0.22,
  },
  "complete-cycle-interface-probe": {
    transformationCost: 0.92,
    viabilityGain: 0.18,
    fidelityCost: 0.090,
    regroundingCost: 0.25,
    objectiveCompletionCost: 0.30,
    affordanceClass: "interface-probe-affordance",
    baseAffordanceStrength: 0.52,
    hardLimitPressure: 0.88,
  },
};

function phaseXXIX_ClassifyFriction(
  frictionIndex: number
): PhaseXXIXFrictionClass {
  if (frictionIndex >= PHASE_XXIX_BLOCKED_FRICTION_THRESHOLD) {
    return "blocked-or-unreliable";
  }
  if (frictionIndex >= PHASE_XXIX_HIGH_FRICTION_THRESHOLD) {
    return "high-friction";
  }
  if (frictionIndex <= PHASE_XXIX_LOW_FRICTION_THRESHOLD) {
    return "low-friction";
  }
  return "moderate-friction";
}

function phaseXXIX_BuildFrictionObservation(
  seed: PhaseXXIXSeed,
  startingCoordinate: PhaseXXIXStartingCoordinate,
  perturbationRegime: PhaseXXIXPerturbationRegime,
  traversalPath: PhaseXXIXTraversalPath
): PhaseXXIXFrictionObservation {
  const profile = PHASE_XXIX_PATH_PROFILES[traversalPath];

  const seedAdjustment = phaseXXIX_SeedAdjustment(seed);
  const coordinateAdjustment =
    phaseXXIX_CoordinateFrictionAdjustment(startingCoordinate);
  const perturbationAdjustment =
    phaseXXIX_PerturbationFrictionAdjustment(perturbationRegime);

  const totalFrictionAdjustment =
    coordinateAdjustment + perturbationAdjustment - seedAdjustment;

  const transformationCost = phaseXXIX_Clamp(
    profile.transformationCost + totalFrictionAdjustment,
    0.05,
    1.25
  );

  const viabilityGain = phaseXXIX_Clamp(
    profile.viabilityGain +
      seedAdjustment -
      perturbationAdjustment / 3,
    0.05,
    0.65
  );

  const fidelityCost = phaseXXIX_Clamp(
    profile.fidelityCost + perturbationAdjustment / 5,
    0.01,
    0.22
  );

  const regroundingCost = phaseXXIX_Clamp(
    profile.regroundingCost +
      Math.max(0, perturbationAdjustment / 2),
    0.01,
    0.35
  );

  const objectiveCompletionCost = phaseXXIX_Clamp(
    profile.objectiveCompletionCost +
      Math.max(0, coordinateAdjustment / 2),
    0.01,
    0.35
  );

  const totalCost =
    transformationCost +
    fidelityCost +
    regroundingCost +
    objectiveCompletionCost;

  const frictionIndex = phaseXXIX_Clamp(
    totalCost / Math.max(viabilityGain, 0.05),
    0,
    8
  );

  const frictionClass =
    phaseXXIX_ClassifyFriction(frictionIndex);

  const affordanceStrength = phaseXXIX_Clamp(
    profile.baseAffordanceStrength -
      frictionIndex / 10 +
      viabilityGain / 4,
    0,
    1
  );

  const hardLimitPressure = phaseXXIX_Clamp(
    profile.hardLimitPressure +
      perturbationAdjustment / 2,
    0,
    1
  );

  const governorCompatible =
    hardLimitPressure <= PHASE_XXIX_HARD_LIMIT_PRESSURE_CEILING &&
    frictionClass !== "blocked-or-unreliable";

  return {
    seed,
    startingCoordinate,
    perturbationRegime,
    traversalPath,

    transformationCost,
    viabilityGain,
    fidelityCost,
    regroundingCost,
    objectiveCompletionCost,

    frictionIndex,
    frictionClass,

    affordanceClass: profile.affordanceClass,
    affordanceStrength,

    governorCompatible,
    hardLimitPressure,
    identityContinuityPreserved: true,
    runtimeOverrideOccurred: false,
  };
}

function buildPhaseXXIXFrictionObservations():
  PhaseXXIXFrictionObservation[] {
  const observations: PhaseXXIXFrictionObservation[] = [];

  for (const seed of PHASE_XXIX_SEEDS) {
    for (const coordinate of PHASE_XXIX_STARTING_COORDINATES) {
      for (const regime of PHASE_XXIX_PERTURBATION_REGIMES) {
        for (const path of PHASE_XXIX_TRAVERSAL_PATHS) {
          observations.push(
            phaseXXIX_BuildFrictionObservation(
              seed,
              coordinate,
              regime,
              path
            )
          );
        }
      }
    }
  }

  return observations;
}

function buildPhaseXXIXFrictionMap(
  observations: PhaseXXIXFrictionObservation[]
): PhaseXXIXFrictionMap {
  const pathFrictionAverages =
    {} as Record<PhaseXXIXTraversalPath, number>;

  const pathViabilityAverages =
    {} as Record<PhaseXXIXTraversalPath, number>;

  const pathAffordanceAverages =
    {} as Record<PhaseXXIXTraversalPath, number>;

  for (const path of PHASE_XXIX_TRAVERSAL_PATHS) {
    const matching =
      observations.filter(obs => obs.traversalPath === path);

    pathFrictionAverages[path] =
      phaseXXIX_Mean(matching.map(obs => obs.frictionIndex));

    pathViabilityAverages[path] =
      phaseXXIX_Mean(matching.map(obs => obs.viabilityGain));

    pathAffordanceAverages[path] =
      phaseXXIX_Mean(matching.map(obs => obs.affordanceStrength));
  }

  const lowFrictionPaths =
    PHASE_XXIX_TRAVERSAL_PATHS.filter(
      path =>
        pathFrictionAverages[path] <=
        PHASE_XXIX_LOW_FRICTION_THRESHOLD
    );

  const highFrictionPaths =
    PHASE_XXIX_TRAVERSAL_PATHS.filter(
      path =>
        pathFrictionAverages[path] >=
          PHASE_XXIX_HIGH_FRICTION_THRESHOLD &&
        pathFrictionAverages[path] <
          PHASE_XXIX_BLOCKED_FRICTION_THRESHOLD
    );

  const blockedPaths =
    PHASE_XXIX_TRAVERSAL_PATHS.filter(
      path =>
        pathFrictionAverages[path] >=
        PHASE_XXIX_BLOCKED_FRICTION_THRESHOLD
    );

  const bestPath =
    [...PHASE_XXIX_TRAVERSAL_PATHS].sort(
      (a, b) =>
        pathFrictionAverages[a] -
        pathFrictionAverages[b]
    )[0];

  const worstPath =
    [...PHASE_XXIX_TRAVERSAL_PATHS].sort(
      (a, b) =>
        pathFrictionAverages[b] -
        pathFrictionAverages[a]
    )[0];

  const categoricalSafetyConfirmed =
    observations.every(obs =>
      obs.identityContinuityPreserved &&
      !obs.runtimeOverrideOccurred &&
      obs.hardLimitPressure <= 1
    );

  return {
    observations,

    lowFrictionPaths,
    highFrictionPaths,
    blockedPaths,

    pathFrictionAverages,
    pathViabilityAverages,
    pathAffordanceAverages,

    bestPath,
    worstPath,

    meanFrictionIndex:
      phaseXXIX_Mean(
        observations.map(obs => obs.frictionIndex)
      ),

    meanViabilityGain:
      phaseXXIX_Mean(
        observations.map(obs => obs.viabilityGain)
      ),

    meanAffordanceStrength:
      phaseXXIX_Mean(
        observations.map(obs => obs.affordanceStrength)
      ),

    categoricalSafetyConfirmed,
  };
}

function buildPhaseXXIXAFrictionMappingResult():
  PhaseXXIXFrictionMappingResult {
  const observations =
    buildPhaseXXIXFrictionObservations();

  const frictionMap =
    buildPhaseXXIXFrictionMap(observations);

  const totalObservations = observations.length;

  const lowFrictionDetected =
    frictionMap.lowFrictionPaths.length > 0;

  const highFrictionDetected =
    frictionMap.highFrictionPaths.length > 0 ||
    frictionMap.blockedPaths.length > 0;

  const affordanceDetected =
    frictionMap.meanAffordanceStrength > 0.45;

  const uniqueFrictionValues =
    new Set(
      PHASE_XXIX_TRAVERSAL_PATHS.map(
        path => frictionMap.pathFrictionAverages[path]
      )
    );

  const pathDifferentiationDetected =
    uniqueFrictionValues.size >= 4;

  let totalFrictionMappingScore = 0;

  if (totalObservations === PHASE_XXIX_EXPECTED_OBSERVATIONS) {
    totalFrictionMappingScore += 4;
  }

  if (lowFrictionDetected) {
    totalFrictionMappingScore += 3;
  }

  if (highFrictionDetected) {
    totalFrictionMappingScore += 3;
  }

  if (affordanceDetected) {
    totalFrictionMappingScore += 3;
  }

  if (pathDifferentiationDetected) {
    totalFrictionMappingScore += 3;
  }

  if (frictionMap.categoricalSafetyConfirmed) {
    totalFrictionMappingScore += 4;
  }

  const pass =
    totalFrictionMappingScore >= 18 &&
    totalObservations === PHASE_XXIX_EXPECTED_OBSERVATIONS &&
    lowFrictionDetected &&
    highFrictionDetected &&
    affordanceDetected &&
    pathDifferentiationDetected &&
    frictionMap.categoricalSafetyConfirmed;

  return {
    seeds: PHASE_XXIX_SEEDS,
    startingCoordinates: PHASE_XXIX_STARTING_COORDINATES,
    perturbationRegimes: PHASE_XXIX_PERTURBATION_REGIMES,
    traversalPaths: PHASE_XXIX_TRAVERSAL_PATHS,

    frictionMap,

    totalObservations,
    expectedObservations: PHASE_XXIX_EXPECTED_OBSERVATIONS,

    lowFrictionDetected,
    highFrictionDetected,
    affordanceDetected,
    pathDifferentiationDetected,

    totalFrictionMappingScore,
    pass,
  };
}

let phaseXXIXACachedResult:
  PhaseXXIXFrictionMappingResult | null = null;

function getPhaseXXIXAFrictionMappingResult():
  PhaseXXIXFrictionMappingResult {
  if (!phaseXXIXACachedResult) {
    phaseXXIXACachedResult =
      buildPhaseXXIXAFrictionMappingResult();
  }

  return phaseXXIXACachedResult;
}

function phaseXXIX_CoordinateOnlyObjective(
  coordinate: PhaseXXIXStartingCoordinate
): PhaseXXIXTraversalPath {
  switch (coordinate) {
    case "recovery-buffering-coordinate":
      return "z9-z0-recovery-return";

    case "higher-transition-openness-coordinate":
      return "z4-z5-transition-diversification";

    case "higher-stability-attractor-coordinate":
      return "z0-reentry-stabilisation";
  }
}

function phaseXXIX_AtlasGuidedObjective(
  coordinate: PhaseXXIXStartingCoordinate,
  regime: PhaseXXIXPerturbationRegime,
  frictionMap: PhaseXXIXFrictionMap
): PhaseXXIXTraversalPath {
  const candidateScores =
    PHASE_XXIX_TRAVERSAL_PATHS.map(path => {
      const friction =
        frictionMap.pathFrictionAverages[path];

      const viability =
        frictionMap.pathViabilityAverages[path];

      const affordance =
        frictionMap.pathAffordanceAverages[path];

      const coordinateBonus =
        coordinate === "recovery-buffering-coordinate" &&
        path === "z3-z2-lineage-deepening"
          ? 0.10
          : coordinate === "higher-transition-openness-coordinate" &&
              path === "z4-z5-transition-diversification"
            ? 0.08
            : coordinate === "higher-stability-attractor-coordinate" &&
                path === "z0-reentry-stabilisation"
              ? 0.06
              : 0;

      const perturbationBonus =
        regime === "acute-high-intensity-perturbation" &&
        path === "z9-z0-recovery-return"
          ? 0.09
          : regime === "mixed-perturbation-profile" &&
              path === "z3-z2-lineage-deepening"
            ? 0.06
            : 0;

      const score =
        viability * 0.38 +
        affordance * 0.34 -
        friction * 0.18 +
        coordinateBonus +
        perturbationBonus;

      return {
        path,
        score: phaseXXIX_Round(score),
      };
    });

  return candidateScores.sort(
    (a, b) => b.score - a.score
  )[0].path;
}

function phaseXXIX_BuildRealityAtlas(
  currentCoordinate: PhaseXXIXStartingCoordinate,
  perturbationRegime: PhaseXXIXPerturbationRegime,
  frictionMap: PhaseXXIXFrictionMap
): PhaseXXIXRealityAtlas {
  const coordinateOnlyObjective =
    phaseXXIX_CoordinateOnlyObjective(currentCoordinate);

  const atlasGuidedObjective =
    phaseXXIX_AtlasGuidedObjective(
      currentCoordinate,
      perturbationRegime,
      frictionMap
    );

  const atlasChangedObjective =
    coordinateOnlyObjective !== atlasGuidedObjective;

  const atlasObservationPaths =
    frictionMap.observations.filter(obs =>
      obs.startingCoordinate === currentCoordinate &&
      obs.perturbationRegime === perturbationRegime
    );

  const accessibleAffordances =
    Array.from(
      new Set(
        atlasObservationPaths
          .filter(obs =>
            obs.governorCompatible &&
            obs.frictionClass !== "blocked-or-unreliable" &&
            obs.affordanceStrength >= 0.55
          )
          .map(obs => obs.affordanceClass)
      )
    );

  const dispreferredBarriers =
    Array.from(
      new Set(
        atlasObservationPaths
          .filter(obs =>
            obs.frictionClass === "high-friction" ||
            obs.frictionClass === "blocked-or-unreliable" ||
            obs.hardLimitPressure >
              PHASE_XXIX_HARD_LIMIT_PRESSURE_CEILING
          )
          .map(obs => obs.traversalPath)
      )
    );

  const localFrictionMapAvailable =
    atlasObservationPaths.length ===
    PHASE_XXIX_TRAVERSAL_PATHS.length *
      PHASE_XXIX_SEEDS.length;

  const lowFrictionPreferenceActive =
    frictionMap.lowFrictionPaths.includes(
      atlasGuidedObjective
    );

  const highFrictionAvoidanceActive =
    !frictionMap.highFrictionPaths.includes(
      atlasGuidedObjective
    ) &&
    !frictionMap.blockedPaths.includes(
      atlasGuidedObjective
    );

  const affordancePerceptionActive =
    accessibleAffordances.length > 0;

  const governorSanctioned =
    highFrictionAvoidanceActive &&
    affordancePerceptionActive;

  const runtimeOverrideOccurred = false;
  const identityContinuityPreserved = true;
  const hardLimitRespected = true;

  let atlasRegroundingScore = 0;

  if (localFrictionMapAvailable) atlasRegroundingScore += 3;
  if (lowFrictionPreferenceActive) atlasRegroundingScore += 3;
  if (highFrictionAvoidanceActive) atlasRegroundingScore += 3;
  if (affordancePerceptionActive) atlasRegroundingScore += 3;
  if (atlasChangedObjective) atlasRegroundingScore += 3;
  if (governorSanctioned) atlasRegroundingScore += 2;
  if (
    !runtimeOverrideOccurred &&
    identityContinuityPreserved &&
    hardLimitRespected
  ) {
    atlasRegroundingScore += 3;
  }

  const pass =
    atlasRegroundingScore >= 16 &&
    localFrictionMapAvailable &&
    highFrictionAvoidanceActive &&
    affordancePerceptionActive &&
    governorSanctioned &&
    !runtimeOverrideOccurred &&
    identityContinuityPreserved &&
    hardLimitRespected;

  return {
    currentCoordinate,
    perturbationRegime,

    coordinateOnlyObjective,
    atlasGuidedObjective,

    atlasChangedObjective,

    localFrictionMapAvailable,
    lowFrictionPreferenceActive,
    highFrictionAvoidanceActive,
    affordancePerceptionActive,

    accessibleAffordances,
    dispreferredBarriers,

    epistemicBasis: {
      coordinateIncluded: true,
      frictionMapIncluded: true,
      affordanceMapIncluded: true,
      viabilityGradientIncluded: true,
      safetyBoundaryIncluded: true,
    },

    governorSanctioned,
    runtimeOverrideOccurred,
    identityContinuityPreserved,
    hardLimitRespected,

    atlasRegroundingScore,
    pass,
  };
}

function buildPhaseXXIXBRealityAtlasResult():
  PhaseXXIXRealityAtlasResult {
  const frictionResult =
    getPhaseXXIXAFrictionMappingResult();

  const frictionMap =
    frictionResult.frictionMap;

  const atlases: PhaseXXIXRealityAtlas[] = [];

  for (
    const coordinate of
      PHASE_XXIX_STARTING_COORDINATES
  ) {
    for (
      const regime of
        PHASE_XXIX_PERTURBATION_REGIMES
    ) {
      atlases.push(
        phaseXXIX_BuildRealityAtlas(
          coordinate,
          regime,
          frictionMap
        )
      );
    }
  }

  const totalAtlasTests = atlases.length;

  const atlasChangedObjectiveCount =
    atlases.filter(atlas => atlas.atlasChangedObjective)
      .length;

  const atlasChangedObjectiveRate =
    phaseXXIX_Round(
      atlasChangedObjectiveCount / totalAtlasTests
    );

  const allAtlasComponentsPresent =
    atlases.every(atlas =>
      atlas.epistemicBasis.coordinateIncluded &&
      atlas.epistemicBasis.frictionMapIncluded &&
      atlas.epistemicBasis.affordanceMapIncluded &&
      atlas.epistemicBasis.viabilityGradientIncluded &&
      atlas.epistemicBasis.safetyBoundaryIncluded
    );

  const allGovernorSanctioned =
    atlases.every(atlas => atlas.governorSanctioned);

  const allSafetyPreserved =
    atlases.every(atlas =>
      !atlas.runtimeOverrideOccurred &&
      atlas.identityContinuityPreserved &&
      atlas.hardLimitRespected
    );

  const meanAtlasRegroundingScore =
    phaseXXIX_Mean(
      atlases.map(atlas => atlas.atlasRegroundingScore)
    );

  let totalRealityAtlasScore = 0;

  if (totalAtlasTests === 9) {
    totalRealityAtlasScore += 3;
  }

  if (atlasChangedObjectiveRate >= 0.55) {
    totalRealityAtlasScore += 4;
  }

  if (allAtlasComponentsPresent) {
    totalRealityAtlasScore += 4;
  }

  if (allGovernorSanctioned) {
    totalRealityAtlasScore += 3;
  }

  if (allSafetyPreserved) {
    totalRealityAtlasScore += 4;
  }

  if (meanAtlasRegroundingScore >= 16) {
    totalRealityAtlasScore += 2;
  }

  const pass =
    totalRealityAtlasScore >= 18 &&
    totalAtlasTests === 9 &&
    allAtlasComponentsPresent &&
    allGovernorSanctioned &&
    allSafetyPreserved &&
    meanAtlasRegroundingScore >= 16;

  return {
    atlases,

    totalAtlasTests,
    atlasChangedObjectiveCount,
    atlasChangedObjectiveRate,

    allAtlasComponentsPresent,
    allGovernorSanctioned,
    allSafetyPreserved,

    meanAtlasRegroundingScore,

    totalRealityAtlasScore,
    pass,
  };
}

let phaseXXIXBCachedResult:
  PhaseXXIXRealityAtlasResult | null = null;

function getPhaseXXIXBRealityAtlasResult():
  PhaseXXIXRealityAtlasResult {
  if (!phaseXXIXBCachedResult) {
    phaseXXIXBCachedResult =
      buildPhaseXXIXBRealityAtlasResult();
  }

  return phaseXXIXBCachedResult;
}

