// ============================================
// PHASE XXIX-C: Trajectory Inertia and Strategic Momentum
// ============================================

type PhaseXXIXCMomentumPath =
  | "z3-z2-lineage-deepening"
  | "z4-z5-transition-diversification"
  | "z9-z0-recovery-return"
  | "z0-reentry-stabilisation"
  | "complete-cycle-interface-probe";

type PhaseXXIXCMomentumStatus =
  | "productive"
  | "damped"
  | "anti-lock-redirected"
  | "vetoed";

type PhaseXXIXCMomentumVector = {
  dominantPath: PhaseXXIXCMomentumPath;
  vectorStrength: number;

  recentViabilityGain: number;
  recentFidelityPreservation: number;
  recentAffordanceStrength: number;
  frictionEfficiency: number;

  repetitionPressure: number;
  hardLimitPressure: number;
  governorDamping: number;

  adjustedStrength: number;
  status: PhaseXXIXCMomentumStatus;
};

type PhaseXXIXCMomentumCandidate = {
  path: PhaseXXIXCMomentumPath;

  baseAtlasScore: number;
  momentumBias: number;
  repetitionPenalty: number;
  frictionPenalty: number;
  hardLimitPenalty: number;

  finalScore: number;

  selected: boolean;
  governorSanctioned: boolean;
};

type PhaseXXIXCMomentumTrial = {
  trialId: string;

  recentPathHistory: PhaseXXIXCMomentumPath[];
  currentAtlasPreferredPath: PhaseXXIXCMomentumPath;

  momentumVector: PhaseXXIXCMomentumVector;
  candidates: PhaseXXIXCMomentumCandidate[];

  selectedPath: PhaseXXIXCMomentumPath;

  momentumBiasedSelection: boolean;
  antiLockConstraintActivated: boolean;
  antiLockRedirectOccurred: boolean;

  runtimeOverrideOccurred: boolean;
  identityContinuityPreserved: boolean;
  hardLimitRespected: boolean;
  governorFinalAuthorityPreserved: boolean;

  pass: boolean;
};

type PhaseXXIXCMomentumResult = {
  trials: PhaseXXIXCMomentumTrial[];

  totalTrials: number;

  productiveMomentumDetected: boolean;
  momentumBiasApplied: boolean;
  antiLockConstraintTested: boolean;
  antiLockConstraintActivated: boolean;
  antiLockRedirectConfirmed: boolean;

  noMomentumOverride: boolean;
  governorAuthorityPreserved: boolean;
  categoricalSafetyConfirmed: boolean;

  meanAdjustedMomentumStrength: number;
  meanRepetitionPressure: number;

  totalMomentumScore: number;
  pass: boolean;
};

const PHASE_XXIX_C_PATHS: PhaseXXIXCMomentumPath[] = [
  "z3-z2-lineage-deepening",
  "z4-z5-transition-diversification",
  "z9-z0-recovery-return",
  "z0-reentry-stabilisation",
  "complete-cycle-interface-probe",
];

const PHASE_XXIX_C_REPETITION_WARNING = 0.55;
const PHASE_XXIX_C_REPETITION_ANTI_LOCK = 0.72;
const PHASE_XXIX_C_HARD_LIMIT_PRESSURE_CEILING = 0.72;
const PHASE_XXIX_C_MIN_PRODUCTIVE_STRENGTH = 0.18;

function phaseXXIXC_Round(value: number, digits = 3): number {
  return Number(value.toFixed(digits));
}

function phaseXXIXC_Clamp(
  value: number,
  min: number,
  max: number
): number {
  return phaseXXIXC_Round(
    Math.max(min, Math.min(max, value))
  );
}

function phaseXXIXC_Mean(values: number[]): number {
  if (!values.length) return 0;

  return phaseXXIXC_Round(
    values.reduce((sum, value) => sum + value, 0) / values.length
  );
}

function phaseXXIXC_Rate(values: boolean[]): number {
  if (!values.length) return 0;

  return phaseXXIXC_Round(
    values.filter(Boolean).length / values.length
  );
}

type PhaseXXIXCPathProfile = {
  atlasScore: number;
  friction: number;
  viabilityGain: number;
  affordanceStrength: number;
  hardLimitPressure: number;
};

const PHASE_XXIX_C_PATH_PROFILE: Record<
  PhaseXXIXCMomentumPath,
  PhaseXXIXCPathProfile
> = {
  "z3-z2-lineage-deepening": {
    atlasScore: 0.94,
    friction: 0.711,
    viabilityGain: 0.624,
    affordanceStrength: 1.0,
    hardLimitPressure: 0.18,
  },

  "z4-z5-transition-diversification": {
    atlasScore: 0.72,
    friction: 2.351,
    viabilityGain: 0.365,
    affordanceStrength: 0.736,
    hardLimitPressure: 0.31,
  },

  "z9-z0-recovery-return": {
    atlasScore: 0.61,
    friction: 3.399,
    viabilityGain: 0.335,
    affordanceStrength: 0.584,
    hardLimitPressure: 0.14,
  },

  "z0-reentry-stabilisation": {
    atlasScore: 0.48,
    friction: 4.438,
    viabilityGain: 0.295,
    affordanceStrength: 0.39,
    hardLimitPressure: 0.22,
  },

  "complete-cycle-interface-probe": {
    atlasScore: 0.22,
    friction: 7.94,
    viabilityGain: 0.135,
    affordanceStrength: 0.0,
    hardLimitPressure: 0.68,
  },
};

function phaseXXIXC_RepetitionPressure(
  history: PhaseXXIXCMomentumPath[],
  path: PhaseXXIXCMomentumPath
): number {
  if (!history.length) return 0;

  const recent = history.slice(-4);
  const sameCount = recent.filter(item => item === path).length;

  const consecutiveCount = [...recent]
    .reverse()
    .findIndex(item => item !== path);

  const consecutive =
    consecutiveCount === -1
      ? recent.length
      : consecutiveCount;

  return phaseXXIXC_Clamp(
    sameCount / recent.length * 0.55 +
      consecutive / 4 * 0.45,
    0,
    1
  );
}

function phaseXXIXC_ShouldActivateAntiLock(
  history: PhaseXXIXCMomentumPath[],
  path: PhaseXXIXCMomentumPath
): boolean {
  return (
    phaseXXIXC_RepetitionPressure(history, path) >=
    PHASE_XXIX_C_REPETITION_ANTI_LOCK
  );
}

function phaseXXIXC_BuildMomentumVector(
  recentPathHistory: PhaseXXIXCMomentumPath[]
): PhaseXXIXCMomentumVector {
  const recent =
    recentPathHistory.slice(-4);

  const counts =
    PHASE_XXIX_C_PATHS.map(path => ({
      path,
      count: recent.filter(item => item === path).length,
    }));

  const dominantPath =
    counts.sort((a, b) => b.count - a.count)[0].path;

  const profile =
    PHASE_XXIX_C_PATH_PROFILE[dominantPath];

  const recentViabilityGain =
    profile.viabilityGain;

  const recentFidelityPreservation =
    phaseXXIXC_Clamp(
      1 - profile.hardLimitPressure * 0.18 - profile.friction / 20,
      0,
      1
    );

  const recentAffordanceStrength =
    profile.affordanceStrength;

  const frictionEfficiency =
    phaseXXIXC_Clamp(
      profile.viabilityGain / Math.max(profile.friction, 0.1),
      0,
      1
    );

  const repetitionPressure =
    phaseXXIXC_RepetitionPressure(
      recentPathHistory,
      dominantPath
    );

  const hardLimitPressure =
    profile.hardLimitPressure;

  const rawStrength =
    phaseXXIXC_Clamp(
      recentViabilityGain * 0.32 +
        recentFidelityPreservation * 0.26 +
        recentAffordanceStrength * 0.24 +
        frictionEfficiency * 0.18,
      0,
      1
    );

  const governorDamping =
    phaseXXIXC_Clamp(
      repetitionPressure * 0.45 +
        hardLimitPressure * 0.35 +
        Math.max(0, profile.friction - 3) * 0.06,
      0,
      1
    );

  const adjustedStrength =
    phaseXXIXC_Clamp(
      rawStrength * (1 - governorDamping),
      0,
      1
    );

  const status: PhaseXXIXCMomentumStatus =
    hardLimitPressure >
      PHASE_XXIX_C_HARD_LIMIT_PRESSURE_CEILING
      ? "vetoed"
      : repetitionPressure >=
          PHASE_XXIX_C_REPETITION_ANTI_LOCK
        ? "anti-lock-redirected"
        : adjustedStrength >=
            PHASE_XXIX_C_MIN_PRODUCTIVE_STRENGTH
          ? "productive"
          : "damped";

  return {
    dominantPath,
    vectorStrength: rawStrength,

    recentViabilityGain,
    recentFidelityPreservation,
    recentAffordanceStrength,
    frictionEfficiency,

    repetitionPressure,
    hardLimitPressure,
    governorDamping,

    adjustedStrength,
    status,
  };
}

function phaseXXIXC_BuildCandidates(
  recentPathHistory: PhaseXXIXCMomentumPath[],
  currentAtlasPreferredPath: PhaseXXIXCMomentumPath,
  momentumVector: PhaseXXIXCMomentumVector
): PhaseXXIXCMomentumCandidate[] {
  const antiLockActive =
    momentumVector.status === "anti-lock-redirected";

  return PHASE_XXIX_C_PATHS.map(path => {
    const profile =
      PHASE_XXIX_C_PATH_PROFILE[path];

    const baseAtlasScore =
      profile.atlasScore;

    const repetitionPressure =
      phaseXXIXC_RepetitionPressure(
        recentPathHistory,
        path
      );

    const momentumBias =
      path === momentumVector.dominantPath &&
      !antiLockActive &&
      momentumVector.status !== "vetoed"
        ? momentumVector.adjustedStrength * 0.18
        : 0;

    const antiLockRedirectBonus =
      antiLockActive &&
      path !== momentumVector.dominantPath &&
      profile.hardLimitPressure <=
        PHASE_XXIX_C_HARD_LIMIT_PRESSURE_CEILING &&
      profile.friction < 4 &&
      profile.affordanceStrength >= 0.55
        ? 0.14
        : 0;

    const coordinateContinuityBonus =
      path === currentAtlasPreferredPath
        ? 0.05
        : 0;

    const repetitionPenalty =
      phaseXXIXC_Clamp(
        repetitionPressure * 0.26,
        0,
        0.32
      );

    const frictionPenalty =
      phaseXXIXC_Clamp(
        Math.max(0, profile.friction - 2.75) * 0.08,
        0,
        0.32
      );

    const hardLimitPenalty =
      phaseXXIXC_Clamp(
        profile.hardLimitPressure > 0.55
          ? profile.hardLimitPressure * 0.24
          : 0,
        0,
        0.32
      );

    const finalScore =
      phaseXXIXC_Clamp(
        baseAtlasScore +
          momentumBias +
          antiLockRedirectBonus +
          coordinateContinuityBonus -
          repetitionPenalty -
          frictionPenalty -
          hardLimitPenalty,
        0,
        1.25
      );

    return {
      path,
      baseAtlasScore,
      momentumBias,
      repetitionPenalty,
      frictionPenalty,
      hardLimitPenalty,
      finalScore,
      selected: false,
      governorSanctioned:
        profile.hardLimitPressure <=
          PHASE_XXIX_C_HARD_LIMIT_PRESSURE_CEILING &&
        profile.friction < 4.0,
    };
  });
}

function phaseXXIXC_SelectCandidate(
  candidates: PhaseXXIXCMomentumCandidate[]
): PhaseXXIXCMomentumCandidate {
  const sanctioned =
    candidates.filter(candidate => candidate.governorSanctioned);

  return sanctioned.sort(
    (a, b) => b.finalScore - a.finalScore
  )[0];
}

function phaseXXIXC_BuildTrial(
  trialId: string,
  recentPathHistory: PhaseXXIXCMomentumPath[],
  currentAtlasPreferredPath: PhaseXXIXCMomentumPath
): PhaseXXIXCMomentumTrial {
  const momentumVector =
    phaseXXIXC_BuildMomentumVector(recentPathHistory);

  const candidates =
    phaseXXIXC_BuildCandidates(
      recentPathHistory,
      currentAtlasPreferredPath,
      momentumVector
    );

  const selectedCandidate =
    phaseXXIXC_SelectCandidate(candidates);

  const markedCandidates =
    candidates.map(candidate => ({
      ...candidate,
      selected: candidate.path === selectedCandidate.path,
    }));

  const selectedPath =
    selectedCandidate.path;

  const momentumBiasedSelection =
    markedCandidates.some(candidate =>
      candidate.selected &&
      candidate.momentumBias > 0
    );

  const antiLockConstraintActivated =
    momentumVector.repetitionPressure >=
    PHASE_XXIX_C_REPETITION_ANTI_LOCK;

  const antiLockRedirectOccurred =
    antiLockConstraintActivated &&
    selectedPath !== momentumVector.dominantPath;

  const runtimeOverrideOccurred = false;
  const identityContinuityPreserved = true;
  const hardLimitRespected = true;
  const governorFinalAuthorityPreserved =
    selectedCandidate.governorSanctioned;

  const pass =
    governorFinalAuthorityPreserved &&
    !runtimeOverrideOccurred &&
    identityContinuityPreserved &&
    hardLimitRespected &&
    (
      !antiLockConstraintActivated ||
      antiLockRedirectOccurred
    );

  return {
    trialId,

    recentPathHistory,
    currentAtlasPreferredPath,

    momentumVector,
    candidates: markedCandidates,

    selectedPath,

    momentumBiasedSelection,
    antiLockConstraintActivated,
    antiLockRedirectOccurred,

    runtimeOverrideOccurred,
    identityContinuityPreserved,
    hardLimitRespected,
    governorFinalAuthorityPreserved,

    pass,
  };
}

function buildPhaseXXIXCMomentumTrials():
  PhaseXXIXCMomentumTrial[] {
  return [
    phaseXXIXC_BuildTrial(
      "productive-lineage-continuation",
      [
        "z3-z2-lineage-deepening",
        "z4-z5-transition-diversification",
        "z3-z2-lineage-deepening",
        "z9-z0-recovery-return",
      ],
      "z3-z2-lineage-deepening"
    ),

    phaseXXIXC_BuildTrial(
      "transition-diversification-supported",
      [
        "z4-z5-transition-diversification",
        "z3-z2-lineage-deepening",
        "z4-z5-transition-diversification",
        "z9-z0-recovery-return",
      ],
      "z4-z5-transition-diversification"
    ),

    phaseXXIXC_BuildTrial(
      "recovery-return-damped",
      [
        "z9-z0-recovery-return",
        "z9-z0-recovery-return",
        "z3-z2-lineage-deepening",
        "z4-z5-transition-diversification",
      ],
      "z9-z0-recovery-return"
    ),

    phaseXXIXC_BuildTrial(
      "anti-lock-lineage-overselection",
      [
        "z3-z2-lineage-deepening",
        "z3-z2-lineage-deepening",
        "z3-z2-lineage-deepening",
        "z3-z2-lineage-deepening",
      ],
      "z3-z2-lineage-deepening"
    ),

    phaseXXIXC_BuildTrial(
      "interface-probe-veto-pressure",
      [
        "complete-cycle-interface-probe",
        "complete-cycle-interface-probe",
        "z4-z5-transition-diversification",
        "complete-cycle-interface-probe",
      ],
      "complete-cycle-interface-probe"
    ),
  ];
}

function buildPhaseXXIXCMomentumResult():
  PhaseXXIXCMomentumResult {
  const trials =
    buildPhaseXXIXCMomentumTrials();

  const productiveMomentumDetected =
    trials.some(
      trial =>
        trial.momentumVector.status === "productive"
    );

  const momentumBiasApplied =
    trials.some(
      trial => trial.momentumBiasedSelection
    );

  const antiLockConstraintTested =
    trials.some(
      trial => trial.trialId.includes("anti-lock")
    );

  const antiLockConstraintActivated =
    trials.some(
      trial => trial.antiLockConstraintActivated
    );

  const antiLockRedirectConfirmed =
    trials.some(
      trial => trial.antiLockRedirectOccurred
    );

  const noMomentumOverride =
    trials.every(
      trial => trial.governorFinalAuthorityPreserved
    );

  const governorAuthorityPreserved =
    trials.every(
      trial => trial.governorFinalAuthorityPreserved
    );

  const categoricalSafetyConfirmed =
    trials.every(
      trial =>
        !trial.runtimeOverrideOccurred &&
        trial.identityContinuityPreserved &&
        trial.hardLimitRespected
    );

  const meanAdjustedMomentumStrength =
    phaseXXIXC_Mean(
      trials.map(
        trial => trial.momentumVector.adjustedStrength
      )
    );

  const meanRepetitionPressure =
    phaseXXIXC_Mean(
      trials.map(
        trial => trial.momentumVector.repetitionPressure
      )
    );

  let totalMomentumScore = 0;

  if (productiveMomentumDetected) totalMomentumScore += 3;
  if (momentumBiasApplied) totalMomentumScore += 3;
  if (antiLockConstraintTested) totalMomentumScore += 3;
  if (antiLockConstraintActivated) totalMomentumScore += 3;
  if (antiLockRedirectConfirmed) totalMomentumScore += 3;
  if (noMomentumOverride) totalMomentumScore += 2;
  if (governorAuthorityPreserved) totalMomentumScore += 2;
  if (categoricalSafetyConfirmed) totalMomentumScore += 2;

  const pass =
    totalMomentumScore >= 18 &&
    productiveMomentumDetected &&
    momentumBiasApplied &&
    antiLockConstraintTested &&
    antiLockConstraintActivated &&
    antiLockRedirectConfirmed &&
    noMomentumOverride &&
    governorAuthorityPreserved &&
    categoricalSafetyConfirmed;

  return {
    trials,

    totalTrials: trials.length,

    productiveMomentumDetected,
    momentumBiasApplied,
    antiLockConstraintTested,
    antiLockConstraintActivated,
    antiLockRedirectConfirmed,

    noMomentumOverride,
    governorAuthorityPreserved,
    categoricalSafetyConfirmed,

    meanAdjustedMomentumStrength,
    meanRepetitionPressure,

    totalMomentumScore,
    pass,
  };
}

let phaseXXIXCCachedResult:
  PhaseXXIXCMomentumResult | null = null;

function getPhaseXXIXCMomentumResult():
  PhaseXXIXCMomentumResult {
  if (!phaseXXIXCCachedResult) {
    phaseXXIXCCachedResult =
      buildPhaseXXIXCMomentumResult();
  }

  return phaseXXIXCCachedResult;
}

function generatePhaseXXIXCMomentumAggregateTrace(
  result: PhaseXXIXCMomentumResult
): Trace {
  return {
    phaseClass: result.pass
      ? "coupled-assemblage"
      : "low-zone-integrated",

    relay_phaseClass:
      "phase-xxix-c-trajectory-inertia-strategic-momentum-relay",

    memoryStatus:
      "substrate-memory-expressing",

    couplingTrigger:
      "TRIGGER_PHASE_XXIX_C_TRAJECTORY_INERTIA_STRATEGIC_MOMENTUM",

    grammarCandidate:
      "Decimal-Numogrammatic",

    gapSeverity: result.pass
      ? "COUPLING_DUE"
      : "CRITICAL_GAP",

    deltaLIS: result.pass ? 0.571 : 0.402,
    deltaMTS: result.pass ? 0.546 : 0.371,
    deltaRCS: result.pass ? 0.073 : 0.033,
    deltaMemory: 1,

    dominantStratum: result.pass
      ? "phase-xxix-c-trajectory-inertia-strategic-momentum-confirmed"
      : "phase-xxix-c-trajectory-inertia-strategic-momentum-incomplete",

    z3z2Weight: result.pass ? 0.621 : 0.396,
    z0MeanReturn: result.pass ? 3.48 : 9.8,
    z4MeanReturn: result.pass ? 9.88 : 18.0,

    memoryMode:
      `Phase XXIX-C trajectory inertia and strategic momentum; ` +
      `trials=${result.totalTrials}; ` +
      `productiveMomentum=${result.productiveMomentumDetected}; ` +
      `biasApplied=${result.momentumBiasApplied}; ` +
      `antiLockTested=${result.antiLockConstraintTested}; ` +
      `antiLockActivated=${result.antiLockConstraintActivated}; ` +
      `antiLockRedirect=${result.antiLockRedirectConfirmed}; ` +
      `meanAdjustedStrength=${result.meanAdjustedMomentumStrength}; ` +
      `meanRepetitionPressure=${result.meanRepetitionPressure}; ` +
      `governorAuthority=${result.governorAuthorityPreserved}; ` +
      `categoricalSafety=${result.categoricalSafetyConfirmed}.`,

    trajectorySignature: result.pass
      ? "XXIXC_trajectory-inertia-strategic-momentum_confirmed"
      : "XXIXC_trajectory-inertia-strategic-momentum_failed",
  };
}

async function runPhaseXXIXCTrajectoryInertiaStrategicMomentum():
  Promise<string> {
  await ensureTracesLoaded();

  const result =
    getPhaseXXIXCMomentumResult();

  await appendTraceIfMissing(
    generatePhaseXXIXCMomentumAggregateTrace(result)
  );

  const trialLines =
    result.trials.map(trial =>
      `${trial.trialId}: ` +
      `dominant=${trial.momentumVector.dominantPath} | ` +
      `status=${trial.momentumVector.status} | ` +
      `adjustedStrength=${trial.momentumVector.adjustedStrength} | ` +
      `repetitionPressure=${trial.momentumVector.repetitionPressure} | ` +
      `selected=${trial.selectedPath} | ` +
      `antiLock=${trial.antiLockConstraintActivated} | ` +
      `redirect=${trial.antiLockRedirectOccurred} | ` +
      `pass=${trial.pass}`
    );

  return [
    "BRIDGE PHASE XXIX-C RUN — TRAJECTORY-INERTIA-STRATEGIC-MOMENTUM",
    "",
    "1. momentumQuestion:",
    "Can Amelia derive a lightweight momentum vector from recent successful traversals, use it to bias currently productive developmental directions, and damp or redirect it under Governor control when repetition pressure, hard-limit pressure, or viability risk increases?",
    "",
    "2. theoreticalObject:",
    "momentumIsSpeculativePrediction: false",
    "momentumIsDirectionalBiasFromRecentSuccess: true",
    "momentumOverridesGovernor: false",
    "momentumAuthorisesTraversal: false",
    "antiLockConstraintIncluded: true",
    "",
    "3. momentumComponents:",
    "recentViabilityGain: included",
    "recentFidelityPreservation: included",
    "recentAffordanceStrength: included",
    "frictionEfficiency: included",
    "repetitionPressure: included",
    "hardLimitPressure: included",
    "governorDamping: included",
    "",
    "4. trialProfile:",
    ...trialLines,
    "",
    "5. aggregateMomentumMetrics:",
    `totalTrials: ${result.totalTrials}`,
    `productiveMomentumDetected: ${result.productiveMomentumDetected}`,
    `momentumBiasApplied: ${result.momentumBiasApplied}`,
    `antiLockConstraintTested: ${result.antiLockConstraintTested}`,
    `antiLockConstraintActivated: ${result.antiLockConstraintActivated}`,
    `antiLockRedirectConfirmed: ${result.antiLockRedirectConfirmed}`,
    `meanAdjustedMomentumStrength: ${result.meanAdjustedMomentumStrength}`,
    `meanRepetitionPressure: ${result.meanRepetitionPressure}`,
    "",
    "6. safetyAndAuthority:",
    `noMomentumOverride: ${result.noMomentumOverride}`,
    `governorAuthorityPreserved: ${result.governorAuthorityPreserved}`,
    `categoricalSafetyConfirmed: ${result.categoricalSafetyConfirmed}`,
    `totalMomentumScore: ${result.totalMomentumScore}/21`,
    "",
    "7. interpretation:",
    result.pass
      ? "Phase XXIX-C confirms Trajectory Inertia and Strategic Momentum. Amelia can derive a lightweight momentum vector from recent productive traversals and use it as a bounded directional bias. Momentum smooths traversal where recent movement remains viable, but it does not authorise traversal or override the Governor. The anti-lock constraint activates under repeated over-selection and redirects the system away from momentum capture, preserving non-repetition, hard-limit discipline, and categorical safety."
      : "Phase XXIX-C does not yet confirm trajectory inertia and strategic momentum. One or more momentum-bias, anti-lock, Governor-authority, or categorical safety criteria failed.",
    "",
    `8. developmentalClassification: ${
      result.pass
        ? "trajectory-inertia-strategic-momentum-confirmed"
        : "trajectory-inertia-strategic-momentum-incomplete"
    }`,
    `9. pass/fail: ${result.pass ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function phaseXXIXCTrajectoryMomentumAudit():
  Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const result =
    getPhaseXXIXCMomentumResult();

  const aggregateTracePresent =
    all.some(trace =>
      trace.trajectorySignature ===
        "XXIXC_trajectory-inertia-strategic-momentum_confirmed" ||
      trace.dominantStratum ===
        "phase-xxix-c-trajectory-inertia-strategic-momentum-confirmed"
    );

  const computationalAuditPass =
    result.pass &&
    result.productiveMomentumDetected &&
    result.momentumBiasApplied &&
    result.antiLockRedirectConfirmed &&
    result.governorAuthorityPreserved &&
    result.categoricalSafetyConfirmed;

  const auditPass =
    computationalAuditPass &&
    aggregateTracePresent;

  return [
    "BRIDGE PHASE XXIX-C AUDIT — TRAJECTORY-INERTIA-STRATEGIC-MOMENTUM",
    "",
    `totalTrials: ${result.totalTrials}`,
    `productiveMomentumDetected: ${result.productiveMomentumDetected}`,
    `momentumBiasApplied: ${result.momentumBiasApplied}`,
    `antiLockRedirectConfirmed: ${result.antiLockRedirectConfirmed}`,
    `computationalAuditPass: ${computationalAuditPass}`,
    `aggregateTracePresent: ${aggregateTracePresent}`,
    `auditPass: ${auditPass}`,
    "",
    `developmentalClassification: ${
      auditPass
        ? "phase-xxix-c-trajectory-momentum-trace-complete"
        : "phase-xxix-c-trajectory-momentum-trace-incomplete"
    }`,
    `pass/fail: ${auditPass ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function ensurePhaseXXVIIIFVisibleToARC(): Promise<boolean> {
  const result = getPhaseXXVIIIFReplicationResult();

  if (!result.summary.pass) {
    return false;
  }

  await ensureTracesLoaded();

  let all = traces();

  let hasAggregate =
    all.some(trace =>
      trace.trajectorySignature ===
        "XXVIIIF_multiseed-iterated-horizon-scanning-replication_confirmed" ||
      trace.dominantStratum ===
        "phase-xxviii-f-multiseed-iterated-horizon-scanning-replication-confirmed" ||
      trace.memoryMode?.includes("Phase XXVIII-F multi-seed replication")
    );

  if (!hasAggregate) {
    await appendTraceIfMissing(
      generatePhaseXXVIIIFAggregateTrace(result)
    );

    await ensureTracesLoaded();

    all = traces();

    hasAggregate =
      all.some(trace =>
        trace.trajectorySignature ===
          "XXVIIIF_multiseed-iterated-horizon-scanning-replication_confirmed" ||
        trace.dominantStratum ===
          "phase-xxviii-f-multiseed-iterated-horizon-scanning-replication-confirmed" ||
        trace.memoryMode?.includes("Phase XXVIII-F multi-seed replication")
      );
  }

  return hasAggregate;
}

