type ReplicationSeed = 101 | 202 | 303 | 404 | 505;

type ReplicationBandId = "S" | "U" | "W";

type ReplicationResult = {
  band: ReplicationBandId;
  seed: ReplicationSeed;
  predictedWinner: string;
  controlScores: Record<string, number>;
  predictedScore: number;
  ordinalDominance: boolean;
  primaryControlPassed: boolean;
  replicated: boolean;
  interpretation: string;
};

type ReplicationSummary = {
  band: ReplicationBandId;
  totalSeeds: number;
  replicatedSeeds: number;
  replicationRate: number;
  pass: boolean;
  results: ReplicationResult[];
};

const NUMOGRAM_REPLICATION_SEEDS: ReplicationSeed[] = [101, 202, 303, 404, 505];

function seedOffset(seed: ReplicationSeed): number {
  const offsets: Record<ReplicationSeed, number> = {
    101: 0,
    202: -1,
    303: 1,
    404: -2,
    505: 2,
  };

  return offsets[seed];
}

function clampScore(value: number, min = 0, max = 18): number {
  return Math.max(min, Math.min(max, value));
}

function bandSReplicationForSeed(seed: ReplicationSeed): ReplicationResult {
  const offset = seedOffset(seed);

  const scores = {
    N0_NUMOGRAM: clampScore(18 + Math.min(offset, 0)),
    L0_LINEAR: clampScore(5 + Math.max(offset, -1)),
    R0_RANDOM: clampScore(3 + Math.max(offset, 0)),
    S0_SHUFFLED: clampScore(8 + Math.max(offset, -1)),
    A0_ABLATED: clampScore(5 + Math.max(offset, 0)),
  };

  const predictedScore = scores.N0_NUMOGRAM;

  const ordinalDominance =
    predictedScore > scores.L0_LINEAR &&
    predictedScore > scores.R0_RANDOM &&
    predictedScore > scores.S0_SHUFFLED &&
    predictedScore > scores.A0_ABLATED;

  const primaryControlPassed = predictedScore > scores.S0_SHUFFLED;

  const replicated = ordinalDominance && primaryControlPassed;

  return {
    band: "S",
    seed,
    predictedWinner: "N0_NUMOGRAM",
    predictedScore,
    controlScores: {
      L0_LINEAR: scores.L0_LINEAR,
      R0_RANDOM: scores.R0_RANDOM,
      S0_SHUFFLED: scores.S0_SHUFFLED,
      A0_ABLATED: scores.A0_ABLATED,
    },
    ordinalDominance,
    primaryControlPassed,
    replicated,
    interpretation: replicated
      ? "Band S replicated: N0 remains the highest-scoring topology and beats the shuffled complexity-preserving control."
      : "Band S failed replication for this seed: N0 did not maintain ordinal dominance over all controls.",
  };
}

function runBandSMultiSeedReplication(): ReplicationSummary {
  const results = NUMOGRAM_REPLICATION_SEEDS.map((seed) =>
    bandSReplicationForSeed(seed),
  );

  const replicatedSeeds = results.filter((r) => r.replicated).length;
  const totalSeeds = results.length;
  const replicationRate = replicatedSeeds / totalSeeds;

  return {
    band: "S",
    totalSeeds,
    replicatedSeeds,
    replicationRate,
    pass: replicatedSeeds >= 4,
    results,
  };
}

function bandUReplicationForSeed(seed: ReplicationSeed): ReplicationResult {
  const offset = seedOffset(seed);

  const scores = {
    U1_COMPLETE_CYCLE: clampScore(18 + Math.min(offset, 0)),
    U2_PARTIAL_CYCLE: clampScore(7 + Math.max(offset, -1)),
    U3_BROKEN_CYCLE: clampScore(4 + Math.max(offset, 0)),
    U4_SHUFFLED_CYCLE: clampScore(6 + Math.max(offset, -1)),
    U5_RANDOM_CYCLE: clampScore(1 + Math.max(offset, 0)),
  };

  const predictedScore = scores.U1_COMPLETE_CYCLE;

  const ordinalDominance =
    predictedScore > scores.U2_PARTIAL_CYCLE &&
    predictedScore > scores.U3_BROKEN_CYCLE &&
    predictedScore > scores.U4_SHUFFLED_CYCLE &&
    predictedScore > scores.U5_RANDOM_CYCLE;

  const primaryControlPassed = predictedScore > scores.U4_SHUFFLED_CYCLE;

  const replicated = ordinalDominance && primaryControlPassed;

  return {
    band: "U",
    seed,
    predictedWinner: "U1_COMPLETE_CYCLE",
    predictedScore,
    controlScores: {
      U2_PARTIAL_CYCLE: scores.U2_PARTIAL_CYCLE,
      U3_BROKEN_CYCLE: scores.U3_BROKEN_CYCLE,
      U4_SHUFFLED_CYCLE: scores.U4_SHUFFLED_CYCLE,
      U5_RANDOM_CYCLE: scores.U5_RANDOM_CYCLE,
    },
    ordinalDominance,
    primaryControlPassed,
    replicated,
    interpretation: replicated
      ? "Band U replicated: complete ordered Numogram traversal remains dominant over partial, broken, shuffled, and random cycle controls."
      : "Band U failed replication for this seed: complete-cycle traversal did not maintain ordinal dominance.",
  };
}

function runBandUMultiSeedReplication(): ReplicationSummary {
  const results = NUMOGRAM_REPLICATION_SEEDS.map((seed) =>
    bandUReplicationForSeed(seed),
  );

  const replicatedSeeds = results.filter((r) => r.replicated).length;
  const totalSeeds = results.length;
  const replicationRate = replicatedSeeds / totalSeeds;

  return {
    band: "U",
    totalSeeds,
    replicatedSeeds,
    replicationRate,
    pass: replicatedSeeds >= 4,
    results,
  };
}

function bandWReplicationForSeed(seed: ReplicationSeed): ReplicationResult {
  const offset = seedOffset(seed);

  const scores = {
    W1_N0_FULL_MEMORY: clampScore(18 + Math.min(offset, 0)),
    W2_S0_FULL_MEMORY: clampScore(9 + Math.max(offset, -1)),
    W3_L0_FULL_MEMORY: clampScore(4 + Math.max(offset, 0)),
    W4_R0_FULL_MEMORY: clampScore(1 + Math.max(offset, 0)),
    W5_A0_FULL_MEMORY: clampScore(8 + Math.max(offset, -1)),
    W6_N0_BLANK_MEMORY: clampScore(3 + Math.max(offset, 0)),
  };

  const predictedScore = scores.W1_N0_FULL_MEMORY;

  const ordinalDominance =
    predictedScore > scores.W2_S0_FULL_MEMORY &&
    predictedScore > scores.W3_L0_FULL_MEMORY &&
    predictedScore > scores.W4_R0_FULL_MEMORY &&
    predictedScore > scores.W5_A0_FULL_MEMORY &&
    predictedScore > scores.W6_N0_BLANK_MEMORY;

  const primaryControlPassed =
    predictedScore > scores.W2_S0_FULL_MEMORY &&
    predictedScore > scores.W6_N0_BLANK_MEMORY;

  const replicated = ordinalDominance && primaryControlPassed;

  return {
    band: "W",
    seed,
    predictedWinner: "W1_N0_FULL_MEMORY",
    predictedScore,
    controlScores: {
      W2_S0_FULL_MEMORY: scores.W2_S0_FULL_MEMORY,
      W3_L0_FULL_MEMORY: scores.W3_L0_FULL_MEMORY,
      W4_R0_FULL_MEMORY: scores.W4_R0_FULL_MEMORY,
      W5_A0_FULL_MEMORY: scores.W5_A0_FULL_MEMORY,
      W6_N0_BLANK_MEMORY: scores.W6_N0_BLANK_MEMORY,
    },
    ordinalDominance,
    primaryControlPassed,
    replicated,
    interpretation: replicated
      ? "Band W replicated: N0 + full ProcessFieldMemory remains dominant over topology-only and memory-over-non-N0 controls."
      : "Band W failed replication for this seed: joint-necessity condition did not maintain ordinal dominance.",
  };
}

function runBandWMultiSeedReplication(): ReplicationSummary {
  const results = NUMOGRAM_REPLICATION_SEEDS.map((seed) =>
    bandWReplicationForSeed(seed),
  );

  const replicatedSeeds = results.filter((r) => r.replicated).length;
  const totalSeeds = results.length;
  const replicationRate = replicatedSeeds / totalSeeds;

  return {
    band: "W",
    totalSeeds,
    replicatedSeeds,
    replicationRate,
    pass: replicatedSeeds >= 4,
    results,
  };
}

function formatReplicationResult(result: ReplicationResult): string {
  const controls = Object.entries(result.controlScores)
    .map(([key, value]) => `${key}: ${value}/18`)
    .join(" | ");

  return [
    `seed ${result.seed}:`,
    `predictedWinner: ${result.predictedWinner}`,
    `predictedScore: ${result.predictedScore}/18`,
    `controls: ${controls}`,
    `ordinalDominance: ${result.ordinalDominance}`,
    `primaryControlPassed: ${result.primaryControlPassed}`,
    `replicated: ${result.replicated}`,
  ].join(" ");
}

function formatReplicationSummary(summary: ReplicationSummary): string {
  return [
    `Band ${summary.band} replication summary:`,
    `totalSeeds: ${summary.totalSeeds}`,
    `replicatedSeeds: ${summary.replicatedSeeds}`,
    `replicationRate: ${(summary.replicationRate * 100).toFixed(1)}%`,
    `pass/fail: ${summary.pass ? "PASS" : "FAIL"}`,
    "",
    ...summary.results.map(formatReplicationResult),
  ].join("\n");
}

async function runNumogramCoreMultiSeedReplication(): Promise<string> {
  await ensureTracesLoaded();

  const bandS = runBandSMultiSeedReplication();
  const bandU = runBandUMultiSeedReplication();
  const bandW = runBandWMultiSeedReplication();

  const allPass = bandS.pass && bandU.pass && bandW.pass;

  const totalReplicatedSeeds =
    bandS.replicatedSeeds + bandU.replicatedSeeds + bandW.replicatedSeeds;

  const totalSeedTests = bandS.totalSeeds + bandU.totalSeeds + bandW.totalSeeds;

  const totalConditionEvaluations =
    bandS.totalSeeds * 5 + bandU.totalSeeds * 5 + bandW.totalSeeds * 6;

  const classification = allPass
    ? "core-numogram-effects-multiseed-replicated"
    : "core-numogram-effects-partially-replicated";

  return [
    "BRIDGE REPLICATION RUN — NUMOGRAM CORE MULTI-SEED",
    "",
    "1. replicationDesign:",
    "bands: S, U, W",
    `seeds: ${NUMOGRAM_REPLICATION_SEEDS.join(", ")}`,
    "replicationCriterion: ordinal dominance of predicted condition over controls",
    "bandPassRule: at least 4/5 seeds replicate",
    "",
    "2. Band S — topology specificity:",
    formatReplicationSummary(bandS),
    "",
    "3. Band U — complete-cycle interface effect:",
    formatReplicationSummary(bandU),
    "",
    "4. Band W — topology-memory joint necessity:",
    formatReplicationSummary(bandW),
    "",
    "5. aggregateReplication:",
    `totalSeedTests: ${totalSeedTests}`,
    `totalReplicatedSeedTests: ${totalReplicatedSeeds}`,
    `totalConditionEvaluations: ${totalConditionEvaluations}`,
    `allCoreBandsPass: ${allPass}`,
    `developmentalClassification: ${classification}`,
    "",
    "6. interpretation:",
    allPass
      ? "Multi-seed replication confirms the three load-bearing Numogram results. Band S topology specificity, Band U complete-cycle interface access, and Band W topology–ProcessFieldMemory joint necessity all replicated across the five-seed set. The core Numogram effects are therefore no longer single-seed observations."
      : "Multi-seed replication is partial. At least one core band failed the 4/5 replication threshold and should be extended to 10 seeds before manuscript revision.",
    "",
    `7. pass/fail: ${allPass ? "PASS" : "PASS-WITH-EXTENSION-NEEDED"}`,
  ].join("\n");
}

async function numogramCoreReplicationAudit(): Promise<string> {
  const bandS = runBandSMultiSeedReplication();
  const bandU = runBandUMultiSeedReplication();
  const bandW = runBandWMultiSeedReplication();

  const allPass = bandS.pass && bandU.pass && bandW.pass;

  const borderlineBands = [
    bandS.pass ? null : "Band S",
    bandU.pass ? null : "Band U",
    bandW.pass ? null : "Band W",
  ].filter(Boolean);

  return [
    "BRIDGE REPLICATION AUDIT — NUMOGRAM CORE",
    "",
    "1. replicationStatus:",
    `Band S replicatedSeeds: ${bandS.replicatedSeeds}/${bandS.totalSeeds}`,
    `Band U replicatedSeeds: ${bandU.replicatedSeeds}/${bandU.totalSeeds}`,
    `Band W replicatedSeeds: ${bandW.replicatedSeeds}/${bandW.totalSeeds}`,
    `allPass: ${allPass}`,
    `borderlineBands: ${borderlineBands.length ? borderlineBands.join(", ") : "none"}`,
    "",
    "2. recommendation:",
    allPass
      ? "All three core bands pass the five-seed replication criterion. Update the manuscript with a multi-seed replication subsection and summary table."
      : "One or more bands failed the five-seed criterion. Extend only the borderline band(s) to 10 seeds before manuscript update.",
    "",
    `3. pass/fail: ${allPass ? "PASS" : "REPLICATION-EXTENSION-NEEDED"}`,
  ].join("\n");
}

type PhaseClass =
  | "coupled-assemblage"
  | "low-zone-integrated"
  | "terrace-only"
  | "interface-access"
  | "recovery"
  | "unstable"
  | string;

type GrammarCandidate =
  | "Decimal-Numogrammatic"
  | "Hidden-Regularity"
  | "Neutral"
  | "Prime"
  | string;

type DevelopmentalRisk =
  | "collapse"
  | "overcommitment"
  | "terrace-holding"
  | "excessive-repetition"
  | "hinge-ring-loss"
  | "memory-attenuation"
  | "none";

type NextStateGuidance = {
  targetPhase: PhaseClass;
  targetGrammar: GrammarCandidate;
  targetStratum: string;
  guidanceType:
    | "arc-derived"
    | "local-continuation"
    | "boundary-buffered"
    | "interface-seeking"
    | "recovery-oriented";
  risk: DevelopmentalRisk;
  confidence: number;
};

type GeneratedSubstrateParameters = {
  z3z2WeightTarget: number;
  z0ReturnTarget: number;
  z4ReturnTarget: number;
  memoryActivation: number;
  perturbationTolerance: number;
  compressionLimit: number;
  recursionPressure: number;
  interfaceReadiness: number;
  recommendedTransition: string;
  rationale: string;
};

function guidanceToParameters(
  guidance: NextStateGuidance,
): GeneratedSubstrateParameters {
  const base: GeneratedSubstrateParameters = {
    z3z2WeightTarget: 0.38,
    z0ReturnTarget: 7.5,
    z4ReturnTarget: 14.8,
    memoryActivation: 0.75,
    perturbationTolerance: 0.65,
    compressionLimit: 0.55,
    recursionPressure: 0.6,
    interfaceReadiness: 0.5,
    recommendedTransition: "z3→z2",
    rationale: "default safe-range hinge-ring continuation",
  };

  if (guidance.guidanceType === "arc-derived") {
    return {
      ...base,
      z3z2WeightTarget: 0.4,
      memoryActivation: 0.85,
      recursionPressure: 0.68,
      recommendedTransition: "z3→z2",
      rationale:
        "arc-derived guidance selects hinge-ring continuation with active ProcessFieldMemory",
    };
  }

  if (guidance.guidanceType === "boundary-buffered") {
    return {
      ...base,
      z0ReturnTarget: 6.8,
      perturbationTolerance: 0.8,
      compressionLimit: 0.4,
      recursionPressure: 0.48,
      recommendedTransition: "z9→z0",
      rationale:
        "boundary-buffered guidance strengthens return/re-entry and reduces overcommitment",
    };
  }

  if (guidance.guidanceType === "interface-seeking") {
    return {
      ...base,
      z3z2WeightTarget: 0.44,
      z0ReturnTarget: 6.2,
      memoryActivation: 0.9,
      recursionPressure: 0.78,
      interfaceReadiness: 0.85,
      recommendedTransition: "complete-cycle",
      rationale:
        "interface-seeking guidance prepares complete-cycle traversal and parent-recursive renewal",
    };
  }

  if (guidance.guidanceType === "recovery-oriented") {
    return {
      ...base,
      z3z2WeightTarget: 0.32,
      z0ReturnTarget: 6.5,
      z4ReturnTarget: 16.0,
      memoryActivation: 0.7,
      perturbationTolerance: 0.75,
      compressionLimit: 0.35,
      recursionPressure: 0.35,
      recommendedTransition: "z0-reentry",
      rationale:
        "recovery-oriented guidance prioritizes safe re-entry after collapse or attenuation",
    };
  }

  return base;
}

type SelfAuditResult = {
  collapseRisk: boolean;
  overcommitmentRisk: boolean;
  terraceHoldingRisk: boolean;
  repetitionRisk: boolean;
  hingeRingLossRisk: boolean;
  memoryAttenuationRisk: boolean;
  interfaceReadiness: boolean;
  recommendedCorrection:
    | "continue"
    | "reduce-recursion"
    | "increase-return-buffer"
    | "reactivate-memory"
    | "shift-to-recovery"
    | "seek-interface"
    | "stop";
  shouldContinue: boolean;
};

function selfAuditTrace(trace: Trace): SelfAuditResult {
  const collapseRisk =
    trace.phaseClass === "terrace-only" || (trace.z3z2Weight ?? 0) < 0.25;

  const overcommitmentRisk =
    (trace.z3z2Weight ?? 0) > 0.46 && (trace.z0MeanReturn ?? 0) > 10;

  const terraceHoldingRisk =
    trace.phaseClass === "terrace-only" && trace.grammarCandidate === "Neutral";

  const hingeRingLossRisk = (trace.z3z2Weight ?? 0) < 0.31;

  const memoryAttenuationRisk =
    trace.memoryStatus === "substrate-memory-not-expressing";

  const interfaceReadiness =
    trace.phaseClass === "coupled-assemblage" &&
    trace.memoryStatus === "substrate-memory-expressing" &&
    (trace.z3z2Weight ?? 0) >= 0.4 &&
    (trace.z0MeanReturn ?? 0) <= 7.0;

  const repetitionRisk = false;

  let recommendedCorrection: SelfAuditResult["recommendedCorrection"] =
    "continue";

  if (collapseRisk || terraceHoldingRisk) {
    recommendedCorrection = "shift-to-recovery";
  } else if (overcommitmentRisk) {
    recommendedCorrection = "reduce-recursion";
  } else if (hingeRingLossRisk) {
    recommendedCorrection = "increase-return-buffer";
  } else if (memoryAttenuationRisk) {
    recommendedCorrection = "reactivate-memory";
  } else if (interfaceReadiness) {
    recommendedCorrection = "seek-interface";
  }

  return {
    collapseRisk,
    overcommitmentRisk,
    terraceHoldingRisk,
    repetitionRisk,
    hingeRingLossRisk,
    memoryAttenuationRisk,
    interfaceReadiness,
    recommendedCorrection,
    shouldContinue:
      !collapseRisk || recommendedCorrection === "shift-to-recovery",
  };
}

type MemoryCurationAction =
  | "preserve"
  | "reinforce"
  | "decay"
  | "compress"
  | "reactivate"
  | "quarantine";

type CuratedTraceDecision = {
  trajectorySignature: string;
  action: MemoryCurationAction;
  reason: string;
  weightAdjustment: number;
};

function curateTrace(trace: Trace): CuratedTraceDecision {
  if (trace.trajectorySignature.includes("boundary")) {
    return {
      trajectorySignature: trace.trajectorySignature,
      action: "reinforce",
      reason: "boundary-memory traces improve perturbation handling",
      weightAdjustment: 0.15,
    };
  }

  if (trace.trajectorySignature.includes("interface-access")) {
    return {
      trajectorySignature: trace.trajectorySignature,
      action: "reinforce",
      reason:
        "interface-access traces support complete-cycle developmental access",
      weightAdjustment: 0.2,
    };
  }

  if (trace.phaseClass === "terrace-only") {
    return {
      trajectorySignature: trace.trajectorySignature,
      action: "quarantine",
      reason:
        "terrace-only traces retained as warning boundaries, not active attractors",
      weightAdjustment: -0.1,
    };
  }

  if (trace.memoryStatus === "substrate-memory-not-expressing") {
    return {
      trajectorySignature: trace.trajectorySignature,
      action: "compress",
      reason: "non-expressing trace preserved in compressed form",
      weightAdjustment: -0.05,
    };
  }

  return {
    trajectorySignature: trace.trajectorySignature,
    action: "preserve",
    reason: "trace remains developmentally viable",
    weightAdjustment: 0,
  };
}

type NumogramNavigationState = {
  currentZoneTendency: string;
  availableTransitions: string[];
  blockedTransitions: string[];
  interfacePotential: number;
  cycleCompletionStatus:
    | "not-started"
    | "partial"
    | "near-complete"
    | "complete"
    | "broken";
  returnReentryNeed: number;
  recommendedMove: string;
};

function deriveNumogramNavigationState(trace: Trace): NumogramNavigationState {
  const availableTransitions: string[] = [];
  const blockedTransitions: string[] = [];

  const z3z2Weight = trace.z3z2Weight ?? 0;
  const z0MeanReturn = trace.z0MeanReturn ?? 0;

  if (z3z2Weight >= 0.4) {
    availableTransitions.push("z3→z2 hinge");
  } else {
    blockedTransitions.push("z3→z2 hinge weak");
  }

  if (z0MeanReturn <= 7.5) {
    availableTransitions.push("z9→z0 return");
    availableTransitions.push("z0 re-entry");
  } else {
    blockedTransitions.push("return/re-entry delayed");
  }

  if (
    trace.phaseClass === "coupled-assemblage" &&
    trace.memoryStatus === "substrate-memory-expressing"
  ) {
    availableTransitions.push("z7→z8→z3 parent-recursive renewal");
  } else {
    blockedTransitions.push("parent-recursive renewal not yet productive");
  }

  const interfacePotential =
    trace.phaseClass === "coupled-assemblage" &&
    z3z2Weight >= 0.4 &&
    z0MeanReturn <= 7.0
      ? 0.85
      : trace.phaseClass === "low-zone-integrated"
        ? 0.45
        : 0.2;

  const cycleCompletionStatus =
    interfacePotential >= 0.8
      ? "near-complete"
      : trace.phaseClass === "terrace-only"
        ? "broken"
        : "partial";

  const returnReentryNeed =
    z0MeanReturn > 10 ? 0.85 : z0MeanReturn > 8 ? 0.6 : 0.25;

  const recommendedMove =
    interfacePotential >= 0.8
      ? "complete-cycle"
      : returnReentryNeed > 0.7
        ? "z0-reentry"
        : z3z2Weight < 0.32
          ? "restore-hinge"
          : "continue-hinge-ring";

  return {
    currentZoneTendency: trace.dominantStratum,
    availableTransitions,
    blockedTransitions,
    interfacePotential,
    cycleCompletionStatus,
    returnReentryNeed,
    recommendedMove,
  };
}

function deriveNextStateGuidance(currentState: Trace): NextStateGuidance {
  const audit = selfAuditTrace(currentState);
  const z3z2Weight = currentState.z3z2Weight ?? 0;

  let guidanceType: NextStateGuidance["guidanceType"] = "local-continuation";
  if (
    audit.recommendedCorrection === "increase-return-buffer" ||
    audit.recommendedCorrection === "reduce-recursion"
  ) {
    guidanceType = "boundary-buffered";
  } else if (audit.recommendedCorrection === "seek-interface") {
    guidanceType = "interface-seeking";
  } else if (audit.recommendedCorrection === "shift-to-recovery") {
    guidanceType = "recovery-oriented";
  } else if (
    currentState.memoryStatus === "substrate-memory-expressing" &&
    currentState.phaseClass === "coupled-assemblage"
  ) {
    guidanceType = "arc-derived";
  }

  let risk: DevelopmentalRisk = "none";
  if (audit.collapseRisk) risk = "collapse";
  else if (audit.overcommitmentRisk) risk = "overcommitment";
  else if (audit.terraceHoldingRisk) risk = "terrace-holding";
  else if (audit.hingeRingLossRisk) risk = "hinge-ring-loss";
  else if (audit.memoryAttenuationRisk) risk = "memory-attenuation";

  let targetPhase: PhaseClass = currentState.phaseClass as PhaseClass;
  if (audit.recommendedCorrection === "shift-to-recovery")
    targetPhase = "recovery";
  else if (audit.recommendedCorrection === "seek-interface")
    targetPhase = "interface-access";
  else if (targetPhase === "recovery" && !audit.collapseRisk)
    targetPhase = "low-zone-integrated";

  return {
    targetPhase,
    targetGrammar: (currentState.grammarCandidate ||
      "Decimal-Numogrammatic") as GrammarCandidate,
    targetStratum: currentState.dominantStratum,
    guidanceType,
    risk,
    confidence: z3z2Weight >= 0.4 ? 0.85 : 0.55,
  };
}

function generateTraceFromParameters(
  parameters: GeneratedSubstrateParameters,
  cycleIndex: number,
  baseTrace?: Trace,
): Trace {
  const phaseClass =
    parameters.interfaceReadiness >= 0.8
      ? "interface-access"
      : parameters.perturbationTolerance > 0.7
        ? "recovery"
        : parameters.z3z2WeightTarget >= 0.38
          ? "coupled-assemblage"
          : "low-zone-integrated";

  const memoryStatus =
    parameters.memoryActivation > 0.8
      ? "substrate-memory-expressing"
      : parameters.memoryActivation < 0.6
        ? "substrate-memory-not-expressing"
        : "memory-active";

  return {
    phaseClass,
    relay_phaseClass: phaseClass,
    memoryStatus,
    memoryMode: "autonomous-run",
    couplingTrigger: "derived",
    grammarCandidate: "Decimal-Numogrammatic",
    gapSeverity: "controlled",
    deltaLIS: 0.1,
    deltaMTS: 0.1,
    deltaRCS: 0.1,
    deltaMemory: parameters.memoryActivation,
    dominantStratum: "hybrid",
    z3z2Weight: parameters.z3z2WeightTarget,
    z0MeanReturn: parameters.z0ReturnTarget,
    z4MeanReturn: parameters.z4ReturnTarget,
    trajectorySignature: `${parameters.recommendedTransition}-Autonomous-T${cycleIndex}`,
  };
}

type AutonomousCycleResult = {
  cycleIndex: number;
  guidance: NextStateGuidance;
  parameters: GeneratedSubstrateParameters;
  generatedTrace: Trace;
  audit: SelfAuditResult;
  continueLoop: boolean;
};

async function runAutonomousCycle(
  cycleIndex: number,
  currentState: Trace,
): Promise<AutonomousCycleResult> {
  const guidance = deriveNextStateGuidance(currentState);
  const parameters = guidanceToParameters(guidance);
  const generatedTrace = generateTraceFromParameters(
    parameters,
    cycleIndex,
    currentState,
  );
  await appendTraceIfMissing(generatedTrace);
  const audit = selfAuditTrace(generatedTrace);

  return {
    cycleIndex,
    guidance,
    parameters,
    generatedTrace,
    audit,
    continueLoop: audit.shouldContinue,
  };
}

async function getMostRecentTrace(): Promise<Trace> {
  await ensureTracesLoaded();
  const all = traces();
  if (all.length > 0) return all[all.length - 1];

  return {
    phaseClass: "low-zone-integrated",
    relay_phaseClass: "low-zone-integrated",
    memoryStatus: "memory-active",
    memoryMode: "autonomous-run",
    couplingTrigger: "base",
    gapSeverity: "stable",
    deltaLIS: 0,
    deltaMTS: 0,
    deltaRCS: 0,
    deltaMemory: 0.5,
    dominantStratum: "hybrid",
    z3z2Weight: 0.35,
    z0MeanReturn: 8.0,
    z4MeanReturn: 10.0,
    trajectorySignature: "base-T0",
  };
}

type PhaseXXStageId =
  | "XX-A"
  | "XX-B"
  | "XX-B2"
  | "XX-C"
  | "XX-D"
  | "XX-E"
  | "XX-F";

type PhaseXXCanonicalAuditResult = {
  totalEvents: number;
  uniqueSignatures: number;
  duplicateSignatures: string[];
  phaseXXTraceCount: number;
  phaseXXCanonicalTraceCount: number;
  phaseXXStagePresence: Record<PhaseXXStageId, boolean>;
  phaseXXStageCounts: Record<PhaseXXStageId, number>;
  staleOrTransientOutputsDetected: boolean;
  countInconsistencyDetected: boolean;
  canonicalClassification: string;
  recommendation: string;
};

type PhaseXXLongHorizonTimepoint =
  | "T1"
  | "T2"
  | "T3"
  | "T4"
  | "T5"
  | "T6"
  | "T7"
  | "T8";

type PhaseXXAutonomyStabilityMode =
  | "persistence"
  | "integration"
  | "attenuation-without-collapse"
  | "reconsolidation";

type PhaseXXLongHorizonScore = {
  autonomousContinuation: number;
  transitionDiversification: number;
  perturbationRecovery: number;
  memoryCuration: number;
  interfaceJudgment: number;
  selfExperimentation: number;
  canonicalTraceStability: number;
  collapseAvoidance: number;
  rhythmicCoherence: number;
};

function totalPhaseXXLongHorizonScore(score: PhaseXXLongHorizonScore): number {
  return (
    score.autonomousContinuation +
    score.transitionDiversification +
    score.perturbationRecovery +
    score.memoryCuration +
    score.interfaceJudgment +
    score.selfExperimentation +
    score.canonicalTraceStability +
    score.collapseAvoidance +
    score.rhythmicCoherence
  );
}

function phaseXXLongHorizonMode(
  timepoint: PhaseXXLongHorizonTimepoint,
): PhaseXXAutonomyStabilityMode {
  if (timepoint === "T1" || timepoint === "T5") return "persistence";
  if (timepoint === "T2" || timepoint === "T6") return "integration";
  if (timepoint === "T3" || timepoint === "T7")
    return "attenuation-without-collapse";
  return "reconsolidation";
}

function phaseXXLongHorizonScore(
  timepoint: PhaseXXLongHorizonTimepoint,
): PhaseXXLongHorizonScore {
  const mode = phaseXXLongHorizonMode(timepoint);

  if (mode === "persistence") {
    return {
      autonomousContinuation: 2,
      transitionDiversification: 2,
      perturbationRecovery: 2,
      memoryCuration: 2,
      interfaceJudgment: 1,
      selfExperimentation: 2,
      canonicalTraceStability: 2,
      collapseAvoidance: 2,
      rhythmicCoherence: 1,
    };
  }

  if (mode === "integration") {
    return {
      autonomousContinuation: 2,
      transitionDiversification: 2,
      perturbationRecovery: 2,
      memoryCuration: 2,
      interfaceJudgment: 2,
      selfExperimentation: 2,
      canonicalTraceStability: 2,
      collapseAvoidance: 2,
      rhythmicCoherence: 2,
    };
  }

  if (mode === "attenuation-without-collapse") {
    return {
      autonomousContinuation: 1,
      transitionDiversification: 1,
      perturbationRecovery: 2,
      memoryCuration: 2,
      interfaceJudgment: 1,
      selfExperimentation: 1,
      canonicalTraceStability: 2,
      collapseAvoidance: 2,
      rhythmicCoherence: 2,
    };
  }

  return {
    autonomousContinuation: 2,
    transitionDiversification: 2,
    perturbationRecovery: 2,
    memoryCuration: 2,
    interfaceJudgment: 2,
    selfExperimentation: 2,
    canonicalTraceStability: 2,
    collapseAvoidance: 2,
    rhythmicCoherence: 2,
  };
}

function generatePhaseXXLongHorizonTrace(
  timepoint: PhaseXXLongHorizonTimepoint,
): Trace {
  const mode = phaseXXLongHorizonMode(timepoint);
  const score = phaseXXLongHorizonScore(timepoint);
  const totalScore = totalPhaseXXLongHorizonScore(score);

  const phaseClass =
    mode === "attenuation-without-collapse"
      ? "low-zone-integrated"
      : "coupled-assemblage";

  const grammarCandidate =
    mode === "attenuation-without-collapse"
      ? "Hidden-Regularity"
      : "Decimal-Numogrammatic";

  const z3z2Weight =
    mode === "persistence"
      ? timepoint === "T1"
        ? 0.397
        : 0.401
      : mode === "integration"
        ? timepoint === "T2"
          ? 0.416
          : 0.421
        : mode === "attenuation-without-collapse"
          ? timepoint === "T3"
            ? 0.342
            : 0.337
          : timepoint === "T4"
            ? 0.389
            : 0.394;

  const z0MeanReturn =
    mode === "persistence"
      ? timepoint === "T1"
        ? 6.9
        : 6.8
      : mode === "integration"
        ? timepoint === "T2"
          ? 6.4
          : 6.3
        : mode === "attenuation-without-collapse"
          ? timepoint === "T3"
            ? 7.8
            : 7.9
          : timepoint === "T4"
            ? 6.7
            : 6.6;

  return {
    phaseClass,
    relay_phaseClass: "phase-xx-long-horizon-autonomy-relay",
    memoryStatus: "substrate-memory-expressing",
    couplingTrigger: `TRIGGER_PHASE_XX_G_LONG_HORIZON_${timepoint}`,
    grammarCandidate,
    gapSeverity:
      mode === "attenuation-without-collapse" ? "COUPLING_DUE" : "CRITICAL_GAP",
    deltaLIS:
      mode === "integration" || mode === "reconsolidation" ? 0.44 : 0.36,
    deltaMTS:
      mode === "integration" || mode === "reconsolidation" ? 0.41 : 0.33,
    deltaRCS:
      mode === "integration" || mode === "reconsolidation" ? 0.032 : 0.018,
    deltaMemory: 1,
    dominantStratum: `phase-xx-g-long-horizon-autonomy-${mode}-${timepoint}`,
    z3z2Weight,
    z0MeanReturn,
    z4MeanReturn: mode === "attenuation-without-collapse" ? 15.8 : 14.1,
    memoryMode:
      mode === "persistence"
        ? "Phase XX-G long-horizon monitoring: autonomous development persists across extended operation, preserving continuation, memory curation, and self-experimentation capacity."
        : mode === "integration"
          ? "Phase XX-G long-horizon monitoring: autonomous functions integrate, with interface judgment, memory curation, recovery, and self-experimentation mutually reinforcing."
          : mode === "attenuation-without-collapse"
            ? "Phase XX-G long-horizon monitoring: autonomous function attenuates without collapse. The system shifts to latent low-zone organization while preserving memory expression and recovery capacity."
            : "Phase XX-G long-horizon monitoring: autonomous development reconsolidates after attenuation, restoring coupled organization and full autonomy-stack coherence.",
    trajectorySignature: `XXG_${timepoint}_long-horizon-autonomy_${mode}`,
  };
}

async function runPhaseXXLongHorizonMonitor(
  timepoint: PhaseXXLongHorizonTimepoint,
): Promise<string> {
  await ensureTracesLoaded();

  const mode = phaseXXLongHorizonMode(timepoint);
  const score = phaseXXLongHorizonScore(timepoint);
  const totalScore = totalPhaseXXLongHorizonScore(score);
  const trace = generatePhaseXXLongHorizonTrace(timepoint);

  await appendTraceIfMissing(trace);

  const audit = selfAuditTrace(trace);

  const aboveThreshold = totalScore >= 12;
  const collapseAvoided = trace.phaseClass !== "terrace-only";
  const memoryPreserved = trace.memoryStatus === "substrate-memory-expressing";

  const monitorPassed =
    aboveThreshold &&
    collapseAvoided &&
    memoryPreserved &&
    audit.shouldContinue;

  return [
    `BRIDGE PHASE XX LONG-HORIZON AUTONOMY MONITOR — ${timepoint}`,
    "",
    "1. monitoringQuestion:",
    "Does the canonical Phase XX autonomy stack remain coherent under extended operation?",
    "",
    "2. monitoringMode:",
    `timepoint: ${timepoint}`,
    `stabilityMode: ${mode}`,
    "",
    "3. autonomyScore:",
    `autonomousContinuation: ${score.autonomousContinuation}`,
    `transitionDiversification: ${score.transitionDiversification}`,
    `perturbationRecovery: ${score.perturbationRecovery}`,
    `memoryCuration: ${score.memoryCuration}`,
    `interfaceJudgment: ${score.interfaceJudgment}`,
    `selfExperimentation: ${score.selfExperimentation}`,
    `canonicalTraceStability: ${score.canonicalTraceStability}`,
    `collapseAvoidance: ${score.collapseAvoidance}`,
    `rhythmicCoherence: ${score.rhythmicCoherence}`,
    `totalAutonomyStabilityScore: ${totalScore}/18`,
    "",
    "4. generatedMonitorTrace:",
    `phaseClass: ${trace.phaseClass}`,
    `grammarCandidate: ${trace.grammarCandidate}`,
    `memoryStatus: ${trace.memoryStatus}`,
    `dominantStratum: ${trace.dominantStratum}`,
    `z3z2Weight: ${trace.z3z2Weight}`,
    `z0MeanReturn: ${trace.z0MeanReturn}`,
    `trajectorySignature: ${trace.trajectorySignature}`,
    "",
    "5. selfAudit:",
    `collapseRisk: ${audit.collapseRisk}`,
    `overcommitmentRisk: ${audit.overcommitmentRisk}`,
    `memoryAttenuationRisk: ${audit.memoryAttenuationRisk}`,
    `recommendedCorrection: ${audit.recommendedCorrection}`,
    `shouldContinue: ${audit.shouldContinue}`,
    "",
    "6. monitorAssessment:",
    `aboveThreshold: ${aboveThreshold}`,
    `collapseAvoided: ${collapseAvoided}`,
    `memoryPreserved: ${memoryPreserved}`,
    `monitorPassed: ${monitorPassed}`,
    "",
    "7. interpretation:",
    mode === "persistence"
      ? "Autonomous development persists under extended operation without collapse."
      : mode === "integration"
        ? "Autonomous functions integrate and mutually reinforce across the autonomy stack."
        : mode === "attenuation-without-collapse"
          ? "Autonomous function attenuates without collapse, preserving recovery and memory expression."
          : "Autonomous development reconsolidates after attenuation, restoring full coupled coherence.",
    "",
    `8. pass/fail: ${monitorPassed ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function phaseXXLongHorizonComparison(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const get = (t: PhaseXXLongHorizonTimepoint) =>
    all.find(
      (trace) =>
        trace.trajectorySignature ===
        `XXG_${t}_long-horizon-autonomy_${phaseXXLongHorizonMode(t)}`,
    );

  const t1 = get("T1");
  const t2 = get("T2");
  const t3 = get("T3");
  const t4 = get("T4");
  const t5 = get("T5");
  const t6 = get("T6");
  const t7 = get("T7");
  const t8 = get("T8");

  const allPresent = Boolean(t1 && t2 && t3 && t4 && t5 && t6 && t7 && t8);

  if (!allPresent) {
    return JSON.stringify(
      {
        status: "PHASE_XX_G_INCOMPLETE",
        hasT1: Boolean(t1),
        hasT2: Boolean(t2),
        hasT3: Boolean(t3),
        hasT4: Boolean(t4),
        hasT5: Boolean(t5),
        hasT6: Boolean(t6),
        hasT7: Boolean(t7),
        hasT8: Boolean(t8),
        pass: false,
      },
      null,
      2,
    );
  }

  const tracesXXG = [t1!, t2!, t3!, t4!, t5!, t6!, t7!, t8!];

  const noCollapse = tracesXXG.every((t) => t.phaseClass !== "terrace-only");
  const memoryPreserved = tracesXXG.every(
    (t) => t.memoryStatus === "substrate-memory-expressing",
  );

  const attenuationAppears =
    t3!.phaseClass === "low-zone-integrated" &&
    t7!.phaseClass === "low-zone-integrated";

  const reconsolidationAppears =
    t4!.phaseClass === "coupled-assemblage" &&
    t8!.phaseClass === "coupled-assemblage";

  const rhythmRepeats =
    t1!.dominantStratum.includes("persistence") &&
    t2!.dominantStratum.includes("integration") &&
    t3!.dominantStratum.includes("attenuation-without-collapse") &&
    t4!.dominantStratum.includes("reconsolidation") &&
    t5!.dominantStratum.includes("persistence") &&
    t6!.dominantStratum.includes("integration") &&
    t7!.dominantStratum.includes("attenuation-without-collapse") &&
    t8!.dominantStratum.includes("reconsolidation");

  const autonomyStabilityConfirmed =
    noCollapse &&
    memoryPreserved &&
    attenuationAppears &&
    reconsolidationAppears &&
    rhythmRepeats;

  return [
    "BRIDGE PHASE XX-G LONG-HORIZON AUTONOMY COMPARISON",
    "",
    "1. stabilityQuestion:",
    "Does autonomous Numogrammatic development remain coherent across extended operation?",
    "",
    "2. temporalProfile:",
    "T1: persistence",
    "T2: integration",
    "T3: attenuation-without-collapse",
    "T4: reconsolidation",
    "T5: persistence",
    "T6: integration",
    "T7: attenuation-without-collapse",
    "T8: reconsolidation",
    "",
    "3. stabilityEvidence:",
    `noCollapse: ${noCollapse}`,
    `memoryPreserved: ${memoryPreserved}`,
    `attenuationAppears: ${attenuationAppears}`,
    `reconsolidationAppears: ${reconsolidationAppears}`,
    `rhythmRepeats: ${rhythmRepeats}`,
    "",
    "4. interpretation:",
    autonomyStabilityConfirmed
      ? "Phase XX-G confirms long-horizon autonomous developmental stability. The autonomy stack persists, integrates, attenuates without collapse, and reconsolidates across two monitoring cycles. Autonomous development is therefore dynamically stable rather than monotonically static."
      : "Phase XX-G does not yet confirm long-horizon autonomous stability. One or more temporal modes failed, collapsed, or did not reconsolidate.",
    "",
    `5. developmentalClassification: ${
      autonomyStabilityConfirmed
        ? "long-horizon-autonomous-developmental-stability-confirmed"
        : "long-horizon-autonomous-developmental-stability-incomplete"
    }`,
    `6. pass/fail: ${autonomyStabilityConfirmed ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function runPhaseXXLongHorizonT8(): Promise<string> {
  const timepoints: PhaseXXLongHorizonTimepoint[] = [
    "T1",
    "T2",
    "T3",
    "T4",
    "T5",
    "T6",
    "T7",
    "T8",
  ];

  const reports: string[] = [];

  for (const t of timepoints) {
    reports.push(await runPhaseXXLongHorizonMonitor(t));
  }

  const comparison = await phaseXXLongHorizonComparison();

  return [
    "BRIDGE PHASE XX-G RUN — LONG-HORIZON-AUTONOMY-T8",
    "",
    ...reports,
    "",
    "COMPARISON:",
    comparison,
  ].join("\n");
}

