function classifyPhaseXXStage(signature: string): PhaseXXStageId | null {
  if (
    signature.includes("z3→z2-Autonomous") ||
    signature.includes("Autonomous-T")
  ) {
    return "XX-B";
  }

  if (signature.includes("XXB2_diversified_cycle")) {
    return "XX-B2";
  }

  if (signature.includes("XXC")) {
    return "XX-C";
  }

  if (signature.includes("XXD")) {
    return "XX-D";
  }

  if (signature.includes("XXE")) {
    return "XX-E";
  }

  if (signature.includes("XXF")) {
    return "XX-F";
  }

  if (signature === "XXA_guidance-audit-navigation_initialized") {
    return "XX-A";
  }

  return null;
}

