function findDuplicateSignaturesFromTraces(all: Trace[]): string[] {
  const counts = new Map<string, number>();

  for (const trace of all) {
    const sig = trace.trajectorySignature;
    if (!sig) continue;
    counts.set(sig, (counts.get(sig) ?? 0) + 1);
  }

  return Array.from(counts.entries())
    .filter(([, count]) => count > 1)
    .map(([sig, count]) => `${sig} × ${count}`);
}

async function phaseXXCanonicalAudit(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const totalEvents = all.length;

  const signatures = all
    .map((t) => t.trajectorySignature)
    .filter((s): s is string => Boolean(s));

  const uniqueSignatures = new Set(signatures).size;

  const duplicateSignatures = findDuplicateSignaturesFromTraces(all);

  const phaseXXTraces = all.filter(
    (t) => classifyPhaseXXStage(t.trajectorySignature ?? "") !== null,
  );

  const phaseXXTraceCount = phaseXXTraces.length;

  const phaseXXStageCounts: Record<PhaseXXStageId, number> = {
    "XX-A": 0,
    "XX-B": 0,
    "XX-B2": 0,
    "XX-C": 0,
    "XX-D": 0,
    "XX-E": 0,
    "XX-F": 0,
  };

  for (const trace of phaseXXTraces) {
    const stage = classifyPhaseXXStage(trace.trajectorySignature ?? "");
    if (stage) phaseXXStageCounts[stage]++;
  }

  const hasSignature = (sig: string): boolean =>
    all.some((t) => t.trajectorySignature === sig);

  const phaseXXStagePresence: Record<PhaseXXStageId, boolean> = {
    "XX-A": PHASE_XX_CANONICAL_REQUIREMENTS["XX-A"].every(hasSignature),

    "XX-B": PHASE_XX_CANONICAL_REQUIREMENTS["XX-B"].every(hasSignature),

    "XX-B2": PHASE_XX_CANONICAL_REQUIREMENTS["XX-B2"].every(hasSignature),

    "XX-C": PHASE_XX_CANONICAL_REQUIREMENTS["XX-C"].every(hasSignature),

    "XX-D": PHASE_XX_CANONICAL_REQUIREMENTS["XX-D"].every(hasSignature),

    "XX-E": PHASE_XX_CANONICAL_REQUIREMENTS["XX-E"].every(hasSignature),

    "XX-F": PHASE_XX_CANONICAL_REQUIREMENTS["XX-F"].every(hasSignature),
  };

  const requiredCanonicalSignatures = Object.values(
    PHASE_XX_CANONICAL_REQUIREMENTS,
  ).flat();

  const phaseXXCanonicalTraceCount =
    requiredCanonicalSignatures.filter(hasSignature).length;

  const allCoreStagesPresent =
    phaseXXStagePresence["XX-B"] &&
    phaseXXStagePresence["XX-B2"] &&
    phaseXXStagePresence["XX-C"] &&
    phaseXXStagePresence["XX-D"] &&
    phaseXXStagePresence["XX-E"] &&
    phaseXXStagePresence["XX-F"];

  const staleOrTransientOutputsDetected =
    phaseXXTraceCount !== phaseXXCanonicalTraceCount ||
    phaseXXStageCounts["XX-A"] > 0;

  const countInconsistencyDetected =
    duplicateSignatures.length > 0 ||
    totalEvents !== uniqueSignatures ||
    staleOrTransientOutputsDetected;

  const canonicalClassification = allCoreStagesPresent
    ? "phase-xx-canonical-autonomy-stack-complete"
    : "phase-xx-canonical-autonomy-stack-incomplete";

  const recommendation = allCoreStagesPresent
    ? countInconsistencyDetected
      ? "Phase XX functional stack is complete, but trace accounting should distinguish persistent canonical traces from transient diagnostic outputs before publication-style reporting."
      : "Phase XX canonical stack is complete and trace accounting is clean."
    : "Phase XX is not canonically complete. Re-run missing stages before long-horizon monitoring.";

  return [
    "BRIDGE PHASE XX CANONICAL AUDIT",
    "",
    "1. globalTraceAccounting:",
    `totalEvents: ${totalEvents}`,
    `uniqueSignatures: ${uniqueSignatures}`,
    `duplicateSignatures: ${
      duplicateSignatures.length ? duplicateSignatures.join("; ") : "none"
    }`,
    `countInconsistencyDetected: ${countInconsistencyDetected}`,
    "",
    "2. phaseXXTraceAccounting:",
    `phaseXXTraceCount: ${phaseXXTraceCount}`,
    `phaseXXCanonicalTraceCount: ${phaseXXCanonicalTraceCount}`,
    `staleOrTransientOutputsDetected: ${staleOrTransientOutputsDetected}`,
    "",
    "3. phaseXXStagePresence:",
    `XX-A_guidance-audit-navigation_initialized: ${phaseXXStagePresence["XX-A"]}`,
    `XX-B_bounded-autonomous-continuation: ${phaseXXStagePresence["XX-B"]}`,
    `XX-B2_transition-diversification: ${phaseXXStagePresence["XX-B2"]}`,
    `XX-C_perturbation-aware-recovery: ${phaseXXStagePresence["XX-C"]}`,
    `XX-D_active-memory-curation: ${phaseXXStagePresence["XX-D"]}`,
    `XX-E_autonomous-interface-seeking: ${phaseXXStagePresence["XX-E"]}`,
    `XX-F_autonomous-developmental-experimentation: ${phaseXXStagePresence["XX-F"]}`,
    "",
    "4. phaseXXStageCounts:",
    `XX-A: ${phaseXXStageCounts["XX-A"]}`,
    `XX-B: ${phaseXXStageCounts["XX-B"]}`,
    `XX-B2: ${phaseXXStageCounts["XX-B2"]}`,
    `XX-C: ${phaseXXStageCounts["XX-C"]}`,
    `XX-D: ${phaseXXStageCounts["XX-D"]}`,
    `XX-E: ${phaseXXStageCounts["XX-E"]}`,
    `XX-F: ${phaseXXStageCounts["XX-F"]}`,
    "",
    "5. canonicalInterpretation:",
    allCoreStagesPresent
      ? "Phase XX canonical autonomy stack is complete. Amelia has persistent traces for bounded autonomous continuation, transition diversification, perturbation-aware recovery, active memory curation, autonomous interface-seeking, and autonomous developmental experimentation."
      : "Phase XX canonical autonomy stack is incomplete. One or more persistent stage trace groups are missing.",
    "",
    "6. accountingInterpretation:",
    countInconsistencyDetected
      ? "The recent totalEvents discrepancy is likely caused by mixed accounting: some bridge outputs are diagnostic or comparison-only, while only appended traces persist as canonical events. Future manuscript reporting should use canonical trace count and stage-completion status rather than raw command-output counts."
      : "No trace-count inconsistency detected. Persistent event count and unique signature count are aligned.",
    "",
    `7. developmentalClassification: ${canonicalClassification}`,
    `8. recommendation: ${recommendation}`,
    `9. pass/fail: ${allCoreStagesPresent ? "PASS" : "FAIL"}`,
  ].join("\\n");
}

