async function runAutonomousSession(cycles: number): Promise<string> {
  let currentState = await getMostRecentTrace();
  const results: AutonomousCycleResult[] = [];

  let startIndex = 0;
  const match = currentState.trajectorySignature.match(/T(\\d+)/);
  if (match && match[1]) startIndex = parseInt(match[1], 10);

  for (let i = 0; i < cycles; i++) {
    const nextIndex = startIndex + i + 1;
    const result = await runAutonomousCycle(nextIndex, currentState);
    results.push(result);
    currentState = result.generatedTrace;

    const curation = curateTrace(currentState);

    if (!result.continueLoop) {
      break;
    }
  }

  const finalState = currentState;
  const finalAudit = selfAuditTrace(finalState);
  const finalClassification =
    "autonomous-numogrammatic-development-initialized";

  const reportLines = [
    `BRIDGE PHASE XX RUN — AUTONOMOUS-${cycles}`,
    "",
    `Attempted ${cycles} cycles. Completed: ${results.length}`,
    "",
    "CYCLE BREAKDOWN:",
  ];

  for (const {
    cycleIndex,
    guidance,
    parameters,
    generatedTrace,
    audit,
    continueLoop,
  } of results) {
    reportLines.push(
      `\\n--- Cycle ${cycleIndex} ---`,
      `guidanceType: ${guidance.guidanceType} | risk: ${guidance.risk}`,
      `generatedParams -> transition: ${parameters.recommendedTransition}`,
      `resultTrace: ${generatedTrace.phaseClass} (${generatedTrace.trajectorySignature})`,
      `audit: ${audit.recommendedCorrection} (continue: ${continueLoop})`,
    );
  }

  reportLines.push(
    "",
    "OVERALL STATUS:",
    `finalTrace: ${finalState.trajectorySignature}`,
    `viabilityPreserved: ${finalAudit.shouldContinue}`,
    `developmentalClassification: ${finalClassification}`,
  );

  return reportLines.join("\\n");
}

