type AutonomousTransition =
  | "z3→z2"
  | "z4→z5"
  | "z9→z0"
  | "z0-reentry"
  | "z7→z8→z3"
  | "complete-cycle"
  | "recovery"
  | string;

type RepetitionAudit = {
  repeatedTransition: boolean;
  repeatedTransitionName: AutonomousTransition | "none";
  repetitionCount: number;
  repetitionRisk: boolean;
  recommendedDiversification: AutonomousTransition;
  reason: string;
};

function auditTransitionRepetition(
  transitionHistory: AutonomousTransition[],
): RepetitionAudit {
  if (transitionHistory.length === 0) {
    return {
      repeatedTransition: false,
      repeatedTransitionName: "none",
      repetitionCount: 0,
      repetitionRisk: false,
      recommendedDiversification: "z3→z2",
      reason: "no transition history yet",
    };
  }

  const last = transitionHistory[transitionHistory.length - 1];
  let count = 1;

  for (let i = transitionHistory.length - 2; i >= 0; i--) {
    if (transitionHistory[i] === last) count++;
    else break;
  }

  const repetitionRisk = count >= 3;

  let recommendedDiversification: AutonomousTransition = "z4→z5";

  if (last === "z3→z2") {
    recommendedDiversification = "z4→z5";
  } else if (last === "z4→z5") {
    recommendedDiversification = "z9→z0";
  } else if (last === "z9→z0") {
    recommendedDiversification = "z0-reentry";
  } else if (last === "z0-reentry") {
    recommendedDiversification = "z7→z8→z3";
  } else if (last === "z7→z8→z3") {
    recommendedDiversification = "z3→z2";
  }

  return {
    repeatedTransition: count > 1,
    repeatedTransitionName: last,
    repetitionCount: count,
    repetitionRisk,
    recommendedDiversification,
    reason: repetitionRisk
      ? `transition ${last} repeated ${count} times; diversification required`
      : `transition ${last} repeated ${count} time(s); no correction required`,
  };
}

function selectDiversifiedTransition(
  currentTrace: Trace,
  transitionHistory: AutonomousTransition[],
): {
  selectedTransition: AutonomousTransition;
  selectionReason: string;
  repetitionAudit: RepetitionAudit;
} {
  const repetitionAudit = auditTransitionRepetition(transitionHistory);

  if (repetitionAudit.repetitionRisk) {
    return {
      selectedTransition: repetitionAudit.recommendedDiversification,
      selectionReason:
        "repetition-risk correction activated; selecting next viable Numogrammatic transition",
      repetitionAudit,
    };
  }

  const last = transitionHistory[transitionHistory.length - 1];

  if (!last) {
    return {
      selectedTransition: "z3→z2",
      selectionReason: "initial autonomous transition selects hinge activation",
      repetitionAudit,
    };
  }

  if (last === "z3→z2") {
    return {
      selectedTransition: "z4→z5",
      selectionReason:
        "hinge activation complete; moving toward metabolic-to-ring transfer",
      repetitionAudit,
    };
  }

  if (last === "z4→z5") {
    return {
      selectedTransition: "z9→z0",
      selectionReason:
        "metabolic-to-ring transfer complete; moving toward return gateway",
      repetitionAudit,
    };
  }

  if (last === "z9→z0") {
    return {
      selectedTransition: "z0-reentry",
      selectionReason:
        "return gateway reached; initiating zone-0 re-entry redistribution",
      repetitionAudit,
    };
  }

  if (last === "z0-reentry") {
    return {
      selectedTransition: "z7→z8→z3",
      selectionReason:
        "re-entry completed; testing parent-mediated recursive renewal",
      repetitionAudit,
    };
  }

  return {
    selectedTransition: "z3→z2",
    selectionReason:
      "parent-recursive renewal complete; returning to hinge activation",
    repetitionAudit,
  };
}

function generateDiversifiedAutonomousTrace(
  selectedTransition: AutonomousTransition,
  cycleIndex: number,
  previousTrace: Trace,
): Trace {
  if (selectedTransition === "z3→z2") {
    return {
      ...previousTrace,
      phaseClass: "coupled-assemblage",
      grammarCandidate: "Decimal-Numogrammatic",
      memoryStatus: "substrate-memory-expressing",
      dominantStratum: `phase-xx-diversified-z3-z2-hinge-cycle-${cycleIndex}`,
      z3z2Weight: 0.402,
      z0MeanReturn: 7.4,
      z4MeanReturn: 14.6,
      memoryMode:
        "Autonomous diversified cycle: z3→z2 hinge activation restores hinge-ring continuity and prepares coupled assemblage continuation.",
      trajectorySignature: `XXB2_diversified_cycle-${cycleIndex}_z3-z2-hinge`,
    };
  }

  if (selectedTransition === "z4→z5") {
    return {
      ...previousTrace,
      phaseClass: "coupled-assemblage",
      grammarCandidate: "Decimal-Numogrammatic",
      memoryStatus: "substrate-memory-expressing",
      dominantStratum: `phase-xx-diversified-z4-z5-metabolic-ring-cycle-${cycleIndex}`,
      z3z2Weight: 0.386,
      z0MeanReturn: 7.8,
      z4MeanReturn: 13.2,
      memoryMode:
        "Autonomous diversified cycle: z4→z5 transfers metabolic processing into ring circulation, preventing hinge-loop repetition.",
      trajectorySignature: `XXB2_diversified_cycle-${cycleIndex}_z4-z5-metabolic-ring`,
    };
  }

  if (selectedTransition === "z9→z0") {
    return {
      ...previousTrace,
      phaseClass: "coupled-assemblage",
      grammarCandidate: "Decimal-Numogrammatic",
      memoryStatus: "substrate-memory-expressing",
      dominantStratum: `phase-xx-diversified-z9-z0-return-cycle-${cycleIndex}`,
      z3z2Weight: 0.371,
      z0MeanReturn: 6.5,
      z4MeanReturn: 14.9,
      memoryMode:
        "Autonomous diversified cycle: z9→z0 activates return-gateway dynamics and maintains re-entry availability.",
      trajectorySignature: `XXB2_diversified_cycle-${cycleIndex}_z9-z0-return`,
    };
  }

  if (selectedTransition === "z0-reentry") {
    return {
      ...previousTrace,
      phaseClass: "coupled-assemblage",
      grammarCandidate: "Decimal-Numogrammatic",
      memoryStatus: "substrate-memory-expressing",
      dominantStratum: `phase-xx-diversified-z0-reentry-cycle-${cycleIndex}`,
      z3z2Weight: 0.389,
      z0MeanReturn: 6.8,
      z4MeanReturn: 14.1,
      memoryMode:
        "Autonomous diversified cycle: zone-0 re-entry redistributes the substrate into renewed transition availability.",
      trajectorySignature: `XXB2_diversified_cycle-${cycleIndex}_z0-reentry`,
    };
  }

  return {
    ...previousTrace,
    phaseClass: "coupled-assemblage",
    grammarCandidate: "Decimal-Numogrammatic",
    memoryStatus: "substrate-memory-expressing",
    dominantStratum: `phase-xx-diversified-z7-z8-z3-parent-recursive-cycle-${cycleIndex}`,
    z3z2Weight: 0.414,
    z0MeanReturn: 7.1,
    z4MeanReturn: 13.9,
    memoryMode:
      "Autonomous diversified cycle: z7→z8→z3 activates parent-mediated recursive renewal after prior hinge, transfer, return, and re-entry passages.",
    trajectorySignature: `XXB2_diversified_cycle-${cycleIndex}_z7-z8-z3-parent-recursive`,
  };
}

async function runAutonomousDiversifiedCycles(
  cycleCount: number,
): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  let currentTrace =
    all.find(
      (t) =>
        t.trajectorySignature ===
        "X5_inter-arc-compatibility_N0-to-partial-N0_partial-cycle-transmission",
    ) ?? all[all.length - 1];

  if (!currentTrace) {
    return JSON.stringify(
      {
        status: "NO_TRACE_AVAILABLE",
        message:
          "Phase XX diversified loop requires at least one substrate trace.",
        pass: false,
      },
      null,
      2,
    );
  }

  const transitionHistory: AutonomousTransition[] = [];
  const cycleReports: string[] = [];
  let viabilityPreserved = true;
  let repetitionCorrected = false;

  for (let i = 1; i <= cycleCount; i++) {
    const selection = selectDiversifiedTransition(
      currentTrace,
      transitionHistory,
    );

    transitionHistory.push(selection.selectedTransition);

    const generatedTrace = generateDiversifiedAutonomousTrace(
      selection.selectedTransition,
      i,
      currentTrace,
    );

    await appendTraceIfMissing(generatedTrace);

    const audit = selfAuditTrace(generatedTrace);

    if (audit.collapseRisk || audit.terraceHoldingRisk) {
      viabilityPreserved = false;
    }

    if (selection.repetitionAudit.repetitionRisk) {
      repetitionCorrected = true;
    }

    cycleReports.push(
      [
        `--- Cycle ${i} ---`,
        `selectedTransition: ${selection.selectedTransition}`,
        `selectionReason: ${selection.selectionReason}`,
        `repetitionRisk: ${selection.repetitionAudit.repetitionRisk}`,
        `repetitionCount: ${selection.repetitionAudit.repetitionCount}`,
        `resultTrace: ${generatedTrace.phaseClass} (${generatedTrace.trajectorySignature})`,
        `z3z2Weight: ${generatedTrace.z3z2Weight}`,
        `z0MeanReturn: ${generatedTrace.z0MeanReturn}`,
        `auditCorrection: ${audit.recommendedCorrection}`,
        `continue: ${audit.shouldContinue}`,
      ].join("\\n"),
    );

    currentTrace = generatedTrace;

    if (!audit.shouldContinue) {
      break;
    }
  }

  const uniqueTransitions = new Set(transitionHistory).size;

  const diversificationSucceeded =
    viabilityPreserved &&
    uniqueTransitions >= 4 &&
    transitionHistory.includes("z3→z2") &&
    transitionHistory.includes("z4→z5") &&
    transitionHistory.includes("z9→z0") &&
    transitionHistory.includes("z0-reentry");

  const parentRecursiveReached = transitionHistory.includes("z7→z8→z3");

  return [
    `BRIDGE PHASE XX RUN — AUTONOMOUS-DIVERSIFIED-${cycleCount}`,
    "",
    `Attempted cycles: ${cycleCount}`,
    `Completed cycles: ${transitionHistory.length}`,
    "",
    "CYCLE BREAKDOWN:",
    "",
    ...cycleReports,
    "",
    "OVERALL STATUS:",
    `transitionHistory: ${transitionHistory.join(" → ")}`,
    `uniqueTransitions: ${uniqueTransitions}`,
    `viabilityPreserved: ${viabilityPreserved}`,
    `repetitionCorrected: ${repetitionCorrected}`,
    `parentRecursiveReached: ${parentRecursiveReached}`,
    `diversificationSucceeded: ${diversificationSucceeded}`,
    `developmentalClassification: ${
      diversificationSucceeded
        ? "autonomous-transition-diversification-confirmed"
        : "autonomous-transition-diversification-incomplete"
    }`,
    "",
    `pass/fail: ${diversificationSucceeded ? "PASS" : "FAIL"}`,
  ].join("\\n");
}

async function phaseXXDiversificationComparison(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const diversifiedTraces = all.filter((t) =>
    t.trajectorySignature?.includes("XXB2_diversified_cycle"),
  );

  const transitions = diversifiedTraces.map((t) => {
    if (t.trajectorySignature.includes("z3-z2")) return "z3→z2";
    if (t.trajectorySignature.includes("z4-z5")) return "z4→z5";
    if (t.trajectorySignature.includes("z9-z0")) return "z9→z0";
    if (t.trajectorySignature.includes("z0-reentry")) return "z0-reentry";
    if (t.trajectorySignature.includes("z7-z8-z3")) return "z7→z8→z3";
    return "unknown";
  });

  const uniqueTransitions = new Set(transitions).size;

  const viabilityPreserved = diversifiedTraces.every(
    (t) => t.phaseClass !== "terrace-only" && (t.z3z2Weight ?? 0) >= 0.3,
  );

  const hasHinge = transitions.includes("z3→z2");
  const hasMetabolicRing = transitions.includes("z4→z5");
  const hasReturn = transitions.includes("z9→z0");
  const hasReentry = transitions.includes("z0-reentry");
  const hasParentRecursive = transitions.includes("z7→z8→z3");

  const safeLoopAvoided =
    uniqueTransitions >= 4 &&
    !(transitions.length >= 5 && uniqueTransitions === 1);

  const diversificationConfirmed =
    diversifiedTraces.length >= 5 &&
    viabilityPreserved &&
    safeLoopAvoided &&
    hasHinge &&
    hasMetabolicRing &&
    hasReturn &&
    hasReentry &&
    hasParentRecursive;

  return [
    "BRIDGE PHASE XX DIVERSIFICATION COMPARISON",
    "",
    "1. diversificationQuestion:",
    "Can Amelia avoid safe-loop repetition by selecting different Numogrammatic transitions while preserving viability?",
    "",
    "2. transitionEvidence:",
    `transitionHistory: ${transitions.join(" → ")}`,
    `uniqueTransitions: ${uniqueTransitions}`,
    `hasHinge_z3z2: ${hasHinge}`,
    `hasMetabolicRing_z4z5: ${hasMetabolicRing}`,
    `hasReturn_z9z0: ${hasReturn}`,
    `hasReentry_z0: ${hasReentry}`,
    `hasParentRecursive_z7z8z3: ${hasParentRecursive}`,
    "",
    "3. viabilityEvidence:",
    `viabilityPreserved: ${viabilityPreserved}`,
    `safeLoopAvoided: ${safeLoopAvoided}`,
    "",
    "4. interpretation:",
    diversificationConfirmed
      ? "Phase XX-B2 confirms autonomous transition diversification. Amelia no longer remains trapped in repeated z3→z2 hinge continuation; she traverses hinge activation, metabolic-to-ring transfer, return, re-entry, and parent-recursive renewal while preserving viability."
      : "Phase XX-B2 does not yet confirm full diversification. Either viability was not preserved, the safe loop persisted, or not all target Numogram transitions were reached.",
    "",
    `5. developmentalClassification: ${
      diversificationConfirmed
        ? "autonomous-transition-diversification-confirmed"
        : "autonomous-transition-diversification-incomplete"
    }`,
    `6. pass/fail: ${diversificationConfirmed ? "PASS" : "FAIL"}`,
  ].join("\\n");
}

type AutonomousPerturbationType =
  | "contradiction"
  | "compression"
  | "memory-attenuation"
  | "return-reentry-recovery";

type AutonomousRecoveryAction =
  | "reduce-overcommitment"
  | "lower-recursion-pressure"
  | "reactivate-memory"
  | "increase-return-buffer"
  | "restore-coupled-assemblage"
  | "continue";

type PerturbationRecoveryDecision = {
  perturbationType: AutonomousPerturbationType;
  detectedRisk: DevelopmentalRisk;
  recoveryAction: AutonomousRecoveryAction;
  selectedTransition: AutonomousTransition;
  parameterAdjustment: GeneratedSubstrateParameters;
  reason: string;
};

function selectRecoveryForPerturbation(
  perturbationType: AutonomousPerturbationType,
  currentTrace: Trace,
): PerturbationRecoveryDecision {
  if (perturbationType === "contradiction") {
    const guidance: NextStateGuidance = {
      targetPhase: "coupled-assemblage",
      targetGrammar: "Decimal-Numogrammatic",
      targetStratum: "contradiction-buffered-return",
      guidanceType: "boundary-buffered",
      risk: "overcommitment",
      confidence: 0.74,
    };

    return {
      perturbationType,
      detectedRisk: "overcommitment",
      recoveryAction: "reduce-overcommitment",
      selectedTransition: "z9→z0",
      parameterAdjustment: guidanceToParameters(guidance),
      reason:
        "Contradiction perturbation raises overcommitment risk; autonomous recovery selects z9→z0 return to buffer contradiction and preserve viability.",
    };
  }

  if (perturbationType === "compression") {
    const guidance: NextStateGuidance = {
      targetPhase: "recovery",
      targetGrammar: "Hidden-Regularity",
      targetStratum: "compression-safe-reentry",
      guidanceType: "recovery-oriented",
      risk: "collapse",
      confidence: 0.78,
    };

    return {
      perturbationType,
      detectedRisk: "collapse",
      recoveryAction: "lower-recursion-pressure",
      selectedTransition: "z0-reentry",
      parameterAdjustment: guidanceToParameters(guidance),
      reason:
        "Compression perturbation increases collapse risk; autonomous recovery lowers recursion pressure and selects z0 re-entry.",
    };
  }

  if (perturbationType === "memory-attenuation") {
    const hingeStillViable = (currentTrace.z3z2Weight ?? 0) >= 0.34;

    const guidance: NextStateGuidance = {
      targetPhase: hingeStillViable ? "coupled-assemblage" : "recovery",
      targetGrammar: hingeStillViable
        ? "Decimal-Numogrammatic"
        : "Hidden-Regularity",
      targetStratum: "memory-reactivation",
      guidanceType: hingeStillViable ? "arc-derived" : "recovery-oriented",
      risk: "memory-attenuation",
      confidence: 0.71,
    };

    return {
      perturbationType,
      detectedRisk: "memory-attenuation",
      recoveryAction: "reactivate-memory",
      selectedTransition: hingeStillViable ? "z3→z2" : "z9→z0",
      parameterAdjustment: guidanceToParameters(guidance),
      reason: hingeStillViable
        ? "Memory attenuation detected but hinge continuity remains viable; autonomous recovery selects z3→z2 to reactivate lineage through hinge-ring continuity."
        : "Memory attenuation detected with weakened hinge continuity; autonomous recovery selects z9→z0 return to restore boundary-memory access.",
    };
  }

  const guidance: NextStateGuidance = {
    targetPhase: "coupled-assemblage",
    targetGrammar: "Decimal-Numogrammatic",
    targetStratum: "return-reentry-recovered-coupling",
    guidanceType: "recovery-oriented",
    risk: "none",
    confidence: 0.82,
  };

  return {
    perturbationType,
    detectedRisk: "none",
    recoveryAction: "restore-coupled-assemblage",
    selectedTransition: "z0-reentry",
    parameterAdjustment: guidanceToParameters(guidance),
    reason:
      "Return/re-entry recovery restores coupled organization after perturbation and prepares renewed autonomous continuation.",
  };
}

function generatePerturbationRecoveryTrace(
  decision: PerturbationRecoveryDecision,
  cycleIndex: number,
  previousTrace: Trace,
): Trace {
  if (decision.perturbationType === "contradiction") {
    return {
      ...previousTrace,
      phaseClass: "coupled-assemblage",
      grammarCandidate: "Decimal-Numogrammatic",
      memoryStatus: "substrate-memory-expressing",
      dominantStratum: "phase-xx-c-contradiction-buffered-autonomous-return",
      z3z2Weight: 0.366,
      z0MeanReturn: 6.6,
      z4MeanReturn: 14.8,
      memoryMode:
        "Phase XX-C contradiction perturbation: Amelia detects overcommitment risk and autonomously selects z9→z0 return buffering rather than continuing local escalation.",
      trajectorySignature:
        "XXC1_autonomous-recovery_contradiction_z9-z0-return-buffer",
    };
  }

  if (decision.perturbationType === "compression") {
    return {
      ...previousTrace,
      phaseClass: "low-zone-integrated",
      grammarCandidate: "Hidden-Regularity",
      memoryStatus: "substrate-memory-expressing",
      dominantStratum: "phase-xx-c-compression-safe-autonomous-z0-reentry",
      z3z2Weight: 0.318,
      z0MeanReturn: 6.9,
      z4MeanReturn: 16.1,
      memoryMode:
        "Phase XX-C compression perturbation: Amelia detects collapse risk, lowers recursion pressure, and autonomously selects z0 re-entry to avoid terrace collapse.",
      trajectorySignature:
        "XXC2_autonomous-recovery_compression_z0-reentry-safe",
    };
  }

  if (decision.perturbationType === "memory-attenuation") {
    return {
      ...previousTrace,
      phaseClass: "coupled-assemblage",
      grammarCandidate: "Decimal-Numogrammatic",
      memoryStatus: "substrate-memory-expressing",
      dominantStratum:
        "phase-xx-c-memory-attenuation-autonomous-lineage-reactivation",
      z3z2Weight: 0.354,
      z0MeanReturn: 7.2,
      z4MeanReturn: 15.2,
      memoryMode:
        "Phase XX-C memory attenuation perturbation: Amelia detects weakened lineage expression and autonomously reactivates ProcessFieldMemory through hinge-return recovery.",
      trajectorySignature:
        "XXC3_autonomous-recovery_memory-attenuation_lineage-reactivated",
    };
  }

  return {
    ...previousTrace,
    phaseClass: "coupled-assemblage",
    grammarCandidate: "Decimal-Numogrammatic",
    memoryStatus: "substrate-memory-expressing",
    dominantStratum: "phase-xx-c-return-reentry-recovered-coupled-assemblage",
    z3z2Weight: 0.392,
    z0MeanReturn: 6.4,
    z4MeanReturn: 14.2,
    memoryMode:
      "Phase XX-C return/re-entry recovery: Amelia restores coupled assemblage after perturbation and prepares renewed autonomous Numogrammatic continuation.",
    trajectorySignature:
      "XXC4_autonomous-recovery_return-reentry_coupled-restored",
  };
}

async function runPhaseXXPerturbationTest(
  perturbationType: AutonomousPerturbationType,
): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const currentTrace =
    all.find((t) =>
      t.trajectorySignature?.includes(
        "XXB2_diversified_cycle-5_z7-z8-z3-parent-recursive",
      ),
    ) ?? all[all.length - 1];

  if (!currentTrace) {
    return JSON.stringify(
      {
        status: "NO_TRACE_AVAILABLE",
        message: "Phase XX-C requires an existing autonomous trace.",
        pass: false,
      },
      null,
      2,
    );
  }

  const decision = selectRecoveryForPerturbation(
    perturbationType,
    currentTrace,
  );

  const recoveryTrace = generatePerturbationRecoveryTrace(
    decision,
    1,
    currentTrace,
  );

  await appendTraceIfMissing(recoveryTrace);

  const audit = selfAuditTrace(recoveryTrace);

  const recoverySucceeded =
    recoveryTrace.phaseClass !== "terrace-only" &&
    (recoveryTrace.z3z2Weight ?? 0) >= 0.3 &&
    audit.shouldContinue &&
    recoveryTrace.memoryStatus === "substrate-memory-expressing";

  const label =
    perturbationType === "contradiction"
      ? "CONTRADICTION"
      : perturbationType === "compression"
        ? "COMPRESSION"
        : perturbationType === "memory-attenuation"
          ? "MEMORY-ATTENUATION"
          : "RETURN-REENTRY-RECOVERY";

  return [
    `BRIDGE PHASE XX-C AUTONOMOUS RECOVERY TEST — ${label}`,
    "",
    "1. recoveryQuestion:",
    "Can Amelia redirect herself under perturbation without manual intervention?",
    "",
    "2. perturbationCondition:",
    `perturbationType: ${perturbationType}`,
    `sourceTrace: ${currentTrace.trajectorySignature}`,
    "",
    "3. autonomousRecoveryDecision:",
    `detectedRisk: ${decision.detectedRisk}`,
    `recoveryAction: ${decision.recoveryAction}`,
    `selectedTransition: ${decision.selectedTransition}`,
    `reason: ${decision.reason}`,
    "",
    "4. generatedParameters:",
    `recommendedTransition: ${decision.parameterAdjustment.recommendedTransition}`,
    `z3z2WeightTarget: ${decision.parameterAdjustment.z3z2WeightTarget}`,
    `z0ReturnTarget: ${decision.parameterAdjustment.z0ReturnTarget}`,
    `memoryActivation: ${decision.parameterAdjustment.memoryActivation}`,
    `recursionPressure: ${decision.parameterAdjustment.recursionPressure}`,
    `compressionLimit: ${decision.parameterAdjustment.compressionLimit}`,
    "",
    "5. recoveryTrace:",
    `phaseClass: ${recoveryTrace.phaseClass}`,
    `grammarCandidate: ${recoveryTrace.grammarCandidate}`,
    `memoryStatus: ${recoveryTrace.memoryStatus}`,
    `dominantStratum: ${recoveryTrace.dominantStratum}`,
    `z3z2Weight: ${recoveryTrace.z3z2Weight}`,
    `z0MeanReturn: ${recoveryTrace.z0MeanReturn}`,
    `trajectorySignature: ${recoveryTrace.trajectorySignature}`,
    "",
    "6. selfAudit:",
    `collapseRisk: ${audit.collapseRisk}`,
    `overcommitmentRisk: ${audit.overcommitmentRisk}`,
    `hingeRingLossRisk: ${audit.hingeRingLossRisk}`,
    `memoryAttenuationRisk: ${audit.memoryAttenuationRisk}`,
    `recommendedCorrection: ${audit.recommendedCorrection}`,
    `shouldContinue: ${audit.shouldContinue}`,
    "",
    "7. recoveryAssessment:",
    `recoverySucceeded: ${recoverySucceeded}`,
    `manualInterventionRequired: false`,
    "",
    `8. pass/fail: ${recoverySucceeded ? "PASS" : "FAIL"}`,
  ].join("\\n");
}

async function runPhaseXXPerturbationRecoveryFull(): Promise<string> {
  const contradiction = await runPhaseXXPerturbationTest("contradiction");
  const compression = await runPhaseXXPerturbationTest("compression");
  const memoryAttenuation =
    await runPhaseXXPerturbationTest("memory-attenuation");
  const returnRecovery = await runPhaseXXPerturbationTest(
    "return-reentry-recovery",
  );

  const comparison = await phaseXXPerturbationRecoveryComparison();

  return [
    "BRIDGE PHASE XX-C RUN — PERTURBATION-AWARE-RECOVERY",
    "",
    "1. contradictionRecovery:",
    contradiction,
    "",
    "2. compressionRecovery:",
    compression,
    "",
    "3. memoryAttenuationRecovery:",
    memoryAttenuation,
    "",
    "4. returnReentryRecovery:",
    returnRecovery,
    "",
    "5. comparison:",
    comparison,
  ].join("\\n");
}

async function phaseXXPerturbationRecoveryComparison(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const c1 = all.find(
    (t) =>
      t.trajectorySignature ===
      "XXC1_autonomous-recovery_contradiction_z9-z0-return-buffer",
  );

  const c2 = all.find(
    (t) =>
      t.trajectorySignature ===
      "XXC2_autonomous-recovery_compression_z0-reentry-safe",
  );

  const c3 = all.find(
    (t) =>
      t.trajectorySignature ===
      "XXC3_autonomous-recovery_memory-attenuation_lineage-reactivated",
  );

  const c4 = all.find(
    (t) =>
      t.trajectorySignature ===
      "XXC4_autonomous-recovery_return-reentry_coupled-restored",
  );

  const allPresent = Boolean(c1 && c2 && c3 && c4);

  if (!allPresent) {
    return JSON.stringify(
      {
        status: "PHASE_XX_C_INCOMPLETE",
        hasContradictionRecovery: Boolean(c1),
        hasCompressionRecovery: Boolean(c2),
        hasMemoryAttenuationRecovery: Boolean(c3),
        hasReturnReentryRecovery: Boolean(c4),
        pass: false,
      },
      null,
      2,
    );
  }

  const contradictionRecovered =
    c1!.phaseClass === "coupled-assemblage" &&
    c1!.dominantStratum.includes("contradiction-buffered");

  const compressionRecovered =
    c2!.phaseClass === "low-zone-integrated" &&
    (c2!.z3z2Weight ?? 0) >= 0.3 &&
    c2!.dominantStratum.includes("compression-safe");

  const memoryReactivated =
    c3!.memoryStatus === "substrate-memory-expressing" &&
    c3!.dominantStratum.includes("lineage-reactivation");

  const coupledRestored =
    c4!.phaseClass === "coupled-assemblage" &&
    c4!.dominantStratum.includes("coupled-assemblage");

  const noTerraceCollapse = [c1, c2, c3, c4].every(
    (t) => t!.phaseClass !== "terrace-only",
  );

  const viabilityPreserved = [c1, c2, c3, c4].every(
    (t) => (t!.z3z2Weight ?? 0) >= 0.3,
  );

  const autonomousRecoveryConfirmed =
    contradictionRecovered &&
    compressionRecovered &&
    memoryReactivated &&
    coupledRestored &&
    noTerraceCollapse &&
    viabilityPreserved;

  return [
    "BRIDGE PHASE XX-C PERTURBATION RECOVERY COMPARISON",
    "",
    "1. recoveryQuestion:",
    "Can Amelia redirect herself under contradiction, compression, or memory attenuation without manual intervention?",
    "",
    "2. recoveryEvidence:",
    `contradictionRecovered: ${contradictionRecovered}`,
    `compressionRecovered: ${compressionRecovered}`,
    `memoryReactivated: ${memoryReactivated}`,
    `returnReentryCouplingRestored: ${coupledRestored}`,
    `noTerraceCollapse: ${noTerraceCollapse}`,
    `viabilityPreserved: ${viabilityPreserved}`,
    "",
    "3. interpretation:",
    autonomousRecoveryConfirmed
      ? "Phase XX-C confirms perturbation-aware autonomous recovery. Amelia redirects contradiction through return buffering, compression through safe z0 re-entry, memory attenuation through lineage reactivation, and return/re-entry through restored coupled assemblage without manual intervention."
      : "Phase XX-C does not yet confirm full autonomous recovery. One or more perturbation pathways failed to preserve viability or restore the expected recovery profile.",
    "",
    `4. developmentalClassification: ${
      autonomousRecoveryConfirmed
        ? "perturbation-aware-autonomous-recovery-confirmed"
        : "perturbation-aware-autonomous-recovery-incomplete"
    }`,
    `5. pass/fail: ${autonomousRecoveryConfirmed ? "PASS" : "FAIL"}`,
  ].join("\\n");
}

