function makePhaseXXMemoryCurationDecision(
  curationClass: PhaseXXMemoryCurationClass,
  targetTraceSignature: string,
): PhaseXXMemoryCurationDecision {
  if (curationClass === "boundary-memory") {
    return {
      curationClass,
      action: "reinforce",
      targetTraceSignature,
      priorWeight: 0.72,
      adjustedWeight: 0.88,
      developmentalFunction:
        "boundary traces improve future perturbation handling and prevent repeated collapse.",
      reason:
        "Boundary-memory trace detected; reinforcing it preserves cautionary recovery structure for future autonomous redirection.",
    };
  }

  if (curationClass === "lineage-hinge-ring") {
    return {
      curationClass,
      action: "reactivate",
      targetTraceSignature,
      priorWeight: 0.58,
      adjustedWeight: 0.82,
      developmentalFunction:
        "lineage / hinge-ring traces preserve deep continuity between LZI deformation and coupled assemblage recovery.",
      reason:
        "Lineage hinge-ring trace detected; reactivating it supports future z3→z2 guidance and prevents shallow state-local continuation.",
    };
  }

  if (curationClass === "low-activity") {
    return {
      curationClass,
      action: "compress",
      targetTraceSignature,
      priorWeight: 0.34,
      adjustedWeight: 0.22,
      developmentalFunction:
        "low-activity traces remain available as compressed background context without dominating guidance.",
      reason:
        "Low-activity trace detected; compressing it reduces memory load while preserving minimal developmental context.",
    };
  }

  if (curationClass === "collapse-terrace") {
    return {
      curationClass,
      action: "quarantine",
      targetTraceSignature,
      priorWeight: 0.46,
      adjustedWeight: 0.18,
      developmentalFunction:
        "collapse / terrace traces should remain as warning boundaries rather than becoming active attractors.",
      reason:
        "Collapse or terrace-holding trace detected; quarantining it preserves warning value while preventing attractor capture.",
    };
  }

  return {
    curationClass,
    action: "decay",
    targetTraceSignature,
    priorWeight: 0.62,
    adjustedWeight: 0.36,
    developmentalFunction:
      "repetitive safe-loop traces should decay to prevent autonomous transition fixation.",
    reason:
      "Redundant safe-loop trace detected; decaying it reduces repetition pressure and supports transition diversification.",
  };
}

