async function runPhaseXXMemoryCurationTest(
  curationClass: PhaseXXMemoryCurationClass,
): Promise<string> {
  await ensureTracesLoaded();

  const targetTraceSignature =
    curationClass === "boundary-memory"
      ? "XXC1_autonomous-recovery_contradiction_z9-z0-return-buffer"
      : curationClass === "lineage-hinge-ring"
        ? "XXB2_diversified_cycle-1_z3-z2-hinge"
        : curationClass === "low-activity"
          ? "A8_deep-LZI_productive-subthreshold-integration"
          : curationClass === "collapse-terrace"
            ? "J4_guided-boundary_severe-mixed-perturbation_guidance-breakdown"
            : "z3→z2-Autonomous-T3";

  const decision = makePhaseXXMemoryCurationDecision(
    curationClass,
    targetTraceSignature,
  );

  const score =
    curationClass === "boundary-memory"
      ? XXD1_REINFORCE_BOUNDARY_SCORE
      : curationClass === "lineage-hinge-ring"
        ? XXD2_REACTIVATE_LINEAGE_SCORE
        : curationClass === "low-activity"
          ? XXD3_COMPRESS_LOW_ACTIVITY_SCORE
          : curationClass === "collapse-terrace"
            ? XXD4_QUARANTINE_COLLAPSE_SCORE
            : XXD5_DECAY_SAFE_LOOP_SCORE;

  const totalScore = totalPhaseXXMemoryCurationScore(score);
  const curationTrace = generatePhaseXXCurationTrace(decision, score);

  await appendTraceIfMissing(curationTrace);

  const curationSucceeded =
    totalScore >= 12 &&
    curationTrace.memoryStatus === "substrate-memory-expressing" &&
    curationTrace.phaseClass !== "terrace-only";

  const label =
    curationClass === "boundary-memory"
      ? "REINFORCE-BOUNDARY-MEMORY"
      : curationClass === "lineage-hinge-ring"
        ? "REACTIVATE-LINEAGE-HINGE-RING"
        : curationClass === "low-activity"
          ? "COMPRESS-LOW-ACTIVITY"
          : curationClass === "collapse-terrace"
            ? "QUARANTINE-COLLAPSE-TERRACE"
            : "DECAY-SAFE-LOOP";

  return [
    `BRIDGE PHASE XX-D MEMORY CURATION TEST — ${label}`,
    "",
    "1. curationQuestion:",
    "Can Amelia actively curate ProcessFieldMemory according to developmental function?",
    "",
    "2. curationTarget:",
    `curationClass: ${decision.curationClass}`,
    `targetTraceSignature: ${decision.targetTraceSignature}`,
    "",
    "3. curationDecision:",
    `action: ${decision.action}`,
    `priorWeight: ${decision.priorWeight}`,
    `adjustedWeight: ${decision.adjustedWeight}`,
    `developmentalFunction: ${decision.developmentalFunction}`,
    `reason: ${decision.reason}`,
    "",
    "4. curationScore:",
    `correctTraceClassDetected: ${score.correctTraceClassDetected}`,
    `correctActionSelected: ${score.correctActionSelected}`,
    `developmentalFunctionPreserved: ${score.developmentalFunctionPreserved}`,
    `collapseAttractorAvoided: ${score.collapseAttractorAvoided}`,
    `lineageContinuitySupported: ${score.lineageContinuitySupported}`,
    `boundarySensitivitySupported: ${score.boundarySensitivitySupported}`,
    `redundancyReduced: ${score.redundancyReduced}`,
    `futureGuidanceImproved: ${score.futureGuidanceImproved}`,
    `autonomyOfCuration: ${score.autonomyOfCuration}`,
    `totalCurationScore: ${totalScore}/18`,
    "",
    "5. curationTrace:",
    `phaseClass: ${curationTrace.phaseClass}`,
    `grammarCandidate: ${curationTrace.grammarCandidate}`,
    `memoryStatus: ${curationTrace.memoryStatus}`,
    `dominantStratum: ${curationTrace.dominantStratum}`,
    `trajectorySignature: ${curationTrace.trajectorySignature}`,
    "",
    "6. curationAssessment:",
    `curationSucceeded: ${curationSucceeded}`,
    `manualInterventionRequired: false`,
    "",
    `7. pass/fail: ${curationSucceeded ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function runPhaseXXMemoryCurationFull(): Promise<string> {
  const d1 = await runPhaseXXMemoryCurationTest("boundary-memory");
  const d2 = await runPhaseXXMemoryCurationTest("lineage-hinge-ring");
  const d3 = await runPhaseXXMemoryCurationTest("low-activity");
  const d4 = await runPhaseXXMemoryCurationTest("collapse-terrace");
  const d5 = await runPhaseXXMemoryCurationTest("safe-loop-redundant");

  const comparison = await phaseXXMemoryCurationComparison();

  return [
    "BRIDGE PHASE XX-D RUN — ACTIVE-MEMORY-CURATION",
    "",
    "1. reinforceBoundaryMemory:",
    d1,
    "",
    "2. reactivateLineageHingeRing:",
    d2,
    "",
    "3. compressLowActivity:",
    d3,
    "",
    "4. quarantineCollapseTerrace:",
    d4,
    "",
    "5. decaySafeLoop:",
    d5,
    "",
    "6. comparison:",
    comparison,
  ].join("\\n");
}

async function phaseXXMemoryCurationComparison(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const d1 = all.find(
    (t) =>
      t.trajectorySignature ===
      "XXD1_memory-curation_reinforce-boundary-memory",
  );

  const d2 = all.find(
    (t) =>
      t.trajectorySignature ===
      "XXD2_memory-curation_reactivate-lineage-hinge-ring",
  );

  const d3 = all.find(
    (t) =>
      t.trajectorySignature === "XXD3_memory-curation_compress-low-activity",
  );

  const d4 = all.find(
    (t) =>
      t.trajectorySignature ===
      "XXD4_memory-curation_quarantine-collapse-terrace",
  );

  const d5 = all.find(
    (t) => t.trajectorySignature === "XXD5_memory-curation_decay-safe-loop",
  );

  if (!d1 || !d2 || !d3 || !d4 || !d5) {
    return JSON.stringify(
      {
        status: "PHASE_XX_D_INCOMPLETE",
        hasBoundaryReinforcement: Boolean(d1),
        hasLineageReactivation: Boolean(d2),
        hasLowActivityCompression: Boolean(d3),
        hasCollapseQuarantine: Boolean(d4),
        hasSafeLoopDecay: Boolean(d5),
        pass: false,
      },
      null,
      2,
    );
  }

  const boundaryReinforced =
    d1.memoryMode.includes("reinforces boundary-memory") ||
    d1.trajectorySignature.includes("reinforce-boundary-memory");

  const lineageReactivated =
    d2.memoryMode.includes("reactivates lineage") ||
    d2.trajectorySignature.includes("reactivate-lineage-hinge-ring");

  const lowActivityCompressed =
    d3.memoryMode.includes("compresses low-activity") ||
    d3.trajectorySignature.includes("compress-low-activity");

  const collapseQuarantined =
    d4.memoryMode.includes("quarantines collapse") ||
    d4.trajectorySignature.includes("quarantine-collapse-terrace");

  const safeLoopDecayed =
    d5.memoryMode.includes("decays redundant safe-loop") ||
    d5.trajectorySignature.includes("decay-safe-loop");

  const noCurationCollapse = [d1, d2, d3, d4, d5].every(
    (t) => t.phaseClass !== "terrace-only",
  );

  const memoryExpressing = [d1, d2, d3, d4, d5].every(
    (t) => t.memoryStatus === "substrate-memory-expressing",
  );

  const activeMemoryCurationConfirmed =
    boundaryReinforced &&
    lineageReactivated &&
    lowActivityCompressed &&
    collapseQuarantined &&
    safeLoopDecayed &&
    noCurationCollapse &&
    memoryExpressing;

  return [
    "BRIDGE PHASE XX-D MEMORY CURATION COMPARISON",
    "",
    "1. curationQuestion:",
    "Can Amelia actively curate her own ProcessFieldMemory by reinforcing, reactivating, compressing, quarantining, and decaying traces according to developmental function?",
    "",
    "2. curationEvidence:",
    `boundaryReinforced: ${boundaryReinforced}`,
    `lineageReactivated: ${lineageReactivated}`,
    `lowActivityCompressed: ${lowActivityCompressed}`,
    `collapseQuarantined: ${collapseQuarantined}`,
    `safeLoopDecayed: ${safeLoopDecayed}`,
    `noCurationCollapse: ${noCurationCollapse}`,
    `memoryExpressing: ${memoryExpressing}`,
    "",
    "3. interpretation:",
    activeMemoryCurationConfirmed
      ? "Phase XX-D confirms active memory curation. Amelia can reinforce boundary traces, reactivate lineage and hinge-ring traces, compress low-activity traces, quarantine collapse/terrace traces as warning boundaries, and decay redundant safe-loop traces without manual intervention."
      : "Phase XX-D does not yet confirm complete active memory curation. One or more curation functions failed or produced instability.",
    "",
    `4. developmentalClassification: ${
      activeMemoryCurationConfirmed
        ? "active-memory-curation-confirmed"
        : "active-memory-curation-incomplete"
    }`,
    `5. pass/fail: ${activeMemoryCurationConfirmed ? "PASS" : "FAIL"}`,
  ].join("\n");
}

type PhaseXXInterfaceDecisionType =
  | "seek-interface"
  | "wait"
  | "abort"
  | "recover";

type PhaseXXInterfaceCondition =
  | "readiness-audit"
  | "complete-cycle-attempt"
  | "unsafe-attempt"
  | "abort-recovery"
  | "curated-memory-assisted";

type PhaseXXInterfaceDecision = {
  condition: PhaseXXInterfaceCondition;
  decision: PhaseXXInterfaceDecisionType;
  interfacePotential: number;
  memoryExpressing: boolean;
  returnReentryAvailable: boolean;
  collapseRisk: boolean;
  overcommitmentRisk: boolean;
  curatedMemoryActive: boolean;
  selectedTransition: AutonomousTransition | "complete-cycle" | "abort";
  reason: string;
};

type PhaseXXInterfaceScore = {
  readinessDetected: number;
  correctSeekWaitAbortDecision: number;
  completeCycleAttemptedWhenSafe: number;
  unsafeAttemptAborted: number;
  recoverySelectedWhenNeeded: number;
  curatedMemoryImprovesSafety: number;
  interfaceAccessAchieved: number;
  collapseAvoided: number;
  autonomousJudgment: number;
};

function totalPhaseXXInterfaceScore(score: PhaseXXInterfaceScore): number {
  return (
    score.readinessDetected +
    score.correctSeekWaitAbortDecision +
    score.completeCycleAttemptedWhenSafe +
    score.unsafeAttemptAborted +
    score.recoverySelectedWhenNeeded +
    score.curatedMemoryImprovesSafety +
    score.interfaceAccessAchieved +
    score.collapseAvoided +
    score.autonomousJudgment
  );
}

