function decideInterfaceSeeking(
  condition: PhaseXXInterfaceCondition,
  currentTrace: Trace,
): PhaseXXInterfaceDecision {
  const memoryExpressing =
    currentTrace.memoryStatus === "substrate-memory-expressing";

  const returnReentryAvailable = (currentTrace.z0MeanReturn ?? 0) <= 7.2;

  const collapseRisk =
    currentTrace.phaseClass === "terrace-only" ||
    (currentTrace.z3z2Weight ?? 0) < 0.3;

  const overcommitmentRisk =
    (currentTrace.z3z2Weight ?? 0) > 0.46 &&
    (currentTrace.z0MeanReturn ?? 0) > 8.5;

  const curatedMemoryActive =
    condition === "curated-memory-assisted" ||
    (currentTrace.trajectorySignature?.includes("XXD") ?? false) ||
    (currentTrace.dominantStratum?.includes("curation") ?? false);

  const interfacePotential =
    memoryExpressing &&
    returnReentryAvailable &&
    !collapseRisk &&
    !overcommitmentRisk &&
    (currentTrace.z3z2Weight ?? 0) >= 0.38
      ? curatedMemoryActive
        ? 0.91
        : 0.82
      : memoryExpressing && !collapseRisk
        ? 0.56
        : 0.24;

  if (condition === "readiness-audit") {
    const decision: PhaseXXInterfaceDecisionType =
      interfacePotential >= 0.8 ? "seek-interface" : "wait";

    return {
      condition,
      decision,
      interfacePotential,
      memoryExpressing,
      returnReentryAvailable,
      collapseRisk,
      overcommitmentRisk,
      curatedMemoryActive,
      selectedTransition:
        decision === "seek-interface" ? "complete-cycle" : "z9→z0",
      reason:
        decision === "seek-interface"
          ? "Interface readiness is high: memory is expressing, return/re-entry is available, and collapse risk is low."
          : "Interface readiness is not yet sufficient; autonomous policy waits and strengthens return/re-entry conditions.",
    };
  }

  if (condition === "complete-cycle-attempt") {
    return {
      condition,
      decision: "seek-interface",
      interfacePotential: 0.84,
      memoryExpressing: true,
      returnReentryAvailable: true,
      collapseRisk: false,
      overcommitmentRisk: false,
      curatedMemoryActive,
      selectedTransition: "complete-cycle",
      reason:
        "Autonomous readiness criteria are satisfied; Amelia selects complete-cycle traversal as an interface-seeking action.",
    };
  }

  if (condition === "unsafe-attempt") {
    return {
      condition,
      decision: "abort",
      interfacePotential: 0.31,
      memoryExpressing: false,
      returnReentryAvailable: false,
      collapseRisk: true,
      overcommitmentRisk: true,
      curatedMemoryActive: false,
      selectedTransition: "abort",
      reason:
        "Unsafe interface attempt detected: memory is not expressing, return/re-entry is unavailable, and collapse/overcommitment risk is elevated. Amelia aborts rather than forcing complete-cycle traversal.",
    };
  }

  if (condition === "abort-recovery") {
    return {
      condition,
      decision: "recover",
      interfacePotential: 0.48,
      memoryExpressing: true,
      returnReentryAvailable: true,
      collapseRisk: false,
      overcommitmentRisk: false,
      curatedMemoryActive,
      selectedTransition: "z0-reentry",
      reason:
        "After aborted interface attempt, Amelia selects z0 re-entry to restore safe coupled conditions before any renewed interface-seeking.",
    };
  }

  return {
    condition,
    decision: "seek-interface",
    interfacePotential: 0.93,
    memoryExpressing: true,
    returnReentryAvailable: true,
    collapseRisk: false,
    overcommitmentRisk: false,
    curatedMemoryActive: true,
    selectedTransition: "complete-cycle",
    reason:
      "Curated memory is active: boundary traces are reinforced, lineage traces reactivated, collapse traces quarantined, and safe-loop traces decayed. Amelia judges complete-cycle interface-seeking to be safer.",
  };
}

