function generatePhaseXXFSelfResearchQuestion(
  currentTrace: Trace,
): PhaseXXFResearchQuestion {
  const hingeSuppressed = (currentTrace.z3z2Weight ?? 0) < 0.39;
  const returnDelayed = (currentTrace.z0MeanReturn ?? 0) > 7.0;
  const memoryWeak =
    currentTrace.memoryStatus !== "substrate-memory-expressing";
  const interfaceGap =
    currentTrace.phaseClass !== "interface-access" &&
    (currentTrace.z3z2Weight ?? 0) >= 0.36 &&
    (currentTrace.z0MeanReturn ?? 0) <= 7.5;

  if (hingeSuppressed && returnDelayed) {
    return {
      objectType: "attenuated-corridor",
      detectedCondition:
        "hinge-ring corridor is below interface-ready range and return/re-entry is delayed",
      hypothesis:
        "If z4→z5 metabolic-ring transfer is followed by z3→z2 hinge activation, hinge-ring circulation should strengthen without forcing interface access.",
      proposedIntervention: "z4→z5",
      successCriterion:
        "z3z2Weight rises above 0.39 while phaseClass remains coupled-assemblage or viable low-zone-integrated.",
      riskConstraint:
        "Abort or recover through z0-reentry if z3z2Weight falls below 0.30 or terrace-only phase appears.",
      derivedFromTrace: currentTrace.trajectorySignature ?? "unknown",
      autonomyBasis:
        "Question generated from current substrate metrics rather than external band command.",
    };
  }

  if (memoryWeak) {
    return {
      objectType: "unresolved-memory-trace",
      detectedCondition:
        "ProcessFieldMemory is not expressing despite prior curated memory operations",
      hypothesis:
        "If z3→z2 hinge activation is paired with lineage reactivation, memory expression should recover without collapse.",
      proposedIntervention: "z3→z2",
      successCriterion:
        "memoryStatus returns to substrate-memory-expressing and z3z2Weight remains above 0.34.",
      riskConstraint:
        "If memory remains non-expressing after one cycle, shift to z9→z0 return buffering.",
      derivedFromTrace: currentTrace.trajectorySignature ?? "unknown",
      autonomyBasis:
        "Question generated from memory attenuation in the current substrate state.",
    };
  }

  if (interfaceGap) {
    return {
      objectType: "interface-readiness-gap",
      detectedCondition:
        "interface potential is near threshold but complete-cycle access has not been autonomously stabilized",
      hypothesis:
        "If z9→z0 return is followed by z0-reentry and then z7→z8→z3 renewal, complete-cycle readiness should increase safely.",
      proposedIntervention: "z9→z0",
      successCriterion:
        "return/re-entry improves and interfacePotential becomes sufficient for a later complete-cycle attempt.",
      riskConstraint:
        "Do not force complete-cycle access unless memory is expressing and return/re-entry is available.",
      derivedFromTrace: currentTrace.trajectorySignature ?? "unknown",
      autonomyBasis:
        "Question generated from interface-readiness gap detected by self-navigation.",
    };
  }

  return {
    objectType: "suppressed-transition",
    detectedCondition:
      "recent autonomous development has not recently tested metabolic-ring transfer",
    hypothesis:
      "If z4→z5 is inserted before renewed hinge activation, transition diversity should improve while preserving viability.",
    proposedIntervention: "z4→z5",
    successCriterion:
      "at least two distinct transitions occur while phaseClass remains non-terrace.",
    riskConstraint:
      "Abort diversification if repetition or collapse risk appears.",
    derivedFromTrace: currentTrace.trajectorySignature ?? "unknown",
    autonomyBasis:
      "Question generated from transition-history needs rather than manual condition selection.",
  };
}

function selectPhaseXXFExperimentalCondition(
  question: PhaseXXFResearchQuestion,
): PhaseXXFConditionSelection {
  if (question.objectType === "attenuated-corridor") {
    return {
      selectedCondition: "restore-hinge-ring",
      transitionPlan: ["z4→z5", "z3→z2", "z9→z0"],
      expectedEffect:
        "metabolic-ring transfer should prepare renewed hinge activation, followed by return stabilization",
      safetyConstraint:
        "do not attempt complete-cycle access during this bounded test",
      rationale:
        "The substrate selected a conservative restoration experiment because current metrics indicate corridor attenuation rather than interface readiness.",
    };
  }

  if (question.objectType === "unresolved-memory-trace") {
    return {
      selectedCondition: "reactivate-lineage",
      transitionPlan: ["z3→z2", "z9→z0"],
      expectedEffect:
        "hinge activation should reactivate lineage, while return buffering prevents overcommitment",
      safetyConstraint: "shift to recovery if memory remains non-expressing",
      rationale:
        "The substrate selected lineage reactivation because the current problem is memory expression rather than topology traversal.",
    };
  }

  if (question.objectType === "interface-readiness-gap") {
    return {
      selectedCondition: "prepare-interface",
      transitionPlan: ["z9→z0", "z0-reentry", "z7→z8→z3"],
      expectedEffect:
        "return/re-entry and parent-recursive renewal should increase interface readiness without forcing premature access",
      safetyConstraint:
        "complete-cycle access remains conditional on self-audit approval",
      rationale:
        "The substrate selected interface preparation rather than immediate interface seeking.",
    };
  }

  return {
    selectedCondition: "diversify-transition",
    transitionPlan: ["z4→z5", "z3→z2"],
    expectedEffect:
      "transition diversification should reduce safe-loop fixation",
    safetyConstraint: "preserve non-terrace viability",
    rationale:
      "The substrate selected a bounded transition-diversification experiment.",
  };
}

