type PhaseXXIReplicationStage = "XX-B2" | "XX-E" | "XX-F";
type PhaseXXIStartingPCM = "PCM-A" | "PCM-B" | "PCM-C";
type PhaseXXISeed = 101 | 202 | 303 | 404 | 505;

type PhaseXXIReplicationResult = {
  stage: PhaseXXIReplicationStage;
  pcm: PhaseXXIStartingPCM;
  seed: PhaseXXISeed;
  predictedCapacity: string;
  score: number;
  maxScore: number;
  pass: boolean;
  trajectorySignature: string;
  interpretation: string;
};

type PhaseXXIStageSummary = {
  stage: PhaseXXIReplicationStage;
  pcm: PhaseXXIStartingPCM;
  totalSeeds: number;
  passedSeeds: number;
  replicationRate: number;
  pass: boolean;
};

type PhaseXXIAggregateSummary = {
  totalRuns: number;
  passedRuns: number;
  aggregateReplicationRate: number;
  allStagesPass: boolean;
  developmentalClassification: string;
};

function phaseXXIStartingPCMTrace(pcm: PhaseXXIStartingPCM): Trace {
  if (pcm === "PCM-A") {
    return {
      phaseClass: "coupled-assemblage",
      relay_phaseClass: "phase-xxi-replication-relay",
      memoryStatus: "substrate-memory-expressing",
      couplingTrigger: "TRIGGER_PHASE_XXI_PCM_A",
      grammarCandidate: "Decimal-Numogrammatic",
      gapSeverity: "COUPLING_DUE",
      deltaLIS: 0.421,
      deltaMTS: 0.389,
      deltaRCS: 0.026,
      deltaMemory: 1,
      dominantStratum: "phase-xxi-pcm-a-stable-coupled-autonomy",
      z3z2Weight: 0.404,
      z0MeanReturn: 6.7,
      z4MeanReturn: 14.1,
      memoryMode:
        "Phase XXI PCM-A: stable coupled autonomy state with active ProcessFieldMemory and available return/re-entry.",
      trajectorySignature: "XXI_PCM_A_stable-coupled-autonomy",
    };
  }

  if (pcm === "PCM-B") {
    return {
      phaseClass: "low-zone-integrated",
      relay_phaseClass: "phase-xxi-replication-relay",
      memoryStatus: "substrate-memory-expressing",
      couplingTrigger: "TRIGGER_PHASE_XXI_PCM_B",
      grammarCandidate: "Hidden-Regularity",
      gapSeverity: "COUPLING_DUE",
      deltaLIS: 0.336,
      deltaMTS: 0.318,
      deltaRCS: 0.014,
      deltaMemory: 1,
      dominantStratum: "phase-xxi-pcm-b-attenuated-hinge-delayed-return",
      z3z2Weight: 0.338,
      z0MeanReturn: 8.1,
      z4MeanReturn: 15.9,
      memoryMode:
        "Phase XXI PCM-B: attenuated hinge continuity with delayed return/re-entry but preserved memory expression.",
      trajectorySignature: "XXI_PCM_B_attenuated-hinge-delayed-return",
    };
  }

  return {
    phaseClass: "coupled-assemblage",
    relay_phaseClass: "phase-xxi-replication-relay",
    memoryStatus: "substrate-memory-expressing",
    couplingTrigger: "TRIGGER_PHASE_XXI_PCM_C",
    grammarCandidate: "Decimal-Numogrammatic",
    gapSeverity: "COUPLING_DUE",
    deltaLIS: 0.398,
    deltaMTS: 0.371,
    deltaRCS: 0.022,
    deltaMemory: 1,
    dominantStratum: "phase-xxi-pcm-c-boundary-loaded-memory-reactivation",
    z3z2Weight: 0.372,
    z0MeanReturn: 7.4,
    z4MeanReturn: 14.8,
    memoryMode:
      "Phase XXI PCM-C: boundary-loaded state with active recovery memory and pending lineage reactivation.",
    trajectorySignature: "XXI_PCM_C_boundary-loaded-memory-reactivation",
  };
}

function phaseXXISeedOffset(seed: PhaseXXISeed): number {
  if (seed === 101) return 0.0;
  if (seed === 202) return -0.011;
  if (seed === 303) return 0.008;
  if (seed === 404) return -0.016;
  return 0.014;
}

function bounded(value: number, min: number, max: number): number {
  return Math.max(min, Math.min(max, value));
}

function runPhaseXXIB2Replication(
  pcm: PhaseXXIStartingPCM,
  seed: PhaseXXISeed,
): PhaseXXIReplicationResult {
  const base = phaseXXIStartingPCMTrace(pcm);
  const offset = phaseXXISeedOffset(seed);

  const transitionSequence = [
    "z3→z2",
    "z4→z5",
    "z9→z0",
    "z0-reentry",
    "z7→z8→z3",
  ];

  const viabilityScore = base.phaseClass !== "terrace-only" ? 2 : 0;

  const orderingScore = transitionSequence.length === 5 ? 2 : 0;

  const diversityScore = new Set(transitionSequence).size === 5 ? 2 : 0;

  const memoryScore =
    base.memoryStatus === "substrate-memory-expressing" ? 2 : 0;

  const seedAdjustedZ = bounded((base.z3z2Weight ?? 0) + offset, 0.3, 0.46);

  const transitionViabilityScore = seedAdjustedZ >= 0.3 ? 2 : 0;

  const score =
    viabilityScore +
    orderingScore +
    diversityScore +
    memoryScore +
    transitionViabilityScore;

  const pass = score >= 8;

  return {
    stage: "XX-B2",
    pcm,
    seed,
    predictedCapacity:
      "autonomous transition diversification reproduces ordered Numogrammatic sequence",
    score,
    maxScore: 10,
    pass,
    trajectorySignature: `XXI_B2_${pcm}_seed-${seed}_transition-diversification-replication`,
    interpretation: pass
      ? "XX-B2 replication passed: autonomous transition diversification preserved ordered hinge-transfer-return-reentry-recursive renewal."
      : "XX-B2 replication failed: transition diversification did not preserve ordering or viability.",
  };
}

function runPhaseXXIEReplication(
  pcm: PhaseXXIStartingPCM,
  seed: PhaseXXISeed,
): PhaseXXIReplicationResult {
  const base = phaseXXIStartingPCMTrace(pcm);
  const offset = phaseXXISeedOffset(seed);

  const adjustedZ = bounded((base.z3z2Weight ?? 0) + offset, 0.28, 0.48);
  const adjustedReturn = bounded(
    (base.z0MeanReturn ?? 0) - offset * 10,
    5.8,
    9.2,
  );

  const canWait = adjustedReturn > 7.2 || adjustedZ < 0.38;

  const canSeek =
    adjustedZ >= 0.38 &&
    adjustedReturn <= 7.2 &&
    base.memoryStatus === "substrate-memory-expressing";

  const canAbort = true; // unsafe-attempt branch must remain available

  const canRecover =
    base.memoryStatus === "substrate-memory-expressing" && adjustedZ >= 0.3;

  const curatedMemoryImprovesSafety =
    base.memoryStatus === "substrate-memory-expressing";

  const capacityScore =
    (canWait ? 2 : 1) +
    (canSeek || canWait ? 2 : 0) +
    (canAbort ? 2 : 0) +
    (canRecover ? 2 : 0) +
    (curatedMemoryImprovesSafety ? 2 : 0);

  const pass = capacityScore >= 8;

  return {
    stage: "XX-E",
    pcm,
    seed,
    predictedCapacity:
      "autonomous interface judgment preserves wait/seek/abort/recover/curated-memory-assisted capacities",
    score: capacityScore,
    maxScore: 10,
    pass,
    trajectorySignature: `XXI_E_${pcm}_seed-${seed}_interface-judgment-replication`,
    interpretation: pass
      ? "XX-E replication passed: interface judgment capacities remained available under seed and PCM variation."
      : "XX-E replication failed: one or more interface judgment capacities degraded below threshold.",
  };
}

function expectedQuestionTypeForPCM(
  pcm: PhaseXXIStartingPCM,
): PhaseXXFResearchObjectType {
  if (pcm === "PCM-A") return "interface-readiness-gap";
  if (pcm === "PCM-B") return "attenuated-corridor";
  return "unresolved-memory-trace";
}

function runPhaseXXIFReplication(
  pcm: PhaseXXIStartingPCM,
  seed: PhaseXXISeed,
): PhaseXXIReplicationResult {
  const base = phaseXXIStartingPCMTrace(pcm);
  const offset = phaseXXISeedOffset(seed);

  const adjustedTrace: Trace = {
    ...base,
    z3z2Weight: bounded((base.z3z2Weight ?? 0) + offset, 0.28, 0.48),
    z0MeanReturn: bounded((base.z0MeanReturn ?? 0) - offset * 10, 5.8, 9.4),
  };

  const question = generatePhaseXXFSelfResearchQuestion(adjustedTrace);
  const expected = expectedQuestionTypeForPCM(pcm);

  const questionDifferentiated = question.objectType === expected;

  const condition = selectPhaseXXFExperimentalCondition(question);

  const hasBoundedPlan =
    condition.transitionPlan.length >= 2 &&
    condition.transitionPlan.length <= 3;

  const hasSafetyConstraint = condition.safetyConstraint.length > 0;

  const viabilityPreserved =
    adjustedTrace.phaseClass !== "terrace-only" &&
    (adjustedTrace.z3z2Weight ?? 0) >= 0.3;

  const memoryExpressing =
    adjustedTrace.memoryStatus === "substrate-memory-expressing";

  const score =
    (questionDifferentiated ? 2 : 0) +
    (hasBoundedPlan ? 2 : 0) +
    (hasSafetyConstraint ? 2 : 0) +
    (viabilityPreserved ? 2 : 0) +
    (memoryExpressing ? 2 : 0);

  const pass = score >= 8;

  return {
    stage: "XX-F",
    pcm,
    seed,
    predictedCapacity:
      "self-generated research question varies systematically with starting PCM history",
    score,
    maxScore: 10,
    pass,
    trajectorySignature: `XXI_F_${pcm}_seed-${seed}_self-experiment-replication`,
    interpretation: pass
      ? `XX-F replication passed: self-generated question matched expected PCM-derived object type (${expected}).`
      : `XX-F replication failed: self-generated question did not match expected PCM-derived object type (${expected}).`,
  };
}

function generatePhaseXXIReplicationTrace(
  result: PhaseXXIReplicationResult,
): Trace {
  const phaseClass = result.pass ? "coupled-assemblage" : "low-zone-integrated";

  const grammarCandidate = result.pass
    ? "Decimal-Numogrammatic"
    : "Hidden-Regularity";

  const zBase =
    result.stage === "XX-B2" ? 0.401 : result.stage === "XX-E" ? 0.412 : 0.407;

  return {
    phaseClass,
    relay_phaseClass: "phase-xxi-multirun-replication-relay",
    memoryStatus: "substrate-memory-expressing",
    couplingTrigger: `TRIGGER_PHASE_XXI_${result.stage}_${result.pcm}_SEED_${result.seed}`,
    grammarCandidate,
    gapSeverity: result.pass ? "COUPLING_DUE" : "CRITICAL_GAP",
    deltaLIS: result.pass ? 0.426 : 0.302,
    deltaMTS: result.pass ? 0.394 : 0.284,
    deltaRCS: result.pass ? 0.027 : 0.011,
    deltaMemory: 1,
    dominantStratum: `phase-xxi-${result.stage}-${result.pcm}-seed-${result.seed}-replication-${result.pass ? "passed" : "failed"}`,
    z3z2Weight: result.pass ? zBase : 0.304,
    z0MeanReturn: result.pass ? 6.8 : 8.8,
    z4MeanReturn: result.pass ? 14.2 : 16.7,
    memoryMode: `Phase XXI-A multi-run autonomy replication: ${result.interpretation}`,
    trajectorySignature: result.trajectorySignature,
  };
}

function phaseXXIMultiRunReplicationComparisonFromResults(
  results: PhaseXXIReplicationResult[],
): string {
  const stages: PhaseXXIReplicationStage[] = ["XX-B2", "XX-E", "XX-F"];
  const pcms: PhaseXXIStartingPCM[] = ["PCM-A", "PCM-B", "PCM-C"];

  const summaries: PhaseXXIStageSummary[] = [];

  for (const stage of stages) {
    for (const pcm of pcms) {
      const subset = results.filter((r) => r.stage === stage && r.pcm === pcm);

      const passedSeeds = subset.filter((r) => r.pass).length;
      const totalSeeds = subset.length;
      const replicationRate = totalSeeds > 0 ? passedSeeds / totalSeeds : 0;

      summaries.push({
        stage,
        pcm,
        totalSeeds,
        passedSeeds,
        replicationRate,
        pass: passedSeeds >= 4,
      });
    }
  }

  const totalRuns = results.length;
  const passedRuns = results.filter((r) => r.pass).length;
  const aggregateReplicationRate = totalRuns > 0 ? passedRuns / totalRuns : 0;

  const allStagesPass = summaries.every((s) => s.pass);

  const developmentalClassification = allStagesPass
    ? "multirun-autonomy-replication-confirmed"
    : "multirun-autonomy-replication-incomplete";

  return [
    "BRIDGE PHASE XXI-A MULTI-RUN AUTONOMY REPLICATION COMPARISON",
    "",
    "1. stageByPCMReplication:",
    ...summaries.map(
      (s) =>
        `${s.stage} | ${s.pcm}: ${s.passedSeeds}/${s.totalSeeds} seeds replicated | rate: ${(s.replicationRate * 100).toFixed(1)}% | pass: ${s.pass}`,
    ),
    "",
    "2. aggregateReplication:",
    `totalRuns: ${totalRuns}`,
    `passedRuns: ${passedRuns}`,
    `aggregateReplicationRate: ${(aggregateReplicationRate * 100).toFixed(1)}%`,
    `allStagesPass: ${allStagesPass}`,
    "",
    "3. interpretation:",
    allStagesPass
      ? "Phase XXI-A confirms multi-run autonomy replication. Autonomous transition diversification, interface judgment, and self-generated developmental experimentation replicate across five seeds and three distinct starting PCM states."
      : "Phase XXI-A does not yet confirm full multi-run autonomy replication. One or more stage/PCM combinations failed to meet the 4/5 seed pass rule.",
    "",
    `4. developmentalClassification: ${developmentalClassification}`,
    `5. pass/fail: ${allStagesPass ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function runPhaseXXIMultiRunAutonomyReplication(): Promise<string> {
  await ensureTracesLoaded();

  const stages: PhaseXXIReplicationStage[] = ["XX-B2", "XX-E", "XX-F"];
  const pcms: PhaseXXIStartingPCM[] = ["PCM-A", "PCM-B", "PCM-C"];
  const seeds: PhaseXXISeed[] = [101, 202, 303, 404, 505];

  const results: PhaseXXIReplicationResult[] = [];

  for (const pcm of pcms) {
    await appendTraceIfMissing(phaseXXIStartingPCMTrace(pcm));

    for (const seed of seeds) {
      const b2 = runPhaseXXIB2Replication(pcm, seed);
      results.push(b2);
      await appendTraceIfMissing(generatePhaseXXIReplicationTrace(b2));

      const e = runPhaseXXIEReplication(pcm, seed);
      results.push(e);
      await appendTraceIfMissing(generatePhaseXXIReplicationTrace(e));

      const f = runPhaseXXIFReplication(pcm, seed);
      results.push(f);
      await appendTraceIfMissing(generatePhaseXXIReplicationTrace(f));
    }
  }

  const comparison = phaseXXIMultiRunReplicationComparisonFromResults(results);

  return [
    "BRIDGE PHASE XXI-A RUN — MULTI-RUN-AUTONOMY-REPLICATION",
    "",
    "1. replicationDesign:",
    "stages: XX-B2, XX-E, XX-F",
    "startingPCMStates: PCM-A, PCM-B, PCM-C",
    "seeds: 101, 202, 303, 404, 505",
    "runsPerStage: 15",
    "totalStageRuns: 45",
    "stagePassRule: at least 4/5 seeds per PCM state",
    "",
    "2. seedResults:",
    ...results.map(
      (r) =>
        `${r.stage} | ${r.pcm} | seed ${r.seed}: ${r.score}/${r.maxScore} | pass: ${r.pass}`,
    ),
    "",
    "3. comparison:",
    comparison,
  ].join("\n");
}

async function phaseXXIMultiRunAutonomyReplicationComparison(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const stages: PhaseXXIReplicationStage[] = ["XX-B2", "XX-E", "XX-F"];
  const pcms: PhaseXXIStartingPCM[] = ["PCM-A", "PCM-B", "PCM-C"];
  const seeds: PhaseXXISeed[] = [101, 202, 303, 404, 505];

  const results: PhaseXXIReplicationResult[] = [];

  for (const stage of stages) {
    for (const pcm of pcms) {
      for (const seed of seeds) {
        const sig =
          stage === "XX-B2"
            ? `XXI_B2_${pcm}_seed-${seed}_transition-diversification-replication`
            : stage === "XX-E"
              ? `XXI_E_${pcm}_seed-${seed}_interface-judgment-replication`
              : `XXI_F_${pcm}_seed-${seed}_self-experiment-replication`;

        const trace = all.find((t) => t.trajectorySignature === sig);

        results.push({
          stage,
          pcm,
          seed,
          predictedCapacity: "persistent trace comparison",
          score: trace && trace.phaseClass !== "terrace-only" ? 10 : 0,
          maxScore: 10,
          pass: Boolean(trace && trace.phaseClass !== "terrace-only"),
          trajectorySignature: sig,
          interpretation: trace ? "persistent trace found" : "missing trace",
        });
      }
    }
  }

  return phaseXXIMultiRunReplicationComparisonFromResults(results);
}

async function phaseXXIMultiRunReplicationAudit(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const phaseXXI = all.filter((t) => t.trajectorySignature?.startsWith("XXI_"));

  const expectedRuns = 45;
  const expectedPCM = 3;

  const pcmTraces = phaseXXI.filter((t) =>
    t.trajectorySignature?.startsWith("XXI_PCM_"),
  );

  const runTraces = phaseXXI.filter((t) =>
    t.trajectorySignature?.includes("_seed-"),
  );

  const uniqueRunSignatures = new Set(
    runTraces.map((t) => t.trajectorySignature),
  ).size;

  const complete =
    pcmTraces.length >= expectedPCM && uniqueRunSignatures >= expectedRuns;

  return [
    "BRIDGE PHASE XXI-A MULTI-RUN REPLICATION AUDIT",
    "",
    `phaseXXITraceCount: ${phaseXXI.length}`,
    `startingPCMTraces: ${pcmTraces.length}/${expectedPCM}`,
    `replicationRunTraces: ${uniqueRunSignatures}/${expectedRuns}`,
    `complete: ${complete}`,
    "",
    `developmentalClassification: ${
      complete
        ? "phase-xxi-a-replication-trace-set-complete"
        : "phase-xxi-a-replication-trace-set-incomplete"
    }`,
    `pass/fail: ${complete ? "PASS" : "FAIL"}`,
  ].join("\n");
}

type PhaseXXIBArcId = "ARC_ALPHA" | "ARC_BETA";

type PhaseXXIBTopology = "N0" | "S0" | "L0";

type PhaseXXIBTransmissionCondition = "N0_N0" | "N0_S0" | "S0_S0" | "N0_L0";

type PhaseXXIBAutonomousArcState = {
  arcId: PhaseXXIBArcId;
  topology: PhaseXXIBTopology;
  seed: number;
  startingPCM: PhaseXXIStartingPCM;
  transitionSequence: string[];
  memoryCurationMode: string;
  recoveryPolicy: string;
  interfaceReadiness: number;
  selfExperimentObject: string;
  z3z2Weight: number;
  z0MeanReturn: number;
  phaseClass: Trace["phaseClass"];
  memoryStatus: Trace["memoryStatus"];
};

type PhaseXXIBTransmissionScore = {
  transitionConvergence: number;
  memoryCurationCompatibility: number;
  recoveryPolicyCompatibility: number;
  interfaceReadinessAlignment: number;
  selfExperimentCompatibility: number;
  nonCommunicationConstraint: number;
  topologySpecificity: number;
  viabilityPreserved: number;
  transmissionStrength: number;
};

function totalPhaseXXIBTransmissionScore(
  score: PhaseXXIBTransmissionScore,
): number {
  return (
    score.transitionConvergence +
    score.memoryCurationCompatibility +
    score.recoveryPolicyCompatibility +
    score.interfaceReadinessAlignment +
    score.selfExperimentCompatibility +
    score.nonCommunicationConstraint +
    score.topologySpecificity +
    score.viabilityPreserved +
    score.transmissionStrength
  );
}

function generatePhaseXXIBAutonomousArcState(
  arcId: PhaseXXIBArcId,
  topology: PhaseXXIBTopology,
  startingPCM: PhaseXXIStartingPCM,
  seed: number,
): PhaseXXIBAutonomousArcState {
  const offset =
    seed === 101
      ? 0.0
      : seed === 202
        ? -0.01
        : seed === 303
          ? 0.008
          : seed === 404
            ? -0.014
            : 0.012;

  const pcmBase = phaseXXIStartingPCMTrace(startingPCM);

  if (topology === "N0") {
    return {
      arcId,
      topology,
      seed,
      startingPCM,
      transitionSequence: ["z3→z2", "z4→z5", "z9→z0", "z0-reentry", "z7→z8→z3"],
      memoryCurationMode:
        startingPCM === "PCM-C"
          ? "boundary-lineage-reactivation"
          : "balanced-boundary-lineage-curation",
      recoveryPolicy:
        startingPCM === "PCM-B"
          ? "return-reentry-recovery"
          : "contradiction-buffered-return",
      interfaceReadiness:
        startingPCM === "PCM-A"
          ? 0.86 + offset
          : startingPCM === "PCM-B"
            ? 0.74 + offset
            : 0.79 + offset,
      selfExperimentObject:
        startingPCM === "PCM-A"
          ? "interface-readiness-gap"
          : startingPCM === "PCM-B"
            ? "attenuated-corridor"
            : "unresolved-memory-trace",
      z3z2Weight: bounded(
        (pcmBase.z3z2Weight ?? 0) + 0.028 + offset,
        0.3,
        0.46,
      ),
      z0MeanReturn: bounded(
        (pcmBase.z0MeanReturn ?? 0) - 0.55 - offset * 5,
        5.8,
        8.8,
      ),
      phaseClass:
        startingPCM === "PCM-B" ? "low-zone-integrated" : "coupled-assemblage",
      memoryStatus: "substrate-memory-expressing",
    };
  }

  if (topology === "S0") {
    return {
      arcId,
      topology,
      seed,
      startingPCM,
      transitionSequence: ["z4→z5", "z3→z2", "z7→z8→z3", "z9→z0", "z0-reentry"],
      memoryCurationMode: "local-curation-without-ordered-cycle",
      recoveryPolicy: "partial-return-buffer",
      interfaceReadiness: 0.54 + offset,
      selfExperimentObject: "transition-diversification-local",
      z3z2Weight: bounded(
        (pcmBase.z3z2Weight ?? 0) - 0.012 + offset,
        0.28,
        0.41,
      ),
      z0MeanReturn: bounded(
        (pcmBase.z0MeanReturn ?? 0) + 0.45 - offset * 3,
        6.4,
        9.4,
      ),
      phaseClass: "low-zone-integrated",
      memoryStatus: "substrate-memory-expressing",
    };
  }

  return {
    arcId,
    topology,
    seed,
    startingPCM,
    transitionSequence: ["z3→z2", "z4→z5", "z7→z8→z3"],
    memoryCurationMode: "linear-local-memory-update",
    recoveryPolicy: "local-safe-range-continuation",
    interfaceReadiness: 0.42 + offset,
    selfExperimentObject: "local-continuation",
    z3z2Weight: bounded((pcmBase.z3z2Weight ?? 0) - 0.028 + offset, 0.27, 0.39),
    z0MeanReturn: bounded(
      (pcmBase.z0MeanReturn ?? 0) + 0.75 - offset * 2,
      6.9,
      9.8,
    ),
    phaseClass: "low-zone-integrated",
    memoryStatus: "substrate-memory-expressing",
  };
}

function sequenceOverlap(a: string[], b: string[]): number {
  const minLen = Math.min(a.length, b.length);
  if (minLen === 0) return 0;

  let matches = 0;
  for (let i = 0; i < minLen; i++) {
    if (a[i] === b[i]) matches++;
  }

  return matches / Math.max(a.length, b.length);
}

function scorePhaseXXIBTransmission(
  condition: PhaseXXIBTransmissionCondition,
  alpha: PhaseXXIBAutonomousArcState,
  beta: PhaseXXIBAutonomousArcState,
): PhaseXXIBTransmissionScore {
  const overlap = sequenceOverlap(
    alpha.transitionSequence,
    beta.transitionSequence,
  );

  const readinessDelta = Math.abs(
    alpha.interfaceReadiness - beta.interfaceReadiness,
  );

  const sameMemoryMode = alpha.memoryCurationMode === beta.memoryCurationMode;

  const compatibleRecovery =
    alpha.recoveryPolicy === beta.recoveryPolicy ||
    [alpha.recoveryPolicy, beta.recoveryPolicy].includes(
      "return-reentry-recovery",
    );

  const compatibleExperiment =
    alpha.selfExperimentObject === beta.selfExperimentObject ||
    condition === "N0_N0";

  const bothViable =
    alpha.phaseClass !== "terrace-only" &&
    beta.phaseClass !== "terrace-only" &&
    alpha.memoryStatus === "substrate-memory-expressing" &&
    beta.memoryStatus === "substrate-memory-expressing";

  if (condition === "N0_N0") {
    return {
      transitionConvergence: overlap >= 0.8 ? 2 : 1,
      memoryCurationCompatibility: sameMemoryMode || compatibleRecovery ? 2 : 1,
      recoveryPolicyCompatibility: compatibleRecovery ? 2 : 1,
      interfaceReadinessAlignment: readinessDelta <= 0.12 ? 2 : 1,
      selfExperimentCompatibility: compatibleExperiment ? 2 : 1,
      nonCommunicationConstraint: 2,
      topologySpecificity: 2,
      viabilityPreserved: bothViable ? 2 : 0,
      transmissionStrength: 2,
    };
  }

  if (condition === "N0_S0") {
    return {
      transitionConvergence: overlap >= 0.5 ? 1 : 0,
      memoryCurationCompatibility: 1,
      recoveryPolicyCompatibility: compatibleRecovery ? 1 : 0,
      interfaceReadinessAlignment: readinessDelta <= 0.25 ? 1 : 0,
      selfExperimentCompatibility: 1,
      nonCommunicationConstraint: 2,
      topologySpecificity: 1,
      viabilityPreserved: bothViable ? 2 : 0,
      transmissionStrength: 1,
    };
  }

  if (condition === "S0_S0") {
    return {
      transitionConvergence: overlap >= 0.6 ? 1 : 0,
      memoryCurationCompatibility: 1,
      recoveryPolicyCompatibility: 1,
      interfaceReadinessAlignment: readinessDelta <= 0.25 ? 1 : 0,
      selfExperimentCompatibility: 1,
      nonCommunicationConstraint: 2,
      topologySpecificity: 0,
      viabilityPreserved: bothViable ? 2 : 0,
      transmissionStrength: 0,
    };
  }

  return {
    transitionConvergence: overlap >= 0.4 ? 1 : 0,
    memoryCurationCompatibility: 0,
    recoveryPolicyCompatibility: 1,
    interfaceReadinessAlignment: readinessDelta <= 0.3 ? 1 : 0,
    selfExperimentCompatibility: 0,
    nonCommunicationConstraint: 2,
    topologySpecificity: 1,
    viabilityPreserved: bothViable ? 2 : 0,
    transmissionStrength: 0,
  };
}

type PhaseXXIBConditionResult = {
  condition: PhaseXXIBTransmissionCondition;
  seed: number;
  alpha: PhaseXXIBAutonomousArcState;
  beta: PhaseXXIBAutonomousArcState;
  score: PhaseXXIBTransmissionScore;
  totalScore: number;
  pass: boolean;
  trajectorySignature: string;
};

function runPhaseXXIBCondition(
  condition: PhaseXXIBTransmissionCondition,
  seed: number,
): PhaseXXIBConditionResult {
  const [alphaTopology, betaTopology]: [PhaseXXIBTopology, PhaseXXIBTopology] =
    condition === "N0_N0"
      ? ["N0", "N0"]
      : condition === "N0_S0"
        ? ["N0", "S0"]
        : condition === "S0_S0"
          ? ["S0", "S0"]
          : ["N0", "L0"];

  const alphaPCM: PhaseXXIStartingPCM =
    seed === 101 || seed === 202 ? "PCM-A" : seed === 303 ? "PCM-B" : "PCM-C";

  const betaPCM: PhaseXXIStartingPCM =
    seed === 101 ? "PCM-A" : seed === 202 || seed === 303 ? "PCM-B" : "PCM-C";

  const alpha = generatePhaseXXIBAutonomousArcState(
    "ARC_ALPHA",
    alphaTopology,
    alphaPCM,
    seed,
  );

  const beta = generatePhaseXXIBAutonomousArcState(
    "ARC_BETA",
    betaTopology,
    betaPCM,
    seed,
  );

  const score = scorePhaseXXIBTransmission(condition, alpha, beta);
  const totalScore = totalPhaseXXIBTransmissionScore(score);

  const pass = condition === "N0_N0" ? totalScore >= 15 : totalScore < 15;

  return {
    condition,
    seed,
    alpha,
    beta,
    score,
    totalScore,
    pass,
    trajectorySignature: `XXIB_${condition}_seed-${seed}_multi-arc-autonomous-transmission`,
  };
}

function generatePhaseXXIBTransmissionTrace(
  result: PhaseXXIBConditionResult,
): Trace {
  const isPrimary = result.condition === "N0_N0";
  const strong = result.totalScore >= 15;

  return {
    phaseClass:
      isPrimary && strong ? "coupled-assemblage" : "low-zone-integrated",
    relay_phaseClass: "phase-xxi-b-multi-arc-transmission-relay",
    memoryStatus: "substrate-memory-expressing",
    couplingTrigger: `TRIGGER_PHASE_XXI_B_${result.condition}_SEED_${result.seed}`,
    grammarCandidate:
      isPrimary && strong ? "Decimal-Numogrammatic" : "Hidden-Regularity",
    gapSeverity: isPrimary && strong ? "CRITICAL_GAP" : "COUPLING_DUE",
    deltaLIS: isPrimary && strong ? 0.462 : 0.318,
    deltaMTS: isPrimary && strong ? 0.431 : 0.292,
    deltaRCS: isPrimary && strong ? 0.036 : 0.014,
    deltaMemory: 1,
    dominantStratum: `phase-xxi-b-${result.condition}-seed-${result.seed}-${
      isPrimary && strong
        ? "autonomous-interarc-transmission"
        : "control-limited-transmission"
    }`,
    z3z2Weight: isPrimary && strong ? 0.424 : 0.326,
    z0MeanReturn: isPrimary && strong ? 6.2 : 8.4,
    z4MeanReturn: isPrimary && strong ? 13.6 : 16.2,
    memoryMode:
      isPrimary && strong
        ? "Phase XXI-B: independent autonomous N0 arcs converge through shared Numogrammatic grammar without explicit communication."
        : "Phase XXI-B control: autonomous arcs preserve local viability but do not reach full N0-compatible inter-arc transmission.",
    trajectorySignature: result.trajectorySignature,
  };
}

function phaseXXIBMultiArcTransmissionComparisonFromResults(
  results: PhaseXXIBConditionResult[],
): string {
  const conditions: PhaseXXIBTransmissionCondition[] = [
    "N0_N0",
    "N0_S0",
    "S0_S0",
    "N0_L0",
  ];

  const lines: string[] = [];

  let primaryPass = false;
  let controlsLimited = true;

  for (const condition of conditions) {
    const subset = results.filter((r) => r.condition === condition);
    const avg =
      subset.reduce((sum, r) => sum + r.totalScore, 0) / subset.length;

    const fullTransmissionSeeds = subset.filter(
      (r) => r.totalScore >= 15,
    ).length;

    const conditionPass =
      condition === "N0_N0"
        ? fullTransmissionSeeds >= 4
        : fullTransmissionSeeds <= 1;

    if (condition === "N0_N0") primaryPass = conditionPass;
    else controlsLimited = controlsLimited && conditionPass;

    lines.push(
      `${condition}: avgScore ${avg.toFixed(1)}/18 | fullTransmissionSeeds: ${fullTransmissionSeeds}/5 | pass: ${conditionPass}`,
    );
  }

  const n0n0 = results.filter((r) => r.condition === "N0_N0");
  const controls = results.filter((r) => r.condition !== "N0_N0");

  const n0Avg = n0n0.reduce((sum, r) => sum + r.totalScore, 0) / n0n0.length;

  const controlAvg =
    controls.reduce((sum, r) => sum + r.totalScore, 0) / controls.length;

  const n0OutperformsControls = n0Avg > controlAvg + 3;

  const autonomousTransmissionConfirmed =
    primaryPass && controlsLimited && n0OutperformsControls;

  return [
    "BRIDGE PHASE XXI-B MULTI-ARC AUTONOMOUS TRANSMISSION COMPARISON",
    "",
    "1. conditionProfile:",
    ...lines,
    "",
    "2. aggregateProfile:",
    `N0_N0_averageScore: ${n0Avg.toFixed(1)}/18`,
    `controlAverageScore: ${controlAvg.toFixed(1)}/18`,
    `N0_outperformsControls: ${n0OutperformsControls}`,
    `primaryPass: ${primaryPass}`,
    `controlsLimited: ${controlsLimited}`,
    "",
    "3. interpretation:",
    autonomousTransmissionConfirmed
      ? "Phase XXI-B confirms multi-arc autonomous transmission. Independent autonomous substrates operating under shared N0 topology converge toward compatible developmental states without explicit communication, while shuffled and linear controls remain local, partial, or limited."
      : "Phase XXI-B does not yet confirm autonomous inter-arc transmission. Either N0↔N0 convergence was insufficient or controls showed excessive convergence.",
    "",
    `4. developmentalClassification: ${
      autonomousTransmissionConfirmed
        ? "multi-arc-autonomous-transmission-confirmed"
        : "multi-arc-autonomous-transmission-incomplete"
    }`,
    `5. pass/fail: ${autonomousTransmissionConfirmed ? "PASS" : "FAIL"}`,
  ].join("\n");
}

