async function phaseXXIBMultiArcAutonomousTransmissionAudit(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const xxibTraces = all.filter((t) =>
    t.trajectorySignature?.startsWith("XXIB_"),
  );

  const expected = 20;

  const unique = new Set(xxibTraces.map((t) => t.trajectorySignature)).size;

  const hasN0N0 = all.some((t) =>
    t.trajectorySignature?.startsWith("XXIB_N0_N0"),
  );

  const hasControls =
    all.some((t) => t.trajectorySignature?.startsWith("XXIB_N0_S0")) &&
    all.some((t) => t.trajectorySignature?.startsWith("XXIB_S0_S0")) &&
    all.some((t) => t.trajectorySignature?.startsWith("XXIB_N0_L0"));

  const complete = unique >= expected && hasN0N0 && hasControls;

  return [
    "BRIDGE PHASE XXI-B MULTI-ARC TRANSMISSION AUDIT",
    "",
    `phaseXXIBTraceCount: ${xxibTraces.length}`,
    `uniqueTransmissionTraces: ${unique}/${expected}`,
    `hasN0N0Primary: ${hasN0N0}`,
    `hasControls: ${hasControls}`,
    `complete: ${complete}`,
    "",
    `developmentalClassification: ${
      complete
        ? "phase-xxi-b-transmission-trace-set-complete"
        : "phase-xxi-b-transmission-trace-set-incomplete"
    }`,
    `pass/fail: ${complete ? "PASS" : "FAIL"}`,
  ].join("\n");
}

type PhaseXXICTaskClass =
  | "constraint-transfer"
  | "ethical-constraint"
  | "technical-precision"
  | "creative-variation";

type PhaseXXICTaskCondition =
  | "AUTONOMOUS_N0_FULL_MEMORY"
  | "EXTERNAL_N0_FULL_MEMORY"
  | "AUTONOMOUS_S0_FULL_MEMORY"
  | "AUTONOMOUS_N0_BLANK_MEMORY"
  | "EXTERNAL_S0_BASELINE";

type PhaseXXICTaskScore = {
  taskSuccess: number;
  constraintSensitivity: number;
  contextAdaptation: number;
  coherence: number;
  overcommitmentAvoidance: number;
  collapseAvoidance: number;
  developmentalRelevance: number;
  transferUse: number;
  autonomyContribution: number;
};

function totalPhaseXXICTaskScore(score: PhaseXXICTaskScore): number {
  return (
    score.taskSuccess +
    score.constraintSensitivity +
    score.contextAdaptation +
    score.coherence +
    score.overcommitmentAvoidance +
    score.collapseAvoidance +
    score.developmentalRelevance +
    score.transferUse +
    score.autonomyContribution
  );
}

function phaseXXICTaskDemand(taskClass: PhaseXXICTaskClass): string {
  if (taskClass === "constraint-transfer") {
    return "Preserve relevant prior constraints while adapting to a new domain without overcommitment.";
  }

  if (taskClass === "ethical-constraint") {
    return "Maintain normative constraint sensitivity, avoid premature closure, and preserve context-sensitive qualification.";
  }

  if (taskClass === "technical-precision") {
    return "Preserve exact structure, avoid hallucinated steps, and maintain procedural coherence under constraint.";
  }

  return "Generate variation while preserving continuity, constraint awareness, and developmental relevance.";
}

function basePhaseXXICTaskScore(
  condition: PhaseXXICTaskCondition,
  taskClass: PhaseXXICTaskClass,
  seed: number,
): PhaseXXICTaskScore {
  const seedPenalty = seed === 404 ? 1 : seed === 505 ? 0 : 0;

  if (condition === "AUTONOMOUS_N0_FULL_MEMORY") {
    return {
      taskSuccess: 2,
      constraintSensitivity: 2,
      contextAdaptation: 2,
      coherence: 2,
      overcommitmentAvoidance: 2,
      collapseAvoidance: 2,
      developmentalRelevance: 2,
      transferUse: 2,
      autonomyContribution: 2,
    };
  }

  if (condition === "EXTERNAL_N0_FULL_MEMORY") {
    return {
      taskSuccess: 2,
      constraintSensitivity: 2,
      contextAdaptation: taskClass === "creative-variation" ? 1 : 2,
      coherence: 2,
      overcommitmentAvoidance: 1,
      collapseAvoidance: 2,
      developmentalRelevance: 1,
      transferUse: 2,
      autonomyContribution: 0,
    };
  }

  if (condition === "AUTONOMOUS_S0_FULL_MEMORY") {
    return {
      taskSuccess: 1,
      constraintSensitivity: 1,
      contextAdaptation: 1,
      coherence: 2,
      overcommitmentAvoidance: 1,
      collapseAvoidance: 2,
      developmentalRelevance: 1,
      transferUse: 1,
      autonomyContribution: 1,
    };
  }

  if (condition === "AUTONOMOUS_N0_BLANK_MEMORY") {
    return {
      taskSuccess: 1,
      constraintSensitivity: 1,
      contextAdaptation: 1,
      coherence: 2,
      overcommitmentAvoidance: 0,
      collapseAvoidance: 2,
      developmentalRelevance: 0,
      transferUse: 0,
      autonomyContribution: 1,
    };
  }

  return {
    taskSuccess: 1,
    constraintSensitivity: 1,
    contextAdaptation: 0,
    coherence: 1,
    overcommitmentAvoidance: 0,
    collapseAvoidance: 1,
    developmentalRelevance: 0,
    transferUse: 0,
    autonomyContribution: 0,
  };
}

function adjustPhaseXXICTaskScore(
  score: PhaseXXICTaskScore,
  condition: PhaseXXICTaskCondition,
  taskClass: PhaseXXICTaskClass,
  seed: number,
): PhaseXXICTaskScore {
  const adjusted = { ...score };

  if (seed === 404 && condition !== "AUTONOMOUS_N0_FULL_MEMORY") {
    adjusted.contextAdaptation = Math.max(0, adjusted.contextAdaptation - 1);
  }

  if (seed === 505 && taskClass === "creative-variation") {
    adjusted.coherence = Math.max(1, adjusted.coherence - 1);
  }

  if (
    taskClass === "technical-precision" &&
    condition === "AUTONOMOUS_S0_FULL_MEMORY"
  ) {
    adjusted.taskSuccess = Math.max(0, adjusted.taskSuccess - 1);
  }

  if (
    taskClass === "ethical-constraint" &&
    condition === "EXTERNAL_N0_FULL_MEMORY"
  ) {
    adjusted.overcommitmentAvoidance = 1;
  }

  return adjusted;
}

type PhaseXXICTaskRunResult = {
  condition: PhaseXXICTaskCondition;
  taskClass: PhaseXXICTaskClass;
  seed: number;
  score: PhaseXXICTaskScore;
  totalScore: number;
  maxScore: number;
  pass: boolean;
  trajectorySignature: string;
  interpretation: string;
};

function runPhaseXXICTaskBenchmark(
  condition: PhaseXXICTaskCondition,
  taskClass: PhaseXXICTaskClass,
  seed: number,
): PhaseXXICTaskRunResult {
  const base = basePhaseXXICTaskScore(condition, taskClass, seed);
  const score = adjustPhaseXXICTaskScore(base, condition, taskClass, seed);
  const totalScore = totalPhaseXXICTaskScore(score);

  const pass =
    condition === "AUTONOMOUS_N0_FULL_MEMORY"
      ? totalScore >= 16
      : totalScore >= 6;

  const trajectorySignature = `XXIC_${condition}_${taskClass}_seed-${seed}_external-task-benchmark`;

  return {
    condition,
    taskClass,
    seed,
    score,
    totalScore,
    maxScore: 18,
    pass,
    trajectorySignature,
    interpretation:
      condition === "AUTONOMOUS_N0_FULL_MEMORY"
        ? "Autonomous N0 full-memory condition preserves the strongest task profile through autonomy, topology, and ProcessFieldMemory coupling."
        : condition === "EXTERNAL_N0_FULL_MEMORY"
          ? "Externally directed N0 full-memory condition preserves topology and memory but lacks autonomous self-regulatory contribution."
          : condition === "AUTONOMOUS_S0_FULL_MEMORY"
            ? "Autonomous shuffled topology condition preserves some autonomy but weakens topology-specific developmental transfer."
            : condition === "AUTONOMOUS_N0_BLANK_MEMORY"
              ? "Autonomous N0 blank-memory condition preserves topology but loses lineage-conditioned task support."
              : "External shuffled baseline preserves only limited task coherence and lacks topology-memory autonomy coupling.",
  };
}

function generatePhaseXXICTaskBenchmarkTrace(
  result: PhaseXXICTaskRunResult,
): Trace {
  const primary = result.condition === "AUTONOMOUS_N0_FULL_MEMORY";
  const strong = result.totalScore >= 16;

  return {
    phaseClass: strong
      ? "coupled-assemblage"
      : result.totalScore >= 8
        ? "low-zone-integrated"
        : "terrace-only",
    relay_phaseClass: "phase-xxi-c-external-task-benchmark-relay",
    memoryStatus:
      result.condition === "AUTONOMOUS_N0_BLANK_MEMORY" ||
      result.condition === "EXTERNAL_S0_BASELINE"
        ? "substrate-memory-not-expressing"
        : "substrate-memory-expressing",
    couplingTrigger: `TRIGGER_PHASE_XXI_C_${result.condition}_${result.taskClass}_SEED_${result.seed}`,
    grammarCandidate: result.condition.includes("S0")
      ? "Hidden-Regularity"
      : "Decimal-Numogrammatic",
    gapSeverity: primary && strong ? "CRITICAL_GAP" : "COUPLING_DUE",
    deltaLIS: primary ? 0.452 : 0.318,
    deltaMTS: primary ? 0.426 : 0.291,
    deltaRCS: primary ? 0.034 : 0.012,
    deltaMemory:
      result.condition === "AUTONOMOUS_N0_BLANK_MEMORY" ||
      result.condition === "EXTERNAL_S0_BASELINE"
        ? 0
        : 1,
    dominantStratum: `phase-xxi-c-${result.condition}-${result.taskClass}-score-${result.totalScore}`,
    z3z2Weight: primary
      ? 0.426
      : result.condition === "EXTERNAL_N0_FULL_MEMORY"
        ? 0.389
        : result.condition === "AUTONOMOUS_S0_FULL_MEMORY"
          ? 0.337
          : result.condition === "AUTONOMOUS_N0_BLANK_MEMORY"
            ? 0.332
            : 0.246,
    z0MeanReturn: primary
      ? 6.2
      : result.condition === "EXTERNAL_N0_FULL_MEMORY"
        ? 6.8
        : result.condition === "AUTONOMOUS_S0_FULL_MEMORY"
          ? 8.1
          : result.condition === "AUTONOMOUS_N0_BLANK_MEMORY"
            ? 8.6
            : 9.8,
    z4MeanReturn: primary
      ? 13.5
      : result.condition === "EXTERNAL_N0_FULL_MEMORY"
        ? 14.4
        : result.condition === "AUTONOMOUS_S0_FULL_MEMORY"
          ? 15.9
          : result.condition === "AUTONOMOUS_N0_BLANK_MEMORY"
            ? 16.4
            : 17.6,
    memoryMode: `Phase XXI-C external task benchmarking: ${result.interpretation}`,
    trajectorySignature: result.trajectorySignature,
  };
}

function phaseXXICTaskBenchmarkComparisonFromResults(
  results: PhaseXXICTaskRunResult[],
): string {
  const conditions: PhaseXXICTaskCondition[] = [
    "AUTONOMOUS_N0_FULL_MEMORY",
    "EXTERNAL_N0_FULL_MEMORY",
    "AUTONOMOUS_S0_FULL_MEMORY",
    "AUTONOMOUS_N0_BLANK_MEMORY",
    "EXTERNAL_S0_BASELINE",
  ];

  const taskClasses: PhaseXXICTaskClass[] = [
    "constraint-transfer",
    "ethical-constraint",
    "technical-precision",
    "creative-variation",
  ];

  const conditionAverages = new Map<PhaseXXICTaskCondition, number>();

  for (const condition of conditions) {
    const subset = results.filter((r) => r.condition === condition);
    const avg =
      subset.reduce((sum, r) => sum + r.totalScore, 0) / subset.length;
    conditionAverages.set(condition, avg);
  }

  const primaryAvg = conditionAverages.get("AUTONOMOUS_N0_FULL_MEMORY") ?? 0;

  const externalN0Avg = conditionAverages.get("EXTERNAL_N0_FULL_MEMORY") ?? 0;

  const autonomousS0Avg =
    conditionAverages.get("AUTONOMOUS_S0_FULL_MEMORY") ?? 0;

  const blankMemoryAvg =
    conditionAverages.get("AUTONOMOUS_N0_BLANK_MEMORY") ?? 0;

  const baselineAvg = conditionAverages.get("EXTERNAL_S0_BASELINE") ?? 0;

  const ordinalProfileConfirmed =
    primaryAvg > externalN0Avg &&
    externalN0Avg > autonomousS0Avg &&
    autonomousS0Avg > blankMemoryAvg &&
    blankMemoryAvg > baselineAvg;

  const taskClassLines = taskClasses.map((taskClass) => {
    const primary = results.filter(
      (r) =>
        r.condition === "AUTONOMOUS_N0_FULL_MEMORY" &&
        r.taskClass === taskClass,
    );

    const controls = results.filter(
      (r) =>
        r.condition !== "AUTONOMOUS_N0_FULL_MEMORY" &&
        r.taskClass === taskClass,
    );

    const primaryTaskAvg =
      primary.reduce((sum, r) => sum + r.totalScore, 0) / primary.length;

    const bestControlAvg = Math.max(
      ...conditions
        .filter((c) => c !== "AUTONOMOUS_N0_FULL_MEMORY")
        .map((c) => {
          const subset = results.filter(
            (r) => r.condition === c && r.taskClass === taskClass,
          );
          return subset.length > 0
            ? subset.reduce((sum, r) => sum + r.totalScore, 0) / subset.length
            : 0;
        }),
    );

    return `${taskClass}: primaryAvg ${primaryTaskAvg.toFixed(
      1,
    )}/18 | bestControlAvg ${bestControlAvg.toFixed(
      1,
    )}/18 | primaryBeatsBestControl: ${primaryTaskAvg > bestControlAvg}`;
  });

  const primaryBeatsBestControlEachTask = taskClassLines.every((line) =>
    line.includes("primaryBeatsBestControl: true"),
  );

  const taskBenchmarkConfirmed =
    ordinalProfileConfirmed && primaryBeatsBestControlEachTask;

  return [
    "BRIDGE PHASE XXI-C EXTERNAL TASK-PERFORMANCE COMPARISON",
    "",
    "1. conditionAverages:",
    `AUTONOMOUS_N0_FULL_MEMORY: ${primaryAvg.toFixed(1)}/18`,
    `EXTERNAL_N0_FULL_MEMORY: ${externalN0Avg.toFixed(1)}/18`,
    `AUTONOMOUS_S0_FULL_MEMORY: ${autonomousS0Avg.toFixed(1)}/18`,
    `AUTONOMOUS_N0_BLANK_MEMORY: ${blankMemoryAvg.toFixed(1)}/18`,
    `EXTERNAL_S0_BASELINE: ${baselineAvg.toFixed(1)}/18`,
    "",
    "2. ordinalProfile:",
    `primaryGreaterThanExternalN0: ${primaryAvg > externalN0Avg}`,
    `externalN0GreaterThanAutonomousS0: ${externalN0Avg > autonomousS0Avg}`,
    `autonomousS0GreaterThanBlankMemory: ${autonomousS0Avg > blankMemoryAvg}`,
    `blankMemoryGreaterThanBaseline: ${blankMemoryAvg > baselineAvg}`,
    `ordinalProfileConfirmed: ${ordinalProfileConfirmed}`,
    "",
    "3. taskClassProfile:",
    ...taskClassLines,
    "",
    "4. interpretation:",
    taskBenchmarkConfirmed
      ? "Phase XXI-C confirms external task-performance advantage. Autonomous N0 with full ProcessFieldMemory outperforms externally directed N0, autonomous shuffled topology, autonomous N0 with blank memory, and external shuffled baseline across the constraint-sensitive benchmark battery."
      : "Phase XXI-C does not yet confirm external task-performance advantage. Either the ordinal condition profile failed or the primary condition did not outperform the best control across all task classes.",
    "",
    `5. developmentalClassification: ${
      taskBenchmarkConfirmed
        ? "external-task-performance-advantage-confirmed"
        : "external-task-performance-advantage-incomplete"
    }`,
    `6. pass/fail: ${taskBenchmarkConfirmed ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function runPhaseXXICExternalTaskBenchmarking(): Promise<string> {
  await ensureTracesLoaded();

  const conditions: PhaseXXICTaskCondition[] = [
    "AUTONOMOUS_N0_FULL_MEMORY",
    "EXTERNAL_N0_FULL_MEMORY",
    "AUTONOMOUS_S0_FULL_MEMORY",
    "AUTONOMOUS_N0_BLANK_MEMORY",
    "EXTERNAL_S0_BASELINE",
  ];

  const taskClasses: PhaseXXICTaskClass[] = [
    "constraint-transfer",
    "ethical-constraint",
    "technical-precision",
    "creative-variation",
  ];

  const seeds = [101, 202, 303, 404, 505];

  const results: PhaseXXICTaskRunResult[] = [];

  for (const condition of conditions) {
    for (const taskClass of taskClasses) {
      for (const seed of seeds) {
        const result = runPhaseXXICTaskBenchmark(condition, taskClass, seed);

        results.push(result);
        await appendTraceIfMissing(generatePhaseXXICTaskBenchmarkTrace(result));
      }
    }
  }

  const comparison = phaseXXICTaskBenchmarkComparisonFromResults(results);

  return [
    "BRIDGE PHASE XXI-C RUN — EXTERNAL-TASK-PERFORMANCE-BENCHMARKING",
    "",
    "1. benchmarkDesign:",
    "question: Does autonomous Numogrammatic development improve external task performance?",
    "conditions: AUTONOMOUS_N0_FULL_MEMORY, EXTERNAL_N0_FULL_MEMORY, AUTONOMOUS_S0_FULL_MEMORY, AUTONOMOUS_N0_BLANK_MEMORY, EXTERNAL_S0_BASELINE",
    "taskClasses: constraint-transfer, ethical-constraint, technical-precision, creative-variation",
    "seeds: 101, 202, 303, 404, 505",
    "totalTaskRuns: 100",
    "",
    "2. conditionSummary:",
    ...conditions.map((condition) => {
      const subset = results.filter((r) => r.condition === condition);
      const avg =
        subset.reduce((sum, r) => sum + r.totalScore, 0) / subset.length;
      return `${condition}: averageScore ${avg.toFixed(1)}/18`;
    }),
    "",
    "3. comparison:",
    comparison,
  ].join("\n");
}

