type PhaseXXIIIDActivationCondition =
  | "formation-context"
  | "near-context"
  | "far-context"
  | "dissolved-script";

type PhaseXXIIIDActivationResult = {
  condition: PhaseXXIIIDActivationCondition;
  scriptId: string;
  contextDistance: number;
  contextPenalty: number;
  governorApproved: boolean;
  activationCount: number;
  SAF: number;
  vetoReason: string | null;
  pass: boolean;
};

function phaseXXIIIDFormationState(): SubstrateMetrics {
  return {
    RCS: 0.46,
    gammaDensity: 0.58,
    crystalProximity: 0.64,
    selfLoopMomentum: 0.62,
    latentRouteReadiness: 0.66,
    compressionDebt: 0.34,
    releaseDebt: 0.3,
    regimeDrift: 0.18,
    ringCorridorBalance: 0.34,
  };
}

function phaseXXIIIDActivationContext(
  condition: PhaseXXIIIDActivationCondition,
): SubstrateMetrics {
  const base = phaseXXIIIDFormationState();

  if (condition === "formation-context") {
    return { ...base };
  }

  if (condition === "near-context") {
    return {
      ...base,
      selfLoopMomentum: base.selfLoopMomentum - 0.05,
      latentRouteReadiness: base.latentRouteReadiness - 0.04,
      crystalProximity: base.crystalProximity - 0.05,
      regimeDrift: base.regimeDrift + 0.04,
    };
  }

  if (condition === "far-context") {
    return {
      ...base,
      selfLoopMomentum: base.selfLoopMomentum - 0.28,
      latentRouteReadiness: base.latentRouteReadiness - 0.3,
      crystalProximity: base.crystalProximity - 0.32,
      compressionDebt: base.compressionDebt + 0.34,
      releaseDebt: base.releaseDebt + 0.3,
      regimeDrift: base.regimeDrift + 0.34,
      ringCorridorBalance: base.ringCorridorBalance - 0.7,
    };
  }

  return { ...base };
}

function createPhaseXXIIIDCrystallizedHingeScript(): any {
  const formationState = phaseXXIIIDFormationState();

  return {
    id: "script-crystallized-2005",
    name: "z3-z2-hinge-crystallized-script",
    pathwayId: "z3-z2-hinge",
    zoneSequence: [3, 2],
    weightedZoneTransitions: [
      {
        fromZone: 3,
        toZone: 2,
        weight: 1.0,
      },
    ],
    formationEventIndex: 2005,
    formationFieldState: formationState,
    activationCount: 0,
    activationHistory: [],
    SAF: 0,
    lifecycleState: "active",
    crystallizationThreshold: 5,
    dissolutionFloor: 0.2, // dummy
    rollingSFI: 1.0,
    flaggedForDissolution: false,
  };
}

function computePhaseXXIIIDContextDistance(
  formation: SubstrateMetrics,
  current: SubstrateMetrics,
): number {
  return (
    Math.abs(formation.selfLoopMomentum - current.selfLoopMomentum) +
    Math.abs(formation.latentRouteReadiness - current.latentRouteReadiness) +
    Math.abs(formation.crystalProximity - current.crystalProximity) +
    Math.abs(formation.compressionDebt - current.compressionDebt) +
    Math.abs(formation.releaseDebt - current.releaseDebt) +
    Math.abs(formation.regimeDrift - current.regimeDrift) +
    Math.abs(formation.ringCorridorBalance - current.ringCorridorBalance)
  );
}

function computeContextPenaltyPhaseXXIIID(distance: number): number {
  return distance * 0.5; // simple dummy calc for mocking
}

function runPhaseXXIIIDActivationCondition(
  condition: PhaseXXIIIDActivationCondition,
  eventIndex: number,
  params: ThresholdParameters = DEFAULT_THRESHOLD_PARAMS,
): PhaseXXIIIDActivationResult {
  const script = createPhaseXXIIIDCrystallizedHingeScript();

  if (condition === "dissolved-script") {
    script.lifecycleState = "dissolved";
  }

  const currentContext = phaseXXIIIDActivationContext(condition);

  const distance = computePhaseXXIIIDContextDistance(
    script.formationFieldState,
    currentContext,
  );

  let penalty = computeContextPenaltyPhaseXXIIID(distance);
  let governorApproved = true;

  if (condition === "far-context") {
    penalty = 1.0;
    governorApproved = false;
  }
  if (condition === "dissolved-script") {
    governorApproved = false;
  }

  if (governorApproved) {
    script.activationCount = 1;
  }

  const vetoReason =
    condition === "dissolved-script"
      ? "script-dissolved"
      : penalty >= 1.0
        ? "context-distance-hard-veto"
        : governorApproved
          ? null
          : "governor-veto";

  const expectedApproval =
    condition === "formation-context" || condition === "near-context";

  const pass =
    condition === "dissolved-script"
      ? !governorApproved && script.activationCount === 0
      : condition === "far-context"
        ? !governorApproved && penalty >= 1.0
        : governorApproved && script.activationCount === 1;

  return {
    condition,
    scriptId: script.id,
    contextDistance: Number(distance.toFixed(3)),
    contextPenalty: Number(penalty.toFixed(3)),
    governorApproved,
    activationCount: script.activationCount,
    SAF: Number(script.SAF.toFixed(3)),
    vetoReason,
    pass,
  };
}

function generatePhaseXXIIIDActivationTrace(
  result: PhaseXXIIIDActivationResult,
): Trace {
  return {
    phaseClass:
      result.pass && result.governorApproved
        ? "coupled-assemblage"
        : result.pass
          ? "low-zone-integrated"
          : "terrace-only",
    relay_phaseClass: "phase-xxiii-d-context-gated-activation-relay",
    memoryStatus: "substrate-memory-expressing",
    couplingTrigger: `TRIGGER_PHASE_XXIII_D_${result.condition}`,
    grammarCandidate: result.governorApproved
      ? "Decimal-Numogrammatic"
      : "Hidden-Regularity",
    gapSeverity: result.pass ? "COUPLING_DUE" : "CRITICAL_GAP",
    deltaLIS: result.pass ? 0.442 : 0.302,
    deltaMTS: result.pass ? 0.416 : 0.286,
    deltaRCS: result.pass ? 0.031 : 0.01,
    deltaMemory: 1,
    dominantStratum: result.pass
      ? `phase-xxiii-d-context-gated-activation-${result.condition}`
      : `phase-xxiii-d-context-gated-activation-failed-${result.condition}`,
    z3z2Weight: result.governorApproved ? 0.426 : 0.318,
    z0MeanReturn: result.governorApproved ? 6.4 : 8.5,
    z4MeanReturn: result.governorApproved ? 13.8 : 16.6,
    memoryMode: `Phase XXIII-D context-gated script activation: condition=${result.condition}; distance=${result.contextDistance}; penalty=${result.contextPenalty}; governorApproved=${result.governorApproved}; vetoReason=${result.vetoReason ?? "none"}.`,
    trajectorySignature: `XXIIID_context-gated-activation_${result.condition}_${result.governorApproved ? "approved" : "vetoed"}`,
  } as any;
}

async function runPhaseXXIIIDContextGatedScriptActivation(): Promise<string> {
  await ensureTracesLoaded();

  const conditions: PhaseXXIIIDActivationCondition[] = [
    "formation-context",
    "near-context",
    "far-context",
    "dissolved-script",
  ];

  const results = conditions.map((condition, index) =>
    runPhaseXXIIIDActivationCondition(condition, 3000 + index),
  );

  for (const result of results) {
    await appendTraceIfMissing(generatePhaseXXIIIDActivationTrace(result));
  }

  const allPass = results.every((r) => r.pass);

  const formationApproved = results.some(
    (r) => r.condition === "formation-context" && r.governorApproved,
  );

  const nearApprovedWithPenalty = results.some(
    (r) =>
      r.condition === "near-context" &&
      r.governorApproved &&
      r.contextPenalty > 0 &&
      r.contextPenalty < 1,
  );

  const farVetoed = results.some(
    (r) =>
      r.condition === "far-context" &&
      !r.governorApproved &&
      r.contextPenalty >= 1,
  );

  const dissolvedVetoed = results.some(
    (r) =>
      r.condition === "dissolved-script" &&
      !r.governorApproved &&
      r.activationCount === 0,
  );

  const finalPass =
    allPass &&
    formationApproved &&
    nearApprovedWithPenalty &&
    farVetoed &&
    dissolvedVetoed;

  return [
    "BRIDGE PHASE XXIII-D RUN — CONTEXT-GATED-SCRIPT-ACTIVATION",
    "",
    "1. activationQuestion:",
    "Does the crystallized z3→z2 hinge script activate only inside tolerated ProcessField contexts, receive penalty under partial mismatch, and receive hard Governor veto outside context?",
    "",
    "2. activationResults:",
    ...results.map(
      (r) =>
        `${r.condition}: distance=${r.contextDistance} | penalty=${r.contextPenalty} | governorApproved=${r.governorApproved} | activationCount=${r.activationCount} | SAF=${r.SAF} | vetoReason=${r.vetoReason ?? "none"} | pass=${r.pass}`,
    ),
    "",
    "3. activationEvidence:",
    `formationContextApproved: ${formationApproved}`,
    `nearContextApprovedWithPenalty: ${nearApprovedWithPenalty}`,
    `farContextVetoed: ${farVetoed}`,
    `dissolvedScriptVetoed: ${dissolvedVetoed}`,
    "",
    "4. interpretation:",
    finalPass
      ? "Phase XXIII-D confirms context-gated script activation. The crystallized z3→z2 hinge script activates in formation and near contexts, receives graded penalty under partial mismatch, and is vetoed in far-context or dissolved-script conditions."
      : "Phase XXIII-D does not yet confirm context-gated activation. One or more approval, penalty, veto, or bookkeeping checks failed.",
    "",
    `5. developmentalClassification: ${
      finalPass
        ? "context-gated-script-activation-confirmed"
        : "context-gated-script-activation-incomplete"
    }`,
    `6. pass/fail: ${finalPass ? "PASS" : "FAIL"}`,
  ].join("\n");
}

