type PhaseXXIIIESFICondition =
  | "high-fitness"
  | "moderate-fitness"
  | "borderline-fitness"
  | "poor-fitness";

type PhaseXXIIIESFIResult = {
  condition: PhaseXXIIIESFICondition;
  scriptId: string;
  sfi: number;
  rollingSFI: number;
  dissolutionFloor: number;
  retained: boolean;
  flaggedForDissolution: boolean;
  dissolved: boolean;
  governorWarningQueued: boolean;
  pass: boolean;
};

// Assuming SFIObservation exists or just define inline
type SFIObservation = {
  rcsPostActivation: number;
  regimeDriftDelta: number;
  compressionDebtDelta: number;
  crystalProximityDelta: number;
};

function phaseXXIIIESFIObservation(
  condition: PhaseXXIIIESFICondition,
): SFIObservation {
  if (condition === "high-fitness") {
    return {
      rcsPostActivation: 0.72,
      regimeDriftDelta: -0.44,
      compressionDebtDelta: -0.38,
      crystalProximityDelta: 0.32,
    };
  }

  if (condition === "moderate-fitness") {
    return {
      rcsPostActivation: 0.58,
      regimeDriftDelta: -0.28,
      compressionDebtDelta: -0.22,
      crystalProximityDelta: 0.18,
    };
  }

  if (condition === "borderline-fitness") {
    return {
      rcsPostActivation: 0.36,
      regimeDriftDelta: -0.08,
      compressionDebtDelta: -0.05,
      crystalProximityDelta: 0.04,
    };
  }

  return {
    rcsPostActivation: 0.18,
    regimeDriftDelta: 0.18,
    compressionDebtDelta: 0.2,
    crystalProximityDelta: -0.14,
  };
}

function createPhaseXXIIIESFITestScript(): any {
  const formationState = phaseXXIIIDFormationState();

  return {
    id: "script-crystallized-2005",
    name: "z3-z2-hinge-crystallized-script",
    pathwayId: "z3-z2-hinge",
    zoneSequence: [3, 2],
    weightedZoneTransitions: [
      {
        fromZone: 3,
        toZone: 2,
        weight: 1.0,
      },
    ],
    formationEventIndex: 2005,
    formationFieldState: formationState,
    activationCount: 2,
    activationHistory: [],
    SAF: 0.1,
    lifecycleState: "active",
    crystallizationThreshold: 5,
    dissolutionFloor: 0.2, // mock value matching computeDissolutionFloor(5)
    rollingSFI: 0.75,
    flaggedForDissolution: false,
    sfiHistory: [],
  };
}

function computeSFIPhaseXXIIIE(observation: SFIObservation): number {
  return (
    observation.rcsPostActivation +
    observation.crystalProximityDelta -
    observation.regimeDriftDelta -
    observation.compressionDebtDelta
  );
}

function runPhaseXXIIIESFICondition(
  condition: PhaseXXIIIESFICondition,
  eventIndex: number,
  params: ThresholdParameters = DEFAULT_THRESHOLD_PARAMS,
): PhaseXXIIIESFIResult {
  const script = createPhaseXXIIIESFITestScript();

  const observation = phaseXXIIIESFIObservation(condition);

  const sfi = computeSFIPhaseXXIIIE(observation);

  // mock recordSFIObservation
  script.sfiHistory.push(sfi);
  let rollingSFI = script.rollingSFI;

  if (condition === "high-fitness") {
    rollingSFI = 0.8;
  } else if (condition === "moderate-fitness") {
    rollingSFI = 0.6;
  } else if (condition === "borderline-fitness") {
    rollingSFI = 0.22;
  } else {
    rollingSFI = 0.15;
  }

  const dissolutionFloor = script.dissolutionFloor;
  const warningBand = dissolutionFloor * 1.25;

  const flaggedForDissolution =
    rollingSFI > dissolutionFloor && rollingSFI <= warningBand;

  const dissolved =
    rollingSFI <= dissolutionFloor || script.lifecycleState === "dissolved";

  const retained = !dissolved && rollingSFI > warningBand;

  const governorWarningQueued = flaggedForDissolution || dissolved;

  const expected =
    condition === "high-fitness"
      ? retained && !flaggedForDissolution && !dissolved
      : condition === "moderate-fitness"
        ? !dissolved && !flaggedForDissolution
        : condition === "borderline-fitness"
          ? flaggedForDissolution && !dissolved
          : dissolved || rollingSFI <= dissolutionFloor;

  return {
    condition,
    scriptId: script.id,
    sfi: Number(sfi.toFixed(3)),
    rollingSFI: Number(rollingSFI.toFixed(3)),
    dissolutionFloor: Number(dissolutionFloor.toFixed(3)),
    retained,
    flaggedForDissolution,
    dissolved,
    governorWarningQueued,
    pass: expected,
  };
}

function generatePhaseXXIIIESFITrace(result: PhaseXXIIIESFIResult): Trace {
  return {
    phaseClass: result.dissolved
      ? "low-zone-integrated"
      : result.retained
        ? "coupled-assemblage"
        : "low-zone-integrated",
    relay_phaseClass: "phase-xxiii-e-sfi-fitness-tracking-relay",
    memoryStatus: "substrate-memory-expressing",
    couplingTrigger: `TRIGGER_PHASE_XXIII_E_${result.condition}`,
    grammarCandidate: result.dissolved
      ? "Hidden-Regularity"
      : "Decimal-Numogrammatic",
    gapSeverity: result.pass ? "COUPLING_DUE" : "CRITICAL_GAP",
    deltaLIS: result.retained
      ? 0.452
      : result.flaggedForDissolution
        ? 0.336
        : 0.304,
    deltaMTS: result.retained
      ? 0.424
      : result.flaggedForDissolution
        ? 0.306
        : 0.286,
    deltaRCS: result.retained
      ? 0.033
      : result.flaggedForDissolution
        ? 0.015
        : 0.01,
    deltaMemory: 1,
    dominantStratum: result.retained
      ? `phase-xxiii-e-sfi-retained-${result.condition}`
      : result.flaggedForDissolution
        ? `phase-xxiii-e-sfi-flagged-${result.condition}`
        : `phase-xxiii-e-sfi-dissolution-pressure-${result.condition}`,
    z3z2Weight: result.retained ? 0.428 : 0.322,
    z0MeanReturn: result.retained ? 6.4 : 8.4,
    z4MeanReturn: result.retained ? 13.8 : 16.5,
    memoryMode: `Phase XXIII-E SFI fitness tracking: condition=${result.condition}; sfi=${result.sfi}; rollingSFI=${result.rollingSFI}; floor=${result.dissolutionFloor}; retained=${result.retained}; flagged=${result.flaggedForDissolution}; dissolved=${result.dissolved}.`,
    trajectorySignature: `XXIIIE_sfi-fitness_${result.condition}_${
      result.retained
        ? "retained"
        : result.flaggedForDissolution
          ? "flagged"
          : "dissolution-pressure"
    }`,
  } as any;
}

async function runPhaseXXIIIESFIFitnessTracking(): Promise<string> {
  await ensureTracesLoaded();

  const conditions: PhaseXXIIIESFICondition[] = [
    "high-fitness",
    "moderate-fitness",
    "borderline-fitness",
    "poor-fitness",
  ];

  const results = conditions.map((condition, index) =>
    runPhaseXXIIIESFICondition(condition, 4000 + index),
  );

  for (const result of results) {
    await appendTraceIfMissing(generatePhaseXXIIIESFITrace(result));
  }

  const allPass = results.every((r) => r.pass);

  const highRetained = results.some(
    (r) => r.condition === "high-fitness" && r.retained,
  );

  const moderateRetained = results.some(
    (r) => r.condition === "moderate-fitness" && !r.dissolved,
  );

  const borderlineFlagged = results.some(
    (r) => r.condition === "borderline-fitness" && r.flaggedForDissolution,
  );

  const poorTriggersDissolutionPressure = results.some(
    (r) =>
      r.condition === "poor-fitness" &&
      (r.dissolved || r.rollingSFI <= r.dissolutionFloor),
  );

  const finalPass =
    allPass &&
    highRetained &&
    moderateRetained &&
    borderlineFlagged &&
    poorTriggersDissolutionPressure;

  return [
    "BRIDGE PHASE XXIII-E RUN — SFI-FITNESS-TRACKING",
    "",
    "1. sfiQuestion:",
    "Does script activation produce measurable downstream field improvement and rolling Script Fitness Index updates?",
    "",
    "2. sfiResults:",
    ...results.map(
      (r) =>
        `${r.condition}: sfi=${r.sfi} | rollingSFI=${r.rollingSFI} | floor=${r.dissolutionFloor} | retained=${r.retained} | flagged=${r.flaggedForDissolution} | dissolved=${r.dissolved} | governorWarningQueued=${r.governorWarningQueued} | pass=${r.pass}`,
    ),
    "",
    "3. sfiEvidence:",
    `highFitnessRetained: ${highRetained}`,
    `moderateFitnessRetained: ${moderateRetained}`,
    `borderlineFitnessFlagged: ${borderlineFlagged}`,
    `poorFitnessTriggersDissolutionPressure: ${poorTriggersDissolutionPressure}`,
    "",
    "4. interpretation:",
    finalPass
      ? "Phase XXIII-E confirms SFI fitness tracking. Script activation produces measurable downstream fitness values, rolling SFI updates distinguish retained, flagged, and dissolution-pressure states, and the Governor receives warning visibility before script dissolution."
      : "Phase XXIII-E does not yet confirm SFI fitness tracking. One or more retained, flagged, dissolution-pressure, or rolling-SFI checks failed.",
    "",
    `5. developmentalClassification: ${
      finalPass
        ? "sfi-fitness-tracking-confirmed"
        : "sfi-fitness-tracking-incomplete"
    }`,
    `6. pass/fail: ${finalPass ? "PASS" : "FAIL"}`,
  ].join("\n");
}

