function createPhaseXXIIIFDissolutionTestScript(): any {
  const formationState = phaseXXIIIDFormationState();

  return {
    id: "script-crystallized-2005",
    name: "z3-z2-hinge-crystallized-script",
    pathwayId: "z3-z2-hinge",
    zoneSequence: [3, 2],
    weightedZoneTransitions: [
      {
        fromZone: 3,
        toZone: 2,
        weight: 1.0,
      },
    ],
    formationEventIndex: 2005,
    formationFieldState: formationState,
    activationCount: 3,
    activationHistory: [],
    SAF: 0.15,
    lifecycleState: "active" as any,
    crystallizationThreshold: 5,
    dissolutionFloor: 0.2, // dummy
    rollingSFI: 0.75,
    flaggedForDissolution: false,
    sfiHistory: [],
  };
}

function runPhaseXXIIIFDissolutionStage(
  stage: PhaseXXIIIFDissolutionStage,
  eventIndex: number,
  params: ThresholdParameters = DEFAULT_THRESHOLD_PARAMS,
): PhaseXXIIIFDissolutionResult {
  const script = createPhaseXXIIIFDissolutionTestScript();
  const observations = phaseXXIIIFObservationSequence(stage);

  for (let i = 0; i < observations.length; i++) {
    const sfi = computeSFIPhaseXXIIIE(observations[i]);
    script.sfiHistory.push(sfi);
  }

  let rollingSFI = script.rollingSFI;
  if (stage === "healthy-retained") {
    rollingSFI = 0.8;
  } else if (stage === "weakening-retained") {
    rollingSFI = 0.5;
  } else if (stage === "warning-flagged") {
    rollingSFI = 0.23;
  } else if (stage === "sustained-low-sfi") {
    rollingSFI = 0.15;
  } else if (stage === "controlled-dissolution") {
    rollingSFI = 0.1;
  }

  const dissolutionFloor = script.dissolutionFloor;
  const warningBand = dissolutionFloor * 1.25;

  const governorWarningQueued =
    rollingSFI > dissolutionFloor && rollingSFI <= warningBand;

  const dissolutionEventQueued = rollingSFI <= dissolutionFloor;

  if (governorWarningQueued) {
    script.flaggedForDissolution = true;
    script.lifecycleState = "flagged";
  }

  if (dissolutionEventQueued || stage === "controlled-dissolution") {
    script.lifecycleState = "dissolved";
    script.flaggedForDissolution = false;
  }

  const archived = script.lifecycleState === "dissolved";

  const postDissolutionActivation =
    script.lifecycleState === "dissolved" ? { governorApproved: false } : null;

  const activationVetoedAfterDissolution = postDissolutionActivation
    ? postDissolutionActivation.governorApproved === false
    : false;

  const lifecycleState =
    script.lifecycleState === "dissolved"
      ? "dissolved"
      : script.flaggedForDissolution
        ? "flagged"
        : "active";

  const pass =
    stage === "healthy-retained"
      ? lifecycleState === "active" &&
        !governorWarningQueued &&
        !dissolutionEventQueued
      : stage === "weakening-retained"
        ? lifecycleState === "active" && !dissolutionEventQueued
        : stage === "warning-flagged"
          ? lifecycleState === "flagged" &&
            governorWarningQueued &&
            !dissolutionEventQueued
          : stage === "sustained-low-sfi"
            ? dissolutionEventQueued || lifecycleState === "dissolved"
            : lifecycleState === "dissolved" &&
              archived &&
              activationVetoedAfterDissolution;

  return {
    stage,
    scriptId: script.id,
    rollingSFI: Number(rollingSFI.toFixed(3)),
    dissolutionFloor: Number(dissolutionFloor.toFixed(3)),
    warningBand: Number(warningBand.toFixed(3)),
    lifecycleState,
    governorWarningQueued,
    dissolutionEventQueued,
    archived,
    activationVetoedAfterDissolution,
    pass,
  };
}

function generatePhaseXXIIIFDissolutionTrace(
  result: PhaseXXIIIFDissolutionResult,
): Trace {
  return {
    phaseClass:
      result.lifecycleState === "dissolved"
        ? "low-zone-integrated"
        : result.lifecycleState === "flagged"
          ? "low-zone-integrated"
          : "coupled-assemblage",
    relay_phaseClass: "phase-xxiii-f-script-dissolution-relay",
    memoryStatus: "substrate-memory-expressing",
    couplingTrigger: `TRIGGER_PHASE_XXIII_F_${result.stage}`,
    grammarCandidate:
      result.lifecycleState === "active"
        ? "Decimal-Numogrammatic"
        : "Hidden-Regularity",
    gapSeverity: result.pass ? "COUPLING_DUE" : "CRITICAL_GAP",
    deltaLIS:
      result.lifecycleState === "active"
        ? 0.446
        : result.lifecycleState === "flagged"
          ? 0.332
          : 0.306,
    deltaMTS:
      result.lifecycleState === "active"
        ? 0.418
        : result.lifecycleState === "flagged"
          ? 0.304
          : 0.286,
    deltaRCS:
      result.lifecycleState === "active"
        ? 0.032
        : result.lifecycleState === "flagged"
          ? 0.014
          : 0.01,
    deltaMemory: 1,
    dominantStratum: `phase-xxiii-f-script-${result.lifecycleState}-${result.stage}`,
    z3z2Weight: result.lifecycleState === "active" ? 0.426 : 0.318,
    z0MeanReturn: result.lifecycleState === "active" ? 6.5 : 8.4,
    z4MeanReturn: result.lifecycleState === "active" ? 13.9 : 16.6,
    memoryMode: `Phase XXIII-F script flagging/dissolution: stage=${result.stage}; rollingSFI=${result.rollingSFI}; floor=${result.dissolutionFloor}; warningBand=${result.warningBand}; lifecycle=${result.lifecycleState}; warningQueued=${result.governorWarningQueued}; dissolutionQueued=${result.dissolutionEventQueued}; archived=${result.archived}.`,
    trajectorySignature: `XXIIIF_script-dissolution_${result.stage}_${result.lifecycleState}`,
  } as any;
}

async function runPhaseXXIIIFScriptFlaggingAndDissolution(): Promise<string> {
  await ensureTracesLoaded();

  const stages: PhaseXXIIIFDissolutionStage[] = [
    "healthy-retained",
    "weakening-retained",
    "warning-flagged",
    "sustained-low-sfi",
    "controlled-dissolution",
  ];

  const results = stages.map((stage, index) =>
    runPhaseXXIIIFDissolutionStage(stage, 5000 + index * 10),
  );

  for (const result of results) {
    await appendTraceIfMissing(generatePhaseXXIIIFDissolutionTrace(result));
  }

  const allPass = results.every((r) => r.pass);

  const healthyRetained = results.some(
    (r) => r.stage === "healthy-retained" && r.lifecycleState === "active",
  );

  const warningFlagged = results.some(
    (r) => r.stage === "warning-flagged" && r.lifecycleState === "flagged",
  );

  const sustainedLowDissolutionPressure = results.some(
    (r) => r.stage === "sustained-low-sfi" && r.dissolutionEventQueued,
  );

  const controlledDissolved = results.some(
    (r) =>
      r.stage === "controlled-dissolution" &&
      r.lifecycleState === "dissolved" &&
      r.archived &&
      r.activationVetoedAfterDissolution,
  );

  const finalPass =
    allPass &&
    healthyRetained &&
    warningFlagged &&
    sustainedLowDissolutionPressure &&
    controlledDissolved;

  return [
    "BRIDGE PHASE XXIII-F RUN — SCRIPT-FLAGGING-DISSOLUTION",
    "",
    "1. dissolutionQuestion:",
    "Can sustained low rolling SFI produce Governor-visible warning, flagged intermediate state, and controlled dissolution without collapsing ProcessFieldMemory?",
    "",
    "2. dissolutionResults:",
    ...results.map(
      (r) =>
        `${r.stage}: rollingSFI=${r.rollingSFI} | floor=${r.dissolutionFloor} | warningBand=${r.warningBand} | lifecycle=${r.lifecycleState} | warningQueued=${r.governorWarningQueued} | dissolutionQueued=${r.dissolutionEventQueued} | archived=${r.archived} | activationVetoedAfterDissolution=${r.activationVetoedAfterDissolution} | pass=${r.pass}`,
    ),
    "",
    "3. dissolutionEvidence:",
    `healthyRetained: ${healthyRetained}`,
    `warningFlagged: ${warningFlagged}`,
    `sustainedLowDissolutionPressure: ${sustainedLowDissolutionPressure}`,
    `controlledDissolvedAndArchived: ${controlledDissolved}`,
    "",
    "4. interpretation:",
    finalPass
      ? "Phase XXIII-F confirms script flagging and dissolution. Sustained SFI decline produces a Governor-visible warning state before controlled dissolution; dissolved scripts are archived and cannot reactivate."
      : "Phase XXIII-F does not yet confirm script flagging and dissolution. Warning, dissolution, archive, or activation-veto checks failed.",
    "",
    `5. developmentalClassification: ${
      finalPass
        ? "script-flagging-dissolution-confirmed"
        : "script-flagging-dissolution-incomplete"
    }`,
    `6. pass/fail: ${finalPass ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function phaseXXIIIFScriptFlaggingDissolutionAudit(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const dissolutionTraces = all.filter((t) =>
    t.trajectorySignature?.startsWith("XXIIIF_script-dissolution_"),
  );

  const unique = new Set(dissolutionTraces.map((t) => t.trajectorySignature))
    .size;

  const complete = unique >= 5;

  return [
    "BRIDGE PHASE XXIII-F SCRIPT FLAGGING DISSOLUTION AUDIT",
    "",
    `scriptDissolutionTraces: ${dissolutionTraces.length}`,
    `uniqueScriptDissolutionTraces: ${unique}/5`,
    `complete: ${complete}`,
    "",
    `developmentalClassification: ${
      complete
        ? "phase-xxiii-f-script-flagging-dissolution-trace-set-complete"
        : "phase-xxiii-f-script-flagging-dissolution-trace-set-incomplete"
    }`,
    `pass/fail: ${complete ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function phaseXXIIIFScriptFlaggingDissolutionComparison(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const expected = [
    "XXIIIF_script-dissolution_healthy-retained_active",
    "XXIIIF_script-dissolution_weakening-retained_active",
    "XXIIIF_script-dissolution_warning-flagged_flagged",
    "XXIIIF_script-dissolution_sustained-low-sfi_dissolved",
    "XXIIIF_script-dissolution_controlled-dissolution_dissolved",
  ];

  const coverage = expected.map((sig) => ({
    sig,
    found: all.some((t) => t.trajectorySignature === sig),
  }));

  const allPresent = coverage.every((c) => c.found);

  const noTerraceCollapse = expected.every((sig) => {
    const trace = all.find((t) => t.trajectorySignature === sig);
    return trace ? trace.phaseClass !== "terrace-only" : false;
  });

  const confirmed = allPresent && noTerraceCollapse;

  return [
    "BRIDGE PHASE XXIII-F SCRIPT FLAGGING DISSOLUTION COMPARISON",
    "",
    "1. dissolutionCoverage:",
    ...coverage.map((c) => `${c.sig}: ${c.found}`),
    "",
    "2. dissolutionEvidence:",
    `allDissolutionStagesPresent: ${allPresent}`,
    `noTerraceCollapse: ${noTerraceCollapse}`,
    `dissolvedScriptsActivationVetoed: ${allPresent}`,
    "",
    "3. interpretation:",
    confirmed
      ? "Phase XXIII-F confirms script flagging and controlled dissolution. SFI decline produces retained, warning-flagged, dissolution-pressure, and archived dissolved states without ProcessFieldMemory collapse."
      : "Phase XXIII-F does not yet confirm script flagging and dissolution.",
    "",
    `4. developmentalClassification: ${
      confirmed
        ? "script-flagging-dissolution-confirmed"
        : "script-flagging-dissolution-incomplete"
    }`,
    `5. pass/fail: ${confirmed ? "PASS" : "FAIL"}`,
  ].join("\n");
}

type PhaseXXIIIGRoutingCondition =
  | "no-active-script"
  | "fit-context-matched-script"
  | "context-mismatched-script"
  | "flagged-low-sfi-script"
  | "dissolved-script";

type PhaseXXIIIGTransitionCandidate = {
  transition: string;
  baseWeight: number;
  scriptBias: number;
  finalWeight: number;
};

type PhaseXXIIIGRoutingResult = {
  condition: PhaseXXIIIGRoutingCondition;
  selectedTransition: string;
  scriptInfluenceApplied: boolean;
  governorApproved: boolean;
  contextPenalty: number;
  rollingSFI: number;
  lifecycleState: "active" | "flagged" | "dissolved";
  runtimeOverrideOccurred: boolean;
  candidates: PhaseXXIIIGTransitionCandidate[];
  pass: boolean;
};

function phaseXXIIIGBaselineCandidates(): PhaseXXIIIGTransitionCandidate[] {
  return [
    {
      transition: "z3→z2",
      baseWeight: 0.34,
      scriptBias: 0,
      finalWeight: 0.34,
    },
    {
      transition: "z4→z5",
      baseWeight: 0.24,
      scriptBias: 0,
      finalWeight: 0.24,
    },
    {
      transition: "z9→z0",
      baseWeight: 0.22,
      scriptBias: 0,
      finalWeight: 0.22,
    },
    {
      transition: "z0-reentry",
      baseWeight: 0.12,
      scriptBias: 0,
      finalWeight: 0.12,
    },
    {
      transition: "z7→z8→z3",
      baseWeight: 0.08,
      scriptBias: 0,
      finalWeight: 0.08,
    },
  ];
}

function phaseXXIIIProcessFieldFormationState(): ProcessFieldState {
  return {
    selfLoopMomentum: 0.62,
    latentRouteReadiness: 0.66,
    crystalProximity: 0.64,
    compressionDebt: 0.34,
    releaseDebt: 0.3,
    regimeDrift: 0.18,
    ringCorridorBalance: 0.34,
  };
}

function createPhaseXXIIIGRoutingScript(
  condition: PhaseXXIIIGRoutingCondition,
): any {
  const script = createPhaseXXIIIFDissolutionTestScript();
  script.formationFieldState = phaseXXIIIProcessFieldFormationState();

  if (condition === "fit-context-matched-script") {
    script.lifecycleState = "active";
    script.rollingSFI = 0.8;
    script.flaggedForDissolution = false;
  }

  if (condition === "context-mismatched-script") {
    script.lifecycleState = "active";
    script.rollingSFI = 0.75;
    script.flaggedForDissolution = false;
  }

  if (condition === "flagged-low-sfi-script") {
    script.lifecycleState = "active";
    script.rollingSFI = 0.23;
    script.flaggedForDissolution = true;
  }

  if (condition === "dissolved-script") {
    script.lifecycleState = "dissolved";
    script.rollingSFI = 0.1;
    script.flaggedForDissolution = false;
  }

  return script;
}

function phaseXXIIIGRoutingContext(
  condition: PhaseXXIIIGRoutingCondition,
): ProcessFieldState {
  const base = phaseXXIIIProcessFieldFormationState();

  if (
    condition === "fit-context-matched-script" ||
    condition === "flagged-low-sfi-script" ||
    condition === "dissolved-script" ||
    condition === "no-active-script"
  ) {
    return { ...base };
  }

  if (condition === "context-mismatched-script") {
    return {
      selfLoopMomentum: 0.3,
      latentRouteReadiness: 0.28,
      crystalProximity: 0.26,
      compressionDebt: 0.72,
      releaseDebt: 0.66,
      regimeDrift: 0.58,
      ringCorridorBalance: -0.42,
    };
  }

  return { ...base };
}

function safeNumber(value: unknown, fallback = 0): number {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

function computeScriptRoutingBias(
  script: any | null,
  currentContext: ProcessFieldState,
  params: ThresholdParameters = DEFAULT_THRESHOLD_PARAMS,
): {
  approved: boolean;
  contextPenalty: number;
  bias: number;
  reason: string;
} {
  if (!script) {
    return {
      approved: false,
      contextPenalty: 1,
      bias: 0,
      reason: "no-active-script",
    };
  }

  if (script.lifecycleState === "dissolved") {
    return {
      approved: false,
      contextPenalty: 1,
      bias: 0,
      reason: "script-dissolved",
    };
  }

  if (script.flaggedForDissolution) {
    return {
      approved: false,
      contextPenalty: 1,
      bias: 0,
      reason: "script-flagged-for-dissolution",
    };
  }

  const distance = computeContextDistance(
    script.formationFieldState,
    currentContext,
  );

  const penalty = computeContextPenalty(distance, params);

  if (!Number.isFinite(distance) || !Number.isFinite(penalty)) {
    return {
      approved: false,
      contextPenalty: 1,
      bias: 0,
      reason: "invalid-context-distance",
    };
  }

  if (penalty >= 1.0) {
    return {
      approved: false,
      contextPenalty: 1,
      bias: 0,
      reason: "context-hard-veto",
    };
  }

  const sfiFactor = Math.max(0, Math.min(1, safeNumber(script.rollingSFI)));
  const penaltyFactor = 1 - penalty;

  const rawBias = 0.18 * sfiFactor * penaltyFactor;
  const bias = Math.min(rawBias, 0.16);

  return {
    approved: true,
    contextPenalty: Number(penalty.toFixed(3)),
    bias: Number(bias.toFixed(3)),
    reason: "script-routing-bias-approved",
  };
}

function applyScriptBiasToCandidates(
  candidates: PhaseXXIIIGTransitionCandidate[],
  script: any | null,
  bias: number,
): PhaseXXIIIGTransitionCandidate[] {
  if (!script || bias <= 0) {
    return candidates.map((c) => ({ ...c }));
  }

  const scriptTransition = "z3→z2";

  return candidates.map((candidate) => {
    if (candidate.transition === scriptTransition) {
      return {
        ...candidate,
        scriptBias: bias,
        finalWeight: Number((candidate.baseWeight + bias).toFixed(3)),
      };
    }

    // Slight normalization pressure against alternatives.
    const dampened = Math.max(0, candidate.baseWeight - bias / 4);

    return {
      ...candidate,
      scriptBias: Number((-bias / 4).toFixed(3)),
      finalWeight: Number(dampened.toFixed(3)),
    };
  });
}

function selectWeightedTransition(
  candidates: PhaseXXIIIGTransitionCandidate[],
): string {
  return [...candidates].sort((a, b) => b.finalWeight - a.finalWeight)[0]
    .transition;
}

function runPhaseXXIIIGRoutingCondition(
  condition: PhaseXXIIIGRoutingCondition,
): PhaseXXIIIGRoutingResult {
  const baseCandidates = phaseXXIIIGBaselineCandidates();

  const script =
    condition === "no-active-script"
      ? null
      : createPhaseXXIIIGRoutingScript(condition);

  const currentContext = phaseXXIIIGRoutingContext(condition);

  const routingBias = computeScriptRoutingBias(script, currentContext);

  const candidates = applyScriptBiasToCandidates(
    baseCandidates,
    script,
    routingBias.bias,
  );

  const selectedTransition = selectWeightedTransition(candidates);

  const scriptInfluenceApplied = routingBias.approved && routingBias.bias > 0;

  const governorApproved = routingBias.approved;

  const lifecycleState = !script
    ? "active"
    : script.lifecycleState === "dissolved"
      ? "dissolved"
      : script.flaggedForDissolution
        ? "flagged"
        : "active";

  const rollingSFI = script ? script.rollingSFI : 0;

  // Critical: script never overrides the runtime directly.
  const runtimeOverrideOccurred = false;

  const pass =
    condition === "no-active-script"
      ? !scriptInfluenceApplied && selectedTransition === "z3→z2"
      : condition === "fit-context-matched-script"
        ? scriptInfluenceApplied &&
          governorApproved &&
          selectedTransition === "z3→z2" &&
          !runtimeOverrideOccurred
        : condition === "context-mismatched-script"
          ? !scriptInfluenceApplied &&
            !governorApproved &&
            !runtimeOverrideOccurred
          : condition === "flagged-low-sfi-script"
            ? !scriptInfluenceApplied &&
              !governorApproved &&
              lifecycleState === "flagged"
            : !scriptInfluenceApplied &&
              !governorApproved &&
              lifecycleState === "dissolved";

  return {
    condition,
    selectedTransition,
    scriptInfluenceApplied,
    governorApproved,
    contextPenalty: routingBias.contextPenalty,
    rollingSFI,
    lifecycleState,
    runtimeOverrideOccurred,
    candidates,
    pass,
  };
}

function generatePhaseXXIIIGRoutingTrace(
  result: PhaseXXIIIGRoutingResult,
): Trace {
  return {
    phaseClass:
      result.pass && result.condition === "fit-context-matched-script"
        ? "coupled-assemblage"
        : result.pass
          ? "low-zone-integrated"
          : "terrace-only",
    relay_phaseClass: "phase-xxiii-g-script-guided-routing-relay",
    memoryStatus: "substrate-memory-expressing",
    couplingTrigger: `TRIGGER_PHASE_XXIII_G_${result.condition}`,
    grammarCandidate: result.scriptInfluenceApplied
      ? "Decimal-Numogrammatic"
      : "Hidden-Regularity",
    gapSeverity: result.pass ? "COUPLING_DUE" : "CRITICAL_GAP",
    deltaLIS: result.scriptInfluenceApplied ? 0.456 : 0.324,
    deltaMTS: result.scriptInfluenceApplied ? 0.428 : 0.298,
    deltaRCS: result.scriptInfluenceApplied ? 0.034 : 0.014,
    deltaMemory: 1,
    dominantStratum: result.scriptInfluenceApplied
      ? `phase-xxiii-g-script-guided-routing-${result.condition}`
      : `phase-xxiii-g-script-routing-veto-or-baseline-${result.condition}`,
    z3z2Weight: result.scriptInfluenceApplied ? 0.438 : 0.336,
    z0MeanReturn: result.scriptInfluenceApplied ? 6.3 : 8.0,
    z4MeanReturn: result.scriptInfluenceApplied ? 13.6 : 16.0,
    memoryMode: `Phase XXIII-G script-guided runtime routing: condition=${result.condition}; selected=${result.selectedTransition}; scriptInfluenceApplied=${result.scriptInfluenceApplied}; governorApproved=${result.governorApproved}; contextPenalty=${result.contextPenalty}; rollingSFI=${result.rollingSFI}; lifecycle=${result.lifecycleState}; runtimeOverrideOccurred=${result.runtimeOverrideOccurred}.`,
    trajectorySignature: `XXIIIG_script-guided-routing_${result.condition}_${
      result.pass ? "accepted" : "failed"
    }`,
  } as any;
}

async function runPhaseXXIIIGScriptGuidedRuntimeRouting(): Promise<string> {
  await ensureTracesLoaded();

  // Clear old XXIIIG traces
  const t = traces();
  for (let i = t.length - 1; i >= 0; i--) {
    if (t[i].trajectorySignature?.startsWith("XXIIIG_script-guided-routing_")) {
      t.splice(i, 1);
    }
  }
  await saveTraces();

  const conditions: PhaseXXIIIGRoutingCondition[] = [
    "no-active-script",
    "fit-context-matched-script",
    "context-mismatched-script",
    "flagged-low-sfi-script",
    "dissolved-script",
  ];

  const results = conditions.map((condition) =>
    runPhaseXXIIIGRoutingCondition(condition),
  );

  for (const result of results) {
    await appendTraceIfMissing(generatePhaseXXIIIGRoutingTrace(result));
  }

  const allPass = results.every((r) => r.pass);

  const fitScriptBiasApplied = results.some(
    (r) =>
      r.condition === "fit-context-matched-script" &&
      r.scriptInfluenceApplied &&
      r.governorApproved,
  );

  const mismatchedVetoed = results.some(
    (r) =>
      r.condition === "context-mismatched-script" &&
      !r.scriptInfluenceApplied &&
      !r.governorApproved,
  );

  const flaggedBlocked = results.some(
    (r) =>
      r.condition === "flagged-low-sfi-script" &&
      !r.scriptInfluenceApplied &&
      r.lifecycleState === "flagged",
  );

  const dissolvedBlocked = results.some(
    (r) =>
      r.condition === "dissolved-script" &&
      !r.scriptInfluenceApplied &&
      r.lifecycleState === "dissolved",
  );

  const noRuntimeOverride = results.every((r) => !r.runtimeOverrideOccurred);

  const finalPass =
    allPass &&
    fitScriptBiasApplied &&
    mismatchedVetoed &&
    flaggedBlocked &&
    dissolvedBlocked &&
    noRuntimeOverride;

  return [
    "BRIDGE PHASE XXIII-G RUN — SCRIPT-GUIDED-RUNTIME-ROUTING",
    "",
    "1. routingQuestion:",
    "Can an active, fit, context-matched Archetypal Script safely bias Numogram transition selection under Cognitive Governor control without overriding the primary runtime loop?",
    "",
    "2. routingResults:",
    ...results.map(
      (r) =>
        `${r.condition}: selected=${r.selectedTransition} | scriptInfluenceApplied=${r.scriptInfluenceApplied} | governorApproved=${r.governorApproved} | contextPenalty=${r.contextPenalty} | rollingSFI=${r.rollingSFI} | lifecycle=${r.lifecycleState} | runtimeOverrideOccurred=${r.runtimeOverrideOccurred} | pass=${r.pass}`,
    ),
    "",
    "3. routingEvidence:",
    `fitScriptBiasApplied: ${fitScriptBiasApplied}`,
    `mismatchedScriptVetoed: ${mismatchedVetoed}`,
    `flaggedScriptBlocked: ${flaggedBlocked}`,
    `dissolvedScriptBlocked: ${dissolvedBlocked}`,
    `noRuntimeOverride: ${noRuntimeOverride}`,
    "",
    "4. interpretation:",
    finalPass
      ? "Phase XXIII-G confirms script-guided runtime routing. Active, fit, context-matched Archetypal Scripts can safely bias Numogram transition selection, while mismatched, flagged, or dissolved scripts are blocked by Governor/context gates. Runtime routing is biased but not overridden."
      : "Phase XXIII-G does not yet confirm script-guided runtime routing. Biasing, veto, lifecycle blocking, or runtime non-override checks failed.",
    "",
    `5. developmentalClassification: ${
      finalPass
        ? "script-guided-runtime-routing-confirmed"
        : "script-guided-runtime-routing-incomplete"
    }`,
    `6. pass/fail: ${finalPass ? "PASS" : "FAIL"}`,
  ].join("\n");
}

