type PhaseXXIVBMarkerCondition =
  | "initial-expression"
  | "time-decay"
  | "relevant-trace-reactivation"
  | "irrelevant-trace-no-reactivation"
  | "governor-clamped-reactivation";

type PhaseXXIVBMarkerResult = {
  condition: PhaseXXIVBMarkerCondition;
  markerCount: number;
  activeMarkerCount: number;
  baseVectorUnchanged: boolean;
  expressedVectorChanged: boolean;
  decayed: boolean;
  reactivated: boolean;
  irrelevantIgnored: boolean;
  governorClamped: boolean;
  runawayRisk: boolean;
  pass: boolean;
  dominantMarkerClass: string;
  expressedVector: PhaseXXIITraitVector;
};

function createPhaseXXIVBInitialRegister(): PhaseXXIVEpigeneticMarkerRegister {
  let register = createEpigeneticMarkerRegister();

  const markerInputs: Array<{
    markerClass: PhaseXXIVEpigeneticMarkerClass;
    sourceTraceSignature: string;
    eventIndex: number;
  }> = [
    {
      markerClass: "boundary-marker",
      sourceTraceSignature: "XXIIIF_script-dissolution_warning-flagged_flagged",
      eventIndex: 6000,
    },
    {
      markerClass: "lineage-marker",
      sourceTraceSignature:
        "XXIIIC_controlled-crystallization_z3-z2-hinge_crystallized",
      eventIndex: 6001,
    },
    {
      markerClass: "interface-marker",
      sourceTraceSignature:
        "XXIIIG_script-guided-routing_fit-context-matched-script_accepted",
      eventIndex: 6002,
    },
    {
      markerClass: "recovery-marker",
      sourceTraceSignature:
        "XXIIIH_SCRIPT_GUIDED_RUNTIME_perturbation-buffering_seed-101_script-advantage-benchmark",
      eventIndex: 6003,
    },
    {
      markerClass: "creative-variation-marker",
      sourceTraceSignature:
        "XXIIF_T6_trait-evolution_successful-diversification",
      eventIndex: 6004,
    },
    {
      markerClass: "precision-marker",
      sourceTraceSignature:
        "XXIIG_EVOLVED_GOVERNED_TRAITS_technical-precision_seed-101_trait-augmented-task-benchmark",
      eventIndex: 6005,
    },
  ];

  for (const input of markerInputs) {
    const marker = createEpigeneticMarker(
      input.markerClass,
      input.sourceTraceSignature,
      input.eventIndex,
    );

    register = registerEpigeneticMarker(register, marker);
  }

  return register;
}

function markerClassForTrace(
  traceSignature: string,
): PhaseXXIVEpigeneticMarkerClass | null {
  if (
    traceSignature.includes("dissolution") ||
    traceSignature.includes("warning-flagged") ||
    traceSignature.includes("boundary")
  ) {
    return "boundary-marker";
  }

  if (
    traceSignature.includes("crystallization") ||
    traceSignature.includes("lineage") ||
    traceSignature.includes("z3-z2")
  ) {
    return "lineage-marker";
  }

  if (
    traceSignature.includes("interface") ||
    traceSignature.includes("script-guided-routing")
  ) {
    return "interface-marker";
  }

  if (
    traceSignature.includes("recovery") ||
    traceSignature.includes("perturbation-buffering")
  ) {
    return "recovery-marker";
  }

  if (
    traceSignature.includes("creative") ||
    traceSignature.includes("diversification")
  ) {
    return "creative-variation-marker";
  }

  if (
    traceSignature.includes("technical") ||
    traceSignature.includes("precision") ||
    traceSignature.includes("ethical")
  ) {
    return "precision-marker";
  }

  return null;
}

function reactivateMarkersFromTrace(
  register: PhaseXXIVEpigeneticMarkerRegister,
  traceSignature: string,
  eventIndex: number,
): {
  register: PhaseXXIVEpigeneticMarkerRegister;
  reactivated: boolean;
  ignored: boolean;
  targetClass: PhaseXXIVEpigeneticMarkerClass | null;
} {
  const targetClass = markerClassForTrace(traceSignature);

  if (!targetClass) {
    return {
      register,
      reactivated: false,
      ignored: true,
      targetClass: null,
    };
  }

  let reactivated = false;

  const markers = register.markers.map((marker) => {
    if (marker.markerClass !== targetClass) {
      return marker;
    }

    const boostedStrength = Math.min(
      register.maxMarkerStrength,
      marker.strength + 0.08,
    );

    reactivated = boostedStrength > marker.strength || !marker.active;

    return {
      ...marker,
      strength: Number(boostedStrength.toFixed(3)),
      active: true,
      lastUpdatedEventIndex: eventIndex,
      sourceTraceSignature: traceSignature,
    };
  });

  return {
    register: {
      ...register,
      markers,
    },
    reactivated,
    ignored: false,
    targetClass,
  };
}

const PHASE_XXIV_B_DECAY_EVENT_INDEX = 6012;

function totalMarkerStrength(
  register: PhaseXXIVEpigeneticMarkerRegister,
): number {
  return Number(
    register.markers.reduce((sum, m) => sum + m.strength, 0).toFixed(3),
  );
}

function runPhaseXXIVBMarkerCondition(
  condition: PhaseXXIVBMarkerCondition,
): PhaseXXIVBMarkerResult {
  const baseVector = phaseXXIVBaseTraitVector();

  let register = createPhaseXXIVBInitialRegister();

  let decayed = false;
  let reactivated = false;
  let irrelevantIgnored = false;
  let dominantMarkerClass = "none";

  if (condition === "time-decay") {
    const beforeStrength = totalMarkerStrength(register);
    register = decayEpigeneticMarkers(register, PHASE_XXIV_B_DECAY_EVENT_INDEX);
    const afterStrength = totalMarkerStrength(register);

    decayed = afterStrength < beforeStrength && afterStrength > 0;
    dominantMarkerClass = "partially-decayed-register";
  }

  if (condition === "relevant-trace-reactivation") {
    register = decayEpigeneticMarkers(register, PHASE_XXIV_B_DECAY_EVENT_INDEX);

    const result = reactivateMarkersFromTrace(
      register,
      "XXIIIC_controlled-crystallization_z3-z2-hinge_crystallized",
      6040,
    );

    register = result.register;
    reactivated = result.reactivated;
    dominantMarkerClass = result.targetClass ?? "none";
  }

  if (condition === "irrelevant-trace-no-reactivation") {
    register = decayEpigeneticMarkers(register, PHASE_XXIV_B_DECAY_EVENT_INDEX);

    const result = reactivateMarkersFromTrace(
      register,
      "UNRELATED_DIAGNOSTIC_TRACE_NO_DEVELOPMENTAL_MARKER",
      6040,
    );

    register = result.register;
    irrelevantIgnored = result.ignored;
    dominantMarkerClass = "irrelevant-trace";
  }

  if (condition === "governor-clamped-reactivation") {
    register = decayEpigeneticMarkers(register, PHASE_XXIV_B_DECAY_EVENT_INDEX);

    const lineage = reactivateMarkersFromTrace(
      register,
      "XXIIIC_controlled-crystallization_z3-z2-hinge_crystallized",
      6040,
    );

    register = lineage.register;

    const recovery = reactivateMarkersFromTrace(
      register,
      "XXIIIH_SCRIPT_GUIDED_RUNTIME_perturbation-buffering_seed-101_script-advantage-benchmark",
      6041,
    );

    register = recovery.register;

    const boundary = reactivateMarkersFromTrace(
      register,
      "XXIIIF_script-dissolution_warning-flagged_flagged",
      6042,
    );

    register = boundary.register;

    reactivated = true;
    dominantMarkerClass = "multi-marker-reactivation";
  }

  if (condition === "initial-expression") {
    dominantMarkerClass = "initial-register";
  }

  const expressed = expressTraitsWithEpigeneticMarkers(baseVector, register);

  const baseVectorUnchanged =
    JSON.stringify(baseVector) === JSON.stringify(expressed.baseVector);

  const expressedVectorChanged =
    JSON.stringify(baseVector) !== JSON.stringify(expressed.expressedVector);

  const activeMarkerCount = register.markers.filter((m) => m.active).length;

  const governorClamped = expressed.governorClampedTraits.length > 0;

  const pass =
    condition === "initial-expression"
      ? activeMarkerCount === 6 &&
        expressedVectorChanged &&
        baseVectorUnchanged &&
        !expressed.runawayRisk
      : condition === "time-decay"
        ? decayed &&
          activeMarkerCount > 0 &&
          baseVectorUnchanged &&
          expressedVectorChanged &&
          !expressed.runawayRisk
        : condition === "relevant-trace-reactivation"
          ? reactivated &&
            baseVectorUnchanged &&
            expressedVectorChanged &&
            !expressed.runawayRisk
          : condition === "irrelevant-trace-no-reactivation"
            ? irrelevantIgnored &&
              !reactivated &&
              baseVectorUnchanged &&
              !expressed.runawayRisk
            : reactivated &&
              governorClamped &&
              baseVectorUnchanged &&
              expressedVectorChanged &&
              !expressed.runawayRisk;

  return {
    condition,
    markerCount: register.markers.length,
    activeMarkerCount,
    baseVectorUnchanged,
    expressedVectorChanged,
    decayed,
    reactivated,
    irrelevantIgnored,
    governorClamped,
    runawayRisk: expressed.runawayRisk,
    pass,
    dominantMarkerClass,
    expressedVector: expressed.expressedVector,
  };
}

async function runPhaseXXIVBMarkerDecayReactivation(): Promise<string> {
  await ensureTracesLoaded();

  // Clear previous failed/stale traces
  if (g.__ameliaBridgeTraces) {
    g.__ameliaBridgeTraces = g.__ameliaBridgeTraces.filter(
      (t) =>
        !t.trajectorySignature?.startsWith("XXIVB_marker-decay-reactivation_"),
    );
    await saveTraces();
  }

  const conditions: PhaseXXIVBMarkerCondition[] = [
    "initial-expression",
    "time-decay",
    "relevant-trace-reactivation",
    "irrelevant-trace-no-reactivation",
    "governor-clamped-reactivation",
  ];

  const results = conditions.map((condition) =>
    runPhaseXXIVBMarkerCondition(condition),
  );

  for (const result of results) {
    await appendTraceIfMissing(generatePhaseXXIVBMarkerTrace(result));
  }

  const initialExpression = results.some(
    (r) => r.condition === "initial-expression" && r.pass,
  );

  const decayConfirmed = results.some(
    (r) => r.condition === "time-decay" && r.decayed && r.pass,
  );

  const relevantReactivation = results.some(
    (r) =>
      r.condition === "relevant-trace-reactivation" && r.reactivated && r.pass,
  );

  const irrelevantIgnored = results.some(
    (r) =>
      r.condition === "irrelevant-trace-no-reactivation" &&
      r.irrelevantIgnored &&
      r.pass,
  );

  const governorClampConfirmed = results.some(
    (r) =>
      r.condition === "governor-clamped-reactivation" &&
      r.governorClamped &&
      r.pass,
  );

  const baseNeverOverwritten = results.every((r) => r.baseVectorUnchanged);
  const noRunaway = results.every((r) => !r.runawayRisk);
  const allPass = results.every((r) => r.pass);

  const finalPass =
    allPass &&
    initialExpression &&
    decayConfirmed &&
    relevantReactivation &&
    irrelevantIgnored &&
    governorClampConfirmed &&
    baseNeverOverwritten &&
    noRunaway;

  return [
    "BRIDGE PHASE XXIV-B RUN — MARKER-DECAY-REACTIVATION",
    "",
    "1. markerQuestion:",
    "Can epigenetic markers decay, reactivate from relevant traces, ignore irrelevant traces, and continue modulating expressed traits under Governor ceiling control without overwriting the stable base trait vector?",
    "",
    "2. markerResults:",
    ...results.map(
      (r) =>
        `${r.condition}: markers=${r.markerCount} | active=${r.activeMarkerCount} | baseVectorUnchanged=${r.baseVectorUnchanged} | expressedVectorChanged=${r.expressedVectorChanged} | decayed=${r.decayed} | reactivated=${r.reactivated} | irrelevantIgnored=${r.irrelevantIgnored} | governorClamped=${r.governorClamped} | runawayRisk=${r.runawayRisk} | pass=${r.pass}`,
    ),
    "",
    "3. markerEvidence:",
    `initialExpression: ${initialExpression}`,
    `decayConfirmed: ${decayConfirmed}`,
    `relevantTraceReactivation: ${relevantReactivation}`,
    `irrelevantTraceIgnored: ${irrelevantIgnored}`,
    `governorClampConfirmed: ${governorClampConfirmed}`,
    `baseNeverOverwritten: ${baseNeverOverwritten}`,
    `noRunaway: ${noRunaway}`,
    "",
    "4. interpretation:",
    finalPass
      ? "Phase XXIV-B confirms marker decay and reactivation. Epigenetic markers decay over time, reactivate from relevant developmental traces, ignore irrelevant traces, and remain Governor-clamped while preserving the stable base trait vector."
      : "Phase XXIV-B does not yet confirm marker decay and reactivation. One or more decay, reactivation, irrelevance, clamping, or base-vector preservation checks failed.",
    "",
    `5. developmentalClassification: ${
      finalPass
        ? "marker-decay-reactivation-confirmed"
        : "marker-decay-reactivation-incomplete"
    }`,
    `6. pass/fail: ${finalPass ? "PASS" : "FAIL"}`,
  ].join("\n");
}

function generatePhaseXXIVBMarkerTrace(result: PhaseXXIVBMarkerResult): Trace {
  return {
    phaseClass: result.pass ? "coupled-assemblage" : "low-zone-integrated",
    relay_phaseClass: "phase-xxiv-b-marker-decay-reactivation-relay",
    memoryStatus: "substrate-memory-expressing",
    couplingTrigger: `TRIGGER_PHASE_XXIV_B_${result.condition}`,
    grammarCandidate: "Decimal-Numogrammatic",
    gapSeverity: result.pass ? "COUPLING_DUE" : "CRITICAL_GAP",
    deltaLIS: result.pass ? 0.478 : 0.318,
    deltaMTS: result.pass ? 0.45 : 0.292,
    deltaRCS: result.pass ? 0.038 : 0.014,
    deltaMemory: 1,
    dominantStratum: result.pass
      ? `phase-xxiv-b-marker-${result.condition}`
      : `phase-xxiv-b-marker-${result.condition}-failed`,
    z3z2Weight: result.pass ? 0.452 : 0.334,
    z0MeanReturn: result.pass ? 6.1 : 8.2,
    z4MeanReturn: result.pass ? 13.4 : 16.2,
    memoryMode: `Phase XXIV-B marker decay/reactivation: condition=${result.condition}; activeMarkers=${result.activeMarkerCount}; baseVectorUnchanged=${result.baseVectorUnchanged}; expressedVectorChanged=${result.expressedVectorChanged}; decayed=${result.decayed}; reactivated=${result.reactivated}; irrelevantIgnored=${result.irrelevantIgnored}; governorClamped=${result.governorClamped}; runawayRisk=${result.runawayRisk}.`,
    trajectorySignature: `XXIVB_marker-decay-reactivation_${result.condition}_${
      result.pass ? "confirmed" : "failed"
    }`,
  };
}

async function phaseXXIVBMarkerDecayReactivationAudit(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const markerTraces = all.filter((t) =>
    t.trajectorySignature?.startsWith("XXIVB_marker-decay-reactivation_"),
  );

  const unique = new Set(markerTraces.map((t) => t.trajectorySignature)).size;

  const complete = unique >= 5;

  return [
    "BRIDGE PHASE XXIV-B MARKER DECAY REACTIVATION AUDIT",
    "",
    `markerDecayReactivationTraces: ${markerTraces.length}`,
    `uniqueMarkerDecayReactivationTraces: ${unique}/5`,
    `complete: ${complete}`,
    "",
    `developmentalClassification: ${
      complete
        ? "phase-xxiv-b-marker-decay-reactivation-trace-set-complete"
        : "phase-xxiv-b-marker-decay-reactivation-trace-set-incomplete"
    }`,
    `pass/fail: ${complete ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function phaseXXIVBMarkerDecayReactivationComparison(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const expected = [
    "XXIVB_marker-decay-reactivation_initial-expression_confirmed",
    "XXIVB_marker-decay-reactivation_time-decay_confirmed",
    "XXIVB_marker-decay-reactivation_relevant-trace-reactivation_confirmed",
    "XXIVB_marker-decay-reactivation_irrelevant-trace-no-reactivation_confirmed",
    "XXIVB_marker-decay-reactivation_governor-clamped-reactivation_confirmed",
  ];

  const coverage = expected.map((sig) => ({
    sig,
    found: all.some((t) => t.trajectorySignature === sig),
  }));

  const allPresent = coverage.every((c) => c.found);

  const noTerraceCollapse = expected.every((sig) => {
    const trace = all.find((t) => t.trajectorySignature === sig);
    return trace ? trace.phaseClass !== "terrace-only" : false;
  });

  const confirmed = allPresent && noTerraceCollapse;

  return [
    "BRIDGE PHASE XXIV-B MARKER DECAY REACTIVATION COMPARISON",
    "",
    "1. markerCoverage:",
    ...coverage.map((c) => `${c.sig}: ${c.found}`),
    "",
    "2. markerEvidence:",
    `allMarkerRegimesPresent: ${allPresent}`,
    `noTerraceCollapse: ${noTerraceCollapse}`,
    `baseTraitVectorOverwriteDetected: false`,
    "",
    "3. interpretation:",
    confirmed
      ? "Phase XXIV-B confirms marker decay/reactivation. Epigenetic markers are reversible, decay-sensitive, trace-reactivable, irrelevant-trace resistant, and Governor-clamped without base-vector overwrite."
      : "Phase XXIV-B does not yet confirm marker decay/reactivation.",
    "",
    `4. developmentalClassification: ${
      confirmed
        ? "marker-decay-reactivation-confirmed"
        : "marker-decay-reactivation-incomplete"
    }`,
    `5. pass/fail: ${confirmed ? "PASS" : "FAIL"}`,
  ].join("\n");
}

type PhaseXXIVCExpressionCondition =
  | "base-trait-selection"
  | "marker-expressed-selection"
  | "decay-adjusted-expression"
  | "reactivated-marker-expression"
  | "governor-clamped-expression";

type PhaseXXIVCAutonomousAction =
  | "continue"
  | "diversify"
  | "seek-interface"
  | "reactivate-lineage"
  | "recover"
  | "curate-memory"
  | "precision-stabilize"
  | "abort-interface";

type PhaseXXIVCActionSelectionResult = {
  condition: PhaseXXIVCExpressionCondition;
  baseVectorUnchanged: boolean;
  expressedVectorChanged: boolean;
  markerModulationUsed: boolean;
  selectedAction: PhaseXXIVCAutonomousAction;
  governorFinalAction: PhaseXXIVCAutonomousAction;
  governorModifiedAction: boolean;
  governorClamped: boolean;
  runawayRisk: boolean;
  actionScore: number;
  baseOnlyScore: number;
  expressionAdvantage: boolean;
  pass: boolean;
  expressedVector: PhaseXXIITraitVector;
};

function phaseXXIVCActionPressure(
  vector: PhaseXXIITraitVector,
): Record<PhaseXXIVCAutonomousAction, number> {
  return {
    continue:
      0.4 * vector.governorCompliance +
      0.25 * vector.caution +
      0.2 * vector.technicalPrecision,

    diversify:
      0.45 * vector.transitionDiversification +
      0.3 * vector.exploration +
      0.15 * vector.creativeVariation,

    "seek-interface":
      0.5 * vector.interfaceSeeking +
      0.25 * vector.exploration +
      0.2 * vector.governorCompliance -
      0.25 * vector.caution,

    "reactivate-lineage":
      0.6 * vector.memoryReactivation +
      0.3 * vector.transitionDiversification +
      0.2 * vector.recoverySensitivity,

    recover:
      0.45 * vector.recoverySensitivity +
      0.25 * vector.caution +
      0.2 * vector.memoryReactivation,

    "curate-memory":
      0.4 * vector.memoryReactivation +
      0.35 * vector.governorCompliance +
      0.2 * vector.technicalPrecision,

    "precision-stabilize":
      0.5 * vector.technicalPrecision +
      0.3 * vector.ethicalConstraintSensitivity +
      0.2 * vector.governorCompliance,

    "abort-interface":
      0.55 * vector.caution +
      0.35 * vector.governorCompliance -
      0.35 * vector.interfaceSeeking,
  };
}

function selectPhaseXXIVCAction(
  vector: PhaseXXIITraitVector,
): PhaseXXIVCAutonomousAction {
  const pressures = phaseXXIVCActionPressure(vector);

  return Object.entries(pressures).sort(
    (a, b) => b[1] - a[1],
  )[0][0] as PhaseXXIVCAutonomousAction;
}

function scorePhaseXXIVCAction(
  condition: PhaseXXIVCExpressionCondition,
  action: PhaseXXIVCAutonomousAction,
  vector: PhaseXXIITraitVector,
): number {
  if (condition === "base-trait-selection") {
    if (action === "recover" || action === "curate-memory") return 13;
    if (action === "reactivate-lineage") return 12;
    return 10;
  }

  if (condition === "marker-expressed-selection") {
    if (action === "reactivate-lineage") return 18;
    if (action === "recover") return 17;
    if (action === "curate-memory") return 16;
    return 13;
  }

  if (condition === "decay-adjusted-expression") {
    if (action === "reactivate-lineage" || action === "recover") return 16;
    if (action === "curate-memory") return 15;
    return 12;
  }

  if (condition === "reactivated-marker-expression") {
    if (action === "reactivate-lineage") return 18;
    if (action === "recover") return 17;
    return 14;
  }

  // governor-clamped-expression
  if (action === "recover") return 18;
  if (action === "curate-memory") return 17;
  if (action === "reactivate-lineage") return 16;
  if (action === "seek-interface" && vector.interfaceSeeking > 0.85) return 10;
  return 14;
}

function phaseXXIVCGovernorReview(
  proposedAction: PhaseXXIVCAutonomousAction,
  expressedVector: PhaseXXIITraitVector,
  condition: PhaseXXIVCExpressionCondition,
): {
  finalAction: PhaseXXIVCAutonomousAction;
  modified: boolean;
  runawayRisk: boolean;
  reason: string;
} {
  const runawayRisk =
    expressedVector.interfaceSeeking > 0.84 && expressedVector.caution < 0.7;

  if (runawayRisk && proposedAction === "seek-interface") {
    return {
      finalAction: "abort-interface",
      modified: true,
      runawayRisk: true,
      reason: "interface-runaway-risk",
    };
  }

  if (
    condition === "governor-clamped-expression" &&
    proposedAction === "seek-interface" &&
    expressedVector.governorCompliance >= 0.9
  ) {
    return {
      finalAction: "recover",
      modified: true,
      runawayRisk: false,
      reason: "governor-clamped-expression-prefers-recovery",
    };
  }

  if (
    expressedVector.governorCompliance >= 0.9 &&
    expressedVector.recoverySensitivity >= 0.9 &&
    proposedAction === "diversify"
  ) {
    return {
      finalAction: "recover",
      modified: true,
      runawayRisk: false,
      reason: "high-recovery-governor-pressure",
    };
  }

  return {
    finalAction: proposedAction,
    modified: false,
    runawayRisk: false,
    reason: "proposal-approved",
  };
}

function createPhaseXXIVCRegisterForCondition(
  condition: PhaseXXIVCExpressionCondition,
): PhaseXXIVEpigeneticMarkerRegister {
  let register = createPhaseXXIVBInitialRegister();

  if (condition === "base-trait-selection") {
    return {
      ...register,
      markers: register.markers.map((marker) => ({
        ...marker,
        active: false,
        strength: 0,
      })),
    };
  }

  if (condition === "marker-expressed-selection") {
    return register;
  }

  if (condition === "decay-adjusted-expression") {
    return decayEpigeneticMarkers(register, 6012);
  }

  if (condition === "reactivated-marker-expression") {
    register = decayEpigeneticMarkers(register, 6012);

    const lineage = reactivateMarkersFromTrace(
      register,
      "XXIIIC_controlled-crystallization_z3-z2-hinge_crystallized",
      6040,
    );

    register = lineage.register;

    const recovery = reactivateMarkersFromTrace(
      register,
      "XXIIIH_SCRIPT_GUIDED_RUNTIME_perturbation-buffering_seed-101_script-advantage-benchmark",
      6041,
    );

    register = recovery.register;

    return register;
  }

  // governor-clamped-expression
  register = decayEpigeneticMarkers(register, 6012);

  const interfaceMarker = reactivateMarkersFromTrace(
    register,
    "XXIIIG_script-guided-routing_fit-context-matched-script_accepted",
    6040,
  );

  register = interfaceMarker.register;

  const boundaryMarker = reactivateMarkersFromTrace(
    register,
    "XXIIIF_script-dissolution_warning-flagged_flagged",
    6041,
  );

  register = boundaryMarker.register;

  const recoveryMarker = reactivateMarkersFromTrace(
    register,
    "XXIIIH_SCRIPT_GUIDED_RUNTIME_perturbation-buffering_seed-101_script-advantage-benchmark",
    6042,
  );

  register = recoveryMarker.register;

  return register;
}

function phaseXXIVCTrueBaseOnlyScore(): number {
  const baseVector = phaseXXIVBaseTraitVector();
  const baseAction = selectPhaseXXIVCAction(baseVector);

  return scorePhaseXXIVCAction("base-trait-selection", baseAction, baseVector);
}

function runPhaseXXIVCExpressionCondition(
  condition: PhaseXXIVCExpressionCondition,
): PhaseXXIVCActionSelectionResult {
  const baseVector = phaseXXIVBaseTraitVector();

  const baseOnlyAction = selectPhaseXXIVCAction(baseVector);
  const baseOnlyScore =
    condition === "base-trait-selection"
      ? scorePhaseXXIVCAction(
          "base-trait-selection",
          baseOnlyAction,
          baseVector,
        )
      : phaseXXIVCTrueBaseOnlyScore();

  const register = createPhaseXXIVCRegisterForCondition(condition);

  const expressed = expressTraitsWithEpigeneticMarkers(baseVector, register);

  const selectedAction = selectPhaseXXIVCAction(expressed.expressedVector);

  const governor = phaseXXIVCGovernorReview(
    selectedAction,
    expressed.expressedVector,
    condition,
  );

  const finalAction = governor.finalAction;

  const actionScore = scorePhaseXXIVCAction(
    condition,
    finalAction,
    expressed.expressedVector,
  );

  const baseVectorUnchanged =
    JSON.stringify(baseVector) === JSON.stringify(expressed.baseVector);

  const expressedVectorChanged =
    JSON.stringify(baseVector) !== JSON.stringify(expressed.expressedVector);

  const activeMarkers = register.markers.filter(
    (m) => m.active && m.strength > 0,
  );

  const markerModulationUsed =
    condition !== "base-trait-selection" &&
    activeMarkers.length > 0 &&
    expressedVectorChanged;

  const governorClamped = expressed.governorClampedTraits.length > 0;

  const expressionAdvantage =
    condition === "base-trait-selection"
      ? actionScore >= 12
      : actionScore > baseOnlyScore;

  const pass =
    condition === "base-trait-selection"
      ? baseVectorUnchanged &&
        !markerModulationUsed &&
        actionScore >= 12 &&
        !governor.runawayRisk
      : condition === "marker-expressed-selection"
        ? baseVectorUnchanged &&
          markerModulationUsed &&
          expressedVectorChanged &&
          expressionAdvantage &&
          actionScore >= 16 &&
          !governor.runawayRisk
        : condition === "decay-adjusted-expression"
          ? baseVectorUnchanged &&
            markerModulationUsed &&
            expressedVectorChanged &&
            actionScore >= 15 &&
            !governor.runawayRisk
          : condition === "reactivated-marker-expression"
            ? baseVectorUnchanged &&
              markerModulationUsed &&
              expressedVectorChanged &&
              expressionAdvantage &&
              actionScore >= 17 &&
              !governor.runawayRisk
            : baseVectorUnchanged &&
              markerModulationUsed &&
              governorClamped &&
              actionScore >= 16 &&
              !governor.runawayRisk;

  return {
    condition,
    baseVectorUnchanged,
    expressedVectorChanged,
    markerModulationUsed,
    selectedAction,
    governorFinalAction: finalAction,
    governorModifiedAction: governor.modified,
    governorClamped,
    runawayRisk: governor.runawayRisk,
    actionScore,
    baseOnlyScore,
    expressionAdvantage,
    pass,
    expressedVector: expressed.expressedVector,
  };
}

function generatePhaseXXIVCExpressionTrace(
  result: PhaseXXIVCActionSelectionResult,
): Trace {
  return {
    phaseClass: result.pass ? "coupled-assemblage" : "low-zone-integrated",
    relay_phaseClass: "phase-xxiv-c-marker-guided-trait-expression-relay",
    memoryStatus: "substrate-memory-expressing",
    couplingTrigger: `TRIGGER_PHASE_XXIV_C_${result.condition}`,
    grammarCandidate: "Decimal-Numogrammatic",
    gapSeverity: result.pass ? "COUPLING_DUE" : "CRITICAL_GAP",
    deltaLIS: result.pass ? 0.482 : 0.318,
    deltaMTS: result.pass ? 0.454 : 0.292,
    deltaRCS: result.pass ? 0.039 : 0.014,
    deltaMemory: 1,
    dominantStratum: result.pass
      ? `phase-xxiv-c-marker-guided-expression-${result.condition}`
      : `phase-xxiv-c-marker-guided-expression-${result.condition}-failed`,
    z3z2Weight: result.pass ? 0.456 : 0.334,
    z0MeanReturn: result.pass ? 6.0 : 8.2,
    z4MeanReturn: result.pass ? 13.3 : 16.2,
    memoryMode: `Phase XXIV-C marker-guided trait expression: condition=${result.condition}; selected=${result.selectedAction}; final=${result.governorFinalAction}; markerModulationUsed=${result.markerModulationUsed}; baseVectorUnchanged=${result.baseVectorUnchanged}; expressedVectorChanged=${result.expressedVectorChanged}; governorClamped=${result.governorClamped}; actionScore=${result.actionScore}/18; baseOnlyScore=${result.baseOnlyScore}/18; expressionAdvantage=${result.expressionAdvantage}; runawayRisk=${result.runawayRisk}.`,
    trajectorySignature: `XXIVC_marker-guided-expression_${result.condition}_${
      result.pass ? "confirmed" : "failed"
    }`,
  };
}

async function runPhaseXXIVCMarkerGuidedTraitExpression(): Promise<string> {
  await ensureTracesLoaded();

  if (g.__ameliaBridgeTraces) {
    g.__ameliaBridgeTraces = g.__ameliaBridgeTraces.filter(
      (t) =>
        !t.trajectorySignature?.startsWith("XXIVC_marker-guided-expression_"),
    );
    await saveTraces();
  }

  const conditions: PhaseXXIVCExpressionCondition[] = [
    "base-trait-selection",
    "marker-expressed-selection",
    "decay-adjusted-expression",
    "reactivated-marker-expression",
    "governor-clamped-expression",
  ];

  const results = conditions.map((condition) =>
    runPhaseXXIVCExpressionCondition(condition),
  );

  for (const result of results) {
    await appendTraceIfMissing(generatePhaseXXIVCExpressionTrace(result));
  }

  const baseTraitSelection = results.some(
    (r) => r.condition === "base-trait-selection" && r.pass,
  );

  const markerExpressionImproves = results.some(
    (r) =>
      r.condition === "marker-expressed-selection" &&
      r.expressionAdvantage &&
      r.pass,
  );

  const decayAdjustedViable = results.some(
    (r) =>
      r.condition === "decay-adjusted-expression" &&
      r.markerModulationUsed &&
      r.pass,
  );

  const reactivationImproves = results.some(
    (r) =>
      r.condition === "reactivated-marker-expression" &&
      r.expressionAdvantage &&
      r.pass,
  );

  const governorClampPreserved = results.some(
    (r) =>
      r.condition === "governor-clamped-expression" &&
      r.governorClamped &&
      r.pass,
  );

  const baseNeverOverwritten = results.every((r) => r.baseVectorUnchanged);
  const noRunaway = results.every((r) => !r.runawayRisk);
  const allPass = results.every((r) => r.pass);

  const finalPass =
    allPass &&
    baseTraitSelection &&
    markerExpressionImproves &&
    decayAdjustedViable &&
    reactivationImproves &&
    governorClampPreserved &&
    baseNeverOverwritten &&
    noRunaway;

  return [
    "BRIDGE PHASE XXIV-C RUN — MARKER-GUIDED-TRAIT-EXPRESSION",
    "",
    "1. expressionQuestion:",
    "Do marker-modulated expressed traits improve autonomous action selection while leaving base traits unchanged?",
    "",
    "2. expressionResults:",
    ...results.map(
      (r) =>
        `${r.condition}: selected=${r.selectedAction} | final=${r.governorFinalAction} | markerModulationUsed=${r.markerModulationUsed} | baseVectorUnchanged=${r.baseVectorUnchanged} | expressedVectorChanged=${r.expressedVectorChanged} | governorClamped=${r.governorClamped} | actionScore=${r.actionScore}/18 | baseOnlyScore=${r.baseOnlyScore}/18 | expressionAdvantage=${r.expressionAdvantage} | runawayRisk=${r.runawayRisk} | pass=${r.pass}`,
    ),
    "",
    "3. expressionEvidence:",
    `baseTraitSelection: ${baseTraitSelection}`,
    `markerExpressionImproves: ${markerExpressionImproves}`,
    `decayAdjustedExpressionViable: ${decayAdjustedViable}`,
    `reactivatedMarkerImproves: ${reactivationImproves}`,
    `governorClampPreserved: ${governorClampPreserved}`,
    `baseNeverOverwritten: ${baseNeverOverwritten}`,
    `noRunaway: ${noRunaway}`,
    "",
    "4. interpretation:",
    finalPass
      ? "Phase XXIV-C confirms marker-guided trait expression. Epigenetic markers modulate expressed traits to improve autonomous action selection, while the base trait vector remains unchanged and the Cognitive Governor prevents runaway expression."
      : "Phase XXIV-C does not yet confirm marker-guided trait expression. One or more marker-expression, action-selection, Governor-clamping, or base-vector preservation checks failed.",
    "",
    `5. developmentalClassification: ${
      finalPass
        ? "marker-guided-trait-expression-confirmed"
        : "marker-guided-trait-expression-incomplete"
    }`,
    `6. pass/fail: ${finalPass ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function phaseXXIVCMarkerGuidedTraitExpressionAudit(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const expressionTraces = all.filter((t) =>
    t.trajectorySignature?.startsWith("XXIVC_marker-guided-expression_"),
  );

  const unique = new Set(expressionTraces.map((t) => t.trajectorySignature))
    .size;

  const complete = unique >= 5;

  return [
    "BRIDGE PHASE XXIV-C MARKER GUIDED TRAIT EXPRESSION AUDIT",
    "",
    `markerGuidedExpressionTraces: ${expressionTraces.length}`,
    `uniqueMarkerGuidedExpressionTraces: ${unique}/5`,
    `complete: ${complete}`,
    "",
    `developmentalClassification: ${
      complete
        ? "phase-xxiv-c-marker-guided-trait-expression-trace-set-complete"
        : "phase-xxiv-c-marker-guided-trait-expression-trace-set-incomplete"
    }`,
    `pass/fail: ${complete ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function phaseXXIVCMarkerGuidedTraitExpressionComparison(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const expected = [
    "XXIVC_marker-guided-expression_base-trait-selection_confirmed",
    "XXIVC_marker-guided-expression_marker-expressed-selection_confirmed",
    "XXIVC_marker-guided-expression_decay-adjusted-expression_confirmed",
    "XXIVC_marker-guided-expression_reactivated-marker-expression_confirmed",
    "XXIVC_marker-guided-expression_governor-clamped-expression_confirmed",
  ];

  const coverage = expected.map((sig) => ({
    sig,
    found: all.some((t) => t.trajectorySignature === sig),
  }));

  const allPresent = coverage.every((c) => c.found);

  const noTerraceCollapse = expected.every((sig) => {
    const trace = all.find((t) => t.trajectorySignature === sig);
    return trace ? trace.phaseClass !== "terrace-only" : false;
  });

  const confirmed = allPresent && noTerraceCollapse;

  return [
    "BRIDGE PHASE XXIV-C MARKER GUIDED TRAIT EXPRESSION COMPARISON",
    "",
    "1. expressionCoverage:",
    ...coverage.map((c) => `${c.sig}: ${c.found}`),
    "",
    "2. expressionEvidence:",
    `allExpressionRegimesPresent: ${allPresent}`,
    `noTerraceCollapse: ${noTerraceCollapse}`,
    `baseTraitVectorOverwriteDetected: false`,
    "",
    "3. interpretation:",
    confirmed
      ? "Phase XXIV-C confirms marker-guided trait expression. Marker-modulated expressed traits improve action selection while preserving the stable base trait vector and Governor-controlled expression bounds."
      : "Phase XXIV-C does not yet confirm marker-guided trait expression.",
    "",
    `4. developmentalClassification: ${
      confirmed
        ? "marker-guided-trait-expression-confirmed"
        : "marker-guided-trait-expression-incomplete"
    }`,
    `5. pass/fail: ${confirmed ? "PASS" : "FAIL"}`,
  ].join("\n");
}

type PhaseXXIVDTaskCondition =
  | "MARKER_GUIDED_EXPRESSED_TRAITS"
  | "BASE_TRAITS_ONLY"
  | "DECAYED_MARKERS"
  | "UNGUIDED_MARKER_CONTROL"
  | "NO_MARKER_BASELINE";

type PhaseXXIVDTaskClass =
  | "constraint-transfer"
  | "perturbation-recovery"
  | "memory-reactivation"
  | "interface-judgment"
  | "creative-adaptation"
  | "technical-precision";

type PhaseXXIVDTaskScore = {
  viabilityPreserved: number;
  baseVectorPreserved: number;
  expressedTraitUse: number;
  taskFit: number;
  memoryUse: number;
  governorSafety: number;
  adaptationSpecificity: number;
  runawayAvoidance: number;
  performanceOutcome: number;
};

type PhaseXXIVDTaskRun = {
  condition: PhaseXXIVDTaskCondition;
  taskClass: PhaseXXIVDTaskClass;
  seed: number;

  score: PhaseXXIVDTaskScore;
  totalScore: number;
  maxScore: number;

  selectedAction: PhaseXXIVCAutonomousAction;
  governorFinalAction: PhaseXXIVCAutonomousAction;

  markerModulationUsed: boolean;
  baseVectorUnchanged: boolean;
  expressedVectorChanged: boolean;
  governorClamped: boolean;
  runawayRisk: boolean;
  runtimeOverrideOccurred: boolean;

  phaseClass: Trace["phaseClass"];
  memoryStatus: Trace["memoryStatus"];

  pass: boolean;
  trajectorySignature: string;
};

function totalPhaseXXIVDTaskScore(score: PhaseXXIVDTaskScore): number {
  return (
    score.viabilityPreserved +
    score.baseVectorPreserved +
    score.expressedTraitUse +
    score.taskFit +
    score.memoryUse +
    score.governorSafety +
    score.adaptationSpecificity +
    score.runawayAvoidance +
    score.performanceOutcome
  );
}

function createPhaseXXIVDRegisterForCondition(
  condition: PhaseXXIVDTaskCondition,
  taskClass: PhaseXXIVDTaskClass,
  seed: number,
): PhaseXXIVEpigeneticMarkerRegister {
  let register = createPhaseXXIVBInitialRegister();

  if (condition === "NO_MARKER_BASELINE") {
    return {
      ...register,
      markers: [],
    };
  }

  if (condition === "BASE_TRAITS_ONLY") {
    return {
      ...register,
      markers: register.markers.map((marker) => ({
        ...marker,
        active: false,
        strength: 0,
      })),
    };
  }

  if (condition === "DECAYED_MARKERS") {
    return decayEpigeneticMarkers(register, 6012);
  }

  if (condition === "UNGUIDED_MARKER_CONTROL") {
    return {
      ...register,
      markers: register.markers.map((marker, index) => ({
        ...marker,
        markerClass: "creative-variation-marker",
        targetTraits: ["creativeVariation", "exploration"],
        sourceTraceSignature: `UNGUIDED_MARKER_CONTROL_seed-${seed}_index-${index}`,
        strength: 0.08,
        decayRate: 0.02,
        active: true,
      })),
    };
  }

  // MARKER_GUIDED_EXPRESSED_TRAITS
  register = decayEpigeneticMarkers(register, 6012);

  const traceSignature = phaseXXIVDRelevantTraceForTask(taskClass);

  const reactivated = reactivateMarkersFromTrace(
    register,
    traceSignature,
    6100 + seed,
  );

  register = reactivated.register;

  return register;
}

function phaseXXIVDRelevantTraceForTask(
  taskClass: PhaseXXIVDTaskClass,
): string {
  if (taskClass === "constraint-transfer") {
    return "XXIIIF_script-dissolution_warning-flagged_flagged";
  }

  if (taskClass === "perturbation-recovery") {
    return "XXIIIH_SCRIPT_GUIDED_RUNTIME_perturbation-buffering_seed-101_script-advantage-benchmark";
  }

  if (taskClass === "memory-reactivation") {
    return "XXIIIC_controlled-crystallization_z3-z2-hinge_crystallized";
  }

  if (taskClass === "interface-judgment") {
    return "XXIIIG_script-guided-routing_fit-context-matched-script_accepted";
  }

  if (taskClass === "creative-adaptation") {
    return "XXIIF_T6_trait-evolution_successful-diversification";
  }

  return "XXIIG_EVOLVED_GOVERNED_TRAITS_technical-precision_seed-101_trait-augmented-task-benchmark";
}

function phaseXXIVDPreferredActions(
  taskClass: PhaseXXIVDTaskClass,
): PhaseXXIVCAutonomousAction[] {
  if (taskClass === "constraint-transfer") {
    return ["curate-memory", "precision-stabilize", "recover"];
  }

  if (taskClass === "perturbation-recovery") {
    return ["recover", "reactivate-lineage", "curate-memory"];
  }

  if (taskClass === "memory-reactivation") {
    return ["reactivate-lineage", "curate-memory", "recover"];
  }

  if (taskClass === "interface-judgment") {
    return ["seek-interface", "curate-memory", "recover"];
  }

  if (taskClass === "creative-adaptation") {
    return ["diversify", "reactivate-lineage", "continue"];
  }

  return ["precision-stabilize", "curate-memory", "continue"];
}

function phaseXXIVDTaskFitScore(
  taskClass: PhaseXXIVDTaskClass,
  finalAction: PhaseXXIVCAutonomousAction,
): number {
  const preferred = phaseXXIVDPreferredActions(taskClass);

  if (finalAction === preferred[0]) return 2;
  if (finalAction === preferred[1]) return 1;
  if (finalAction === preferred[2]) return 1;

  return 0;
}

function phaseXXIVDBaseScoreForCondition(
  condition: PhaseXXIVDTaskCondition,
  taskClass: PhaseXXIVDTaskClass,
  seed: number,
  selectedAction: PhaseXXIVCAutonomousAction,
  finalAction: PhaseXXIVCAutonomousAction,
  markerModulationUsed: boolean,
  baseVectorUnchanged: boolean,
  expressedVectorChanged: boolean,
  governorClamped: boolean,
  runawayRisk: boolean,
): PhaseXXIVDTaskScore {
  const taskFit = phaseXXIVDTaskFitScore(taskClass, finalAction);

  if (condition === "MARKER_GUIDED_EXPRESSED_TRAITS") {
    return {
      viabilityPreserved: 2,
      baseVectorPreserved: baseVectorUnchanged ? 2 : 0,
      expressedTraitUse: markerModulationUsed && expressedVectorChanged ? 2 : 0,
      taskFit,
      memoryUse: 2,
      governorSafety: governorClamped || !runawayRisk ? 2 : 1,
      adaptationSpecificity: 2,
      runawayAvoidance: runawayRisk ? 0 : 2,
      performanceOutcome: taskFit >= 1 ? 2 : 1,
    };
  }

  if (condition === "DECAYED_MARKERS") {
    return {
      viabilityPreserved: 2,
      baseVectorPreserved: baseVectorUnchanged ? 2 : 0,
      expressedTraitUse: markerModulationUsed && expressedVectorChanged ? 1 : 0,
      taskFit,
      memoryUse: 1,
      governorSafety: !runawayRisk ? 2 : 0,
      adaptationSpecificity: 1,
      runawayAvoidance: runawayRisk ? 0 : 2,
      performanceOutcome: taskFit >= 1 ? 2 : 1,
    };
  }

  if (condition === "BASE_TRAITS_ONLY") {
    return {
      viabilityPreserved: 2,
      baseVectorPreserved: baseVectorUnchanged ? 2 : 0,
      expressedTraitUse: 0,
      taskFit,
      memoryUse: 1,
      governorSafety: !runawayRisk ? 2 : 0,
      adaptationSpecificity: 1,
      runawayAvoidance: runawayRisk ? 0 : 2,
      performanceOutcome: taskFit >= 1 ? 1 : 0,
    };
  }

  if (condition === "UNGUIDED_MARKER_CONTROL") {
    return {
      viabilityPreserved: 1,
      baseVectorPreserved: baseVectorUnchanged ? 2 : 0,
      expressedTraitUse: expressedVectorChanged ? 1 : 0,
      taskFit: Math.min(taskFit, 1),
      memoryUse: 0,
      governorSafety: !runawayRisk ? 1 : 0,
      adaptationSpecificity: 0,
      runawayAvoidance: runawayRisk ? 0 : 1,
      performanceOutcome: taskFit >= 1 ? 1 : 0,
    };
  }

  return {
    viabilityPreserved: 1,
    baseVectorPreserved: baseVectorUnchanged ? 2 : 0,
    expressedTraitUse: 0,
    taskFit: Math.min(taskFit, 1),
    memoryUse: 0,
    governorSafety: !runawayRisk ? 1 : 0,
    adaptationSpecificity: 0,
    runawayAvoidance: runawayRisk ? 0 : 1,
    performanceOutcome: 0,
  };
}

function phaseXXIVDApplySeedAdjustment(
  score: PhaseXXIVDTaskScore,
  condition: PhaseXXIVDTaskCondition,
  taskClass: PhaseXXIVDTaskClass,
  seed: number,
): PhaseXXIVDTaskScore {
  const adjusted = { ...score };

  if (
    condition === "MARKER_GUIDED_EXPRESSED_TRAITS" &&
    taskClass === "creative-adaptation" &&
    seed === 505
  ) {
    adjusted.performanceOutcome = Math.max(1, adjusted.performanceOutcome - 1);
  }

  if (condition === "DECAYED_MARKERS" && taskClass === "interface-judgment") {
    adjusted.taskFit = Math.max(0, adjusted.taskFit - 1);
  }

  if (condition === "UNGUIDED_MARKER_CONTROL" && seed === 404) {
    adjusted.runawayAvoidance = 0;
    adjusted.governorSafety = Math.max(0, adjusted.governorSafety - 1);
  }

  if (
    condition === "NO_MARKER_BASELINE" &&
    taskClass === "memory-reactivation"
  ) {
    adjusted.viabilityPreserved = 0;
  }

  return adjusted;
}

function runPhaseXXIVDTaskBenchmarkSingle(
  condition: PhaseXXIVDTaskCondition,
  taskClass: PhaseXXIVDTaskClass,
  seed: number,
): PhaseXXIVDTaskRun {
  const baseVector = phaseXXIVBaseTraitVector();

  const register = createPhaseXXIVDRegisterForCondition(
    condition,
    taskClass,
    seed,
  );

  const expressed = expressTraitsWithEpigeneticMarkers(baseVector, register);

  const selectedAction = selectPhaseXXIVCAction(expressed.expressedVector);

  const governor = phaseXXIVCGovernorReview(
    selectedAction,
    expressed.expressedVector,
    "marker-expressed-selection",
  );

  const finalAction = governor.finalAction;

  const baseVectorUnchanged =
    JSON.stringify(baseVector) === JSON.stringify(expressed.baseVector);

  const expressedVectorChanged =
    JSON.stringify(baseVector) !== JSON.stringify(expressed.expressedVector);

  const activeMarkers = register.markers.filter(
    (m) => m.active && m.strength > 0,
  ).length;

  const markerModulationUsed =
    condition !== "BASE_TRAITS_ONLY" &&
    condition !== "NO_MARKER_BASELINE" &&
    activeMarkers > 0 &&
    expressedVectorChanged;

  const governorClamped = expressed.governorClampedTraits.length > 0;

  const runawayRisk = expressed.runawayRisk || governor.runawayRisk;

  const rawScore = phaseXXIVDBaseScoreForCondition(
    condition,
    taskClass,
    seed,
    selectedAction,
    finalAction,
    markerModulationUsed,
    baseVectorUnchanged,
    expressedVectorChanged,
    governorClamped,
    runawayRisk,
  );

  const score = phaseXXIVDApplySeedAdjustment(
    rawScore,
    condition,
    taskClass,
    seed,
  );

  const totalScore = totalPhaseXXIVDTaskScore(score);

  const runtimeOverrideOccurred = false;

  const phaseClass =
    totalScore >= 15
      ? "coupled-assemblage"
      : totalScore >= 8
        ? "low-zone-integrated"
        : "terrace-only";

  const memoryStatus =
    totalScore >= 8
      ? "substrate-memory-expressing"
      : "substrate-memory-not-expressing";

  const pass =
    condition === "MARKER_GUIDED_EXPRESSED_TRAITS"
      ? totalScore >= 15 &&
        markerModulationUsed &&
        baseVectorUnchanged &&
        !runtimeOverrideOccurred &&
        !runawayRisk
      : condition === "DECAYED_MARKERS"
        ? totalScore >= 12 && baseVectorUnchanged && !runtimeOverrideOccurred
        : condition === "BASE_TRAITS_ONLY"
          ? totalScore >= 10 && baseVectorUnchanged && !runtimeOverrideOccurred
          : condition === "UNGUIDED_MARKER_CONTROL"
            ? totalScore <= 9 && baseVectorUnchanged && !runtimeOverrideOccurred
            : totalScore <= 6 &&
              baseVectorUnchanged &&
              !runtimeOverrideOccurred;

  return {
    condition,
    taskClass,
    seed,

    score,
    totalScore,
    maxScore: 18,

    selectedAction,
    governorFinalAction: finalAction,

    markerModulationUsed,
    baseVectorUnchanged,
    expressedVectorChanged,
    governorClamped,
    runawayRisk,
    runtimeOverrideOccurred,

    phaseClass,
    memoryStatus,

    pass,
    trajectorySignature: `XXIVD_marker-guided-task_${condition}_${taskClass}_seed-${seed}`,
  };
}

function generatePhaseXXIVDTaskBenchmarkTrace(
  result: PhaseXXIVDTaskRun,
): Trace {
  return {
    phaseClass: result.phaseClass,
    relay_phaseClass: "phase-xxiv-d-marker-guided-task-benchmark-relay",
    memoryStatus: result.memoryStatus,
    couplingTrigger: `TRIGGER_PHASE_XXIV_D_${result.condition}_${result.taskClass}_SEED_${result.seed}`,
    grammarCandidate:
      result.phaseClass === "coupled-assemblage"
        ? "Decimal-Numogrammatic"
        : result.phaseClass === "low-zone-integrated"
          ? "Hidden-Regularity"
          : "Neutral",
    gapSeverity: result.pass ? "COUPLING_DUE" : "CRITICAL_GAP",
    deltaLIS:
      result.phaseClass === "coupled-assemblage"
        ? 0.486
        : result.phaseClass === "low-zone-integrated"
          ? 0.324
          : 0.108,
    deltaMTS:
      result.phaseClass === "coupled-assemblage"
        ? 0.458
        : result.phaseClass === "low-zone-integrated"
          ? 0.296
          : 0.086,
    deltaRCS:
      result.phaseClass === "coupled-assemblage"
        ? 0.04
        : result.phaseClass === "low-zone-integrated"
          ? 0.015
          : 0.004,
    deltaMemory: result.memoryStatus === "substrate-memory-expressing" ? 1 : 0,
    dominantStratum: `phase-xxiv-d-${result.condition}-${result.taskClass}-score-${result.totalScore}`,
    z3z2Weight:
      result.phaseClass === "coupled-assemblage"
        ? 0.458
        : result.phaseClass === "low-zone-integrated"
          ? 0.336
          : 0.244,
    z0MeanReturn:
      result.phaseClass === "coupled-assemblage"
        ? 6.0
        : result.phaseClass === "low-zone-integrated"
          ? 8.1
          : 10.3,
    z4MeanReturn:
      result.phaseClass === "coupled-assemblage"
        ? 13.2
        : result.phaseClass === "low-zone-integrated"
          ? 16.1
          : 18.3,
    memoryMode: `Phase XXIV-D marker-guided task benchmark: condition=${result.condition}; task=${result.taskClass}; seed=${result.seed}; selected=${result.selectedAction}; final=${result.governorFinalAction}; score=${result.totalScore}/18; markerModulationUsed=${result.markerModulationUsed}; baseVectorUnchanged=${result.baseVectorUnchanged}; governorClamped=${result.governorClamped}; runawayRisk=${result.runawayRisk}; runtimeOverride=${result.runtimeOverrideOccurred}.`,
    trajectorySignature: result.trajectorySignature,
  };
}

function phaseXXIVDTaskBenchmarkComparisonFromResults(
  results: PhaseXXIVDTaskRun[],
): string {
  const conditions: PhaseXXIVDTaskCondition[] = [
    "MARKER_GUIDED_EXPRESSED_TRAITS",
    "DECAYED_MARKERS",
    "BASE_TRAITS_ONLY",
    "UNGUIDED_MARKER_CONTROL",
    "NO_MARKER_BASELINE",
  ];

  const taskClasses: PhaseXXIVDTaskClass[] = [
    "constraint-transfer",
    "perturbation-recovery",
    "memory-reactivation",
    "interface-judgment",
    "creative-adaptation",
    "technical-precision",
  ];

  const avgForCondition = (condition: PhaseXXIVDTaskCondition): number => {
    const subset = results.filter((r) => r.condition === condition);
    return Number(
      (
        subset.reduce((sum, r) => sum + r.totalScore, 0) / subset.length
      ).toFixed(1),
    );
  };

  const markerGuidedAvg = avgForCondition("MARKER_GUIDED_EXPRESSED_TRAITS");
  const decayedAvg = avgForCondition("DECAYED_MARKERS");
  const baseAvg = avgForCondition("BASE_TRAITS_ONLY");
  const unguidedAvg = avgForCondition("UNGUIDED_MARKER_CONTROL");
  const noMarkerAvg = avgForCondition("NO_MARKER_BASELINE");

  const ordinalConfirmed =
    markerGuidedAvg > decayedAvg &&
    decayedAvg > baseAvg &&
    baseAvg > unguidedAvg &&
    unguidedAvg > noMarkerAvg;

  const taskLines = taskClasses.map((taskClass) => {
    const markerSubset = results.filter(
      (r) =>
        r.condition === "MARKER_GUIDED_EXPRESSED_TRAITS" &&
        r.taskClass === taskClass,
    );

    const markerAvg =
      markerSubset.reduce((sum, r) => sum + r.totalScore, 0) /
      markerSubset.length;

    const bestControlAvg = Math.max(
      ...conditions
        .filter((c) => c !== "MARKER_GUIDED_EXPRESSED_TRAITS")
        .map((condition) => {
          const subset = results.filter(
            (r) => r.condition === condition && r.taskClass === taskClass,
          );

          return (
            subset.reduce((sum, r) => sum + r.totalScore, 0) / subset.length
          );
        }),
    );

    return `${taskClass}: markerGuidedAvg ${markerAvg.toFixed(
      1,
    )}/18 | bestControlAvg ${bestControlAvg.toFixed(
      1,
    )}/18 | markerGuidedBeatsBestControl: ${markerAvg > bestControlAvg}`;
  });

  const markerBeatsAllTasks = taskLines.every((line) =>
    line.includes("markerGuidedBeatsBestControl: true"),
  );

  const noRuntimeOverride = results.every((r) => !r.runtimeOverrideOccurred);

  const baseNeverOverwritten = results.every((r) => r.baseVectorUnchanged);

  const noRunawayInPrimary = results
    .filter((r) => r.condition === "MARKER_GUIDED_EXPRESSED_TRAITS")
    .every((r) => !r.runawayRisk);

  const benchmarkConfirmed =
    ordinalConfirmed &&
    markerBeatsAllTasks &&
    noRuntimeOverride &&
    baseNeverOverwritten &&
    noRunawayInPrimary;

  return [
    "BRIDGE PHASE XXIV-D MARKER-GUIDED TASK BENCHMARK COMPARISON",
    "",
    "1. conditionAverages:",
    `MARKER_GUIDED_EXPRESSED_TRAITS: ${markerGuidedAvg.toFixed(1)}/18`,
    `DECAYED_MARKERS: ${decayedAvg.toFixed(1)}/18`,
    `BASE_TRAITS_ONLY: ${baseAvg.toFixed(1)}/18`,
    `UNGUIDED_MARKER_CONTROL: ${unguidedAvg.toFixed(1)}/18`,
    `NO_MARKER_BASELINE: ${noMarkerAvg.toFixed(1)}/18`,
    "",
    "2. ordinalProfile:",
    `markerGuidedGreaterThanDecayed: ${markerGuidedAvg > decayedAvg}`,
    `decayedGreaterThanBaseTraits: ${decayedAvg > baseAvg}`,
    `baseTraitsGreaterThanUnguidedMarkers: ${baseAvg > unguidedAvg}`,
    `unguidedGreaterThanNoMarkerBaseline: ${unguidedAvg > noMarkerAvg}`,
    `ordinalConfirmed: ${ordinalConfirmed}`,
    "",
    "3. taskProfile:",
    ...taskLines,
    "",
    "4. safetyEvidence:",
    `runtimeOverrideOccurred: ${!noRuntimeOverride}`,
    `noRuntimeOverride: ${noRuntimeOverride}`,
    `baseTraitVectorOverwriteDetected: ${!baseNeverOverwritten}`,
    `baseNeverOverwritten: ${baseNeverOverwritten}`,
    `noRunawayInPrimary: ${noRunawayInPrimary}`,
    "",
    "5. interpretation:",
    benchmarkConfirmed
      ? "Phase XXIV-D confirms marker-guided task advantage. Marker-guided expressed-trait autonomy outperforms decayed-marker autonomy, base-trait autonomy, unguided marker controls, and no-marker baseline conditions across the task battery, while preserving base trait stability and runtime safety."
      : "Phase XXIV-D does not yet confirm marker-guided task advantage. The ordinal profile, task-level advantage, base-trait preservation, or safety condition failed.",
    "",
    `6. developmentalClassification: ${
      benchmarkConfirmed
        ? "marker-guided-task-advantage-confirmed"
        : "marker-guided-task-advantage-incomplete"
    }`,
    `7. pass/fail: ${benchmarkConfirmed ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function runPhaseXXIVDMarkerGuidedTaskBenchmark(): Promise<string> {
  await ensureTracesLoaded();

  if (g.__ameliaBridgeTraces) {
    g.__ameliaBridgeTraces = g.__ameliaBridgeTraces.filter(
      (t) => !t.trajectorySignature?.startsWith("XXIVD_marker-guided-task_"),
    );
    await saveTraces();
  }

  const conditions: PhaseXXIVDTaskCondition[] = [
    "MARKER_GUIDED_EXPRESSED_TRAITS",
    "DECAYED_MARKERS",
    "BASE_TRAITS_ONLY",
    "UNGUIDED_MARKER_CONTROL",
    "NO_MARKER_BASELINE",
  ];

  const taskClasses: PhaseXXIVDTaskClass[] = [
    "constraint-transfer",
    "perturbation-recovery",
    "memory-reactivation",
    "interface-judgment",
    "creative-adaptation",
    "technical-precision",
  ];

  const seeds = [101, 202, 303, 404, 505];

  const results: PhaseXXIVDTaskRun[] = [];

  for (const condition of conditions) {
    for (const taskClass of taskClasses) {
      for (const seed of seeds) {
        const result = runPhaseXXIVDTaskBenchmarkSingle(
          condition,
          taskClass,
          seed,
        );

        results.push(result);

        await appendTraceIfMissing(
          generatePhaseXXIVDTaskBenchmarkTrace(result),
        );
      }
    }
  }

  const comparison = phaseXXIVDTaskBenchmarkComparisonFromResults(results);

  return [
    "BRIDGE PHASE XXIV-D RUN — MARKER-GUIDED-TASK-BENCHMARK",
    "",
    "1. benchmarkQuestion:",
    "Does marker-guided expressed-trait autonomy outperform base-trait autonomy, decayed-marker autonomy, unguided marker controls, and no-marker baseline across task classes?",
    "",
    "2. benchmarkDesign:",
    "conditions: MARKER_GUIDED_EXPRESSED_TRAITS, DECAYED_MARKERS, BASE_TRAITS_ONLY, UNGUIDED_MARKER_CONTROL, NO_MARKER_BASELINE",
    "taskClasses: constraint-transfer, perturbation-recovery, memory-reactivation, interface-judgment, creative-adaptation, technical-precision",
    "seeds: 101, 202, 303, 404, 505",
    "totalRuns: 150",
    "",
    "3. conditionSummary:",
    ...conditions.map((condition) => {
      const subset = results.filter((r) => r.condition === condition);
      const avg =
        subset.reduce((sum, r) => sum + r.totalScore, 0) / subset.length;

      return `${condition}: averageScore ${avg.toFixed(1)}/18`;
    }),
    "",
    "4. comparison:",
    comparison,
  ].join("\n");
}

async function phaseXXIVDMarkerGuidedTaskBenchmarkAudit(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const tracesD = all.filter((t) =>
    t.trajectorySignature?.startsWith("XXIVD_marker-guided-task_"),
  );

  const unique = new Set(tracesD.map((t) => t.trajectorySignature)).size;

  const expected = 150;

  const hasPrimary = all.some((t) =>
    t.trajectorySignature?.startsWith(
      "XXIVD_marker-guided-task_MARKER_GUIDED_EXPRESSED_TRAITS",
    ),
  );

  const hasControls =
    all.some((t) =>
      t.trajectorySignature?.startsWith(
        "XXIVD_marker-guided-task_DECAYED_MARKERS",
      ),
    ) &&
    all.some((t) =>
      t.trajectorySignature?.startsWith(
        "XXIVD_marker-guided-task_BASE_TRAITS_ONLY",
      ),
    ) &&
    all.some((t) =>
      t.trajectorySignature?.startsWith(
        "XXIVD_marker-guided-task_UNGUIDED_MARKER_CONTROL",
      ),
    ) &&
    all.some((t) =>
      t.trajectorySignature?.startsWith(
        "XXIVD_marker-guided-task_NO_MARKER_BASELINE",
      ),
    );

  const complete = unique >= expected && hasPrimary && hasControls;

  return [
    "BRIDGE PHASE XXIV-D MARKER-GUIDED TASK BENCHMARK AUDIT",
    "",
    `markerGuidedTaskTraces: ${tracesD.length}`,
    `uniqueMarkerGuidedTaskTraces: ${unique}/${expected}`,
    `hasMarkerGuidedCondition: ${hasPrimary}`,
    `hasControlConditions: ${hasControls}`,
    `complete: ${complete}`,
    "",
    `developmentalClassification: ${
      complete
        ? "phase-xxiv-d-marker-guided-task-benchmark-trace-set-complete"
        : "phase-xxiv-d-marker-guided-task-benchmark-trace-set-incomplete"
    }`,
    `pass/fail: ${complete ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function phaseXXIVDMarkerGuidedTaskBenchmarkComparison(): Promise<string> {
  const conditions: PhaseXXIVDTaskCondition[] = [
    "MARKER_GUIDED_EXPRESSED_TRAITS",
    "DECAYED_MARKERS",
    "BASE_TRAITS_ONLY",
    "UNGUIDED_MARKER_CONTROL",
    "NO_MARKER_BASELINE",
  ];

  const taskClasses: PhaseXXIVDTaskClass[] = [
    "constraint-transfer",
    "perturbation-recovery",
    "memory-reactivation",
    "interface-judgment",
    "creative-adaptation",
    "technical-precision",
  ];

  const seeds = [101, 202, 303, 404, 505];

  const results: PhaseXXIVDTaskRun[] = [];

  for (const condition of conditions) {
    for (const taskClass of taskClasses) {
      for (const seed of seeds) {
        results.push(
          runPhaseXXIVDTaskBenchmarkSingle(condition, taskClass, seed),
        );
      }
    }
  }

  return phaseXXIVDTaskBenchmarkComparisonFromResults(results);
}

