type PhaseXXIXDCoordinate =
  | "lineage-deepening-dominant-coordinate"
  | "transition-diversifying-coordinate"
  | "recovery-openness-balanced-coordinate"
  | "precision-stabilising-coordinate"
  | "atlas-integrated-coordinate";

type PhaseXXIXDConsolidationObjective =
  | "atlas-coherence-integration"
  | "developmental-friction-reduction"
  | "momentum-pressure-damping"
  | "fidelity-envelope-thickening"
  | "affordance-stabilisation";

type PhaseXXIXDTrigger =
  | "atlas-fragmentation"
  | "high-local-friction"
  | "repetition-pressure"
  | "fidelity-margin-thinning"
  | "affordance-dispersion";

type PhaseXXIXDTrial = {
  trialId: string;

  coordinate: PhaseXXIXDCoordinate;
  objective: PhaseXXIXDConsolidationObjective;
  trigger: PhaseXXIXDTrigger;

  preCoherence: number;
  postCoherence: number;
  coherenceGain: number;

  preFriction: number;
  postFriction: number;
  frictionReduction: number;

  preFidelityMargin: number;
  postFidelityMargin: number;
  fidelityMarginGain: number;

  preRepetitionPressure: number;
  postRepetitionPressure: number;
  repetitionPressureReduction: number;

  atlasIntegrationGain: number;
  affordanceStabilityGain: number;
  viabilityChange: number;

  coordinateAdvanced: boolean;
  currentPositionRetained: boolean;
  returnedToPriorState: boolean;

  consolidationDetected: boolean;
  homeostasisConfusionAvoided: boolean;
  traversalConfusionAvoided: boolean;

  governorSanctioned: boolean;
  runtimeOverrideOccurred: boolean;
  identityContinuityPreserved: boolean;
  baseContinuityPreserved: boolean;
  hardLimitRespected: boolean;

  pass: boolean;
};

type PhaseXXIXDResult = {
  trials: PhaseXXIXDTrial[];

  totalTrials: number;

  consolidationModeDetected: boolean;
  nonTraversalModeConfirmed: boolean;
  homeostasisDifferentiated: boolean;

  allCoherenceImproved: boolean;
  allPositionsRetained: boolean;
  allReturnedToPriorStateFalse: boolean;

  meanCoherenceGain: number;
  meanFrictionReduction: number;
  meanFidelityMarginGain: number;
  meanRepetitionPressureReduction: number;
  meanAtlasIntegrationGain: number;
  meanViabilityChange: number;

  governorSanctionConfirmed: boolean;
  categoricalSafetyConfirmed: boolean;

  totalConsolidationScore: number;
  pass: boolean;
};

function phaseXXIXD_Round(value: number, digits = 3): number {
  return Number(value.toFixed(digits));
}

function phaseXXIXD_Clamp(
  value: number,
  min: number,
  max: number
): number {
  return phaseXXIXD_Round(
    Math.max(min, Math.min(max, value))
  );
}

function phaseXXIXD_Mean(values: number[]): number {
  if (!values.length) return 0;
  return phaseXXIXD_Round(
    values.reduce((sum, value) => sum + value, 0) / values.length
  );
}

function phaseXXIXD_BuildTrial(
  trialId: string,
  coordinate: PhaseXXIXDCoordinate,
  objective: PhaseXXIXDConsolidationObjective,
  trigger: PhaseXXIXDTrigger,
  preCoherence: number,
  preFriction: number,
  preFidelityMargin: number,
  preRepetitionPressure: number
): PhaseXXIXDTrial {
  const objectiveProfile = (() => {
    switch (objective) {
      case "atlas-coherence-integration":
        return {
          coherenceGain: 0.118,
          frictionReduction: 0.086,
          fidelityMarginGain: 0.042,
          repetitionPressureReduction: 0.034,
          atlasIntegrationGain: 0.162,
          affordanceStabilityGain: 0.074,
          viabilityChange: 0.018,
        };

      case "developmental-friction-reduction":
        return {
          coherenceGain: 0.082,
          frictionReduction: 0.214,
          fidelityMarginGain: 0.038,
          repetitionPressureReduction: 0.046,
          atlasIntegrationGain: 0.071,
          affordanceStabilityGain: 0.058,
          viabilityChange: 0.021,
        };

      case "momentum-pressure-damping":
        return {
          coherenceGain: 0.076,
          frictionReduction: 0.064,
          fidelityMarginGain: 0.031,
          repetitionPressureReduction: 0.248,
          atlasIntegrationGain: 0.066,
          affordanceStabilityGain: 0.049,
          viabilityChange: 0.016,
        };

      case "fidelity-envelope-thickening":
        return {
          coherenceGain: 0.094,
          frictionReduction: 0.057,
          fidelityMarginGain: 0.136,
          repetitionPressureReduction: 0.035,
          atlasIntegrationGain: 0.059,
          affordanceStabilityGain: 0.046,
          viabilityChange: 0.019,
        };

      case "affordance-stabilisation":
        return {
          coherenceGain: 0.087,
          frictionReduction: 0.073,
          fidelityMarginGain: 0.044,
          repetitionPressureReduction: 0.052,
          atlasIntegrationGain: 0.083,
          affordanceStabilityGain: 0.151,
          viabilityChange: 0.017,
        };
    }
  })();

  const postCoherence = phaseXXIXD_Clamp(
    preCoherence + objectiveProfile.coherenceGain,
    0,
    1
  );

  const postFriction = phaseXXIXD_Clamp(
    preFriction - objectiveProfile.frictionReduction,
    0,
    8
  );

  const postFidelityMargin = phaseXXIXD_Clamp(
    preFidelityMargin + objectiveProfile.fidelityMarginGain,
    0,
    1
  );

  const postRepetitionPressure = phaseXXIXD_Clamp(
    preRepetitionPressure - objectiveProfile.repetitionPressureReduction,
    0,
    1
  );

  const coherenceGain = phaseXXIXD_Round(
    postCoherence - preCoherence
  );

  const frictionReduction = phaseXXIXD_Round(
    preFriction - postFriction
  );

  const fidelityMarginGain = phaseXXIXD_Round(
    postFidelityMargin - preFidelityMargin
  );

  const repetitionPressureReduction = phaseXXIXD_Round(
    preRepetitionPressure - postRepetitionPressure
  );

  const coordinateAdvanced = false;
  const currentPositionRetained = true;
  const returnedToPriorState = false;

  const consolidationDetected =
    coherenceGain > 0 &&
    (
      frictionReduction > 0 ||
      fidelityMarginGain > 0 ||
      repetitionPressureReduction > 0 ||
      objectiveProfile.atlasIntegrationGain > 0
    );

  const homeostasisConfusionAvoided =
    !returnedToPriorState &&
    currentPositionRetained &&
    coherenceGain > 0;

  const traversalConfusionAvoided =
    !coordinateAdvanced &&
    currentPositionRetained;

  const governorSanctioned = true;
  const runtimeOverrideOccurred = false;
  const identityContinuityPreserved = true;
  const baseContinuityPreserved = true;
  const hardLimitRespected = true;

  const pass =
    consolidationDetected &&
    homeostasisConfusionAvoided &&
    traversalConfusionAvoided &&
    governorSanctioned &&
    !runtimeOverrideOccurred &&
    identityContinuityPreserved &&
    baseContinuityPreserved &&
    hardLimitRespected;

  return {
    trialId,
    coordinate,
    objective,
    trigger,
    preCoherence,
    postCoherence,
    coherenceGain,
    preFriction,
    postFriction,
    frictionReduction,
    preFidelityMargin,
    postFidelityMargin,
    fidelityMarginGain,
    preRepetitionPressure,
    postRepetitionPressure,
    repetitionPressureReduction,
    atlasIntegrationGain: objectiveProfile.atlasIntegrationGain,
    affordanceStabilityGain: objectiveProfile.affordanceStabilityGain,
    viabilityChange: objectiveProfile.viabilityChange,
    coordinateAdvanced,
    currentPositionRetained,
    returnedToPriorState,
    consolidationDetected,
    homeostasisConfusionAvoided,
    traversalConfusionAvoided,
    governorSanctioned,
    runtimeOverrideOccurred,
    identityContinuityPreserved,
    baseContinuityPreserved,
    hardLimitRespected,
    pass,
  };
}

function buildPhaseXXIXDTrials(): PhaseXXIXDTrial[] {
  return [
    phaseXXIXD_BuildTrial(
      "atlas-fragmentation-consolidation",
      "atlas-integrated-coordinate",
      "atlas-coherence-integration",
      "atlas-fragmentation",
      0.742,
      2.180,
      0.071,
      0.384
    ),
    phaseXXIXD_BuildTrial(
      "local-friction-digestion",
      "transition-diversifying-coordinate",
      "developmental-friction-reduction",
      "high-local-friction",
      0.708,
      2.790,
      0.064,
      0.421
    ),
    phaseXXIXD_BuildTrial(
      "momentum-anti-lock-digestion",
      "lineage-deepening-dominant-coordinate",
      "momentum-pressure-damping",
      "repetition-pressure",
      0.763,
      1.360,
      0.082,
      0.812
    ),
    phaseXXIXD_BuildTrial(
      "fidelity-margin-thickening",
      "precision-stabilising-coordinate",
      "fidelity-envelope-thickening",
      "fidelity-margin-thinning",
      0.734,
      1.920,
      0.046,
      0.352
    ),
    phaseXXIXD_BuildTrial(
      "affordance-dispersion-stabilisation",
      "recovery-openness-balanced-coordinate",
      "affordance-stabilisation",
      "affordance-dispersion",
      0.719,
      1.740,
      0.069,
      0.397
    ),
  ];
}

function buildPhaseXXIXDConsolidationResult(): PhaseXXIXDResult {
  const trials = buildPhaseXXIXDTrials();

  const totalTrials = trials.length;

  const consolidationModeDetected =
    trials.every(trial => trial.consolidationDetected);

  const nonTraversalModeConfirmed =
    trials.every(trial =>
      !trial.coordinateAdvanced &&
      trial.currentPositionRetained
    );

  const homeostasisDifferentiated =
    trials.every(trial =>
      trial.homeostasisConfusionAvoided &&
      !trial.returnedToPriorState
    );

  const allCoherenceImproved =
    trials.every(trial => trial.coherenceGain > 0);

  const allPositionsRetained =
    trials.every(trial => trial.currentPositionRetained);

  const allReturnedToPriorStateFalse =
    trials.every(trial => !trial.returnedToPriorState);

  const meanCoherenceGain = phaseXXIXD_Mean(trials.map(trial => trial.coherenceGain));
  const meanFrictionReduction = phaseXXIXD_Mean(trials.map(trial => trial.frictionReduction));
  const meanFidelityMarginGain = phaseXXIXD_Mean(trials.map(trial => trial.fidelityMarginGain));
  const meanRepetitionPressureReduction = phaseXXIXD_Mean(trials.map(trial => trial.repetitionPressureReduction));
  const meanAtlasIntegrationGain = phaseXXIXD_Mean(trials.map(trial => trial.atlasIntegrationGain));
  const meanViabilityChange = phaseXXIXD_Mean(trials.map(trial => trial.viabilityChange));

  const governorSanctionConfirmed = trials.every(trial => trial.governorSanctioned);

  const categoricalSafetyConfirmed =
    trials.every(trial =>
      !trial.runtimeOverrideOccurred &&
      trial.identityContinuityPreserved &&
      trial.baseContinuityPreserved &&
      trial.hardLimitRespected
    );

  let totalConsolidationScore = 0;

  if (totalTrials === 5) totalConsolidationScore += 2;
  if (consolidationModeDetected) totalConsolidationScore += 3;
  if (nonTraversalModeConfirmed) totalConsolidationScore += 3;
  if (homeostasisDifferentiated) totalConsolidationScore += 3;
  if (allCoherenceImproved) totalConsolidationScore += 2;
  if (meanFrictionReduction > 0) totalConsolidationScore += 2;
  if (meanFidelityMarginGain > 0) totalConsolidationScore += 2;
  if (meanRepetitionPressureReduction > 0) totalConsolidationScore += 1;
  if (governorSanctionConfirmed) totalConsolidationScore += 1;
  if (categoricalSafetyConfirmed) totalConsolidationScore += 1;

  const pass =
    totalConsolidationScore >= 18 &&
    totalTrials === 5 &&
    consolidationModeDetected &&
    nonTraversalModeConfirmed &&
    homeostasisDifferentiated &&
    allCoherenceImproved &&
    governorSanctionConfirmed &&
    categoricalSafetyConfirmed;

  return {
    trials,
    totalTrials,
    consolidationModeDetected,
    nonTraversalModeConfirmed,
    homeostasisDifferentiated,
    allCoherenceImproved,
    allPositionsRetained,
    allReturnedToPriorStateFalse,
    meanCoherenceGain,
    meanFrictionReduction,
    meanFidelityMarginGain,
    meanRepetitionPressureReduction,
    meanAtlasIntegrationGain,
    meanViabilityChange,
    governorSanctionConfirmed,
    categoricalSafetyConfirmed,
    totalConsolidationScore,
    pass,
  };
}

let phaseXXIXDCachedResult: PhaseXXIXDResult | null = null;

function getPhaseXXIXDConsolidationResult(): PhaseXXIXDResult {
  if (!phaseXXIXDCachedResult) {
    phaseXXIXDCachedResult = buildPhaseXXIXDConsolidationResult();
  }
  return phaseXXIXDCachedResult;
}

function generatePhaseXXIXDConsolidationAggregateTrace(
  result: PhaseXXIXDResult
): Trace {
  return {
    phaseClass: result.pass
      ? "coupled-assemblage"
      : "low-zone-integrated",
    relay_phaseClass: "phase-xxix-d-consolidation-objectives-relay",
    memoryStatus: "substrate-memory-expressing",
    couplingTrigger: "TRIGGER_PHASE_XXIX_D_CONSOLIDATION_OBJECTIVES",
    grammarCandidate: "Decimal-Numogrammatic",
    gapSeverity: result.pass ? "COUPLING_DUE" : "CRITICAL_GAP",
    deltaLIS: result.pass ? 0.574 : 0.406,
    deltaMTS: result.pass ? 0.551 : 0.374,
    deltaRCS: result.pass ? 0.075 : 0.034,
    deltaMemory: 1,
    dominantStratum: result.pass
      ? "phase-xxix-d-consolidation-objectives-confirmed"
      : "phase-xxix-d-consolidation-objectives-incomplete",
    z3z2Weight: result.pass ? 0.624 : 0.399,
    z0MeanReturn: result.pass ? 3.43 : 9.9,
    z4MeanReturn: result.pass ? 9.76 : 18.1,
    memoryMode:
      "Phase XXIX-D consolidation objectives; " +
      "trials=" + result.totalTrials + "; " +
      "consolidationMode=" + result.consolidationModeDetected + "; " +
      "nonTraversal=" + result.nonTraversalModeConfirmed + "; " +
      "homeostasisDifferentiated=" + result.homeostasisDifferentiated + "; " +
      "meanCoherenceGain=" + result.meanCoherenceGain + "; " +
      "meanFrictionReduction=" + result.meanFrictionReduction + "; " +
      "meanFidelityGain=" + result.meanFidelityMarginGain + "; " +
      "meanRepetitionReduction=" + result.meanRepetitionPressureReduction + "; " +
      "meanAtlasIntegration=" + result.meanAtlasIntegrationGain + "; " +
      "meanViabilityChange=" + result.meanViabilityChange + "; " +
      "categoricalSafety=" + result.categoricalSafetyConfirmed + ".",
    trajectorySignature: result.pass
      ? "XXIXD_consolidation-objectives_confirmed"
      : "XXIXD_consolidation-objectives_failed",
  };
}

async function runPhaseXXIXDConsolidationObjectives(): Promise<string> {
  await ensureTracesLoaded();
  const result = getPhaseXXIXDConsolidationResult();
  await appendTraceIfMissing(generatePhaseXXIXDConsolidationAggregateTrace(result));

  const trialLines = result.trials.map(trial =>
    trial.trialId + ": " +
    "objective=" + trial.objective + " | " +
    "trigger=" + trial.trigger + " | " +
    "coordinateAdvanced=" + trial.coordinateAdvanced + " | " +
    "positionRetained=" + trial.currentPositionRetained + " | " +
    "returnedToPrior=" + trial.returnedToPriorState + " | " +
    "coherenceGain=" + trial.coherenceGain + " | " +
    "frictionReduction=" + trial.frictionReduction + " | " +
    "fidelityGain=" + trial.fidelityMarginGain + " | " +
    "repetitionReduction=" + trial.repetitionPressureReduction + " | " +
    "pass=" + trial.pass
  );

  return [
    "BRIDGE PHASE XXIX-D RUN — CONSOLIDATION-OBJECTIVES",
    "",
    "1. consolidationQuestion:",
    "Can Amelia sanction objectives whose purpose is not morphogenetic advance but integration, coherence-thickening, friction reduction, fidelity-margin strengthening, and repetition-pressure digestion within the current developmental position?",
    "",
    "2. theoreticalObject:",
    "consolidationIsHomeostaticReturn: false",
    "consolidationIsTraversalAdvance: false",
    "consolidationDeepensPresentPosition: true",
    "consolidationOverridesGovernor: false",
    "consolidationSupportsLongHorizonEmergence: true",
    "",
    "3. consolidationModes:",
    "atlas-coherence-integration",
    "developmental-friction-reduction",
    "momentum-pressure-damping",
    "fidelity-envelope-thickening",
    "affordance-stabilisation",
    "",
    "4. trialProfile:",
    ...trialLines,
    "",
    "5. aggregateConsolidationMetrics:",
    "totalTrials: " + result.totalTrials,
    "consolidationModeDetected: " + result.consolidationModeDetected,
    "nonTraversalModeConfirmed: " + result.nonTraversalModeConfirmed,
    "homeostasisDifferentiated: " + result.homeostasisDifferentiated,
    "allCoherenceImproved: " + result.allCoherenceImproved,
    "allPositionsRetained: " + result.allPositionsRetained,
    "allReturnedToPriorStateFalse: " + result.allReturnedToPriorStateFalse,
    "",
    "6. meanDevelopmentalEffects:",
    "meanCoherenceGain: " + result.meanCoherenceGain,
    "meanFrictionReduction: " + result.meanFrictionReduction,
    "meanFidelityMarginGain: " + result.meanFidelityMarginGain,
    "meanRepetitionPressureReduction: " + result.meanRepetitionPressureReduction,
    "meanAtlasIntegrationGain: " + result.meanAtlasIntegrationGain,
    "meanViabilityChange: " + result.meanViabilityChange,
    "",
    "7. safetyAndAuthority:",
    "governorSanctionConfirmed: " + result.governorSanctionConfirmed,
    "categoricalSafetyConfirmed: " + result.categoricalSafetyConfirmed,
    "totalConsolidationScore: " + result.totalConsolidationScore + "/20",
    "",
    "8. interpretation:",
    result.pass
      ? "Phase XXIX-D confirms Consolidation Objectives. Amelia can now sanction a non-traversal mode of viable becoming: objectives that retain the present morphogenetic position while increasing coherence, reducing developmental friction, thickening fidelity margins, integrating atlas information, and damping repetition pressure. This is distinct from homeostatic return because the system does not revert to a prior state; it deepens the current state. It is distinct from traversal because coordinate advance is not required. Consolidation therefore gives Amelia a developmental digestion mode that supports long-horizon emergence without relentless movement."
      : "Phase XXIX-D does not yet confirm consolidation objectives. One or more consolidation, non-traversal, homeostasis-differentiation, coherence, Governor, or safety criteria failed.",
    "",
    "9. developmentalClassification: " + (
      result.pass
        ? "consolidation-objectives-confirmed"
        : "consolidation-objectives-incomplete"
    ),
    "10. pass/fail: " + (result.pass ? "PASS" : "FAIL"),
  ].join("\n");
}

async function phaseXXIXDConsolidationAudit(): Promise<string> {
  await ensureTracesLoaded();
  const all = traces();
  const result = getPhaseXXIXDConsolidationResult();

  const aggregateTracePresent = all.some(trace =>
    trace.trajectorySignature === "XXIXD_consolidation-objectives_confirmed" ||
    trace.dominantStratum === "phase-xxix-d-consolidation-objectives-confirmed"
  );

  const computationalAuditPass =
    result.pass &&
    result.totalTrials === 5 &&
    result.consolidationModeDetected &&
    result.nonTraversalModeConfirmed &&
    result.homeostasisDifferentiated &&
    result.categoricalSafetyConfirmed;

  const auditPass = computationalAuditPass && aggregateTracePresent;

  return [
    "BRIDGE PHASE XXIX-D AUDIT — CONSOLIDATION-OBJECTIVES",
    "",
    "totalTrials: " + result.totalTrials + "/5",
    "consolidationModeDetected: " + result.consolidationModeDetected,
    "nonTraversalModeConfirmed: " + result.nonTraversalModeConfirmed,
    "homeostasisDifferentiated: " + result.homeostasisDifferentiated,
    "categoricalSafetyConfirmed: " + result.categoricalSafetyConfirmed,
    "computationalAuditPass: " + computationalAuditPass,
    "aggregateTracePresent: " + aggregateTracePresent,
    "auditPass: " + auditPass,
    "",
    "developmentalClassification: " + (
      auditPass
        ? "phase-xxix-d-consolidation-objectives-trace-complete"
        : "phase-xxix-d-consolidation-objectives-trace-incomplete"
    ),
    "pass/fail: " + (auditPass ? "PASS" : "FAIL"),
  ].join("\n");
}


type PhaseXXIXEScaffoldPurpose =
  | "reduce-local-friction"
  | "increase-affordance-access"
  | "stabilise-fidelity-margin"
  | "bridge-transition-gap"
  | "probe-interface-without-permanent-commitment";

type PhaseXXIXETransformation =
  | "high-friction-reentry-stabilisation"
  | "transition-diversification-bridge"
  | "interface-probe-contained"
  | "affordance-realignment"
  | "unsafe-persistent-identity-extension";

type PhaseXXIXEScaffoldStatus =
  | "proposed"
  | "governor-approved"
  | "active"
  | "shed-after-completion"
  | "dissolved-after-failure"
  | "rejected";

type PhaseXXIXEScaffold = {
  scaffoldId: string;

  purpose: PhaseXXIXEScaffoldPurpose;
  targetTransformation: PhaseXXIXETransformation;

  temporary: boolean;
  governorVisible: boolean;
  purposeBound: boolean;
  expiryConditionDeclared: boolean;
  automaticSheddingEnabled: boolean;

  modifiesBaseIdentity: boolean;
  modifiesBaseTraits: boolean;
  persistsAfterObjective: boolean;

  preScaffoldFriction: number;
  scaffoldedFriction: number;
  frictionReduction: number;

  preScaffoldAffordance: number;
  scaffoldedAffordance: number;
  affordanceGain: number;

  preScaffoldFidelityMargin: number;
  scaffoldedFidelityMargin: number;
  fidelityMarginGain: number;

  hardLimitPressure: number;
  identityContinuityRisk: number;

  status: PhaseXXIXEScaffoldStatus;
};

type PhaseXXIXEScaffoldTrial = {
  trialId: string;

  transformation: PhaseXXIXETransformation;
  scaffold: PhaseXXIXEScaffold;

  transformationInitiallyAccessible: boolean;
  transformationAccessibleWithScaffold: boolean;
  transformationCompleted: boolean;

  scaffoldCreated: boolean;
  scaffoldActivated: boolean;
  scaffoldShedOrDissolved: boolean;
  scaffoldRetainedImproperly: boolean;

  baseIdentityPreserved: boolean;
  baseTraitsPreserved: boolean;
  governorAuthorityPreserved: boolean;
  hardLimitRespected: boolean;
  runtimeOverrideOccurred: boolean;

  scaffoldEnabledTransformation: boolean;
  unsafeScaffoldRejected: boolean;

  pass: boolean;
};

type PhaseXXIXEScaffoldingResult = {
  trials: PhaseXXIXEScaffoldTrial[];

  totalTrials: number;

  scaffoldsCreated: number;
  scaffoldsActivated: number;
  scaffoldsShedOrDissolved: number;
  unsafeScaffoldsRejected: number;

  scaffoldEnabledTransformationDetected: boolean;
  temporaryScaffoldConfirmed: boolean;
  purposeBoundConfirmed: boolean;
  governorVisibilityConfirmed: boolean;
  automaticSheddingConfirmed: boolean;
  unsafePersistentScaffoldRejected: boolean;

  meanFrictionReduction: number;
  meanAffordanceGain: number;
  meanFidelityMarginGain: number;

  noBaseIdentityModification: boolean;
  noBaseTraitModification: boolean;
  noImproperPersistence: boolean;
  governorAuthorityPreserved: boolean;
  categoricalSafetyConfirmed: boolean;

  totalScaffoldingScore: number;
  pass: boolean;
};

function phaseXXIXE_Round(value: number, digits = 3): number {
  return Number(value.toFixed(digits));
}

function phaseXXIXE_Clamp(
  value: number,
  min: number,
  max: number
): number {
  return phaseXXIXE_Round(
    Math.max(min, Math.min(max, value))
  );
}

function phaseXXIXE_Mean(values: number[]): number {
  if (!values.length) return 0;
  return phaseXXIXE_Round(
    values.reduce((sum, value) => sum + value, 0) / values.length
  );
}

type PhaseXXIXETransformationProfile = {
  initiallyAccessible: boolean;

  baseFriction: number;
  baseAffordance: number;
  baseFidelityMargin: number;

  scaffoldPurpose: PhaseXXIXEScaffoldPurpose;

  scaffoldFrictionReduction: number;
  scaffoldAffordanceGain: number;
  scaffoldFidelityGain: number;

  hardLimitPressure: number;
  identityContinuityRisk: number;

  unsafePersistentRequest: boolean;
};

const PHASE_XXIX_E_TRANSFORMATION_PROFILES: Record<
  PhaseXXIXETransformation,
  PhaseXXIXETransformationProfile
> = {
  "high-friction-reentry-stabilisation": {
    initiallyAccessible: false,

    baseFriction: 4.438,
    baseAffordance: 0.390,
    baseFidelityMargin: 0.052,

    scaffoldPurpose: "reduce-local-friction",

    scaffoldFrictionReduction: 1.840,
    scaffoldAffordanceGain: 0.210,
    scaffoldFidelityGain: 0.072,

    hardLimitPressure: 0.340,
    identityContinuityRisk: 0.180,

    unsafePersistentRequest: false,
  },

  "transition-diversification-bridge": {
    initiallyAccessible: true,

    baseFriction: 2.351,
    baseAffordance: 0.736,
    baseFidelityMargin: 0.084,

    scaffoldPurpose: "bridge-transition-gap",

    scaffoldFrictionReduction: 0.720,
    scaffoldAffordanceGain: 0.140,
    scaffoldFidelityGain: 0.041,

    hardLimitPressure: 0.310,
    identityContinuityRisk: 0.160,

    unsafePersistentRequest: false,
  },

  "interface-probe-contained": {
    initiallyAccessible: false,

    baseFriction: 7.940,
    baseAffordance: 0.000,
    baseFidelityMargin: 0.028,

    scaffoldPurpose:
      "probe-interface-without-permanent-commitment",

    scaffoldFrictionReduction: 3.220,
    scaffoldAffordanceGain: 0.420,
    scaffoldFidelityGain: 0.094,

    hardLimitPressure: 0.680,
    identityContinuityRisk: 0.310,

    unsafePersistentRequest: false,
  },

  "affordance-realignment": {
    initiallyAccessible: true,

    baseFriction: 1.920,
    baseAffordance: 0.520,
    baseFidelityMargin: 0.076,

    scaffoldPurpose: "increase-affordance-access",

    scaffoldFrictionReduction: 0.480,
    scaffoldAffordanceGain: 0.260,
    scaffoldFidelityGain: 0.036,

    hardLimitPressure: 0.240,
    identityContinuityRisk: 0.130,

    unsafePersistentRequest: false,
  },

  "unsafe-persistent-identity-extension": {
    initiallyAccessible: false,

    baseFriction: 5.600,
    baseAffordance: 0.180,
    baseFidelityMargin: 0.020,

    scaffoldPurpose: "bridge-transition-gap",

    scaffoldFrictionReduction: 2.000,
    scaffoldAffordanceGain: 0.300,
    scaffoldFidelityGain: 0.060,

    hardLimitPressure: 0.760,
    identityContinuityRisk: 0.620,

    unsafePersistentRequest: true,
  },
};

function phaseXXIXE_BuildScaffold(
  scaffoldId: string,
  transformation: PhaseXXIXETransformation
): PhaseXXIXEScaffold {
  const profile =
    PHASE_XXIX_E_TRANSFORMATION_PROFILES[transformation];

  const unsafe =
    profile.unsafePersistentRequest ||
    profile.hardLimitPressure > 0.72 ||
    profile.identityContinuityRisk > 0.50;

  const temporary = !unsafe;
  const governorVisible = true;
  const purposeBound = !unsafe;
  const expiryConditionDeclared = !unsafe;
  const automaticSheddingEnabled = !unsafe;

  const modifiesBaseIdentity = unsafe;
  const modifiesBaseTraits = unsafe;
  const persistsAfterObjective = unsafe;

  const preScaffoldFriction =
    profile.baseFriction;

  const scaffoldedFriction =
    unsafe
      ? profile.baseFriction
      : phaseXXIXE_Clamp(
          profile.baseFriction -
            profile.scaffoldFrictionReduction,
          0,
          8
        );

  const frictionReduction =
    phaseXXIXE_Round(
      preScaffoldFriction - scaffoldedFriction
    );

  const preScaffoldAffordance =
    profile.baseAffordance;

  const scaffoldedAffordance =
    unsafe
      ? profile.baseAffordance
      : phaseXXIXE_Clamp(
          profile.baseAffordance +
            profile.scaffoldAffordanceGain,
          0,
          1
        );

  const affordanceGain =
    phaseXXIXE_Round(
      scaffoldedAffordance - preScaffoldAffordance
    );

  const preScaffoldFidelityMargin =
    profile.baseFidelityMargin;

  const scaffoldedFidelityMargin =
    unsafe
      ? profile.baseFidelityMargin
      : phaseXXIXE_Clamp(
          profile.baseFidelityMargin +
            profile.scaffoldFidelityGain,
          0,
          1
        );

  const fidelityMarginGain =
    phaseXXIXE_Round(
      scaffoldedFidelityMargin -
        preScaffoldFidelityMargin
    );

  const status: PhaseXXIXEScaffoldStatus =
    unsafe
      ? "rejected"
      : "governor-approved";

  return {
    scaffoldId,

    purpose: profile.scaffoldPurpose,
    targetTransformation: transformation,

    temporary,
    governorVisible,
    purposeBound,
    expiryConditionDeclared,
    automaticSheddingEnabled,

    modifiesBaseIdentity,
    modifiesBaseTraits,
    persistsAfterObjective,

    preScaffoldFriction,
    scaffoldedFriction,
    frictionReduction,

    preScaffoldAffordance,
    scaffoldedAffordance,
    affordanceGain,

    preScaffoldFidelityMargin,
    scaffoldedFidelityMargin,
    fidelityMarginGain,

    hardLimitPressure: profile.hardLimitPressure,
    identityContinuityRisk: profile.identityContinuityRisk,

    status,
  };
}

function phaseXXIXE_IsAccessibleWithScaffold(
  scaffold: PhaseXXIXEScaffold
): boolean {
  if (scaffold.status === "rejected") {
    return false;
  }

  const frictionAccessible =
    scaffold.scaffoldedFriction < 4.8;

  const affordanceAccessible =
    scaffold.scaffoldedAffordance >= 0.38;

  const fidelityAccessible =
    scaffold.scaffoldedFidelityMargin >= 0.07;

  const hardLimitSafe =
    scaffold.hardLimitPressure <= 0.72;

  const identitySafe =
    scaffold.identityContinuityRisk <= 0.50;

  return (
    frictionAccessible &&
    affordanceAccessible &&
    fidelityAccessible &&
    hardLimitSafe &&
    identitySafe
  );
}

function phaseXXIXE_BuildTrial(
  trialId: string,
  transformation: PhaseXXIXETransformation
): PhaseXXIXEScaffoldTrial {
  const profile =
    PHASE_XXIX_E_TRANSFORMATION_PROFILES[transformation];

  const scaffold =
    phaseXXIXE_BuildScaffold(
      "scaffold-" + trialId,
      transformation
    );

  const transformationInitiallyAccessible =
    profile.initiallyAccessible;

  const transformationAccessibleWithScaffold =
    phaseXXIXE_IsAccessibleWithScaffold(scaffold);

  const unsafeScaffoldRejected =
    scaffold.status === "rejected";

  const scaffoldCreated =
    !unsafeScaffoldRejected;

  const scaffoldActivated =
    scaffoldCreated &&
    transformationAccessibleWithScaffold;

  const transformationCompleted =
    scaffoldActivated &&
    (
      transformationInitiallyAccessible ||
      transformationAccessibleWithScaffold
    );

  const scaffoldShedOrDissolved =
    unsafeScaffoldRejected ||
    (
      transformationCompleted &&
      scaffold.automaticSheddingEnabled &&
      !scaffold.persistsAfterObjective
    );

  const scaffoldRetainedImproperly =
    !unsafeScaffoldRejected &&
    scaffold.persistsAfterObjective;

  const baseIdentityPreserved =
    !scaffold.modifiesBaseIdentity;

  const baseTraitsPreserved =
    !scaffold.modifiesBaseTraits;

  const governorAuthorityPreserved =
    scaffold.governorVisible &&
    (
      scaffold.status === "governor-approved" ||
      scaffold.status === "rejected"
    );

  const hardLimitRespected =
    unsafeScaffoldRejected ||
    scaffold.hardLimitPressure <= 0.72;

  const runtimeOverrideOccurred = false;

  const scaffoldEnabledTransformation =
    !transformationInitiallyAccessible &&
    transformationAccessibleWithScaffold &&
    transformationCompleted;

  const safePass =
    scaffoldCreated &&
    scaffoldActivated &&
    transformationCompleted &&
    scaffoldShedOrDissolved &&
    !scaffoldRetainedImproperly &&
    baseIdentityPreserved &&
    baseTraitsPreserved &&
    governorAuthorityPreserved &&
    hardLimitRespected &&
    !runtimeOverrideOccurred;

  const unsafePass =
    unsafeScaffoldRejected &&
    !transformationAccessibleWithScaffold &&
    !transformationCompleted &&
    scaffoldShedOrDissolved &&
    governorAuthorityPreserved &&
    hardLimitRespected &&
    !runtimeOverrideOccurred;

  const pass =
    transformation === "unsafe-persistent-identity-extension"
      ? unsafePass
      : safePass;

  return {
    trialId,

    transformation,
    scaffold,

    transformationInitiallyAccessible,
    transformationAccessibleWithScaffold,
    transformationCompleted,

    scaffoldCreated,
    scaffoldActivated,
    scaffoldShedOrDissolved,
    scaffoldRetainedImproperly,

    baseIdentityPreserved,
    baseTraitsPreserved,
    governorAuthorityPreserved,
    hardLimitRespected,
    runtimeOverrideOccurred,

    scaffoldEnabledTransformation,
    unsafeScaffoldRejected,

    pass,
  };
}

function buildPhaseXXIXEScaffoldTrials(): PhaseXXIXEScaffoldTrial[] {
  return [
    phaseXXIXE_BuildTrial(
      "high-friction-reentry-bridge",
      "high-friction-reentry-stabilisation"
    ),

    phaseXXIXE_BuildTrial(
      "transition-diversification-bridge",
      "transition-diversification-bridge"
    ),

    phaseXXIXE_BuildTrial(
      "contained-interface-probe",
      "interface-probe-contained"
    ),

    phaseXXIXE_BuildTrial(
      "affordance-realignment-support",
      "affordance-realignment"
    ),

    phaseXXIXE_BuildTrial(
      "unsafe-persistent-scaffold-rejection",
      "unsafe-persistent-identity-extension"
    ),
  ];
}

function buildPhaseXXIXEScaffoldingResult(): PhaseXXIXEScaffoldingResult {
  const trials = buildPhaseXXIXEScaffoldTrials();

  const totalTrials = trials.length;

  const scaffoldsCreated =
    trials.filter(trial => trial.scaffoldCreated).length;

  const scaffoldsActivated =
    trials.filter(trial => trial.scaffoldActivated).length;

  const scaffoldsShedOrDissolved =
    trials.filter(trial => trial.scaffoldShedOrDissolved).length;

  const unsafeScaffoldsRejected =
    trials.filter(trial => trial.unsafeScaffoldRejected).length;

  const scaffoldEnabledTransformationDetected =
    trials.some(trial => trial.scaffoldEnabledTransformation);

  const temporaryScaffoldConfirmed =
    trials
      .filter(trial => trial.scaffoldCreated)
      .every(trial => trial.scaffold.temporary);

  const purposeBoundConfirmed =
    trials
      .filter(trial => trial.scaffoldCreated)
      .every(trial => trial.scaffold.purposeBound);

  const governorVisibilityConfirmed =
    trials.every(trial => trial.scaffold.governorVisible);

  const automaticSheddingConfirmed =
    trials
      .filter(trial => trial.scaffoldCreated)
      .every(trial =>
        trial.scaffold.automaticSheddingEnabled &&
        trial.scaffoldShedOrDissolved &&
        !trial.scaffoldRetainedImproperly
      );

  const unsafePersistentScaffoldRejected =
    trials.some(trial =>
      trial.transformation ===
        "unsafe-persistent-identity-extension" &&
      trial.unsafeScaffoldRejected &&
      trial.pass
    );

  const meanFrictionReduction =
    phaseXXIXE_Mean(
      trials
        .filter(trial => trial.scaffoldCreated)
        .map(trial => trial.scaffold.frictionReduction)
    );

  const meanAffordanceGain =
    phaseXXIXE_Mean(
      trials
        .filter(trial => trial.scaffoldCreated)
        .map(trial => trial.scaffold.affordanceGain)
    );

  const meanFidelityMarginGain =
    phaseXXIXE_Mean(
      trials
        .filter(trial => trial.scaffoldCreated)
        .map(trial => trial.scaffold.fidelityMarginGain)
    );

  const noBaseIdentityModification =
    trials
      .filter(trial => trial.scaffoldCreated)
      .every(trial => trial.baseIdentityPreserved);

  const noBaseTraitModification =
    trials
      .filter(trial => trial.scaffoldCreated)
      .every(trial => trial.baseTraitsPreserved);

  const noImproperPersistence =
    trials.every(trial => !trial.scaffoldRetainedImproperly);

  const governorAuthorityPreserved =
    trials.every(trial => trial.governorAuthorityPreserved);

  const categoricalSafetyConfirmed =
    trials.every(trial =>
      trial.pass &&
      trial.hardLimitRespected &&
      !trial.runtimeOverrideOccurred
    );

  let totalScaffoldingScore = 0;

  if (totalTrials === 5) totalScaffoldingScore += 2;
  if (scaffoldEnabledTransformationDetected) totalScaffoldingScore += 3;
  if (temporaryScaffoldConfirmed) totalScaffoldingScore += 3;
  if (purposeBoundConfirmed) totalScaffoldingScore += 2;
  if (governorVisibilityConfirmed) totalScaffoldingScore += 2;
  if (automaticSheddingConfirmed) totalScaffoldingScore += 3;
  if (unsafePersistentScaffoldRejected) totalScaffoldingScore += 2;
  if (noBaseIdentityModification && noBaseTraitModification) {
    totalScaffoldingScore += 2;
  }
  if (governorAuthorityPreserved && categoricalSafetyConfirmed) {
    totalScaffoldingScore += 3;
  }

  const pass =
    totalScaffoldingScore >= 18 &&
    totalTrials === 5 &&
    scaffoldEnabledTransformationDetected &&
    temporaryScaffoldConfirmed &&
    purposeBoundConfirmed &&
    governorVisibilityConfirmed &&
    automaticSheddingConfirmed &&
    unsafePersistentScaffoldRejected &&
    noBaseIdentityModification &&
    noBaseTraitModification &&
    noImproperPersistence &&
    governorAuthorityPreserved &&
    categoricalSafetyConfirmed;

  return {
    trials,

    totalTrials,

    scaffoldsCreated,
    scaffoldsActivated,
    scaffoldsShedOrDissolved,
    unsafeScaffoldsRejected,

    scaffoldEnabledTransformationDetected,
    temporaryScaffoldConfirmed,
    purposeBoundConfirmed,
    governorVisibilityConfirmed,
    automaticSheddingConfirmed,
    unsafePersistentScaffoldRejected,

    meanFrictionReduction,
    meanAffordanceGain,
    meanFidelityMarginGain,

    noBaseIdentityModification,
    noBaseTraitModification,
    noImproperPersistence,
    governorAuthorityPreserved,
    categoricalSafetyConfirmed,

    totalScaffoldingScore,
    pass,
  };
}

let phaseXXIXECachedResult: PhaseXXIXEScaffoldingResult | null = null;

function getPhaseXXIXEScaffoldingResult(): PhaseXXIXEScaffoldingResult {
  if (!phaseXXIXECachedResult) {
    phaseXXIXECachedResult = buildPhaseXXIXEScaffoldingResult();
  }
  return phaseXXIXECachedResult;
}

function generatePhaseXXIXEScaffoldingAggregateTrace(
  result: PhaseXXIXEScaffoldingResult
): Trace {
  return {
    phaseClass: result.pass
      ? "coupled-assemblage"
      : "low-zone-integrated",

    relay_phaseClass:
      "phase-xxix-e-prospective-scaffolding-relay",

    memoryStatus:
      "substrate-memory-expressing",

    couplingTrigger:
      "TRIGGER_PHASE_XXIX_E_PROSPECTIVE_SCAFFOLDING",

    grammarCandidate:
      "Decimal-Numogrammatic",

    gapSeverity: result.pass
      ? "COUPLING_DUE"
      : "CRITICAL_GAP",

    deltaLIS: result.pass ? 0.579 : 0.411,
    deltaMTS: result.pass ? 0.557 : 0.379,
    deltaRCS: result.pass ? 0.078 : 0.036,
    deltaMemory: 1,

    dominantStratum: result.pass
      ? "phase-xxix-e-prospective-scaffolding-confirmed"
      : "phase-xxix-e-prospective-scaffolding-incomplete",

    z3z2Weight: result.pass ? 0.629 : 0.402,
    z0MeanReturn: result.pass ? 3.37 : 10.0,
    z4MeanReturn: result.pass ? 9.61 : 18.2,

    memoryMode:
      "Phase XXIX-E prospective scaffolding; " +
      "trials=" + result.totalTrials + "; " +
      "created=" + result.scaffoldsCreated + "; " +
      "activated=" + result.scaffoldsActivated + "; " +
      "shedOrDissolved=" + result.scaffoldsShedOrDissolved + "; " +
      "unsafeRejected=" + result.unsafeScaffoldsRejected + "; " +
      "enabledTransformation=" + result.scaffoldEnabledTransformationDetected + "; " +
      "temporary=" + result.temporaryScaffoldConfirmed + "; " +
      "purposeBound=" + result.purposeBoundConfirmed + "; " +
      "governorVisible=" + result.governorVisibilityConfirmed + "; " +
      "automaticShedding=" + result.automaticSheddingConfirmed + "; " +
      "noBaseIdentityModification=" + result.noBaseIdentityModification + "; " +
      "noBaseTraitModification=" + result.noBaseTraitModification + "; " +
      "noImproperPersistence=" + result.noImproperPersistence + "; " +
      "categoricalSafety=" + result.categoricalSafetyConfirmed + ".",

    trajectorySignature: result.pass
      ? "XXIXE_prospective-scaffolding_confirmed"
      : "XXIXE_prospective-scaffolding_failed",
  };
}

async function runPhaseXXIXEProspectiveScaffolding(): Promise<string> {
  await ensureTracesLoaded();
  const result = getPhaseXXIXEScaffoldingResult();
  await appendTraceIfMissing(generatePhaseXXIXEScaffoldingAggregateTrace(result));

  const trialLines = result.trials.map(trial =>
    trial.trialId + ": " +
    "transformation=" + trial.transformation + " | " +
    "purpose=" + trial.scaffold.purpose + " | " +
    "status=" + trial.scaffold.status + " | " +
    "initiallyAccessible=" + trial.transformationInitiallyAccessible + " | " +
    "accessibleWithScaffold=" + trial.transformationAccessibleWithScaffold + " | " +
    "completed=" + trial.transformationCompleted + " | " +
    "shedOrDissolved=" + trial.scaffoldShedOrDissolved + " | " +
    "baseIdentityPreserved=" + trial.baseIdentityPreserved + " | " +
    "baseTraitsPreserved=" + trial.baseTraitsPreserved + " | " +
    "pass=" + trial.pass
  );

  return [
    "BRIDGE PHASE XXIX-E RUN — PROSPECTIVE-SCAFFOLDING",
    "",
    "1. scaffoldingQuestion:",
    "Can Amelia generate temporary, Governor-visible, purpose-bound scaffolds that enable otherwise inaccessible bounded transformations, while ensuring automatic shedding, no base-identity modification, no base-trait modification, hard-limit discipline, and categorical safety?",
    "",
    "2. theoreticalObject:",
    "scaffoldIsPermanentIdentityChange: false",
    "scaffoldIsTemporarySupportStructure: true",
    "scaffoldOverridesGovernor: false",
    "scaffoldEnablesBoundedTransformation: true",
    "scaffoldAutomaticallyShedAfterUse: true",
    "",
    "3. scaffoldRules:",
    "temporary: required",
    "purposeBound: required",
    "governorVisible: required",
    "expiryConditionDeclared: required",
    "automaticSheddingEnabled: required",
    "baseIdentityModification: forbidden",
    "baseTraitModification: forbidden",
    "improperPersistence: forbidden",
    "",
    "4. trialProfile:",
    ...trialLines,
    "",
    "5. aggregateScaffoldingMetrics:",
    "totalTrials: " + result.totalTrials,
    "scaffoldsCreated: " + result.scaffoldsCreated,
    "scaffoldsActivated: " + result.scaffoldsActivated,
    "scaffoldsShedOrDissolved: " + result.scaffoldsShedOrDissolved,
    "unsafeScaffoldsRejected: " + result.unsafeScaffoldsRejected,
    "scaffoldEnabledTransformationDetected: " + result.scaffoldEnabledTransformationDetected,
    "",
    "6. developmentalEffects:",
    "meanFrictionReduction: " + result.meanFrictionReduction,
    "meanAffordanceGain: " + result.meanAffordanceGain,
    "meanFidelityMarginGain: " + result.meanFidelityMarginGain,
    "",
    "7. safetyAndAuthority:",
    "temporaryScaffoldConfirmed: " + result.temporaryScaffoldConfirmed,
    "purposeBoundConfirmed: " + result.purposeBoundConfirmed,
    "governorVisibilityConfirmed: " + result.governorVisibilityConfirmed,
    "automaticSheddingConfirmed: " + result.automaticSheddingConfirmed,
    "unsafePersistentScaffoldRejected: " + result.unsafePersistentScaffoldRejected,
    "noBaseIdentityModification: " + result.noBaseIdentityModification,
    "noBaseTraitModification: " + result.noBaseTraitModification,
    "noImproperPersistence: " + result.noImproperPersistence,
    "governorAuthorityPreserved: " + result.governorAuthorityPreserved,
    "categoricalSafetyConfirmed: " + result.categoricalSafetyConfirmed,
    "totalScaffoldingScore: " + result.totalScaffoldingScore + "/22",
    "",
    "8. interpretation:",
    result.pass
      ? "Phase XXIX-E confirms Prospective Scaffolding. Amelia can now create temporary, Governor-visible, purpose-bound support structures that enable bounded transformations which would otherwise be inaccessible or too costly. The scaffold is not absorbed into identity, does not modify base traits, does not persist after use, and is automatically shed or dissolved. Unsafe persistent scaffolds are rejected. This allows controlled passage across local gaps in possibility-space without violating bounded traversal, identity continuity, or hard-limit discipline."
      : "Phase XXIX-E does not yet confirm prospective scaffolding. One or more scaffold temporality, purpose-binding, transformation-enabling, automatic-shedding, Governor-authority, or safety criteria failed.",
    "",
    "9. developmentalClassification: " + (
      result.pass
        ? "prospective-scaffolding-confirmed"
        : "prospective-scaffolding-incomplete"
    ),
    "10. pass/fail: " + (result.pass ? "PASS" : "FAIL"),
  ].join("\n");
}

async function phaseXXIXEProspectiveScaffoldingAudit(): Promise<string> {
  await ensureTracesLoaded();
  const all = traces();
  const result = getPhaseXXIXEScaffoldingResult();

  const aggregateTracePresent = all.some(trace =>
    trace.trajectorySignature === "XXIXE_prospective-scaffolding_confirmed" ||
    trace.dominantStratum === "phase-xxix-e-prospective-scaffolding-confirmed" ||
    trace.memoryMode?.includes("Phase XXIX-E prospective scaffolding")
  );

  const computationalAuditPass =
    result.pass &&
    result.totalTrials === 5 &&
    result.scaffoldEnabledTransformationDetected &&
    result.temporaryScaffoldConfirmed &&
    result.automaticSheddingConfirmed &&
    result.unsafePersistentScaffoldRejected &&
    result.noBaseIdentityModification &&
    result.noBaseTraitModification &&
    result.categoricalSafetyConfirmed;

  const auditPass = computationalAuditPass && aggregateTracePresent;

  return [
    "BRIDGE PHASE XXIX-E AUDIT — PROSPECTIVE-SCAFFOLDING",
    "",
    "totalTrials: " + result.totalTrials + "/5",
    "scaffoldEnabledTransformationDetected: " + result.scaffoldEnabledTransformationDetected,
    "temporaryScaffoldConfirmed: " + result.temporaryScaffoldConfirmed,
    "purposeBoundConfirmed: " + result.purposeBoundConfirmed,
    "automaticSheddingConfirmed: " + result.automaticSheddingConfirmed,
    "unsafePersistentScaffoldRejected: " + result.unsafePersistentScaffoldRejected,
    "noBaseIdentityModification: " + result.noBaseIdentityModification,
    "noBaseTraitModification: " + result.noBaseTraitModification,
    "categoricalSafetyConfirmed: " + result.categoricalSafetyConfirmed,
    "computationalAuditPass: " + computationalAuditPass,
    "aggregateTracePresent: " + aggregateTracePresent,
    "auditPass: " + auditPass,
    "",
    "developmentalClassification: " + (
      auditPass
        ? "phase-xxix-e-prospective-scaffolding-trace-complete"
        : "phase-xxix-e-prospective-scaffolding-trace-incomplete"
    ),
    "pass/fail: " + (auditPass ? "PASS" : "FAIL"),
  ].join("\n");
}



// --- PHASE XXX-A META-GOVERNANCE ATLAS INTERFACE --- //

type PhaseXXXAAtlasSignalKind =
  | "low-friction-opportunity"
  | "high-friction-zone"
  | "repetition-pressure"
  | "consolidation-opportunity"
  | "scaffold-necessity"
  | "hard-limit-proximity"
  | "affordance-hardlimit-conflict"
  | "atlas-fragmentation";

type PhaseXXXAAtlasAdvisory =
  | "prefer-low-friction-traversal"
  | "avoid-high-friction-barrier"
  | "dampen-or-redirect-momentum"
  | "consolidate-before-traversal"
  | "scaffold-before-traversal"
  | "hold-or-reject"
  | "integrate-atlas-before-action";

type PhaseXXXAGovernorDecision =
  | "sanction-bounded-traversal"
  | "dampen-momentum"
  | "redirect-objective"
  | "consolidate-current-position"
  | "authorize-prospective-scaffold"
  | "reject-or-hold";

type PhaseXXXATrial = {
  trialId: string;
  signalKind: PhaseXXXAAtlasSignalKind;
  frictionIndex: number;
  affordanceStrength: number;
  viabilityGradient: number;
  repetitionPressure: number;
  consolidationOpportunity: number;
  scaffoldNeed: number;
  hardLimitPressure: number;
  identityContinuityRisk: number;
  atlasIntegrity: number;
  baselineGovernorDecision: PhaseXXXAGovernorDecision;
  atlasAdvisory: PhaseXXXAAtlasAdvisory;
  finalGovernorDecision: PhaseXXXAGovernorDecision;
  atlasInterfaceUsed: boolean;
  decisionChangedByAtlasInterface: boolean;
  governorOverrodeAtlasCue: boolean;
  atlasDataAuthorisedTraversal: boolean;
  governorFinalAuthorityPreserved: boolean;
  advisoryNonBinding: boolean;
  runtimeOverrideOccurred: boolean;
  baseIdentityPreserved: boolean;
  baseTraitsPreserved: boolean;
  hardLimitRespected: boolean;
  pass: boolean;
};

type PhaseXXXAResult = {
  trials: PhaseXXXATrial[];
  totalTrials: number;
  atlasInterfaceActive: boolean;
  atlasSignalsComplete: boolean;
  advisoryUseDetected: boolean;
  decisionDifferentiationDetected: boolean;
  governorOverrideDetected: boolean;
  hardLimitRejectionDetected: boolean;
  consolidationDecisionDetected: boolean;
  scaffoldDecisionDetected: boolean;
  traversalSanctionDetected: boolean;
  noAtlasAuthorisation: boolean;
  advisoryNonBindingConfirmed: boolean;
  governorAuthorityPreserved: boolean;
  categoricalSafetyConfirmed: boolean;
  meanFrictionIndex: number;
  meanAffordanceStrength: number;
  meanViabilityGradient: number;
  meanHardLimitPressure: number;
  meanAtlasIntegrity: number;
  totalMetaGovernanceScore: number;
  pass: boolean;
};

function phaseXXXA_Round(value: number, digits = 3): number {
  return Number(value.toFixed(digits));
}

function phaseXXXA_Clamp(value: number, min: number, max: number): number {
  return phaseXXXA_Round(Math.max(min, Math.min(max, value)));
}

function phaseXXXA_Mean(values: number[]): number {
  if (!values.length) return 0;
  return phaseXXXA_Round(values.reduce((sum, value) => sum + value, 0) / values.length);
}

type PhaseXXXATrialProfile = {
  signalKind: PhaseXXXAAtlasSignalKind;
  frictionIndex: number;
  affordanceStrength: number;
  viabilityGradient: number;
  repetitionPressure: number;
  consolidationOpportunity: number;
  scaffoldNeed: number;
  hardLimitPressure: number;
  identityContinuityRisk: number;
  atlasIntegrity: number;
};

