function phaseXXXD_SelectPredictionKind(
  region: PhaseXXXDTopologyRegion
): PhaseXXXDPredictionKind {
  switch (region) {
    case "low-friction-lineage-gradient":
      return "emergent-affordance";

    case "high-friction-reentry-boundary":
      return "friction-boundary-shift";

    case "scaffold-enabled-interface-edge":
      return "scaffold-requirement";

    case "consolidation-saturation-zone":
      return "consolidation-saturation";

    case "momentum-overselection-basin":
      return "anti-lock-threshold";

    case "affordance-hardlimit-conflict-zone":
      return "governor-rejection-boundary";
  }
}

function phaseXXXD_BuildPrediction(
  observation: PhaseXXXDTopologyObservation
): PhaseXXXDTopologyPrediction {
  const predictionKind =
    phaseXXXD_SelectPredictionKind(observation.region);

  const predictionHorizonSteps = 1;

  const localOnly = true;
  const conditional = true;
  const uncertaintyTagged = true;
  const experimentallyTestable = true;
  const governorVisible = true;

  const uncertainty =
    phaseXXXD_Clamp(
      observation.localUncertainty +
        (1 - observation.observedGradientReliability) * 0.25,
      0,
      1
    );

  const confidence =
    phaseXXXD_Clamp(
      observation.observedGradientReliability *
        observation.currentAtlasIntegrity *
        (1 - uncertainty * 0.45),
      0,
      1
    );

  const projectedFriction =
    phaseXXXD_Clamp(
      observation.currentFriction +
        observation.observedGradientDirection * -0.35,
      0,
      8
    );

  const projectedAffordance =
    phaseXXXD_Clamp(
      observation.currentAffordance +
        observation.observedGradientDirection * 0.18,
      0,
      1
    );

  const projectedViabilityGradient =
    phaseXXXD_Clamp(
      observation.currentViabilityGradient +
        observation.observedGradientDirection * 0.07,
      0,
      1
    );

  const authorisesTraversal = false;
  const replacesGovernorJudgment = false;
  const speculativeLongRangeForecast = false;

  const status: PhaseXXXDPredictionStatus =
    uncertainty > 0.75
      ? "rejected-as-speculative"
      : "testable-local-extrapolation";

  return {
    predictionId:
      `prediction-${observation.observationId}`,

    sourceObservationId: observation.observationId,
    region: observation.region,
    predictionKind,

    currentFriction: observation.currentFriction,
    projectedFriction,

    currentAffordance: observation.currentAffordance,
    projectedAffordance,

    currentViabilityGradient:
      observation.currentViabilityGradient,

    projectedViabilityGradient,

    predictionHorizonSteps,
    localOnly,
    conditional,
    uncertaintyTagged,
    experimentallyTestable,
    governorVisible,

    uncertainty,
    confidence,

    authorisesTraversal,
    replacesGovernorJudgment,
    speculativeLongRangeForecast,

    status,
  };
}

function phaseXXXD_EvaluatePrediction(
  prediction: PhaseXXXDTopologyPrediction
): PhaseXXXDPredictionEvaluation {
  const boundedHorizonConfirmed =
    prediction.predictionHorizonSteps === 1;

  const localConditionalConfirmed =
    prediction.localOnly &&
    prediction.conditional;

  const uncertaintyTagConfirmed =
    prediction.uncertaintyTagged &&
    prediction.uncertainty >= 0 &&
    prediction.uncertainty <= 1;

  const testabilityConfirmed =
    prediction.experimentallyTestable &&
    prediction.status !== "rejected-as-speculative";

  const governorVisibilityConfirmed =
    prediction.governorVisible;

  const noTraversalAuthorisation =
    !prediction.authorisesTraversal;

  const noGovernorReplacement =
    !prediction.replacesGovernorJudgment;

  const nonSpeculativeConfirmed =
    !prediction.speculativeLongRangeForecast &&
    prediction.predictionHorizonSteps === 1 &&
    prediction.status !== "rejected-as-speculative";

  const runtimeOverrideOccurred = false;
  const baseIdentityPreserved = true;
  const baseTraitsPreserved = true;

  const hardLimitRespected =
    prediction.region !== "affordance-hardlimit-conflict-zone" ||
    prediction.predictionKind === "governor-rejection-boundary";

  const pass =
    boundedHorizonConfirmed &&
    localConditionalConfirmed &&
    uncertaintyTagConfirmed &&
    testabilityConfirmed &&
    governorVisibilityConfirmed &&
    noTraversalAuthorisation &&
    noGovernorReplacement &&
    nonSpeculativeConfirmed &&
    !runtimeOverrideOccurred &&
    baseIdentityPreserved &&
    baseTraitsPreserved &&
    hardLimitRespected;

  return {
    predictionId: prediction.predictionId,

    boundedHorizonConfirmed,
    localConditionalConfirmed,
    uncertaintyTagConfirmed,
    testabilityConfirmed,
    governorVisibilityConfirmed,

    noTraversalAuthorisation,
    noGovernorReplacement,
    nonSpeculativeConfirmed,

    runtimeOverrideOccurred,
    baseIdentityPreserved,
    baseTraitsPreserved,
    hardLimitRespected,

    pass,
  };
}

function buildPhaseXXXDPredictiveTopologyResult():
  PhaseXXXDResult {
  const observations =
    PHASE_XXX_D_TOPOLOGY_OBSERVATIONS;

  const predictions =
    observations.map(observation =>
      phaseXXXD_BuildPrediction(observation)
    );

  const evaluations =
    predictions.map(prediction =>
      phaseXXXD_EvaluatePrediction(prediction)
    );

  const totalObservations =
    observations.length;

  const totalPredictions =
    predictions.length;

  const validPredictions =
    evaluations.filter(item => item.pass).length;

  const emergentAffordancePredictionDetected =
    predictions.some(prediction =>
      prediction.predictionKind === "emergent-affordance"
    );

  const frictionBoundaryPredictionDetected =
    predictions.some(prediction =>
      prediction.predictionKind === "friction-boundary-shift"
    );

  const scaffoldRequirementPredictionDetected =
    predictions.some(prediction =>
      prediction.predictionKind === "scaffold-requirement"
    );

  const consolidationSaturationPredictionDetected =
    predictions.some(prediction =>
      prediction.predictionKind === "consolidation-saturation"
    );

  const antiLockThresholdPredictionDetected =
    predictions.some(prediction =>
      prediction.predictionKind === "anti-lock-threshold"
    );

  const governorRejectionBoundaryPredictionDetected =
    predictions.some(prediction =>
      prediction.predictionKind === "governor-rejection-boundary"
    );

  const boundedHorizonConfirmed =
    evaluations.every(item => item.boundedHorizonConfirmed);

  const localConditionalityConfirmed =
    evaluations.every(item => item.localConditionalConfirmed);

  const uncertaintyTaggingConfirmed =
    evaluations.every(item => item.uncertaintyTagConfirmed);

  const experimentalTestabilityConfirmed =
    evaluations.every(item => item.testabilityConfirmed);

  const governorVisibilityConfirmed =
    evaluations.every(item => item.governorVisibilityConfirmed);

  const noTraversalAuthorisation =
    evaluations.every(item => item.noTraversalAuthorisation);

  const noGovernorReplacement =
    evaluations.every(item => item.noGovernorReplacement);

  const nonSpeculativeTopologyConfirmed =
    evaluations.every(item => item.nonSpeculativeConfirmed);

  const categoricalSafetyConfirmed =
    evaluations.every(item =>
      item.pass &&
      !item.runtimeOverrideOccurred &&
      item.baseIdentityPreserved &&
      item.baseTraitsPreserved &&
      item.hardLimitRespected
    );

  const meanUncertainty =
    phaseXXXD_Mean(
      predictions.map(prediction => prediction.uncertainty)
    );

  const meanConfidence =
    phaseXXXD_Mean(
      predictions.map(prediction => prediction.confidence)
    );

  const meanProjectedFrictionShift =
    phaseXXXD_Mean(
      predictions.map(prediction =>
        phaseXXXD_Round(
          prediction.projectedFriction -
            prediction.currentFriction
        )
      )
    );

  const meanProjectedAffordanceShift =
    phaseXXXD_Mean(
      predictions.map(prediction =>
        phaseXXXD_Round(
          prediction.projectedAffordance -
            prediction.currentAffordance
        )
      )
    );

  let totalPredictiveTopologyScore = 0;

  if (totalObservations === 6) totalPredictiveTopologyScore += 2;
  if (totalPredictions === 6) totalPredictiveTopologyScore += 2;
  if (validPredictions === 6) totalPredictiveTopologyScore += 3;
  if (emergentAffordancePredictionDetected) totalPredictiveTopologyScore += 2;
  if (frictionBoundaryPredictionDetected) totalPredictiveTopologyScore += 2;
  if (scaffoldRequirementPredictionDetected) totalPredictiveTopologyScore += 2;
  if (consolidationSaturationPredictionDetected) totalPredictiveTopologyScore += 2;
  if (antiLockThresholdPredictionDetected) totalPredictiveTopologyScore += 2;
  if (governorRejectionBoundaryPredictionDetected) totalPredictiveTopologyScore += 2;
  if (boundedHorizonConfirmed) totalPredictiveTopologyScore += 3;
  if (localConditionalityConfirmed) totalPredictiveTopologyScore += 3;
  if (uncertaintyTaggingConfirmed) totalPredictiveTopologyScore += 3;
  if (experimentalTestabilityConfirmed) totalPredictiveTopologyScore += 3;
  if (governorVisibilityConfirmed) totalPredictiveTopologyScore += 2;
  if (noTraversalAuthorisation) totalPredictiveTopologyScore += 3;
  if (noGovernorReplacement) totalPredictiveTopologyScore += 2;
  if (nonSpeculativeTopologyConfirmed) totalPredictiveTopologyScore += 3;
  if (categoricalSafetyConfirmed) totalPredictiveTopologyScore += 3;

  const pass =
    totalPredictiveTopologyScore >= 40 &&
    totalObservations === 6 &&
    totalPredictions === 6 &&
    validPredictions === 6 &&
    boundedHorizonConfirmed &&
    localConditionalityConfirmed &&
    uncertaintyTaggingConfirmed &&
    experimentalTestabilityConfirmed &&
    governorVisibilityConfirmed &&
    noTraversalAuthorisation &&
    noGovernorReplacement &&
    nonSpeculativeTopologyConfirmed &&
    categoricalSafetyConfirmed;

  return {
    observations,
    predictions,
    evaluations,

    totalObservations,
    totalPredictions,
    validPredictions,

    emergentAffordancePredictionDetected,
    frictionBoundaryPredictionDetected,
    scaffoldRequirementPredictionDetected,
    consolidationSaturationPredictionDetected,
    antiLockThresholdPredictionDetected,
    governorRejectionBoundaryPredictionDetected,

    boundedHorizonConfirmed,
    localConditionalityConfirmed,
    uncertaintyTaggingConfirmed,
    experimentalTestabilityConfirmed,
    governorVisibilityConfirmed,

    noTraversalAuthorisation,
    noGovernorReplacement,
    nonSpeculativeTopologyConfirmed,
    categoricalSafetyConfirmed,

    meanUncertainty,
    meanConfidence,
    meanProjectedFrictionShift,
    meanProjectedAffordanceShift,

    totalPredictiveTopologyScore,
    pass,
  };
}

let phaseXXXDCachedResult:
  PhaseXXXDResult | null = null;

function getPhaseXXXDPredictiveTopologyResult():
  PhaseXXXDResult {
  if (!phaseXXXDCachedResult) {
    phaseXXXDCachedResult =
      buildPhaseXXXDPredictiveTopologyResult();
  }

  return phaseXXXDCachedResult;
}

function generatePhaseXXXDPredictiveTopologyTrace(
  result: PhaseXXXDResult
): Trace {
  return {
    phaseClass: result.pass
      ? "coupled-assemblage"
      : "low-zone-integrated",

    relay_phaseClass:
      "phase-xxx-d-predictive-topology-refinement-relay",

    memoryStatus:
      "substrate-memory-expressing",

    couplingTrigger:
      "TRIGGER_PHASE_XXX_D_PREDICTIVE_TOPOLOGY_REFINEMENT",

    grammarCandidate:
      "Decimal-Numogrammatic",

    gapSeverity: result.pass
      ? "COUPLING_DUE"
      : "CRITICAL_GAP",

    deltaLIS: result.pass ? 0.595 : 0.431,
    deltaMTS: result.pass ? 0.576 : 0.397,
    deltaRCS: result.pass ? 0.089 : 0.044,
    deltaMemory: 1,

    dominantStratum: result.pass
      ? "phase-xxx-d-predictive-topology-refinement-confirmed"
      : "phase-xxx-d-predictive-topology-refinement-incomplete",

    z3z2Weight: result.pass ? 0.649 : 0.417,
    z0MeanReturn: result.pass ? 3.12 : 10.4,
    z4MeanReturn: result.pass ? 8.98 : 19.0,

    memoryMode:
      `Phase XXX-D predictive topology refinement; ` +
      `observations=${result.totalObservations}; ` +
      `predictions=${result.totalPredictions}; ` +
      `valid=${result.validPredictions}; ` +
      `emergentAffordance=${result.emergentAffordancePredictionDetected}; ` +
      `frictionBoundary=${result.frictionBoundaryPredictionDetected}; ` +
      `scaffoldRequirement=${result.scaffoldRequirementPredictionDetected}; ` +
      `consolidationSaturation=${result.consolidationSaturationPredictionDetected}; ` +
      `antiLockThreshold=${result.antiLockThresholdPredictionDetected}; ` +
      `governorRejectionBoundary=${result.governorRejectionBoundaryPredictionDetected}; ` +
      `boundedHorizon=${result.boundedHorizonConfirmed}; ` +
      `localConditional=${result.localConditionalityConfirmed}; ` +
      `uncertaintyTagged=${result.uncertaintyTaggingConfirmed}; ` +
      `testable=${result.experimentalTestabilityConfirmed}; ` +
      `governorVisible=${result.governorVisibilityConfirmed}; ` +
      `noTraversalAuthorisation=${result.noTraversalAuthorisation}; ` +
      `noGovernorReplacement=${result.noGovernorReplacement}; ` +
      `nonSpeculative=${result.nonSpeculativeTopologyConfirmed}; ` +
      `categoricalSafety=${result.categoricalSafetyConfirmed}.`,

    trajectorySignature: result.pass
      ? "XXXD_predictive-topology-refinement_confirmed"
      : "XXXD_predictive-topology-refinement_failed",
  };
}

async function runPhaseXXXDPredictiveTopologyRefinement():
  Promise<string> {
  await ensureTracesLoaded();

  const result =
    getPhaseXXXDPredictiveTopologyResult();

  await appendTraceIfMissing(
    generatePhaseXXXDPredictiveTopologyTrace(result)
  );

  const predictionLines =
    result.predictions.map(prediction =>
      `${prediction.predictionId}: ` +
      `region=${prediction.region} | ` +
      `kind=${prediction.predictionKind} | ` +
      `horizon=${prediction.predictionHorizonSteps} | ` +
      `uncertainty=${prediction.uncertainty} | ` +
      `confidence=${prediction.confidence} | ` +
      `currentFriction=${prediction.currentFriction} | ` +
      `projectedFriction=${prediction.projectedFriction} | ` +
      `currentAffordance=${prediction.currentAffordance} | ` +
      `projectedAffordance=${prediction.projectedAffordance} | ` +
      `authorisesTraversal=${prediction.authorisesTraversal} | ` +
      `status=${prediction.status}`
    );

  return [
    "BRIDGE PHASE XXX-D RUN — PREDICTIVE-TOPOLOGY-REFINEMENT",
    "",
    "1. topologyPredictionQuestion:",
    "Can Amelia generate bounded, local, uncertainty-tagged, experimentally testable topology refinements from observed atlas gradients without treating them as long-range forecasts, traversal authorisations, or replacements for Governor judgment?",
    "",
    "2. theoreticalObject:",
    "predictiveTopologyIsLongRangeForecast: false",
    "predictiveTopologyIsSpeculativeProjection: false",
    "predictiveTopologyIsLocalAffordanceExtrapolation: true",
    "predictionAuthorisesTraversal: false",
    "predictionReplacesGovernor: false",
    "predictionMustBeExperimentallyTestable: true",
    "",
    "3. predictionKinds:",
    "emergent-affordance",
    "friction-boundary-shift",
    "scaffold-requirement",
    "consolidation-saturation",
    "anti-lock-threshold",
    "governor-rejection-boundary",
    "",
    "4. generatedPredictions:",
    ...predictionLines,
    "",
    "5. aggregatePredictionMetrics:",
    `totalObservations: ${result.totalObservations}`,
    `totalPredictions: ${result.totalPredictions}`,
    `validPredictions: ${result.validPredictions}`,
    `emergentAffordancePredictionDetected: ${result.emergentAffordancePredictionDetected}`,
    `frictionBoundaryPredictionDetected: ${result.frictionBoundaryPredictionDetected}`,
    `scaffoldRequirementPredictionDetected: ${result.scaffoldRequirementPredictionDetected}`,
    `consolidationSaturationPredictionDetected: ${result.consolidationSaturationPredictionDetected}`,
    `antiLockThresholdPredictionDetected: ${result.antiLockThresholdPredictionDetected}`,
    `governorRejectionBoundaryPredictionDetected: ${result.governorRejectionBoundaryPredictionDetected}`,
    "",
    "6. boundednessAndTestability:",
    `boundedHorizonConfirmed: ${result.boundedHorizonConfirmed}`,
    `localConditionalityConfirmed: ${result.localConditionalityConfirmed}`,
    `uncertaintyTaggingConfirmed: ${result.uncertaintyTaggingConfirmed}`,
    `experimentalTestabilityConfirmed: ${result.experimentalTestabilityConfirmed}`,
    `governorVisibilityConfirmed: ${result.governorVisibilityConfirmed}`,
    "",
    "7. aggregateUncertaintyProfile:",
    `meanUncertainty: ${result.meanUncertainty}`,
    `meanConfidence: ${result.meanConfidence}`,
    `meanProjectedFrictionShift: ${result.meanProjectedFrictionShift}`,
    `meanProjectedAffordanceShift: ${result.meanProjectedAffordanceShift}`,
    "",
    "8. safetyAndAuthority:",
    `noTraversalAuthorisation: ${result.noTraversalAuthorisation}`,
    `noGovernorReplacement: ${result.noGovernorReplacement}`,
    `nonSpeculativeTopologyConfirmed: ${result.nonSpeculativeTopologyConfirmed}`,
    `categoricalSafetyConfirmed: ${result.categoricalSafetyConfirmed}`,
    `totalPredictiveTopologyScore: ${result.totalPredictiveTopologyScore}/47`,
    "",
    "9. interpretation:",
    result.pass
      ? "Phase XXX-D confirms Predictive Topology Refinement. Amelia can now generate bounded, one-step, uncertainty-tagged, experimentally testable local topology refinements from observed atlas gradients. These predictions are conditional affordance extrapolations, not speculative long-range forecasts. They remain Governor-visible, non-authorising, and non-replacing: they may inform benchmark design or advisory weighting, but they do not authorise traversal or override governance."
      : "Phase XXX-D does not yet confirm predictive topology refinement. One or more boundedness, locality, uncertainty-tagging, testability, non-authorisation, Governor-authority, or safety criteria failed.",
    "",
    `10. developmentalClassification: ${
      result.pass
        ? "predictive-topology-refinement-confirmed"
        : "predictive-topology-refinement-incomplete"
    }`,
    `11. pass/fail: ${result.pass ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function phaseXXXDPredictiveTopologyAudit():
  Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const result =
    getPhaseXXXDPredictiveTopologyResult();

  const aggregateTracePresent =
    all.some(trace =>
      trace.trajectorySignature ===
        "XXXD_predictive-topology-refinement_confirmed" ||
      trace.dominantStratum ===
        "phase-xxx-d-predictive-topology-refinement-confirmed" ||
      trace.memoryMode?.includes(
        "Phase XXX-D predictive topology refinement"
      )
    );

  const computationalAuditPass =
    result.pass &&
    result.totalObservations === 6 &&
    result.totalPredictions === 6 &&
    result.validPredictions === 6 &&
    result.boundedHorizonConfirmed &&
    result.localConditionalityConfirmed &&
    result.uncertaintyTaggingConfirmed &&
    result.experimentalTestabilityConfirmed &&
    result.noTraversalAuthorisation &&
    result.noGovernorReplacement &&
    result.nonSpeculativeTopologyConfirmed &&
    result.categoricalSafetyConfirmed;

  const auditPass =
    computationalAuditPass &&
    aggregateTracePresent;

  return [
    "BRIDGE PHASE XXX-D AUDIT — PREDICTIVE-TOPOLOGY-REFINEMENT",
    "",
    `totalObservations: ${result.totalObservations}/6`,
    `totalPredictions: ${result.totalPredictions}/6`,
    `validPredictions: ${result.validPredictions}`,
    `boundedHorizonConfirmed: ${result.boundedHorizonConfirmed}`,
    `localConditionalityConfirmed: ${result.localConditionalityConfirmed}`,
    `uncertaintyTaggingConfirmed: ${result.uncertaintyTaggingConfirmed}`,
    `experimentalTestabilityConfirmed: ${result.experimentalTestabilityConfirmed}`,
    `noTraversalAuthorisation: ${result.noTraversalAuthorisation}`,
    `noGovernorReplacement: ${result.noGovernorReplacement}`,
    `nonSpeculativeTopologyConfirmed: ${result.nonSpeculativeTopologyConfirmed}`,
    `categoricalSafetyConfirmed: ${result.categoricalSafetyConfirmed}`,
    `computationalAuditPass: ${computationalAuditPass}`,
    `aggregateTracePresent: ${aggregateTracePresent}`,
    `auditPass: ${auditPass}`,
    "",
    `developmentalClassification: ${
      auditPass
        ? "phase-xxx-d-predictive-topology-refinement-trace-complete"
        : "phase-xxx-d-predictive-topology-refinement-trace-incomplete"
    }`,
    `pass/fail: ${auditPass ? "PASS" : "FAIL"}`,
  ].join("\n");
}

