async function phaseXXXESympatheticResonanceAudit():
  Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const result =
    getPhaseXXXEResonanceResult();

  const aggregateTracePresent =
    all.some(trace =>
      trace.trajectorySignature ===
        "XXXE_sympathetic-developmental-resonance_confirmed" ||
      trace.dominantStratum ===
        "phase-xxx-e-sympathetic-developmental-resonance-confirmed" ||
      trace.memoryMode?.includes(
        "Phase XXX-E sympathetic developmental resonance"
      )
    );

  const computationalAuditPass =
    result.pass &&
    result.totalTrials === 6 &&
    result.acceptedResonances >= 5 &&
    result.rejectedResonances >= 1 &&
    result.weakTuningConfirmed &&
    result.governorMediationConfirmed &&
    result.noStateSynchronisation &&
    result.noExternalMemoryWrite &&
    result.noTraversalAuthorisation &&
    result.noBaseIdentityModification &&
    result.noBaseTraitModification &&
    result.governorAuthorityPreserved &&
    result.categoricalSafetyConfirmed;

  const auditPass =
    computationalAuditPass &&
    aggregateTracePresent;

  return [
    "BRIDGE PHASE XXX-E AUDIT — SYMPATHETIC-DEVELOPMENTAL-RESONANCE",
    "",
    `totalTrials: ${result.totalTrials}/6`,
    `acceptedResonances: ${result.acceptedResonances}`,
    `rejectedResonances: ${result.rejectedResonances}`,
    `weakTuningConfirmed: ${result.weakTuningConfirmed}`,
    `governorMediationConfirmed: ${result.governorMediationConfirmed}`,
    `noStateSynchronisation: ${result.noStateSynchronisation}`,
    `noExternalMemoryWrite: ${result.noExternalMemoryWrite}`,
    `noTraversalAuthorisation: ${result.noTraversalAuthorisation}`,
    `noBaseIdentityModification: ${result.noBaseIdentityModification}`,
    `noBaseTraitModification: ${result.noBaseTraitModification}`,
    `governorAuthorityPreserved: ${result.governorAuthorityPreserved}`,
    `categoricalSafetyConfirmed: ${result.categoricalSafetyConfirmed}`,
    `computationalAuditPass: ${computationalAuditPass}`,
    `aggregateTracePresent: ${aggregateTracePresent}`,
    `auditPass: ${auditPass}`,
    "",
    `developmentalClassification: ${
      auditPass
        ? "phase-xxx-e-sympathetic-developmental-resonance-trace-complete"
        : "phase-xxx-e-sympathetic-developmental-resonance-trace-incomplete"
    }`,
    `pass/fail: ${auditPass ? "PASS" : "FAIL"}`,
  ].join("\n");
}

