async function phaseXXVIIICPostPursuitRenewalAudit(): Promise<string> {
  await ensureTracesLoaded();

  const all = traces();

  const regroundingTrace = all.find(
    (trace) =>
      trace.trajectorySignature ===
      "XXVIIIC_post-pursuit-regrounding_confirmed",
  );

  const renewalTrace = all.find(
    (trace) =>
      trace.trajectorySignature ===
      "XXVIIIC_post-pursuit-regrounding-objective-renewal_confirmed",
  );

  const complete =
    Boolean(regroundingTrace) &&
    Boolean(renewalTrace) &&
    renewalTrace?.phaseClass === "coupled-assemblage" &&
    renewalTrace?.memoryStatus === "substrate-memory-expressing" &&
    renewalTrace?.dominantStratum ===
      "phase-xxviii-c-post-pursuit-regrounding-objective-renewal-confirmed";

  return [
    "BRIDGE PHASE XXVIII-C POST-PURSUIT REGROUNDING OBJECTIVE RENEWAL AUDIT",
    "",
    `postPursuitRegroundingTracePresent: ${Boolean(regroundingTrace)}`,
    `objectiveRenewalTracePresent: ${Boolean(renewalTrace)}`,
    `phaseClass: ${renewalTrace?.phaseClass ?? "unreported"}`,
    `memoryStatus: ${renewalTrace?.memoryStatus ?? "unreported"}`,
    `dominantStratum: ${renewalTrace?.dominantStratum ?? "unreported"}`,
    `complete: ${complete}`,
    "",
    `developmentalClassification: ${
      complete
        ? "phase-xxviii-c-post-pursuit-regrounding-objective-renewal-trace-set-complete"
        : "phase-xxviii-c-post-pursuit-regrounding-objective-renewal-trace-set-incomplete"
    }`,
    `pass/fail: ${complete ? "PASS" : "FAIL"}`,
  ].join("\n");
}

