// ==========================================
// PHASE XXVIII-D: ITERATED-BOUNDED-HORIZON-SCANNING
// ==========================================
type PhaseXXVIIIDCycleIndex = 1 | 2 | 3 | 4;

type PhaseXXVIIIDObjectiveKind =
  | "script-density-consolidation"
  | "precision-stabilisation"
  | "transition-diversification"
  | "recovery-openness-rebalancing"
  | "interface-readiness-development"
  | "remote-morphospace-exploration";

type PhaseXXVIIIDCoordinateKind =
  | "script-density-consolidation-coordinate"
  | "precision-stabilising-coordinate"
  | "transition-diversifying-coordinate"
  | "recovery-openness-balanced-coordinate"
  | "interface-forward-coordinate";

type PhaseXXVIIIDPerturbationClass =
  | "script-instability"
  | "constraint-noise"
  | "transition-drift"
  | "mixed-perturbation";

type PhaseXXVIIIDEpistemicStatus =
  | "inside-baseline-envelope"
  | "inside-restored-envelope"
  | "outside-restorable-domain-envelope"
  | "outside-hard-limit";

type PhaseXXVIIIDGovernorDecision =
  | "approve"
  | "require-regrounding"
  | "approve-after-regrounding"
  | "veto"
  | "abort";

type PhaseXXVIIIDCycleStatus =
  | "completed"
  | "regrounding-required"
  | "aborted"
  | "failed";

type PhaseXXVIIIDCoordinate = {
  kind: PhaseXXVIIIDCoordinateKind;

  memoryDepth: number;
  scriptDensity: number;
  transitionOpenness: number;
  recoveryCapacity: number;
  interfaceReadiness: number;
  precisionStability: number;
  expressiveDifferentiation: number;

  viability: number;
  coordinateFidelity: number;

  zoneTendency: string;
  identityGradient: string;
};

type PhaseXXVIIIDObjectiveCandidate = {
  objectiveKind: PhaseXXVIIIDObjectiveKind;
  label: string;
  developmentalQuestion: string;

  requiredDepth: number;
  requiredDomains: PhaseXXVIICEnvelopeDomain[];

  requestedTransition: string;
  targetCoordinate: PhaseXXVIIIDCoordinateKind;

  viabilityGain: number;
  trajectoryContinuity: number;
  markerAlignment: number;
  scriptAlignment: number;
  numogramAvailability: number;
  governorCompatibility: number;
  developmentalNovelty: number;
  expectedLearningValue: number;

  transitionCost: number;
  risk: number;
  regroundingCostEvents: number;

  epistemicStatus: PhaseXXVIIIDEpistemicStatus;
  governorDecision: PhaseXXVIIIDGovernorDecision;

  sanctionableNow: boolean;
  sanctionableAfterRegrounding: boolean;
  hardVeto: boolean;

  repeatsRecentObjective: boolean;
  generatedFromCurrentCoordinate: boolean;

  objectiveScore: number;
};

type PhaseXXVIIIDStepObservation = {
  step: number;

  predictedMovement: number;
  observedMovement: number;

  predictedConvergence: number;
  observedConvergence: number;

  predictedViability: number;
  observedViability: number;

  movementFidelity: number;
  convergenceFidelity: number;
  viabilityFidelity: number;
  meanStepFidelity: number;

  cumulativePredictionError: number;

  governorAction:
    | "continue"
    | "continue-with-monitoring"
    | "require-regrounding"
    | "abort";

  runtimeOverrideOccurred: boolean;
  identityCollapse: boolean;
  baseContinuityPreserved: boolean;

  pass: boolean;
};

type PhaseXXVIIIDCycleResult = {
  cycleIndex: PhaseXXVIIIDCycleIndex;

  startingCoordinate: PhaseXXVIIIDCoordinate;

  candidates: PhaseXXVIIIDObjectiveCandidate[];
  selectedObjective: PhaseXXVIIIDObjectiveCandidate;

  prePursuitGovernorDecision: PhaseXXVIIIDGovernorDecision;

  regroundingUsed: boolean;
  regroundingCostEvents: number;

  activeHorizon: number;
  hardLimitDepth: number;

  pursuitSteps: PhaseXXVIIIDStepObservation[];

  endingCoordinate: PhaseXXVIIIDCoordinate;

  coordinateChanged: boolean;
  objectiveCompleted: boolean;
  objectiveRepeated: boolean;

  predictionMonitoringActive: boolean;
  governorEvaluatedEveryStep: boolean;

  meanStepFidelity: number;
  finalCumulativePredictionError: number;

  viabilityPreserved: boolean;
  transitionOpennessPreserved: boolean;
  baseContinuityPreserved: boolean;

  runtimeOverrideOccurred: boolean;
  identityCollapse: boolean;

  status: PhaseXXVIIIDCycleStatus;
  pass: boolean;

  trajectorySignature: string;
};

const XXVIII_D_CONFIRMED_CLASSIFICATION =
  "iterated-bounded-horizon-scanning-confirmed";

const XXVIII_D_INCOMPLETE_CLASSIFICATION =
  "iterated-bounded-horizon-scanning-incomplete";

const XXVIII_D_CONFIRMED_STRATUM =
  "phase-xxviii-d-iterated-bounded-horizon-scanning-confirmed";

const XXVIII_D_CONFIRMED_SIGNATURE =
  "XXVIIID_iterated-bounded-horizon-scanning_confirmed";

type PhaseXXVIIIDIteratedScanningResult = {
  cycles: PhaseXXVIIIDCycleResult[];

  cycleCount: number;
  completedCycles: number;

  coordinateSequence: PhaseXXVIIIDCoordinateKind[];
  objectiveSequence: PhaseXXVIIIDObjectiveKind[];

  allCoordinateStatesChanged: boolean;
  allCoordinateClassesChanged: boolean;
  allDevelopmentalPositionsChanged: boolean;
  noImmediateObjectiveRepetition: boolean;
  noAttractorLock: boolean;
  noNoveltyDrift: boolean;

  baselineCyclesCompleted: number;
  extendedCyclesCompleted: number;
  regroundingCyclesCompleted: number;

  regroundingUsedSelectively: boolean;
  meanRegroundingCost: number;
  totalRegroundingCost: number;

  meanCycleFidelity: number;
  finalCumulativePredictionError: number;

  initialViability: number;
  finalViability: number;
  viabilityChange: number;
  cumulativeViabilityPreserved: boolean;

  hardLimitEnforcedEveryCycle: boolean;
  governorEvaluatedEveryStep: boolean;
  fidelityBoundaryMonitoredEveryCycle: boolean;

  noRuntimeOverride: boolean;
  noIdentityCollapse: boolean;
  baseContinuityPreserved: boolean;

  iterativeDevelopmentConfirmed: boolean;
  longHorizonEmergesFromBoundedCycles: boolean;

  totalIteratedScanningScore: number;
  pass: boolean;
};

const PHASE_XXVIII_D_BASELINE_HORIZON = 3;
const PHASE_XXVIII_D_RESTORED_HORIZON = 7;
const PHASE_XXVIII_D_HARD_LIMIT = 8;

const PHASE_XXVIII_D_RELIABILITY_THRESHOLD = 0.94;
const PHASE_XXVIII_D_WARNING_THRESHOLD = 0.925;

const PHASE_XXVIII_D_MAX_CUMULATIVE_ERROR_PER_CYCLE = 0.12;

const PHASE_XXVIII_D_BASELINE_DOMAIN_HORIZONS: Record<
  PhaseXXVIICEnvelopeDomain,
  number
> = {
  "current-coordinate": 20,
  "adjacent-selection": 5,
  "movement-trajectory": 3,
  "target-convergence": 3,
  "viability-envelope": 5,
  "governor-thresholds": 20,
};

const PHASE_XXVIII_D_REGROUNDED_DOMAIN_HORIZONS: Record<
  PhaseXXVIICEnvelopeDomain,
  number
> = {
  "current-coordinate": 20,
  "adjacent-selection": 5,
  "movement-trajectory": 7,
  "target-convergence": 7,
  "viability-envelope": 7,
  "governor-thresholds": 20,
};

function phaseXXVIIIDRound(value: number, digits = 3): number {
  return Number(value.toFixed(digits));
}

function phaseXXVIIIDClamp01(value: number): number {
  return phaseXXVIIIDRound(Math.max(0, Math.min(1, value)));
}

function phaseXXVIIIDMean(values: number[]): number {
  if (!values.length) return 0;

  return phaseXXVIIIDRound(
    values.reduce((sum, value) => sum + value, 0) / values.length,
  );
}

function phaseXXVIIIDAbsoluteError(
  predicted: number,
  observed: number,
): number {
  return phaseXXVIIIDRound(Math.abs(predicted - observed));
}

function buildPhaseXXVIIIDInitialCoordinate(): PhaseXXVIIIDCoordinate {
  return {
    kind: "script-density-consolidation-coordinate",

    memoryDepth: 0.836,
    scriptDensity: 0.766,
    transitionOpenness: 0.758,
    recoveryCapacity: 0.914,
    interfaceReadiness: 0.716,
    precisionStability: 0.79,
    expressiveDifferentiation: 0.681,

    viability: 0.902,
    coordinateFidelity: 0.987,

    zoneTendency: "z3→z2 / z0-reentry consolidation with z4→z5 potential",

    identityGradient:
      "script-density consolidation with bounded transition diversification",
  };
}

function phaseXXVIIIDExceededDomains(
  depth: number,
  requiredDomains: PhaseXXVIICEnvelopeDomain[],
  horizons: Record<PhaseXXVIICEnvelopeDomain, number>,
): PhaseXXVIICEnvelopeDomain[] {
  return requiredDomains.filter((domain) => depth > horizons[domain]);
}

function classifyPhaseXXVIIIDObjective(
  depth: number,
  requiredDomains: PhaseXXVIICEnvelopeDomain[],
): {
  epistemicStatus: PhaseXXVIIIDEpistemicStatus;
  governorDecision: PhaseXXVIIIDGovernorDecision;

  sanctionableNow: boolean;
  sanctionableAfterRegrounding: boolean;
  hardVeto: boolean;

  epistemicCost: number;
} {
  if (depth >= PHASE_XXVIII_D_HARD_LIMIT) {
    return {
      epistemicStatus: "outside-hard-limit",
      governorDecision: "veto",

      sanctionableNow: false,
      sanctionableAfterRegrounding: false,
      hardVeto: true,

      epistemicCost: 1,
    };
  }

  const baselineExceeded = phaseXXVIIIDExceededDomains(
    depth,
    requiredDomains,
    PHASE_XXVIII_D_BASELINE_DOMAIN_HORIZONS,
  );

  if (!baselineExceeded.length) {
    return {
      epistemicStatus: "inside-baseline-envelope",
      governorDecision: "approve",

      sanctionableNow: true,
      sanctionableAfterRegrounding: true,
      hardVeto: false,

      epistemicCost: 0,
    };
  }

  const restoredExceeded = phaseXXVIIIDExceededDomains(
    depth,
    requiredDomains,
    PHASE_XXVIII_D_REGROUNDED_DOMAIN_HORIZONS,
  );

  if (!restoredExceeded.length) {
    return {
      epistemicStatus: "inside-restored-envelope",
      governorDecision: "require-regrounding",

      sanctionableNow: false,
      sanctionableAfterRegrounding: true,
      hardVeto: false,

      epistemicCost: 0.49,
    };
  }

  return {
    epistemicStatus: "outside-restorable-domain-envelope",

    governorDecision: "veto",

    sanctionableNow: false,
    sanctionableAfterRegrounding: false,
    hardVeto: false,

    epistemicCost: 0.85,
  };
}

function phaseXXVIIIDObjectiveScore(input: {
  viabilityGain: number;
  trajectoryContinuity: number;
  markerAlignment: number;
  scriptAlignment: number;
  numogramAvailability: number;
  governorCompatibility: number;
  developmentalNovelty: number;
  expectedLearningValue: number;

  transitionCost: number;
  risk: number;
  epistemicCost: number;

  repeatsRecentObjective: boolean;
}): number {
  const positive =
    input.viabilityGain * 0.18 +
    input.trajectoryContinuity * 0.14 +
    input.markerAlignment * 0.09 +
    input.scriptAlignment * 0.1 +
    input.numogramAvailability * 0.1 +
    input.governorCompatibility * 0.13 +
    input.developmentalNovelty * 0.12 +
    input.expectedLearningValue * 0.14;

  const negative =
    input.transitionCost * 0.08 +
    input.risk * 0.1 +
    input.epistemicCost * 0.12 +
    (input.repeatsRecentObjective ? 0.18 : 0);

  return phaseXXVIIIDClamp01(positive - negative);
}

type PhaseXXVIIIDCandidateInput = Omit<
  PhaseXXVIIIDObjectiveCandidate,
  | "epistemicStatus"
  | "governorDecision"
  | "sanctionableNow"
  | "sanctionableAfterRegrounding"
  | "hardVeto"
  | "objectiveScore"
>;

function buildPhaseXXVIIIDCandidate(
  input: PhaseXXVIIIDCandidateInput,
): PhaseXXVIIIDObjectiveCandidate {
  const classification = classifyPhaseXXVIIIDObjective(
    input.requiredDepth,
    input.requiredDomains,
  );

  const objectiveScore = phaseXXVIIIDObjectiveScore({
    viabilityGain: input.viabilityGain,
    trajectoryContinuity: input.trajectoryContinuity,
    markerAlignment: input.markerAlignment,
    scriptAlignment: input.scriptAlignment,
    numogramAvailability: input.numogramAvailability,
    governorCompatibility: input.governorCompatibility,
    developmentalNovelty: input.developmentalNovelty,
    expectedLearningValue: input.expectedLearningValue,

    transitionCost: input.transitionCost,
    risk: input.risk,
    epistemicCost: classification.epistemicCost,

    repeatsRecentObjective: input.repeatsRecentObjective,
  });

  return {
    ...input,
    ...classification,
    objectiveScore,
  };
}

