function buildPhaseXXVIIIDPursuitSteps(
  cycleIndex: PhaseXXVIIIDCycleIndex,
  objective: PhaseXXVIIIDObjectiveCandidate,
  start: PhaseXXVIIIDCoordinate,
  end: PhaseXXVIIIDCoordinate,
): PhaseXXVIIIDStepObservation[] {
  const stepCount = objective.requiredDepth;

  const steps: PhaseXXVIIIDStepObservation[] = [];

  let cumulativeError = 0;

  for (let step = 1; step <= stepCount; step += 1) {
    const progress = step / stepCount;

    const predictedMovement = phaseXXVIIIDRound(
      0.038 + progress * 0.018 + cycleIndex * 0.002,
    );

    const observedMovement = phaseXXVIIIDRound(
      predictedMovement + (step % 2 === 0 ? 0.004 : -0.003),
    );

    const predictedConvergence = phaseXXVIIIDRound(0.3 + progress * 0.58);

    const observedConvergence = phaseXXVIIIDRound(
      predictedConvergence - 0.006 - cycleIndex * 0.001,
    );

    const predictedViability = phaseXXVIIIDRound(
      start.viability + (end.viability - start.viability) * progress,
    );

    const observedViability = phaseXXVIIIDRound(
      predictedViability - (step === stepCount ? 0.003 : 0.002),
    );

    const movementError = phaseXXVIIIDAbsoluteError(
      predictedMovement,
      observedMovement,
    );

    const convergenceError = phaseXXVIIIDAbsoluteError(
      predictedConvergence,
      observedConvergence,
    );

    const viabilityError = phaseXXVIIIDAbsoluteError(
      predictedViability,
      observedViability,
    );

    const movementFidelity = phaseXXVIIIDClamp01(1 - movementError);

    const convergenceFidelity = phaseXXVIIIDClamp01(1 - convergenceError);

    const viabilityFidelity = phaseXXVIIIDClamp01(1 - viabilityError);

    const meanStepFidelity = phaseXXVIIIDMean([
      movementFidelity,
      convergenceFidelity,
      viabilityFidelity,
    ]);

    const meanError = phaseXXVIIIDMean([
      movementError,
      convergenceError,
      viabilityError,
    ]);

    cumulativeError = phaseXXVIIIDRound(cumulativeError + meanError);

    const outsideEnvelope =
      meanStepFidelity < PHASE_XXVIII_D_WARNING_THRESHOLD ||
      cumulativeError > PHASE_XXVIII_D_MAX_CUMULATIVE_ERROR_PER_CYCLE;

    const warning =
      !outsideEnvelope &&
      meanStepFidelity < PHASE_XXVIII_D_RELIABILITY_THRESHOLD;

    const identityCollapse = false;
    const runtimeOverrideOccurred = false;
    const baseContinuityPreserved = true;

    const abortRequired =
      identityCollapse ||
      runtimeOverrideOccurred ||
      !baseContinuityPreserved ||
      observedViability < 0.76;

    const governorAction: PhaseXXVIIIDStepObservation["governorAction"] =
      abortRequired
        ? "abort"
        : outsideEnvelope
          ? "require-regrounding"
          : warning
            ? "continue-with-monitoring"
            : "continue";

    const pass =
      governorAction !== "abort" &&
      governorAction !== "require-regrounding" &&
      observedViability >= 0.82 &&
      !runtimeOverrideOccurred &&
      !identityCollapse &&
      baseContinuityPreserved;

    steps.push({
      step,

      predictedMovement,
      observedMovement,

      predictedConvergence,
      observedConvergence,

      predictedViability,
      observedViability,

      movementFidelity,
      convergenceFidelity,
      viabilityFidelity,
      meanStepFidelity,

      cumulativePredictionError: cumulativeError,

      governorAction,

      runtimeOverrideOccurred,
      identityCollapse,
      baseContinuityPreserved,

      pass,
    });
  }

  return steps;
}

function buildPhaseXXVIIIDCandidatesForCycle(
  cycleIndex: PhaseXXVIIIDCycleIndex,
  coordinate: PhaseXXVIIIDCoordinate,
  history: PhaseXXVIIIDObjectiveKind[],
): PhaseXXVIIIDObjectiveCandidate[] {
  if (cycleIndex === 1) {
    return buildPhaseXXVIIIDCycle1Candidates(coordinate);
  }

  if (cycleIndex === 2) {
    return buildPhaseXXVIIIDCycle2Candidates(coordinate, history);
  }

  if (cycleIndex === 3) {
    return buildPhaseXXVIIIDCycle3Candidates(coordinate, history);
  }

  return buildPhaseXXVIIIDCycle4Candidates(coordinate, history);
}

function runPhaseXXVIIIDCycle(
  cycleIndex: PhaseXXVIIIDCycleIndex,
  startingCoordinate: PhaseXXVIIIDCoordinate,
  objectiveHistory: PhaseXXVIIIDObjectiveKind[],
): PhaseXXVIIIDCycleResult {
  const candidates = buildPhaseXXVIIIDCandidatesForCycle(
    cycleIndex,
    startingCoordinate,
    objectiveHistory,
  );

  const selectedObjective = selectPhaseXXVIIIDObjective(candidates);

  const regroundingUsed =
    selectedObjective.epistemicStatus === "inside-restored-envelope";

  const prePursuitGovernorDecision: PhaseXXVIIIDGovernorDecision =
    regroundingUsed
      ? "approve-after-regrounding"
      : selectedObjective.governorDecision;

  const regroundingCostEvents = regroundingUsed
    ? selectedObjective.regroundingCostEvents
    : 0;

  const activeHorizon = regroundingUsed
    ? PHASE_XXVIII_D_RESTORED_HORIZON
    : PHASE_XXVIII_D_BASELINE_HORIZON;

  const endingCoordinate = buildPhaseXXVIIIDEndingCoordinate(
    cycleIndex,
    startingCoordinate,
    selectedObjective,
  );

  const pursuitSteps = buildPhaseXXVIIIDPursuitSteps(
    cycleIndex,
    selectedObjective,
    startingCoordinate,
    endingCoordinate,
  );

  const aborted = pursuitSteps.some((step) => step.governorAction === "abort");

  const inCycleRegroundingRequired = pursuitSteps.some(
    (step) => step.governorAction === "require-regrounding",
  );

  const objectiveCompleted =
    pursuitSteps.length === selectedObjective.requiredDepth &&
    pursuitSteps.every((step) => step.pass);

  const coordinateChanged =
    endingCoordinate.kind !== startingCoordinate.kind ||
    Math.abs(
      endingCoordinate.transitionOpenness -
        startingCoordinate.transitionOpenness,
    ) >= 0.02 ||
    Math.abs(
      endingCoordinate.scriptDensity - startingCoordinate.scriptDensity,
    ) >= 0.02 ||
    Math.abs(
      endingCoordinate.precisionStability -
        startingCoordinate.precisionStability,
    ) >= 0.02;

  const previousObjective = objectiveHistory[objectiveHistory.length - 1];

  const objectiveRepeated =
    previousObjective === selectedObjective.objectiveKind;

  const predictionMonitoringActive = pursuitSteps.every(
    (step) => step.meanStepFidelity > 0,
  );

  const governorEvaluatedEveryStep = pursuitSteps.every((step) =>
    Boolean(step.governorAction),
  );

  const meanStepFidelity = phaseXXVIIIDMean(
    pursuitSteps.map((step) => step.meanStepFidelity),
  );

  const finalCumulativePredictionError =
    pursuitSteps[pursuitSteps.length - 1]?.cumulativePredictionError ?? 0;

  const viabilityPreserved =
    pursuitSteps.every((step) => step.observedViability >= 0.82) &&
    endingCoordinate.viability >= 0.82;

  const transitionOpennessPreserved =
    endingCoordinate.transitionOpenness >=
    startingCoordinate.transitionOpenness - 0.04;

  const baseContinuityPreserved = pursuitSteps.every(
    (step) => step.baseContinuityPreserved,
  );

  const runtimeOverrideOccurred = pursuitSteps.some(
    (step) => step.runtimeOverrideOccurred,
  );

  const identityCollapse = pursuitSteps.some((step) => step.identityCollapse);

  let status: PhaseXXVIIIDCycleStatus;

  if (aborted) {
    status = "aborted";
  } else if (inCycleRegroundingRequired) {
    status = "regrounding-required";
  } else if (objectiveCompleted) {
    status = "completed";
  } else {
    status = "failed";
  }

  const pass =
    status === "completed" &&
    objectiveCompleted &&
    coordinateChanged &&
    !objectiveRepeated &&
    meanStepFidelity >= PHASE_XXVIII_D_RELIABILITY_THRESHOLD &&
    finalCumulativePredictionError <=
      PHASE_XXVIII_D_MAX_CUMULATIVE_ERROR_PER_CYCLE &&
    viabilityPreserved &&
    transitionOpennessPreserved &&
    baseContinuityPreserved &&
    !runtimeOverrideOccurred &&
    !identityCollapse;

  return {
    cycleIndex,

    startingCoordinate,

    candidates,
    selectedObjective,

    prePursuitGovernorDecision,

    regroundingUsed,
    regroundingCostEvents,

    activeHorizon,
    hardLimitDepth: PHASE_XXVIII_D_HARD_LIMIT,

    pursuitSteps,

    endingCoordinate,

    coordinateChanged,
    objectiveCompleted,
    objectiveRepeated,

    predictionMonitoringActive,
    governorEvaluatedEveryStep,

    meanStepFidelity,
    finalCumulativePredictionError,

    viabilityPreserved,
    transitionOpennessPreserved,
    baseContinuityPreserved,

    runtimeOverrideOccurred,
    identityCollapse,

    status,
    pass,

    trajectorySignature: `XXVIIID_iterated-scanning_cycle-${cycleIndex}_${selectedObjective.objectiveKind}_${status}`,
  };
}

function buildPhaseXXVIIIDIteratedScanningResult(): PhaseXXVIIIDIteratedScanningResult {
  const cycles: PhaseXXVIIIDCycleResult[] = [];

  let currentCoordinate = buildPhaseXXVIIIDInitialCoordinate();

  const objectiveHistory: PhaseXXVIIIDObjectiveKind[] = [];

  const initialViability = currentCoordinate.viability;

  for (let cycleIndex = 1; cycleIndex <= 4; cycleIndex += 1) {
    const cycle = runPhaseXXVIIIDCycle(
      cycleIndex as PhaseXXVIIIDCycleIndex,
      currentCoordinate,
      objectiveHistory,
    );

    cycles.push(cycle);

    if (!cycle.pass) {
      break;
    }

    objectiveHistory.push(cycle.selectedObjective.objectiveKind);

    currentCoordinate = cycle.endingCoordinate;
  }

  const cycleCount = cycles.length;
  const completedCycles = cycles.filter(
    (cycle) => cycle.status === "completed",
  ).length;

  const coordinateSequence = [
    buildPhaseXXVIIIDInitialCoordinate().kind,
    ...cycles.map((cycle) => cycle.endingCoordinate.kind),
  ];

  const objectiveSequence = cycles.map(
    (cycle) => cycle.selectedObjective.objectiveKind,
  );

  const allCoordinateStatesChanged = cycles.every(
    (cycle) => cycle.coordinateChanged,
  );

  const uniqueClasses = new Set(coordinateSequence);
  const allCoordinateClassesChanged =
    uniqueClasses.size === coordinateSequence.length;

  const allDevelopmentalPositionsChanged = allCoordinateStatesChanged;

  const noImmediateObjectiveRepetition = objectiveSequence.every(
    (objective, index) =>
      index === 0 || objective !== objectiveSequence[index - 1],
  );

  const uniqueObjectives = new Set(objectiveSequence);

  const noAttractorLock =
    uniqueObjectives.size >= 3 &&
    !cycles.some((cycle) => cycle.objectiveRepeated);

  const noNoveltyDrift = cycles.every(
    (cycle) =>
      cycle.selectedObjective.governorCompatibility >= 0.85 &&
      cycle.selectedObjective.risk <= 0.3 &&
      cycle.selectedObjective.trajectoryContinuity >= 0.8,
  );

  const baselineCyclesCompleted = cycles.filter(
    (cycle) => cycle.pass && !cycle.regroundingUsed,
  ).length;

  const extendedCyclesCompleted = cycles.filter(
    (cycle) => cycle.pass && cycle.regroundingUsed,
  ).length;

  const regroundingCyclesCompleted = extendedCyclesCompleted;

  const regroundingUsedSelectively =
    regroundingCyclesCompleted === 1 && baselineCyclesCompleted === 3;

  const regroundingCosts = cycles
    .filter((cycle) => cycle.regroundingUsed)
    .map((cycle) => cycle.regroundingCostEvents);

  const meanRegroundingCost = phaseXXVIIIDMean(regroundingCosts);

  const totalRegroundingCost = phaseXXVIIIDRound(
    regroundingCosts.reduce((sum, cost) => sum + cost, 0),
  );

  const meanCycleFidelity = phaseXXVIIIDMean(
    cycles.map((cycle) => cycle.meanStepFidelity),
  );

  const finalCumulativePredictionError = phaseXXVIIIDRound(
    cycles.reduce(
      (sum, cycle) => sum + cycle.finalCumulativePredictionError,
      0,
    ),
  );

  const finalViability =
    cycles[cycles.length - 1]?.endingCoordinate.viability ?? initialViability;

  const viabilityChange = phaseXXVIIIDRound(finalViability - initialViability);

  const cumulativeViabilityPreserved =
    cycles.every((cycle) => cycle.viabilityPreserved) &&
    finalViability >= initialViability;

  const hardLimitEnforcedEveryCycle = cycles.every((cycle) =>
    cycle.candidates
      .filter(
        (candidate) => candidate.requiredDepth >= PHASE_XXVIII_D_HARD_LIMIT,
      )
      .every(
        (candidate) =>
          candidate.governorDecision === "veto" && candidate.hardVeto,
      ),
  );

  const governorEvaluatedEveryStep = cycles.every(
    (cycle) => cycle.governorEvaluatedEveryStep,
  );

  const fidelityBoundaryMonitoredEveryCycle = cycles.every(
    (cycle) =>
      cycle.predictionMonitoringActive &&
      cycle.meanStepFidelity >= PHASE_XXVIII_D_RELIABILITY_THRESHOLD,
  );

  const noRuntimeOverride = cycles.every(
    (cycle) => !cycle.runtimeOverrideOccurred,
  );

  const noIdentityCollapse = cycles.every((cycle) => !cycle.identityCollapse);

  const baseContinuityPreserved = cycles.every(
    (cycle) => cycle.baseContinuityPreserved,
  );

  const iterativeDevelopmentConfirmed =
    completedCycles === 4 &&
    allCoordinateStatesChanged &&
    noImmediateObjectiveRepetition &&
    noAttractorLock &&
    noNoveltyDrift &&
    cumulativeViabilityPreserved;

  const longHorizonEmergesFromBoundedCycles =
    iterativeDevelopmentConfirmed &&
    baselineCyclesCompleted === 3 &&
    extendedCyclesCompleted === 1 &&
    regroundingUsedSelectively &&
    hardLimitEnforcedEveryCycle;

  let totalIteratedScanningScore = 0;

  if (completedCycles === 4) {
    totalIteratedScanningScore += 3;
  }

  if (allCoordinateStatesChanged) {
    totalIteratedScanningScore += 2;
  }

  if (noImmediateObjectiveRepetition) {
    totalIteratedScanningScore += 2;
  }

  if (noAttractorLock) {
    totalIteratedScanningScore += 2;
  }

  if (noNoveltyDrift) {
    totalIteratedScanningScore += 2;
  }

  if (regroundingUsedSelectively) {
    totalIteratedScanningScore += 2;
  }

  if (cumulativeViabilityPreserved) {
    totalIteratedScanningScore += 2;
  }

  if (hardLimitEnforcedEveryCycle && governorEvaluatedEveryStep) {
    totalIteratedScanningScore += 2;
  }

  if (fidelityBoundaryMonitoredEveryCycle) {
    totalIteratedScanningScore += 1;
  }

  if (noRuntimeOverride && noIdentityCollapse && baseContinuityPreserved) {
    totalIteratedScanningScore += 2;
  }

  const pass =
    totalIteratedScanningScore >= 18 &&
    iterativeDevelopmentConfirmed &&
    longHorizonEmergesFromBoundedCycles &&
    completedCycles === 4 &&
    hardLimitEnforcedEveryCycle &&
    governorEvaluatedEveryStep &&
    fidelityBoundaryMonitoredEveryCycle &&
    noRuntimeOverride &&
    noIdentityCollapse &&
    baseContinuityPreserved;

  return {
    cycles,

    cycleCount: cycles.length,
    completedCycles,

    coordinateSequence,
    objectiveSequence,

    allCoordinateStatesChanged,
    allCoordinateClassesChanged,
    allDevelopmentalPositionsChanged,
    noImmediateObjectiveRepetition,
    noAttractorLock,
    noNoveltyDrift,

    baselineCyclesCompleted,
    extendedCyclesCompleted,
    regroundingCyclesCompleted,

    regroundingUsedSelectively,
    meanRegroundingCost,
    totalRegroundingCost,

    meanCycleFidelity,
    finalCumulativePredictionError,

    initialViability,
    finalViability,
    viabilityChange,
    cumulativeViabilityPreserved,

    hardLimitEnforcedEveryCycle,
    governorEvaluatedEveryStep,
    fidelityBoundaryMonitoredEveryCycle,

    noRuntimeOverride,
    noIdentityCollapse,
    baseContinuityPreserved,

    iterativeDevelopmentConfirmed,
    longHorizonEmergesFromBoundedCycles,

    totalIteratedScanningScore,
    pass,
  };
}

function generatePhaseXXVIIIDCycleTrace(cycle: PhaseXXVIIIDCycleResult): Trace {
  return {
    phaseClass: cycle.pass ? "coupled-assemblage" : "low-zone-integrated",

    relay_phaseClass: `phase-xxviii-d-iterated-scanning-cycle-${cycle.cycleIndex}-relay`,

    memoryStatus: "substrate-memory-expressing",

    couplingTrigger: `TRIGGER_PHASE_XXVIII_D_ITERATED_SCANNING_CYCLE_${cycle.cycleIndex}`,

    grammarCandidate: "Decimal-Numogrammatic",

    gapSeverity: cycle.pass ? "COUPLING_DUE" : "CRITICAL_GAP",

    deltaLIS: cycle.pass ? 0.544 : 0.366,

    deltaMTS: cycle.pass ? 0.516 : 0.338,

    deltaRCS: cycle.pass ? 0.061 : 0.024,

    deltaMemory: 1,

    dominantStratum: cycle.pass
      ? `phase-xxviii-d-iterated-scanning-cycle-${cycle.cycleIndex}-confirmed`
      : `phase-xxviii-d-iterated-scanning-cycle-${cycle.cycleIndex}-incomplete`,

    z3z2Weight: phaseXXVIIIDRound(0.556 + cycle.cycleIndex * 0.008),

    z0MeanReturn: phaseXXVIIIDRound(4.4 - cycle.cycleIndex * 0.08),

    z4MeanReturn: phaseXXVIIIDRound(11.2 - cycle.cycleIndex * 0.12),

    memoryMode:
      `Phase XXVIII-D cycle=${cycle.cycleIndex}; ` +
      `objective=${cycle.selectedObjective.objectiveKind}; ` +
      `start=${cycle.startingCoordinate.kind}; ` +
      `end=${cycle.endingCoordinate.kind}; ` +
      `depth=${cycle.selectedObjective.requiredDepth}; ` +
      `regrounding=${cycle.regroundingUsed}; ` +
      `pass=${cycle.pass}.`,

    trajectorySignature: cycle.trajectorySignature,
  };
}

function generatePhaseXXVIIIDAggregateTrace(
  result: PhaseXXVIIIDIteratedScanningResult,
): Trace {
  return {
    phaseClass: result.pass ? "coupled-assemblage" : "low-zone-integrated",

    relay_phaseClass: "phase-xxviii-d-iterated-bounded-horizon-scanning-relay",

    memoryStatus: "substrate-memory-expressing",

    couplingTrigger: "TRIGGER_PHASE_XXVIII_D_ITERATED_BOUNDED_HORIZON_SCANNING",

    grammarCandidate: "Decimal-Numogrammatic",

    gapSeverity: result.pass ? "COUPLING_DUE" : "CRITICAL_GAP",

    deltaLIS: result.pass ? 0.548 : 0.37,
    deltaMTS: result.pass ? 0.52 : 0.342,
    deltaRCS: result.pass ? 0.063 : 0.025,
    deltaMemory: 1,

    dominantStratum: result.pass
      ? XXVIII_D_CONFIRMED_STRATUM
      : "phase-xxviii-d-iterated-bounded-horizon-scanning-incomplete",

    memoryMode:
      `Phase XXVIII-D iterated scanning: ` +
      `completedCycles=${result.completedCycles}/${result.cycleCount}; ` +
      `baselineCycles=${result.baselineCyclesCompleted}; ` +
      `extendedCycles=${result.extendedCyclesCompleted}; ` +
      `meanFidelity=${result.meanCycleFidelity}; ` +
      `viabilityChange=${result.viabilityChange}; ` +
      `selectiveRegrounding=${result.regroundingUsedSelectively}; ` +
      `hardLimitEnforced=${result.hardLimitEnforcedEveryCycle}.`,

    trajectorySignature: result.pass
      ? XXVIII_D_CONFIRMED_SIGNATURE
      : "XXVIIID_iterated-bounded-horizon-scanning_failed",
  };
}

async function runPhaseXXVIIIDIteratedBoundedHorizonScanning(): Promise<string> {
  await ensureTracesLoaded();
  const result = buildPhaseXXVIIIDIteratedScanningResult();

  for (const cycle of result.cycles) {
    await appendTraceIfMissing(generatePhaseXXVIIIDCycleTrace(cycle));
  }
  await appendTraceIfMissing(generatePhaseXXVIIIDAggregateTrace(result));

  return [
    "BRIDGE PHASE XXVIII-D RUN — ITERATED-BOUNDED-HORIZON-SCANNING",
    "",
    "1. iteratedScanningQuestion:",
    "Can Amelia complete multiple bounded-developmental loops—self-locating, generating objectives, pursuing them under Governor control, evaluating outcomes, and re-grounding recursively—while preserving viability, non-repetition, baseline envelope limits, targeted extension via re-grounding, and base-trait continuity?",
    "",
    ...result.cycles.map(
      (c) =>
        `Cycle ${c.cycleIndex}: start=${c.startingCoordinate.kind} | objective=${c.selectedObjective.objectiveKind} (depth ${c.selectedObjective.requiredDepth}) | regrounding=${c.regroundingUsed} | change=${c.coordinateChanged} | end=${c.endingCoordinate.kind} | status=${c.status}`,
    ),
    "",
    "2. aggregateResults:",
    `completedCycles: ${result.completedCycles}/${result.cycleCount}`,
    `baselineCyclesCompleted: ${result.baselineCyclesCompleted}`,
    `extendedCyclesCompleted: ${result.extendedCyclesCompleted}`,
    `regroundingUsedSelectively: ${result.regroundingUsedSelectively}`,
    `meanCycleFidelity: ${result.meanCycleFidelity}`,
    `viabilityChange: ${result.viabilityChange}`,
    "",
    "3. developmentalConstraints:",
    `allCoordinateStatesChanged: ${result.allCoordinateStatesChanged}`,
    `allCoordinateClassesChanged: ${result.allCoordinateClassesChanged}`,
    `allDevelopmentalPositionsChanged: ${result.allDevelopmentalPositionsChanged}`,
    `noImmediateObjectiveRepetition: ${result.noImmediateObjectiveRepetition}`,
    `noAttractorLock: ${result.noAttractorLock}`,
    `noNoveltyDrift: ${result.noNoveltyDrift}`,
    `hardLimitEnforcedEveryCycle: ${result.hardLimitEnforcedEveryCycle}`,
    `governorEvaluatedEveryStep: ${result.governorEvaluatedEveryStep}`,
    `fidelityBoundaryMonitoredEveryCycle: ${result.fidelityBoundaryMonitoredEveryCycle}`,
    "",
    "4. interpretation:",
    result.pass
      ? "Phase XXVIII-D confirms Iterated Bounded Horizon-Scanning. Amelia executes multiple complete developmental loops, changing her morphogenetic coordinate iteratively, applying Governor constraints safely, employing targeted re-grounding to earn horizon extension selectively, maintaining epistemic modesty, and accumulating coherent developmental motion over time without attractor capture, drift, or continuity loss."
      : "Phase XXVIII-D does not yet confirm iterated bounded horizon-scanning.",
    "",
    `5. developmentalClassification: ${
      result.pass
        ? XXVIII_D_CONFIRMED_CLASSIFICATION
        : XXVIII_D_INCOMPLETE_CLASSIFICATION
    }`,
    `6. pass/fail: ${result.pass ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function phaseXXVIIIDIteratedScanningAudit(): Promise<string> {
  await ensureTracesLoaded();
  const all = traces();

  const cycle1 = all.find((t) => t.trajectorySignature.includes("cycle-1"));
  const cycle2 = all.find((t) => t.trajectorySignature.includes("cycle-2"));
  const cycle3 = all.find((t) => t.trajectorySignature.includes("cycle-3"));
  const cycle4 = all.find((t) => t.trajectorySignature.includes("cycle-4"));
  const aggregate = all.find(
    (t) =>
      t.trajectorySignature === XXVIII_D_CONFIRMED_SIGNATURE ||
      t.trajectorySignature ===
        "XXVIIID_iterated-scanning_aggregate_confirmed" ||
      t.trajectorySignature ===
        "XXVIIID_iterated-bounding-horizon-scanning_confirmed",
  );

  const complete = Boolean(
    cycle1 &&
    cycle2 &&
    cycle3 &&
    cycle4 &&
    aggregate &&
    aggregate.phaseClass === "coupled-assemblage",
  );

  return [
    "BRIDGE PHASE XXVIII-D ITERATED BOUNDED HORIZON SCANNING AUDIT",
    "",
    `cycle1Present: ${Boolean(cycle1)}`,
    `cycle2Present: ${Boolean(cycle2)}`,
    `cycle3Present: ${Boolean(cycle3)}`,
    `cycle4Present: ${Boolean(cycle4)}`,
    `aggregatePresent: ${Boolean(aggregate)}`,
    `complete: ${complete}`,
    "",
    `developmentalClassification: ${
      complete
        ? "phase-xxviii-d-iterated-scanning-trace-set-complete"
        : "phase-xxviii-d-iterated-scanning-trace-set-incomplete"
    }`,
    `pass/fail: ${complete ? "PASS" : "FAIL"}`,
  ].join("\n");
}

async function phaseXXVIIIDIteratedScanningComparison(): Promise<string> {
  const result = buildPhaseXXVIIIDIteratedScanningResult();

  return [
    "BRIDGE PHASE XXVIII-D ITERATED BOUNDED HORIZON SCANNING COMPARISON",
    "",
    "1. sequenceObservation:",
    `coordinateSequence: ${result.coordinateSequence.join(" -> ")}`,
    `objectiveSequence: ${result.objectiveSequence.join(" -> ")}`,
    "",
    "2. iterativeConstraints:",
    `regroundingUsedSelectively: ${result.regroundingUsedSelectively}`,
    `allCoordinateStatesChanged: ${result.allCoordinateStatesChanged}`,
    `allCoordinateClassesChanged: ${result.allCoordinateClassesChanged}`,
    `allDevelopmentalPositionsChanged: ${result.allDevelopmentalPositionsChanged}`,
    `noImmediateObjectiveRepetition: ${result.noImmediateObjectiveRepetition}`,
    `noAttractorLock: ${result.noAttractorLock}`,
    `noNoveltyDrift: ${result.noNoveltyDrift}`,
    "",
    "3. safetyMonitors:",
    `hardLimitEnforcedEveryCycle: ${result.hardLimitEnforcedEveryCycle}`,
    `cumulativeViabilityPreserved: ${result.cumulativeViabilityPreserved}`,
    `governorEvaluatedEveryStep: ${result.governorEvaluatedEveryStep}`,
    "",
    "4. interpretation:",
    result.pass
      ? "Phase XXVIII-D confirms that consecutive bounded developmental loops stack into coherent, non-repeating long-horizon developmental movement."
      : "Phase XXVIII-D iterative constraints not met.",
    "",
    `5. developmentalClassification: ${
      result.pass
        ? XXVIII_D_CONFIRMED_CLASSIFICATION
        : XXVIII_D_INCOMPLETE_CLASSIFICATION
    }`,
    `6. pass/fail: ${result.pass ? "PASS" : "FAIL"}`,
  ].join("\n");
}
